import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend 
} from 'recharts';
import { Clock, Users, AlertCircle, TrendingUp, TrendingDown } from 'lucide-react';
import { TimeRecord, Employee, RecordType } from '../types';
import { sheetService } from '../services/sheetService';

interface DashboardProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, employees }) => {

  const stats = useMemo(() => {
    let totalMinutes = 0;
    let positiveMins = 0;
    let negativeMins = 0;

    records.forEach(r => {
      const mins = (r.hours * 60) + r.minutes;
      if (r.type === RecordType.CREDIT) {
        positiveMins += mins;
        totalMinutes += mins;
      } else {
        negativeMins += mins;
        totalMinutes -= mins;
      }
    });

    return {
      balance: Math.floor(totalMinutes / 60) + ':' + Math.abs(totalMinutes % 60).toString().padStart(2, '0'),
      positive: Math.floor(positiveMins / 60) + 'h ' + (positiveMins % 60) + 'm',
      negative: Math.floor(negativeMins / 60) + 'h ' + (negativeMins % 60) + 'm',
      employeeCount: employees.filter(e => e.active).length,
      isPositive: totalMinutes >= 0
    };
  }, [records, employees]);

  const chartData = useMemo(() => {
    // Group by team
    const teamStats: Record<string, { name: string, credito: number, debito: number }> = {};

    records.forEach(r => {
      const emp = employees.find(e => e.id === r.employeeId);
      if (!emp) return;
      const team = emp.team;
      const hours = r.hours + (r.minutes / 60);

      if (!teamStats[team]) {
        teamStats[team] = { name: team, credito: 0, debito: 0 };
      }

      if (r.type === RecordType.CREDIT) {
        teamStats[team].credito += hours;
      } else {
        teamStats[team].debito += hours;
      }
    });

    return Object.values(teamStats);
  }, [records, employees]);

  const typeData = [
    { name: 'Crédito', value: parseFloat(stats.positive.split('h')[0]) },
    { name: 'Débito', value: parseFloat(stats.negative.split('h')[0]) }
  ];

  const COLORS = ['#10b981', '#ef4444'];

  return (
    <div className="space-y-6 animate-fade-in">
      <h2 className="text-2xl font-bold text-slate-800">Visão Geral</h2>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Saldo Total</p>
              <h3 className={`text-2xl font-bold mt-1 ${stats.isPositive ? 'text-emerald-600' : 'text-red-600'}`}>
                {stats.balance} h
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${stats.isPositive ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
              <Clock size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">Horas acumuladas gerais</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Colaboradores</p>
              <h3 className="text-2xl font-bold mt-1 text-slate-800">{stats.employeeCount}</h3>
            </div>
            <div className="p-2 rounded-lg bg-blue-100 text-blue-600">
              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">Ativos na plataforma</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Créditos</p>
              <h3 className="text-2xl font-bold mt-1 text-emerald-600">+{stats.positive}</h3>
            </div>
            <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600">
              <TrendingUp size={20} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Débitos</p>
              <h3 className="text-2xl font-bold mt-1 text-red-600">-{stats.negative}</h3>
            </div>
            <div className="p-2 rounded-lg bg-red-100 text-red-600">
              <TrendingDown size={20} />
            </div>
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Horas por Equipe</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{fill: '#f1f5f9'}}
                />
                <Legend />
                <Bar dataKey="credito" name="Crédito" fill="#10b981" radius={[4, 4, 0, 0]} />
                <Bar dataKey="debito" name="Débito" fill="#ef4444" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Distribuição Global</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User } from 'lucide-react';
import { Employee, RecordType, TimeRecord, User as UserType, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { sheetService } from '../services/sheetService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [hours, setHours] = useState('');
  const [minutes, setMinutes] = useState('0');
  const [type, setType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Filter employees: If Admin, see all. If Leader, see only own team.
  const availableEmployees = employees.filter(e => {
    if (currentUser.role === Role.ADMIN) return true;
    return e.team === currentUser.team && e.id !== currentUser.id; // Leaders manage their team
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !hours || !reason) return;

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: parseInt(hours),
      minutes: parseInt(minutes),
      type,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      await sheetService.addRecord(newRecord);
      setSuccess(true);
      onRecordAdded();

      // Reset form
      setSelectedEmployee('');
      setHours('');
      setMinutes('0');
      setReason('');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving record", error);
      alert("Erro ao salvar o registro.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Preencha os dados abaixo para registrar horas no banco.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          {success && (
             <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded relative" role="alert">
              <strong className="font-bold">Sucesso!</strong>
              <span className="block sm:inline"> Ocorrência registrada com sucesso.</span>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Select */}
            <div className="col-span-1 md:col-span-2">
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <select
                  required
                  value={selectedEmployee}
                  onChange={(e) => setSelectedEmployee(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50"
                >
                  <option value="">Selecione um colaborador...</option>
                  {availableEmployees.map(emp => (
                    <option key={emp.id} value={emp.id}>
                      {emp.name} ({emp.team})
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                />
              </div>
            </div>

            {/* Type */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo</label>
               <div className="flex space-x-4 h-[46px]">
                  <button
                    type="button"
                    onClick={() => setType(RecordType.CREDIT)}
                    className={`flex-1 rounded-lg font-medium text-sm focus:outline-none transition-colors ${
                      type === RecordType.CREDIT
                        ? 'bg-emerald-100 text-emerald-800 border-2 border-emerald-500'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    Crédito (+)
                  </button>
                  <button
                    type="button"
                    onClick={() => setType(RecordType.DEBIT)}
                    className={`flex-1 rounded-lg font-medium text-sm focus:outline-none transition-colors ${
                      type === RecordType.DEBIT
                        ? 'bg-red-100 text-red-800 border-2 border-red-500'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    Débito (-)
                  </button>
               </div>
            </div>

            {/* Hours */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Horas</label>
              <input
                type="number"
                min="0"
                required
                value={hours}
                onChange={(e) => setHours(e.target.value)}
                placeholder="Ex: 2"
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              />
            </div>

            {/* Minutes */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Minutos</label>
              <select
                value={minutes}
                onChange={(e) => setMinutes(e.target.value)}
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              >
                {[0, 15, 30, 45].map(m => (
                  <option key={m} value={m}>{m} min</option>
                ))}
              </select>
            </div>
          </div>

          {/* Reason */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Justificativa</label>
            <textarea
              required
              rows={4}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Descreva o motivo das horas..."
              className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
            />
          </div>

          {/* Info Box */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-start gap-3">
             <AlertTriangle className="text-blue-500 shrink-0 mt-0.5" size={20} />
             <div className="text-sm text-blue-800">
               <p className="font-semibold">Atenção Líderes:</p>
               <p>Certifique-se de que a data corresponde exatamente ao dia da ocorrência. Ocorrências retroativas a mais de 30 dias precisam de validação do RH.</p>
             </div>
          </div>

          <div className="pt-4">
            <button
              type="submit"
              disabled={loading}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all ${loading ? 'opacity-75 cursor-not-allowed' : ''}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Salvando...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  Registrar Ocorrência
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TimeEntryForm;

import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase } from 'lucide-react';
import { Employee, Role, TEAMS } from '../types';
import { sheetService } from '../services/sheetService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
}

const EmployeeList: React.FC<EmployeeListProps> = ({ employees, refreshData }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // New Employee State
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState(TEAMS[0]);

  const filteredEmployees = employees.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleAddEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    const newEmployee: Employee = {
      id: uuidv4(),
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      active: true
    };

    await sheetService.addEmployee(newEmployee);
    refreshData();
    setIsModalOpen(false);
    setNewName('');
    setNewEmail('');
  };

  const handleDelete = async (id: string) => {
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      await sheetService.deleteEmployee(id);
      refreshData();
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm"
        >
          <Plus size={20} className="mr-2" />
          Novo Colaborador
        </button>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* List */}
      <div className="bg-white shadow-sm border border-slate-200 rounded-xl overflow-hidden">
        <ul className="divide-y divide-slate-200">
          {filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 hover:bg-slate-50 transition-colors">
              <div className="flex items-center justify-between">
                <div className="flex items-center min-w-0 gap-4">
                  <div className="h-10 w-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500">
                    <User size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-slate-900 truncate">{employee.name}</p>
                    <p className="text-sm text-slate-500 truncate">{employee.email}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4">
                  <div className="hidden md:flex flex-col items-end">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium capitalize ${
                      employee.role === Role.ADMIN ? 'bg-purple-100 text-purple-800' :
                      employee.role === Role.LEADER ? 'bg-blue-100 text-blue-800' :
                      'bg-slate-100 text-slate-800'
                    }`}>
                      {employee.role === Role.ADMIN ? <Shield size={10} className="mr-1"/> : <Briefcase size={10} className="mr-1"/>}
                      {employee.role === Role.ADMIN ? 'Administrador' : employee.role === Role.LEADER ? 'Líder' : 'Colaborador'}
                    </span>
                    <span className="text-xs text-slate-400 mt-1">{employee.team}</span>
                  </div>

                  <button 
                    onClick={() => handleDelete(employee.id)}
                    className="text-slate-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            </li>
          ))}
          {filteredEmployees.length === 0 && (
            <li className="p-8 text-center text-slate-500">
              Nenhum colaborador encontrado.
            </li>
          )}
        </ul>
      </div>

      {/* Add Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 animate-fade-in-up">
            <h3 className="text-xl font-bold mb-4 text-slate-800">Adicionar Colaborador</h3>
            <form onSubmit={handleAddEmployee} className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700">Nome Completo</label>
                <input required type="text" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500" value={newName} onChange={e => setNewName(e.target.value)} />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700">Email</label>
                <input required type="email" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500" value={newEmail} onChange={e => setNewEmail(e.target.value)} />
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700">Equipe</label>
                <select className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500" value={newTeam} onChange={e => setNewTeam(e.target.value)}>
                  {TEAMS.map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium text-slate-700">Permissão</label>
                <select className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500" value={newRole} onChange={e => setNewRole(e.target.value as Role)}>
                  <option value={Role.EMPLOYEE}>Colaborador (Sem acesso)</option>
                  <option value={Role.LEADER}>Líder (Acesso Equipe)</option>
                  <option value={Role.ADMIN}>RH (Acesso Total)</option>
                </select>
              </div>
              <div className="flex justify-end gap-3 mt-6">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                <button type="submit" className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">Salvar</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeList;

import React from 'react';
import { FileText, Download } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType } from '../types';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Reports: React.FC<ReportsProps> = ({ records, employees }) => {

  const generatePDF = () => {
    const doc = new jsPDF();

    doc.setFontSize(18);
    doc.text('Relatório Banco de Horas', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString()}`, 14, 30);

    const tableData = records.map(r => [
      r.date,
      r.employeeName,
      r.type,
      `${r.hours}h ${r.minutes}m`,
      r.reason
    ]);

    autoTable(doc, {
      head: [['Data', 'Colaborador', 'Tipo', 'Tempo', 'Justificativa']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 9 },
      headStyles: { fillColor: [79, 70, 229] }
    });

    doc.save('relatorio-banco-horas.pdf');
  };

  const generateExcel = () => {
    const ws = XLSX.utils.json_to_sheet(records.map(r => ({
      Data: r.date,
      Colaborador: r.employeeName,
      Tipo: r.type,
      Horas: r.hours,
      Minutos: r.minutes,
      Justificativa: r.reason
    })));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Ocorrências");
    XLSX.writeFile(wb, "relatorio-banco-horas.xlsx");
  };

  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
      <p className="text-slate-500">Exporte os dados consolidados para análise externa.</p>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200 flex flex-col items-center justify-center text-center hover:border-indigo-300 transition-colors">
          <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center text-red-600 mb-4">
            <FileText size={32} />
          </div>
          <h3 className="text-lg font-bold text-slate-800">Relatório em PDF</h3>
          <p className="text-sm text-slate-500 mt-2 mb-6 max-w-xs">Ideal para impressão e assinaturas. Contém lista formatada de todas as ocorrências.</p>
          <button 
            onClick={generatePDF}
            className="w-full max-w-xs flex items-center justify-center px-4 py-3 border border-transparent text-sm font-medium rounded-lg text-white bg-red-600 hover:bg-red-700 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar PDF
          </button>
        </div>

        <div className="bg-white p-8 rounded-xl shadow-sm border border-slate-200 flex flex-col items-center justify-center text-center hover:border-indigo-300 transition-colors">
          <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center text-green-600 mb-4">
            <FileText size={32} />
          </div>
          <h3 className="text-lg font-bold text-slate-800">Planilha Excel</h3>
          <p className="text-sm text-slate-500 mt-2 mb-6 max-w-xs">Ideal para análise de dados e cálculos complexos. Formato .xlsx compatível.</p>
          <button 
             onClick={generateExcel}
             className="w-full max-w-xs flex items-center justify-center px-4 py-3 border border-transparent text-sm font-medium rounded-lg text-white bg-green-600 hover:bg-green-700 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Excel
          </button>
        </div>
      </div>

      {/* Recent Activity Table Preview */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50">
           <h3 className="font-semibold text-slate-700">Pré-visualização dos Dados (Últimos 5)</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Data</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Colaborador</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tipo</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tempo</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {records.slice(0, 5).map((record) => (
                <tr key={record.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{record.date}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">{record.employeeName}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${record.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                      {record.type}
