import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TimeEntryForm from './components/TimeEntryForm';
import EmployeeList from './components/EmployeeList';
import Reports from './components/Reports';
import { Role, Employee, TimeRecord } from './types';
import { sheetService } from './services/sheetService';
import { Menu } from 'lucide-react';

const App: React.FC = () => {
  // Application State
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [records, setRecords] = useState<TimeRecord[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Authentication Mock State
  // Default to Admin to show all features, button in sidebar to toggle
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);

  // Load Data
  const fetchData = async () => {
    const emps = await sheetService.getEmployees();
    const recs = await sheetService.getRecords();
    setEmployees(emps);
    setRecords(recs);

    // Set default user if not set
    if (!currentUser && emps.length > 0) {
      setCurrentUser(emps[0]); // Default to the first user (Admin)
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleLogout = () => {
    // Simple mock logout/role switch for demo purposes
    if (!currentUser) return;

    const nextRole = currentUser.role === Role.ADMIN ? Role.LEADER : Role.ADMIN;
    const nextUser = employees.find(e => e.role === nextRole) || employees[0];
    setCurrentUser(nextUser);
    setCurrentPage('dashboard');
    alert(`Perfil alternado para: ${nextUser.name} (${nextUser.role === Role.ADMIN ? 'RH' : 'Líder'})`);
  };

  if (!currentUser) {
    return <div className="flex items-center justify-center h-screen bg-slate-50 text-slate-500">Carregando sistema...</div>;
  }

  // Render Page Content based on route
  const renderContent = () => {
    switch (currentPage) {
      case 'dashboard':
        return <Dashboard records={records} employees={employees} />;
      case 'form':
        return <TimeEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} />;
      case 'employees':
        return currentUser.role === Role.ADMIN ? <EmployeeList employees={employees} refreshData={fetchData} /> : <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
      case 'reports':
        return currentUser.role === Role.ADMIN ? <Reports records={records} employees={employees} /> : <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
      default:
        return <Dashboard records={records} employees={employees} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-40 bg-slate-900 text-white p-4 flex justify-between items-center shadow-md">
         <span className="font-bold">Formulário de Ocorrência</span>
         <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
           <Menu size={24} />
         </button>
      </div>

      <Sidebar 
        currentRole={currentUser.role} 
        currentPage={currentPage} 
        setPage={(page) => {
          setCurrentPage(page);
          setIsSidebarOpen(false);
        }}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full pt-16 md:pt-0">
        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { sheetService } from '../services/sheetService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [hours, setHours] = useState('');
  const [minutes, setMinutes] = useState('0');
  const [type, setType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Filter employees: If Admin, see all. If Leader, see only own team.
  const availableEmployees = employees.filter(e => {
    if (currentUser.role === Role.ADMIN) return true;
    return e.team === currentUser.team && e.id !== currentUser.id; // Leaders manage their team
  });

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !hours || !reason) return;

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: parseInt(hours),
      minutes: parseInt(minutes),
      type,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      await sheetService.addRecord(newRecord);
      setSuccess(true);
      onRecordAdded();

      // Reset form
      setSelectedEmployee('');
      setHours('');
      setMinutes('0');
      setReason('');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving record", error);
      alert("Erro ao salvar o registro.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Preencha os dados abaixo para registrar horas no banco.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          {success && (
             <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded relative" role="alert">
              <strong className="font-bold">Sucesso!</strong>
              <span className="block sm:inline"> Ocorrência registrada com sucesso.</span>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Select */}
            <div className="col-span-1 md:col-span-2">
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <select
                  required
                  value={selectedEmployee}
                  onChange={(e) => setSelectedEmployee(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50"
                >
                  <option value="">Selecione um colaborador...</option>
                  {availableEmployees.map(emp => (
                    <option key={emp.id} value={emp.id}>
                      {emp.name} ({emp.team})
                    </option>
                  ))}
                </select>
              </div>
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                />
              </div>
            </div>

            {/* Type */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo</label>
               <div className="flex space-x-4 h-[46px]">
                  <button
                    type="button"
                    onClick={() => setType(RecordType.CREDIT)}
                    className={`flex-1 rounded-lg font-medium text-sm focus:outline-none transition-colors ${
                      type === RecordType.CREDIT
                        ? 'bg-emerald-100 text-emerald-800 border-2 border-emerald-500'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    Crédito (+)
                  </button>
                  <button
                    type="button"
                    onClick={() => setType(RecordType.DEBIT)}
                    className={`flex-1 rounded-lg font-medium text-sm focus:outline-none transition-colors ${
                      type === RecordType.DEBIT
                        ? 'bg-red-100 text-red-800 border-2 border-red-500'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    Débito (-)
                  </button>
               </div>
            </div>

            {/* Hours */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Horas</label>
              <input
                type="number"
                min="0"
                required
                value={hours}
                onChange={(e) => setHours(e.target.value)}
                placeholder="Ex: 2"
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              />
            </div>

            {/* Minutes */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Minutos</label>
              <select
                value={minutes}
                onChange={(e) => setMinutes(e.target.value)}
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
              >
                {[0, 15, 30, 45].map(m => (
                  <option key={m} value={m}>{m} min</option>
                ))}
              </select>
            </div>
          </div>

          {/* Reason */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Justificativa</label>
            <textarea
              required
              rows={4}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Descreva o motivo das horas..."
              className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
            />
          </div>

          {/* Info Box */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-start gap-3">
             <AlertTriangle className="text-blue-500 shrink-0 mt-0.5" size={20} />
             <div className="text-sm text-blue-800">
               <p className="font-semibold">Atenção Líderes:</p>
               <p>Certifique-se de que a data corresponde exatamente ao dia da ocorrência. Ocorrências retroativas a mais de 30 dias precisam de validação do RH.</p>
             </div>
          </div>

          <div className="pt-4">
            <button
              type="submit"
              disabled={loading}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all ${loading ? 'opacity-75 cursor-not-allowed' : ''}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
