import { Employee, TimeRecord, Role, RecordType } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// In a real implementation, this service would fetch() to the Google Apps Script Web App URL.
// For now, we mock it with LocalStorage to persist data within the session.

const EMPLOYEES_KEY = 'bh_employees';
const RECORDS_KEY = 'bh_records';

const loadData = <T,>(key: string, initial: T): T => {
  const stored = localStorage.getItem(key);
  if (stored) {
    return JSON.parse(stored);
  }
  localStorage.setItem(key, JSON.stringify(initial));
  return initial;
};

export const sheetService = {
  getEmployees: async (): Promise<Employee[]> => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 500));
    return loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    const employees = loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
    const newEmployees = [...employees, employee];
    localStorage.setItem(EMPLOYEES_KEY, JSON.stringify(newEmployees));
  },

  deleteEmployee: async (id: string): Promise<void> => {
    const employees = loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
    const newEmployees = employees.filter(e => e.id !== id);
    localStorage.setItem(EMPLOYEES_KEY, JSON.stringify(newEmployees));
  },

  getRecords: async (): Promise<TimeRecord[]> => {
    await new Promise(resolve => setTimeout(resolve, 500));
    return loadData(RECORDS_KEY, INITIAL_RECORDS);
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    const records = loadData(RECORDS_KEY, INITIAL_RECORDS);
    const newRecords = [record, ...records];
    localStorage.setItem(RECORDS_KEY, JSON.stringify(newRecords));
  },

  // Helper to calculate balance in minutes
  calculateBalance: (records: TimeRecord[], employeeId?: string): number => {
    let filtered = records;
    if (employeeId) {
      filtered = records.filter(r => r.employeeId === employeeId);
    }

    return filtered.reduce((acc, curr) => {
      const totalMinutes = (curr.hours * 60) + curr.minutes;
      // If it's CREDIT, we ADD. If DEBIT, we SUBTRACT.
      return curr.type === RecordType.CREDIT ? acc + totalMinutes : acc - totalMinutes;
    }, 0);
  }
};

import React, { useMemo } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend 
} from 'recharts';
import { Clock, Users, AlertCircle, TrendingUp, TrendingDown } from 'lucide-react';
import { TimeRecord, Employee, RecordType } from '../types';
import { sheetService } from '../services/sheetService';

interface DashboardProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, employees }) => {

  const stats = useMemo(() => {
    let totalMinutes = 0;
    let positiveMins = 0;
    let negativeMins = 0;

    records.forEach(r => {
      const mins = (r.hours * 60) + r.minutes;
      if (r.type === RecordType.CREDIT) {
        positiveMins += mins;
        totalMinutes += mins;
      } else {
        negativeMins += mins;
        totalMinutes -= mins;
      }
    });

    return {
      balance: Math.floor(totalMinutes / 60) + ':' + Math.abs(totalMinutes % 60).toString().padStart(2, '0'),
      positive: Math.floor(positiveMins / 60) + 'h ' + (positiveMins % 60) + 'm',
      negative: Math.floor(negativeMins / 60) + 'h ' + (negativeMins % 60) + 'm',
      employeeCount: employees.filter(e => e.active).length,
      isPositive: totalMinutes >= 0
    };
  }, [records, employees]);

  const chartData = useMemo(() => {
    // Group by team
    const teamStats: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};

    records.forEach(r => {
      const emp = employees.find(e => e.id === r.employeeId);
      if (!emp) return;
      const team = emp.team;
      const hours = r.hours + (r.minutes / 60);

      if (!teamStats[team]) {
        teamStats[team] = { name: team, horasPositivas: 0, horasNegativas: 0 };
      }

      if (r.type === RecordType.CREDIT) {
        teamStats[team].horasPositivas += hours;
      } else {
        teamStats[team].horasNegativas += hours;
      }
    });

    return Object.values(teamStats);
  }, [records, employees]);

  const typeData = [
    { name: 'Horas Positivas', value: parseFloat(stats.positive.split('h')[0]) },
    { name: 'Horas Negativas', value: parseFloat(stats.negative.split('h')[0]) }
  ];

  const COLORS = ['#10b981', '#ef4444'];

  return (
    <div className="space-y-6 animate-fade-in">
      <h2 className="text-2xl font-bold text-slate-800">Visão Geral</h2>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Saldo Total</p>
              <h3 className={`text-2xl font-bold mt-1 ${stats.isPositive ? 'text-emerald-600' : 'text-red-600'}`}>
                {stats.balance} h
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${stats.isPositive ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
              <Clock size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">Horas acumuladas gerais</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Colaboradores</p>
              <h3 className="text-2xl font-bold mt-1 text-slate-800">{stats.employeeCount}</h3>
            </div>
            <div className="p-2 rounded-lg bg-blue-100 text-blue-600">
              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">Ativos na plataforma</p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Horas Positivas</p>
              <h3 className="text-2xl font-bold mt-1 text-emerald-600">+{stats.positive}</h3>
            </div>
            <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600">
              <TrendingUp size={20} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Horas Negativas</p>
              <h3 className="text-2xl font-bold mt-1 text-red-600">-{stats.negative}</h3>
            </div>
            <div className="p-2 rounded-lg bg-red-100 text-red-600">
              <TrendingDown size={20} />
            </div>
          </div>
        </div>
      </div>

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Horas por Equipe</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="name" tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                <Tooltip 
                  contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                  cursor={{fill: '#f1f5f9'}}
                />
                <Legend />
                <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#10b981" radius={[4, 4, 0, 0]} />
                <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Distribuição Global</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

