import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { sheetService } from '../services/sheetService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [hours, setHours] = useState('');
  const [minutes, setMinutes] = useState('0');
  const [type, setType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Filter employees: If Admin, see all. If Leader, see only own team.
  const availableEmployees = employees.filter(e => {
    if (currentUser.role === Role.ADMIN) return true;
    return e.team === currentUser.team && e.id !== currentUser.id; // Leaders manage their team
  });

  const filteredEmployees = availableEmployees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !hours || !reason) return;

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: parseInt(hours),
      minutes: parseInt(minutes),
      type,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      await sheetService.addRecord(newRecord);
      setSuccess(true);
      onRecordAdded();

      // Reset form
      setSelectedEmployee('');
      setSearchTerm('');
      setHours('');
      setMinutes('0');
      setReason('');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving record", error);
      alert("Erro ao salvar o registro.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Preencha os dados abaixo para registrar horas no banco.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          {success && (
             <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded relative" role="alert">
              <strong className="font-bold">Sucesso!</strong>
              <span className="block sm:inline"> Ocorrência registrada com sucesso.</span>
            </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); // Reset selection on change
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
                />
              </div>
            </div>

            {/* Type */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo</label>
               <div className="flex space-x-4 h-[46px]">
                  <button
                    type="button"
                    onClick={() => setType(RecordType.CREDIT)}
                    className={`flex-1 rounded-lg font-medium text-sm focus:outline-none transition-colors ${
                      type === RecordType.CREDIT
                        ? 'bg-emerald-100 text-emerald-800 border-2 border-emerald-500'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    Horas Positivas (+)
                  </button>
                  <button
                    type="button"
                    onClick={() => setType(RecordType.DEBIT)}
                    className={`flex-1 rounded-lg font-medium text-sm focus:outline-none transition-colors ${
                      type === RecordType.DEBIT
                        ? 'bg-red-100 text-red-800 border-2 border-red-500'
                        : 'bg-slate-50 text-slate-500 border border-slate-200 hover:bg-slate-100'
                    }`}
                  >
                    Horas Negativas (-)
                  </button>
               </div>
            </div>

            {/* Hours */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Horas</label>
              <input
                type="number"
                min="0"
                required
                value={hours}
                onChange={(e) => setHours(e.target.value)}
                placeholder="Ex: 2"
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
              />
            </div>

            {/* Minutes */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Minutos</label>
              <select
                value={minutes}
                onChange={(e) => setMinutes(e.target.value)}
