import { Employee, TimeRecord, Role, RecordType } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// In a real implementation, this service would fetch() to the Google Apps Script Web App URL.
// For now, we mock it with LocalStorage to persist data within the session.

const EMPLOYEES_KEY = 'bh_employees';
const RECORDS_KEY = 'bh_records';

const loadData = <T,>(key: string, initial: T): T => {
  const stored = localStorage.getItem(key);
  if (stored) {
    return JSON.parse(stored);
  }
  localStorage.setItem(key, JSON.stringify(initial));
  return initial;
};

export const sheetService = {
  getEmployees: async (): Promise<Employee[]> => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 500));
    return loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    const employees = loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
    const newEmployees = [...employees, employee];
    localStorage.setItem(EMPLOYEES_KEY, JSON.stringify(newEmployees));
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    const employees = loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
    const index = employees.findIndex(e => e.id === updatedEmployee.id);

    if (index !== -1) {
      employees[index] = updatedEmployee;
      localStorage.setItem(EMPLOYEES_KEY, JSON.stringify(employees));
    }
  },

  deleteEmployee: async (id: string): Promise<void> => {
    const employees = loadData(EMPLOYEES_KEY, INITIAL_EMPLOYEES);
    const newEmployees = employees.filter(e => e.id !== id);
    localStorage.setItem(EMPLOYEES_KEY, JSON.stringify(newEmployees));
  },

  getRecords: async (): Promise<TimeRecord[]> => {
    await new Promise(resolve => setTimeout(resolve, 500));
    return loadData(RECORDS_KEY, INITIAL_RECORDS);
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    const records = loadData(RECORDS_KEY, INITIAL_RECORDS);
    const newRecords = [record, ...records];
    localStorage.setItem(RECORDS_KEY, JSON.stringify(newRecords));
  },

  // Helper to calculate balance in minutes
  calculateBalance: (records: TimeRecord[], employeeId?: string): number => {
    let filtered = records;
    if (employeeId) {
      filtered = records.filter(r => r.employeeId === employeeId);
    }

    return filtered.reduce((acc, curr) => {
      const totalMinutes = (curr.hours * 60) + curr.minutes;
      // If it's CREDIT, we ADD. If DEBIT, we SUBTRACT.
      return curr.type === RecordType.CREDIT ? acc + totalMinutes : acc - totalMinutes;
    }, 0);
  }
};

