interface DashboardProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, employees }) => {
  const [selectedEmpId, setSelectedEmpId] = useState<string>('');

  // 1. Filter records based on selection
  const filteredRecords = useMemo(() => {
    if (!selectedEmpId) return records;
    return records.filter(r => r.employeeId === selectedEmpId);
  }, [records, selectedEmpId]);

  // 2. Calculate stats based on filtered records
  const stats = useMemo(() => {
    let totalMinutes = 0;
    let positiveMins = 0;
    let negativeMins = 0;
    let neutralCount = 0;

    filteredRecords.forEach(r => {
      const mins = (r.hours * 60) + r.minutes;
      if (r.type === RecordType.CREDIT) {
        positiveMins += mins;
        totalMinutes += mins;
      } else if (r.type === RecordType.DEBIT) {
        negativeMins += mins;
        totalMinutes -= mins;
      } else {
        neutralCount++;
      }
    });

    const isPositive = totalMinutes >= 0;
    const absTotalMinutes = Math.abs(totalMinutes);

    return {
      balance: `${isPositive ? '' : '-'}${Math.floor(absTotalMinutes / 60)}:${(absTotalMinutes % 60).toString().padStart(2, '0')}`,
      positive: Math.floor(positiveMins / 60) + 'h ' + (positiveMins % 60) + 'm',
      negative: Math.floor(negativeMins / 60) + 'h ' + (negativeMins % 60) + 'm',
      neutralCount,
      // If filtering, show 1. If global, show active count.
      employeeCount: selectedEmpId ? 1 : employees.filter(e => e.active).length,
      isPositive
    };
  }, [filteredRecords, employees, selectedEmpId]);

  // 3. Prepare Chart Data based on filtered records
  const chartData = useMemo(() => {
    // If viewing individual, showing "Hours by Team" is less useful, 
    // but it still works to show their contribution. 
    // We could switch to "Hours by Date" for individuals in a future update if needed.
    const teamStats: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};

    filteredRecords.forEach(r => {
      // Find team either from the record snapshot (if we had it) or current employee data
      // Using employee list to get current team
      const emp = employees.find(e => e.id === r.employeeId);
      const team = emp ? emp.team : 'Desconhecido';

      const hours = r.hours + (r.minutes / 60);

      if (!teamStats[team]) {
        teamStats[team] = { name: team, horasPositivas: 0, horasNegativas: 0 };
      }

      if (r.type === RecordType.CREDIT) {
        teamStats[team].horasPositivas += hours;
      } else if (r.type === RecordType.DEBIT) {
        teamStats[team].horasNegativas += hours;
      }
    });

    return Object.values(teamStats);
  }, [filteredRecords, employees]);

  const typeData = [
    { name: 'Horas Positivas', value: parseFloat(stats.positive.split('h')[0]) },
    { name: 'Horas Negativas', value: parseFloat(stats.negative.split('h')[0]) }
  ];

  const COLORS = ['#10b981', '#ef4444'];

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header with Filter */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">
            {selectedEmpId ? 'Visão Individual' : 'Visão Geral'}
          </h2>
          <p className="text-sm text-slate-500">
            {selectedEmpId 
              ? `Analisando saldo de: ${employees.find(e => e.id === selectedEmpId)?.name}` 
              : 'Acompanhamento global do banco de horas'}
          </p>
        </div>

        <div className="relative min-w-[280px]">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Filter className="h-4 w-4 text-slate-400" />
          </div>
          <select
            value={selectedEmpId}
            onChange={(e) => setSelectedEmpId(e.target.value)}
            className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-indigo-500 focus:border-indigo-500 text-sm text-slate-700 shadow-sm"
          >
            <option value="">Todos os Colaboradores</option>
            {employees.map(emp => (
              <option key={emp.id} value={emp.id}>
                {emp.name}
              </option>
            ))}
          </select>
          {selectedEmpId && (
            <button 
              onClick={() => setSelectedEmpId('')}
              className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
              title="Limpar filtro"
            >
              <X size={14} />
            </button>
          )}
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-indigo-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Saldo {selectedEmpId ? 'Atual' : 'Global'}</p>
              <h3 className={`text-2xl font-bold mt-1 ${stats.isPositive ? 'text-emerald-600' : 'text-red-600'}`}>
                {stats.balance} h
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${stats.isPositive ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
              <Clock size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId ? 'Saldo líquido do colaborador' : 'Saldo líquido da empresa'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-blue-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Colaboradores</p>
              <h3 className="text-2xl font-bold mt-1 text-slate-800">{stats.employeeCount}</h3>
            </div>
            <div className="p-2 rounded-lg bg-blue-100 text-blue-600">
              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId ? 'Visualizando 1 colaborador' : 'Total ativos na plataforma'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-emerald-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Positivo</p>
              <h3 className="text-2xl font-bold mt-1 text-emerald-600">+{stats.positive}</h3>
            </div>
            <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600">
              <TrendingUp size={20} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-red-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Negativo</p>
              <h3 className="text-2xl font-bold mt-1 text-red-600">-{stats.negative}</h3>
            </div>
            <div className="p-2 rounded-lg bg-red-100 text-red-600">
              <TrendingDown size={20} />
            </div>
          </div>
        </div>
      </div>

      {stats.neutralCount > 0 && (
         <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 flex items-center text-slate-600">
            <Info className="w-5 h-5 mr-2" />
            <span className="text-sm">
              {selectedEmpId 
                ? `Este colaborador possui ${stats.neutralCount} registros informativos (Atestados, Exames, etc).`
                : `Existem ${stats.neutralCount} registros informativos totais que não impactam o banco de horas.`}
            </span>
         </div>
      )}

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">
            {selectedEmpId ? 'Balanço por Equipe (Colaborador)' : 'Horas por Equipe (Global)'}
          </h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              {chartData.length > 0 ? (
                <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{fill: '#f1f5f9'}}
                  />
                  <Legend />
                  <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#10b981" radius={[4, 4, 0, 0]} />
                  <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} />
                </BarChart>
              ) : (
                <div className="h-full flex items-center justify-center text-slate-400">
                  Nenhum dado para exibir neste período.
                </div>
              )}
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Proporção</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React from 'react';
import { FileText, Download, Users, Briefcase } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType } from '../types';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Reports: React.FC<ReportsProps> = ({ records, employees }) => {

  // --- Helper: Format minutes to HH:MM ---
  const formatTime = (totalMinutes: number) => {
    const hours = Math.floor(Math.abs(totalMinutes) / 60);
    const minutes = Math.abs(totalMinutes) % 60;
    const sign = totalMinutes < 0 ? '-' : '';
    return `${sign}${hours}h ${minutes.toString().padStart(2, '0')}m`;
  };

  // --- Helper: Calculate stats per employee ---
  const getConsolidatedData = () => {
    return employees.filter(e => e.active).map(emp => {
      const empRecords = records.filter(r => r.employeeId === emp.id);

      let creditMins = 0;
      let debitMins = 0;

      empRecords.forEach(r => {
        const mins = (r.hours * 60) + r.minutes;
        if (r.type === RecordType.CREDIT) {
          creditMins += mins;
        } else if (r.type === RecordType.DEBIT) {
          debitMins += mins;
        }
        // Neutral is ignored for balance
      });

      const netBalance = creditMins - debitMins;

      return {
        name: emp.name,
        team: emp.team,
        role: emp.role,
        positive: formatTime(creditMins),
        negative: formatTime(debitMins),
        balance: formatTime(netBalance),
        rawBalance: netBalance // for sorting or logic if needed
      };
    }).sort((a, b) => a.name.localeCompare(b.name)); // Alphabetical order
  };

  // --- DETAILED REPORTS (Logs) ---

  const generateDetailedPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString()}`, 14, 30);

    const tableData = records.map(r => [
      r.date,
      r.employeeName,
      r.occurrenceType || r.type,
      r.reason,
      `${r.hours}h ${r.minutes}m`
    ]);

    autoTable(doc, {
      head: [['Data', 'Colaborador', 'Tipo', 'Descrição', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] }, // Slate color
      columnStyles: { 3: { cellWidth: 60 } }
    });

    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(records.map(r => ({
      Data: r.date,
      Colaborador: r.employeeName,
      'Tipo de Ocorrência': r.occurrenceType,
      Categoria: r.type,
      'Descrição': r.reason,
      Horas: r.hours,
      Minutos: r.minutes
    })));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  // --- GENERAL REPORTS (Consolidated Balance) ---

  const generateGeneralPDF = () => {
    const doc = new jsPDF();
    const data = getConsolidatedData();

    doc.setFontSize(18);
    doc.text('Balanço Geral de Horas por Colaborador', 14, 22);
    doc.setFontSize(11);
    doc.text(`Posição consolidada em: ${new Date().toLocaleDateString()}`, 14, 30);

    const tableData = data.map(d => [
      d.name,
      d.team,
      d.positive,
      d.negative,
      d.balance
    ]);

    autoTable(doc, {
      head: [['Colaborador', 'Setor', 'Total Positivo', 'Total Negativo', 'Saldo Líquido']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 10, halign: 'center' },
      columnStyles: { 
        0: { halign: 'left' }, // Name
        4: { fontStyle: 'bold' } // Balance bold
      },
      headStyles: { fillColor: [79, 70, 229] }, // Indigo color
      didParseCell: (data) => {
        // Color the Balance column text
        if (data.section === 'body' && data.column.index === 4) {
          const rawValue = data.cell.raw as string;
          if (rawValue.startsWith('-')) {
            data.cell.styles.textColor = [220, 38, 38]; // Red
          } else {
            data.cell.styles.textColor = [22, 163, 74]; // Green
          }
        }
      }
    });

    doc.save('balanco-geral-consolidado.pdf');
  };

  const generateGeneralExcel = () => {
    const data = getConsolidatedData();
    const ws = XLSX.utils.json_to_sheet(data.map(d => ({
      Colaborador: d.name,
      Setor: d.team,
      'Total Positivo': d.positive,
      'Total Negativo': d.negative,
      'Saldo Líquido': d.balance
    })));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Saldos Consolidados");
    XLSX.writeFile(wb, "balanco-geral-consolidado.xlsx");
  };

  return (
    <div className="space-y-10 animate-fade-in">

      <div>
        <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
        <p className="text-slate-500">Gere relatórios para análise gerencial ou auditoria de logs.</p>
      </div>

      {/* SECTION 1: CONSOLIDATED SUMMARY */}
      <div className="bg-gradient-to-r from-indigo-50 to-white p-6 rounded-xl border border-indigo-100 shadow-sm">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
            <Users size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Balanço Geral (Consolidado)</h3>
            <p className="text-sm text-slate-500">Resumo de saldo final de horas por colaborador e setor.</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={generateGeneralPDF}
            className="flex items-center justify-center px-4 py-4 border border-transparent text-sm font-medium rounded-lg text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Resumo em PDF
          </button>

          <button 
             onClick={generateGeneralExcel}
             className="flex items-center justify-center px-4 py-4 border border-indigo-200 text-sm font-medium rounded-lg text-indigo-700 bg-white hover:bg-indigo-50 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Resumo em Excel
          </button>
        </div>
      </div>

      {/* SECTION 2: DETAILED LOGS */}
      <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 shadow-sm">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-slate-200 text-slate-700 rounded-lg">
            <FileText size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Extrato de Ocorrências (Detalhado)</h3>
            <p className="text-sm text-slate-500">Lista completa de todos os registros lançados, dia a dia.</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={generateDetailedPDF}
            className="flex items-center justify-center px-4 py-4 border border-slate-300 text-sm font-medium rounded-lg text-slate-700 bg-white hover:bg-slate-100 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Log Completo (PDF)
          </button>

          <button 
             onClick={generateDetailedExcel}
             className="flex items-center justify-center px-4 py-4 border border-slate-300 text-sm font-medium rounded-lg text-slate-700 bg-white hover:bg-green-50 hover:text-green-700 hover:border-green-200 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Log Completo (Excel)
          </button>
        </div>
      </div>

      {/* Preview Table (Kept strictly to Logs for quick check, or could be swapped) */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
           <h3 className="font-semibold text-slate-700">Últimos Lançamentos</h3>
           <span className="text-xs text-slate-400">Visualização de logs recentes</span>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Data</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Colaborador</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tipo</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Descrição</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tempo</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {records.slice(0, 5).map((record) => (
                <tr key={record.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{record.date}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">{record.employeeName}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        record.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' :
                        record.type === RecordType.DEBIT ? 'bg-red-100 text-red-800' :
                        'bg-slate-100 text-slate-600'
                     }`}>
                        {record.occurrenceType}
                     </span>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-500 max-w-xs truncate">{record.reason}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">{record.hours}h {record.minutes}m</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Reports;

payload.text:
Esta é uma mudança estrutural importante. Para atender ao seu pedido, precisamos dividir a solução em duas partes:

1.  **Backend (Google Sheets + Apps Script):** Vou fornecer o código que você deve colocar no Google Apps Script e a estrutura das colunas da planilha.
2.  **Frontend (React):** Vou atualizar o código da aplicação para incluir a Tela de Login e comunicar com esse App Script.

---

### Parte 1: Configuração do Google Sheets e Apps Script

**Passo 1: Crie uma nova Planilha Google**
Renomeie a planilha para "Sistema Banco de Horas". Crie duas abas (guias) na parte inferior:

**Aba 1: `Employees`** (Exatamente com estes cabeçalhos na linha 1)
`id` | `username` | `password` | `name` | `role` | `team` | `active` | `email`

*   *Preencha a primeira linha com um admin para você conseguir logar:*
    *   id: `1`
    *   username: `admin`
    *   password: `123`
    *   name: `Admin RH`
    *   role: `ADMIN`
    *   team: `RH`
    *   active: `TRUE`
    *   email: `admin@empresa.com`

**Aba 2: `Records`** (Exatamente com estes cabeçalhos na linha 1)
`id` | `employeeId` | `employeeName` | `date` | `hours` | `minutes` | `startTime` | `endTime` | `type` | `occurrenceType` | `reason` | `createdAt` | `createdBy`

**Passo 2: Configurar o Apps Script**
1.  Na planilha, vá em **Extensões** > **Apps Script**.
2.  Apague todo o código que estiver lá e cole o código abaixo:

```javascript
const SHEET_ID = ""; // <--- COLE O ID DA SUA PLANILHA AQUI (está na URL entre /d/ e /edit)

function doPost(e) {
  const ss = SpreadsheetApp.openById(SHEET_ID);
  const data = JSON.parse(e.postData.contents);
  const action = data.action;

  let result = {};

  try {
    if (action === "login") {
      result = handleLogin(ss, data.payload);
    } else if (action === "getEmployees") {
      result = getSheetData(ss, "Employees");
    } else if (action === "getRecords") {
      result = getSheetData(ss, "Records");
    } else if (action === "addRecord") {
      result = addRow(ss, "Records", data.payload);
    } else if (action === "addEmployee") {
      result = addRow(ss, "Employees", data.payload);
    } else if (action === "updateEmployee") {
      result = updateRow(ss, "Employees", data.payload);
    } else if (action === "deleteEmployee") {
      result = deleteRow(ss, "Employees", data.payload.id);
    }

    return ContentService.createTextOutput(JSON.stringify(result)).setMimeType(ContentService.MimeType.JSON);

  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({ error: err.toString() })).setMimeType(ContentService.MimeType.JSON);
  }
}

function handleLogin(ss, payload) {
  const sheet = ss.getSheetByName("Employees");
  const data = sheet.getDataRange().getValues();
  const headers = data.shift();

  // Find user by username
  const userRow = data.find(row => row[1] == payload.username && row[2] == payload.password); // 1=username, 2=password

  if (userRow) {
    // Map array to object based on headers
    const userObj = {};
    headers.forEach((header, index) => {
      // Don't send password back
      if (header !== 'password') userObj[header] = userRow[index];
    });
    // Ensure boolean is boolean
    userObj.active = String(userObj.active).toLowerCase() === 'true';
    return { success: true, user: userObj };
  }

  return { success: false, message: "Usuário ou senha inválidos" };
}

function getSheetData(ss, sheetName) {
  const sheet = ss.getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  const headers = data.shift();

  const formatted = data.map(row => {
    let obj = {};
    headers.forEach((header, index) => {
      obj[header] = row[index];
    });
    // Converts common types
    if (obj.active) obj.active = String(obj.active).toLowerCase() === 'true';
    return obj;
  });

  return formatted;
}

function addRow(ss, sheetName, payload) {
  const sheet = ss.getSheetByName(sheetName);
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];

  const row = headers.map(header => {
    return payload[header] || "";
  });

  sheet.appendRow(row);
  return { success: true };
}

function updateRow(ss, sheetName, payload) {
  const sheet = ss.getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  // Find row index by ID (column 0)
  // +1 because data is 0-indexed, but sheet rows are 1-indexed
  const rowIndex = data.findIndex(r => String(r[0]) === String(payload.id)) + 1; 

  if (rowIndex > 0) {
    const headers = data[0];
    const rowValues = headers.map(header => payload[header]);
    sheet.getRange(rowIndex, 1, 1, headers.length).setValues([rowValues]);
    return { success: true };
  }
  return { success: false, message: "ID not found" };
}

function deleteRow(ss, sheetName, id) {
  const sheet = ss.getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  const rowIndex = data.findIndex(r => String(r[0]) === String(id)) + 1;

  if (rowIndex > 1) { // Prevent deleting header
    sheet.deleteRow(rowIndex);
    return { success: true };
  }
  return { success: false };
}
