import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Download } from 'lucide-react';
import { Employee, Role } from '../types';
import { TEAMS, INITIAL_EMPLOYEES } from '../constants';
import { sheetService } from '../services/sheetService';
import { v4 as uuidv4 } from 'uuid';
import * as XLSX from 'xlsx';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
}

const EmployeeList: React.FC<EmployeeListProps> = ({ employees, refreshData }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newUsername, setNewUsername] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState(TEAMS[0]);

  const filteredEmployees = employees.filter(e => 
    e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    e.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewRole(Role.EMPLOYEE);
    setNewTeam(TEAMS[0]);
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewUsername(employee.username);
    setNewEmail(employee.email);
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: newUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      active: true
    };

    if (editingId) {
      await sheetService.updateEmployee(employeeData);
    } else {
      await sheetService.addEmployee(employeeData);
    }

    refreshData();
    setIsModalOpen(false);

    // Reset form
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setEditingId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      await sheetService.deleteEmployee(id);
      refreshData();
    }
  };

  const downloadInitialData = () => {
    const dataToExport = INITIAL_EMPLOYEES.map(e => ({
      id: e.id,
      username: e.username,
      password: e.password || '123', // Padrão para facilitar importação
      name: e.name,
      role: e.role,
      team: e.team,
      active: e.active,
      email: e.email
    }));

    const ws = XLSX.utils.json_to_sheet(dataToExport);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Colaboradores");
    XLSX.writeFile(wb, "dados_iniciais_colaboradores.xlsx");
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
        <div className="flex gap-2">
          <button 
            onClick={downloadInitialData}
            className="bg-white border border-indigo-200 text-indigo-700 px-4 py-2 rounded-lg hover:bg-indigo-50 flex items-center transition-colors shadow-sm"
          >
            <Download size={20} className="mr-2" />
            Baixar Dados Iniciais
          </button>
          <button 
            onClick={openAddModal}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
