const API_URL = "https://script.google.com/macros/s/AKfycbw9l9IopuyTW-8_irAN0xduF09WFKU5X7XGWJ5oYgAupGJFcH3zNx8rtUdm3_OPQS124Q/exec"; 

// --- OFFLINE/DEMO STATE ---
// We keep a local copy to support CRUD operations even if the API is offline or read-only.
let localEmployees: Employee[] = [...INITIAL_EMPLOYEES];
let localRecords: TimeRecord[] = [...INITIAL_RECORDS];

export const sheetService = {

  // --- AUTHENTICATION ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {
    // 1. Try Mock Admin
    if (username === 'admin' && password === '123') {
      return { 
          success: true, 
          user: { id: '1', username: 'admin', name: 'Admin Mock', role: 'ADMIN' as any, team: 'RH', active: true, email: 'admin@test.com' } 
      };
    }

    // 2. Try API
    if (API_URL) {
      try {
        const response = await fetch(API_URL, {
          method: 'POST',
          redirect: 'follow',
          headers: { 'Content-Type': 'text/plain' },
          body: JSON.stringify({ action: 'login', payload: { username, password } })
        });

        if (response.ok) {
          const data = await response.json();
          if (data.success) return data;
        }
      } catch (error) {
        console.warn("Login API failed, trying local users...");
      }
    }

    // 3. Fallback: Check local employees
    const localUser = localEmployees.find(u => u.username === username);
    // Simple password check simulation (accept any password for demo if not defined, or '123')
    if (localUser) {
       return { success: true, user: localUser };
    }

    return { success: false, message: "Usuário não encontrado ou erro de conexão." };
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    try {
      if (!API_URL) throw new Error("No API");
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'getEmployees' })
      });
      if (!response.ok) throw new Error("Network error");
      const data = await response.json();
      // If we got data, maybe update local cache? For now, we trust API if it works.
      return data;
    } catch (e) {
      console.warn("Using offline data for employees.");
      return localEmployees;
    }
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    // Update local state
    localEmployees.push(employee);

    if (!API_URL) return;
    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'addEmployee', payload: employee })
      });
    } catch (e) {
      console.warn("Failed to add employee (Offline Mode). Saved locally.");
    }
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    // Update local state
    const index = localEmployees.findIndex(e => e.id === updatedEmployee.id);
    if (index !== -1) {
      localEmployees[index] = updatedEmployee;
    }

    if (!API_URL) return;
    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'updateEmployee', payload: updatedEmployee })
      });
    } catch (e) {
      console.warn("Failed to update employee (Offline Mode). Saved locally.");
    }
  },

  deleteEmployee: async (id: string): Promise<void> => {
    // Update local state
    localEmployees = localEmployees.filter(e => e.id !== id);

    if (!API_URL) return;
    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'deleteEmployee', payload: { id } })
      });
    } catch (e) {
      console.warn("Failed to delete employee (Offline Mode). Saved locally.");
    }
  },

  // --- RECORDS ---
  getRecords: async (): Promise<TimeRecord[]> => {
    try {
      if (!API_URL) throw new Error("No API");
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'getRecords' })
      });
      if (!response.ok) throw new Error("Network error");
      return await response.json();
    } catch (e) {
      console.warn("Using offline data for records.");
      return localRecords;
    }
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    // Update local state
    localRecords.push(record);

    if (!API_URL) return;
    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        headers: { 'Content-Type': 'text/plain' },
        body: JSON.stringify({ action: 'addRecord', payload: record })
      });
    } catch (e) {
      console.warn("Failed to add record (Offline Mode). Saved locally.");
    }
  }
};

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TimeEntryForm from './components/TimeEntryForm';
import EmployeeList from './components/EmployeeList';
import Reports from './components/Reports';
import Login from './components/Login';
import { Role, Employee, TimeRecord } from './types';
import { sheetService } from './services/sheetService';
import { Menu } from 'lucide-react';

const App: React.FC = () => {
  // Application State
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [records, setRecords] = useState<TimeRecord[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Authentication State
  // TEMPORARY: Bypass login by setting a default admin user
  const [currentUser, setCurrentUser] = useState<Employee | null>({
    id: '1',
    username: 'admin.temp',
    name: 'Admin (Acesso Temporário)',
    role: Role.ADMIN,
    team: 'RH',
    active: true,
    email: 'admin@temp.com'
  });

  // Load Data function (Called after login and on updates)
  const fetchData = async () => {
    // Only fetch if logged in to save API calls
    if (currentUser) {
      const emps = await sheetService.getEmployees();
      const recs = await sheetService.getRecords();

      setEmployees(emps);
      setRecords(recs);
    }
  };

  useEffect(() => {
    if (currentUser) {
      fetchData();
    }
  }, [currentUser]);

  const handleLoginSuccess = (user: Employee) => {
    setCurrentUser(user);
    // Reset page to dashboard on login
    setCurrentPage('dashboard');
  };

  const handleLogout = () => {
    // Since login is disabled, logout just reloads to reset (or could set to null if login was working)
    // setCurrentUser(null);
    if (confirm("O login está temporariamente desativado. Recarregar a página?")) {
      window.location.reload();
    }
  };

  // If not logged in, show Login Screen
  if (!currentUser) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  // Render Page Content based on route
  const renderContent = () => {
    switch (currentPage) {
      case 'dashboard':
        return <Dashboard records={records} employees={employees} />;
      case 'form':
        return <TimeEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} />;
      case 'employees':
        return currentUser.role === Role.ADMIN ? <EmployeeList employees={employees} refreshData={fetchData} /> : <div className="text-center p-10 text-slate-500">Acesso negado. Esta área é restrita ao RH.</div>;
      case 'reports':
        return currentUser.role === Role.ADMIN ? <Reports records={records} employees={employees} /> : <div className="text-center p-10 text-slate-500">Acesso negado. Esta área é restrita ao RH.</div>;
      default:
        return <Dashboard records={records} employees={employees} />;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-40 bg-slate-900 text-white p-4 flex justify-between items-center shadow-md">
         <span className="font-bold">Banco de Horas</span>
         <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
           <Menu size={24} />
         </button>
      </div>

      <Sidebar 
        currentRole={currentUser.role} 
        currentPage={currentPage} 
        setPage={(page) => {
          setCurrentPage(page);
          setIsSidebarOpen(false);
        }}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full pt-16 md:pt-0">
        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend 
} from 'recharts';
import { Clock, Users, TrendingUp, TrendingDown, Info, Filter, X } from 'lucide-react';
import { TimeRecord, Employee, RecordType } from '../types';

interface DashboardProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, employees }) => {
  const [selectedEmpId, setSelectedEmpId] = useState<string>('');

  // 1. Filter records based on selection
  const filteredRecords = useMemo(() => {
    if (!selectedEmpId) return records;
    return records.filter(r => r.employeeId === selectedEmpId);
  }, [records, selectedEmpId]);

  // 2. Calculate stats based on filtered records
  const stats = useMemo(() => {
    let totalMinutes = 0;
    let positiveMins = 0;
    let negativeMins = 0;
    let neutralCount = 0;

    filteredRecords.forEach(r => {
      const mins = (r.hours * 60) + r.minutes;
      if (r.type === RecordType.CREDIT) {
        positiveMins += mins;
        totalMinutes += mins;
      } else if (r.type === RecordType.DEBIT) {
        negativeMins += mins;
        totalMinutes -= mins;
      } else {
        neutralCount++;
      }
    });

    const isPositive = totalMinutes >= 0;
    const absTotalMinutes = Math.abs(totalMinutes);

    return {
      balance: `${isPositive ? '' : '-'}${Math.floor(absTotalMinutes / 60)}:${(absTotalMinutes % 60).toString().padStart(2, '0')}`,
      positive: Math.floor(positiveMins / 60) + 'h ' + (positiveMins % 60) + 'm',
      negative: Math.floor(negativeMins / 60) + 'h ' + (negativeMins % 60) + 'm',
      neutralCount,
      // If filtering, show 1. If global, show active count.
      employeeCount: selectedEmpId ? 1 : employees.filter(e => e.active).length,
      isPositive
    };
  }, [filteredRecords, employees, selectedEmpId]);

  // 3. Prepare Chart Data based on filtered records
  const chartData = useMemo(() => {
    // If viewing individual, showing "Hours by Team" is less useful, 
    // but it still works to show their contribution. 
    // We could switch to "Hours by Date" for individuals in a future update if needed.
    const teamStats: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};

    filteredRecords.forEach(r => {
      // Find team either from the record snapshot (if we had it) or current employee data
      // Using employee list to get current team
      const emp = employees.find(e => e.id === r.employeeId);
      const team = emp ? emp.team : 'Desconhecido';

      const hours = r.hours + (r.minutes / 60);

      if (!teamStats[team]) {
        teamStats[team] = { name: team, horasPositivas: 0, horasNegativas: 0 };
      }

      if (r.type === RecordType.CREDIT) {
        teamStats[team].horasPositivas += hours;
      } else if (r.type === RecordType.DEBIT) {
        teamStats[team].horasNegativas += hours;
      }
    });

    return Object.values(teamStats);
  }, [filteredRecords, employees]);

  const typeData = [
    { name: 'Horas Positivas', value: parseFloat(stats.positive.split('h')[0]) },
    { name: 'Horas Negativas', value: parseFloat(stats.negative.split('h')[0]) }
  ];

  const COLORS = ['#10b981', '#ef4444'];

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Header with Filter */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">
            {selectedEmpId ? 'Visão Individual' : 'Visão Geral'}
          </h2>
          <p className="text-sm text-slate-500">
            {selectedEmpId 
              ? `Analisando saldo de: ${employees.find(e => e.id === selectedEmpId)?.name}` 
              : 'Acompanhamento global do banco de horas'}
          </p>
        </div>

        <div className="relative min-w-[280px]">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Filter className="h-4 w-4 text-slate-400" />
          </div>
          <select
            value={selectedEmpId}
            onChange={(e) => setSelectedEmpId(e.target.value)}
            className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-indigo-500 focus:border-indigo-500 text-sm text-slate-700 shadow-sm"
          >
            <option value="">Todos os Colaboradores</option>
            {employees.map(emp => (
              <option key={emp.id} value={emp.id}>
                {emp.name}
              </option>
            ))}
          </select>
          {selectedEmpId && (
            <button 
              onClick={() => setSelectedEmpId('')}
              className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
              title="Limpar filtro"
            >
              <X size={14} />
            </button>
          )}
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-indigo-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Saldo {selectedEmpId ? 'Atual' : 'Global'}</p>
              <h3 className={`text-2xl font-bold mt-1 ${stats.isPositive ? 'text-emerald-600' : 'text-red-600'}`}>
                {stats.balance} h
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${stats.isPositive ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
              <Clock size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId ? 'Saldo líquido do colaborador' : 'Saldo líquido da empresa'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-blue-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Colaboradores</p>
              <h3 className="text-2xl font-bold mt-1 text-slate-800">{stats.employeeCount}</h3>
            </div>
            <div className="p-2 rounded-lg bg-blue-100 text-blue-600">
              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId ? 'Visualizando 1 colaborador' : 'Total ativos na plataforma'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-emerald-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Positivo</p>
              <h3 className="text-2xl font-bold mt-1 text-emerald-600">+{stats.positive}</h3>
            </div>
            <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600">
              <TrendingUp size={20} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-red-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Negativo</p>
              <h3 className="text-2xl font-bold mt-1 text-red-600">-{stats.negative}</h3>
            </div>
            <div className="p-2 rounded-lg bg-red-100 text-red-600">
              <TrendingDown size={20} />
            </div>
          </div>
        </div>
      </div>

      {stats.neutralCount > 0 && (
         <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 flex items-center text-slate-600">
            <Info className="w-5 h-5 mr-2" />
            <span className="text-sm">
              {selectedEmpId 
                ? `Este colaborador possui ${stats.neutralCount} registros informativos (Atestados, Exames, etc).`
                : `Existem ${stats.neutralCount} registros informativos totais que não impactam o banco de horas.`}
            </span>
         </div>
      )}

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">
            {selectedEmpId ? 'Balanço por Equipe (Colaborador)' : 'Horas por Equipe (Global)'}
          </h3>
          <div className="h-80 w-full">
            {chartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="name" tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{fill: '#f1f5f9'}}
                  />
                  <Legend />
                  <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#10b981" radius={[4, 4, 0, 0]} />
                  <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full w-full flex items-center justify-center text-slate-400">
                Nenhum dado para exibir neste período.
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Proporção</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>
    </div>
  );
};

