              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeList;

import React from 'react';
import { FileText, Download, Users, Briefcase } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType } from '../types';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Reports: React.FC<ReportsProps> = ({ records, employees }) => {

  // --- Helper: Format minutes to HH:MM ---
  const formatTime = (totalMinutes: number) => {
    const hours = Math.floor(Math.abs(totalMinutes) / 60);
    const minutes = Math.abs(totalMinutes) % 60;
    const sign = totalMinutes < 0 ? '-' : '';
    return `${sign}${hours}h ${minutes.toString().padStart(2, '0')}m`;
  };

  // --- Helper: Get Leader Name ---
  const getLeaderName = (leaderId: string) => {
    const leader = employees.find(e => e.id === leaderId);
    return leader ? leader.name : 'Desconhecido';
  };

  // --- Helper: Calculate stats per employee ---
  const getConsolidatedData = () => {
    return employees.filter(e => e.active).map(emp => {
      const empRecords = records.filter(r => r.employeeId === emp.id);

      let creditMins = 0;
      let debitMins = 0;

      empRecords.forEach(r => {
        const mins = (r.hours * 60) + r.minutes;
        if (r.type === RecordType.CREDIT) {
          creditMins += mins;
        } else if (r.type === RecordType.DEBIT) {
          debitMins += mins;
        }
        // Neutral is ignored for balance
      });

      const netBalance = creditMins - debitMins;

      return {
        name: emp.name,
        team: emp.team,
        role: emp.role,
        positive: formatTime(creditMins),
        negative: formatTime(debitMins),
        balance: formatTime(netBalance),
        rawBalance: netBalance // for sorting or logic if needed
      };
    }).sort((a, b) => a.name.localeCompare(b.name)); // Alphabetical order
  };

  // --- DETAILED REPORTS (Logs) ---

  const generateDetailedPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString()}`, 14, 30);

    const tableData = records.map(r => [
      r.date,
      r.employeeName,
      getLeaderName(r.createdBy),
      r.occurrenceType || r.type,
      r.reason,
      `${r.hours}h ${r.minutes}m`
    ]);

    autoTable(doc, {
      head: [['Data', 'Colaborador', 'Líder', 'Tipo', 'Descrição', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] }, // Slate color
      columnStyles: { 4: { cellWidth: 50 } } // Adjusted width for Description
    });

    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(records.map(r => ({
      Data: r.date,
      Colaborador: r.employeeName,
      Líder: getLeaderName(r.createdBy),
      'Tipo de Ocorrência': r.occurrenceType,
      Categoria: r.type,
      'Descrição': r.reason,
      Horas: r.hours,
      Minutos: r.minutes
    })));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  // --- GENERAL REPORTS (Consolidated Balance) ---

  const generateGeneralPDF = () => {
    const doc = new jsPDF();
    const data = getConsolidatedData();

    doc.setFontSize(18);
    doc.text('Balanço Geral de Horas por Colaborador', 14, 22);
    doc.setFontSize(11);
    doc.text(`Posição consolidada em: ${new Date().toLocaleDateString()}`, 14, 30);

    const tableData = data.map(d => [
      d.name,
      d.team,
      d.positive,
      d.negative,
      d.balance
    ]);

    autoTable(doc, {
      head: [['Colaborador', 'Setor', 'Total Positivo', 'Total Negativo', 'Saldo Líquido']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 10, halign: 'center' },
      columnStyles: { 
        0: { halign: 'left' }, // Name
        4: { fontStyle: 'bold' } // Balance bold
      },
      headStyles: { fillColor: [79, 70, 229] }, // Indigo color
      didParseCell: (data) => {
        // Color the Balance column text
        if (data.section === 'body' && data.column.index === 4) {
          const rawValue = data.cell.raw as string;
          if (rawValue.startsWith('-')) {
            data.cell.styles.textColor = [220, 38, 38]; // Red
          } else {
            data.cell.styles.textColor = [22, 163, 74]; // Green
          }
        }
      }
    });

    doc.save('balanco-geral-consolidado.pdf');
  };

  const generateGeneralExcel = () => {
    const data = getConsolidatedData();
    const ws = XLSX.utils.json_to_sheet(data.map(d => ({
      Colaborador: d.name,
      Setor: d.team,
      'Total Positivo': d.positive,
      'Total Negativo': d.negative,
      'Saldo Líquido': d.balance
    })));

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Saldos Consolidados");
    XLSX.writeFile(wb, "balanco-geral-consolidado.xlsx");
  };

  return (
    <div className="space-y-10 animate-fade-in">

      <div>
        <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
        <p className="text-slate-500">Gere relatórios para análise gerencial ou auditoria de logs.</p>
      </div>

      {/* SECTION 1: CONSOLIDATED SUMMARY */}
      <div className="bg-gradient-to-r from-indigo-50 to-white p-6 rounded-xl border border-indigo-100 shadow-sm">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
            <Users size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Balanço Geral (Consolidado)</h3>
            <p className="text-sm text-slate-500">Resumo de saldo final de horas por colaborador e setor.</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={generateGeneralPDF}
            className="flex items-center justify-center px-4 py-4 border border-transparent text-sm font-medium rounded-lg text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Resumo em PDF
          </button>

          <button 
             onClick={generateGeneralExcel}
             className="flex items-center justify-center px-4 py-4 border border-indigo-200 text-sm font-medium rounded-lg text-indigo-700 bg-white hover:bg-indigo-50 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Resumo em Excel
          </button>
        </div>
      </div>

      {/* SECTION 2: DETAILED LOGS */}
      <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 shadow-sm">
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-slate-200 text-slate-700 rounded-lg">
            <FileText size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Extrato de Ocorrências (Detalhado)</h3>
            <p className="text-sm text-slate-500">Lista completa de todos os registros lançados, dia a dia.</p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={generateDetailedPDF}
            className="flex items-center justify-center px-4 py-4 border border-slate-300 text-sm font-medium rounded-lg text-slate-700 bg-white hover:bg-slate-100 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Log Completo (PDF)
          </button>

          <button 
             onClick={generateDetailedExcel}
             className="flex items-center justify-center px-4 py-4 border border-slate-300 text-sm font-medium rounded-lg text-slate-700 bg-white hover:bg-green-50 hover:text-green-700 hover:border-green-200 shadow-sm transition-all"
          >
            <Download className="mr-2" size={18} />
            Baixar Log Completo (Excel)
          </button>
        </div>
      </div>

      {/* Preview Table (Kept strictly to Logs for quick check, or could be swapped) */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
           <h3 className="font-semibold text-slate-700">Últimos Lançamentos</h3>
           <span className="text-xs text-slate-400">Visualização de logs recentes</span>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Data</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Colaborador</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Líder</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tipo</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Descrição</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tempo</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {records.slice(0, 5).map((record) => (
                <tr key={record.id}>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{record.date}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">{record.employeeName}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-indigo-600 font-medium">{getLeaderName(record.createdBy)}</td>
                  <td className="px-6 py-4 whitespace-nowrap">
                     <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                        record.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' :
                        record.type === RecordType.DEBIT ? 'bg-red-100 text-red-800' :
                        'bg-slate-100 text-slate-600'
                     }`}>
                        {record.occurrenceType}
                     </span>
                  </td>
                  <td className="px-6 py-4 text-sm text-slate-500 max-w-xs truncate">{record.reason}</td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">{record.hours}h {record.minutes}m</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Reports;

import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Lock } from 'lucide-react';
import { Employee, Role } from '../types';
import { TEAMS } from '../constants';
import { sheetService } from '../services/sheetService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
}

const EmployeeList: React.FC<EmployeeListProps> = ({ employees, refreshData }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Optimistic UI state
  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newUsername, setNewUsername] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState(TEAMS[0]);

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewPassword(''); // Reset password
    setNewRole(Role.EMPLOYEE);
    setNewTeam(TEAMS[0]);
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewUsername(employee.username);
    setNewEmail(employee.email);
    setNewPassword(''); // Don't show existing password, allow overwrite
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoadingAction('save');

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: newUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      active: true,
      // Only send password if it was typed (for edits) or required (for new)
      password: newPassword || undefined 
    };

    if (editingId) {
      await sheetService.updateEmployee(employeeData);
    } else {
      await sheetService.addEmployee(employeeData);
    }

    refreshData();
    setIsModalOpen(false);
    setLoadingAction(null);

    // Reset form
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewPassword('');
    setEditingId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await sheetService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir. O colaborador não foi encontrado na planilha ou houve um erro de conexão.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
        <div className="flex gap-2">
          <button 
            onClick={openAddModal}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
