import { Employee, TimeRecord } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// ============================================================================
// CONFIGURATION
// ============================================================================
// 1. Deploy your Google Apps Script as a Web App.
// 2. Set 'Who has access' to 'Anyone'.
// 3. Paste the Web App URL below inside the quotes.
// EXEMPLE: "https://script.google.com/macros/s/AKfycbw.../exec"
const API_URL = "https://script.google.com/macros/s/AKfycbywd2sexbSphAVX516PpWqmqlD4Z2WY9VBlzDfGkdAP9wnmIortIUoGwp-0dEZSLbEf3w/exec"; 

// --- OFFLINE/DEMO STATE ---
// Used only if API_URL is empty or fails
let localEmployees: Employee[] = [...INITIAL_EMPLOYEES];
let localRecords: TimeRecord[] = [...INITIAL_RECORDS];

export const sheetService = {

  // --- AUTHENTICATION ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {
    // 1. Try Mock Admin for instant access if needed
    if (username === 'admin' && password === '123') {
      return { 
          success: true, 
          user: { id: '1', username: 'admin', name: 'Admin Mock', role: 'ADMIN' as any, team: 'RH', active: true, email: 'admin@test.com' } 
      };
    }

    // 2. Try API (Server-side validation)
    if (API_URL) {
      try {
        const response = await fetch(API_URL, {
          method: 'POST',
          redirect: 'follow',
          cache: 'no-store',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ action: 'login', payload: { username, password } })
        });

        if (response.ok) {
           const data = await response.json();
           if (data.success && data.user) {
             return { success: true, user: data.user };
           } else if (data.success === false) {
             // Server returned explicit failure
             return { success: false, message: data.message || "Credenciais inválidas." };
           }
        }
      } catch (error) {
        console.warn("Login API check failed, attempting fallback to list check.");
      }
    }

    // 3. Fallback: Check local/fetched employees list (Less secure, but works if API endpoint for 'login' isn't implemented in GAS yet)
    try {
        const employees = await sheetService.getEmployees();
        const foundUser = employees.find(e => e.username === username);

        // Note: In a real production environment, checking password on client side is not recommended.
        // This is a fallback if the specific 'login' action isn't on the server yet.
        if (foundUser) {
           // We assume if the user exists in the fallback mode, we let them in IF no password was returned (legacy) 
           // OR if we match the password field if it exists in the data.
           if (foundUser.password && foundUser.password !== password) {
               return { success: false, message: "Senha incorreta." };
           }
           return { success: true, user: foundUser };
        }
    } catch(e) {
        console.error("Fallback login failed", e);
    }

    return { success: false, message: "Usuário não encontrado." };
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    if (!API_URL) {
      console.warn("API_URL not set. Using local mock data.");
      return localEmployees;
    }

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store', // Prevent caching
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getEmployees', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();
      // Ensure we received an array
      if (Array.isArray(data)) {
        return data;
      } else {
        return localEmployees; // Fallback if format is wrong
      }
    } catch (e) {
      console.error("Fetch employees failed:", e);
      return localEmployees;
    }
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    // Optimistic Update (Local)
    localEmployees.push(employee);

    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'addEmployee', payload: employee })
      });
    } catch (e) {
      console.error("Failed to add employee to Sheet:", e);
    }
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    // Optimistic Update (Local)
    const index = localEmployees.findIndex(e => e.id === updatedEmployee.id);
    if (index !== -1) {
      localEmployees[index] = updatedEmployee;
    }

    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'updateEmployee', payload: updatedEmployee })
      });
    } catch (e) {
      console.error("Failed to update employee on Sheet:", e);
    }
  },

  deleteEmployee: async (id: string): Promise<boolean> => {
    // Optimistic Update (Local)
    localEmployees = localEmployees.filter(e => e.id !== id);

    if (!API_URL) return true;

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'deleteEmployee', payload: { id: String(id).trim() } })
      });

      if (!response.ok) return false;

      // CRITICAL: Check the logic response from GAS, not just HTTP 200
      const result = await response.json();
      if (result && result.success === false) {
          console.error("GAS Error:", result.error);
          return false;
      }

      return true;
    } catch (e) {
      console.error("Failed to delete employee on Sheet:", e);
      return false;
    }
  },

  // --- RECORDS (Placeholder until Sheet is created) ---
  getRecords: async (): Promise<TimeRecord[]> => {
    // Logic similar to employees will be added here once Records sheet is ready
    if (!API_URL) return localRecords;

    // For now, return empty or local, as we focused on Employees first
    return localRecords;
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    localRecords.push(record);
    // Placeholder for API call
  }
};

import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Lock } from 'lucide-react';
import { Employee, Role } from '../types';
import { TEAMS } from '../constants';
import { sheetService } from '../services/sheetService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
}

const EmployeeList: React.FC<EmployeeListProps> = ({ employees, refreshData }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Optimistic UI state
  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newUsername, setNewUsername] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState(TEAMS[0]);

  // Helper to determine if credentials are required
  const isAccessControlEnabled = newRole === Role.ADMIN || newRole === Role.LEADER;

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewPassword(''); // Reset password
    setNewRole(Role.EMPLOYEE);
    setNewTeam(TEAMS[0]);
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewUsername(employee.username);
    setNewEmail(employee.email);
    setNewPassword(''); // Don't show existing password, allow overwrite
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoadingAction('save');

    // If regular employee, auto-generate username from email just to satisfy data structure, 
    // but they won't have a password or login ability.
    const finalUsername = isAccessControlEnabled ? newUsername : newEmail.split('@')[0];

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: finalUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      active: true,
      // Only send password if it is an Admin/Leader AND it was typed/required
      password: (isAccessControlEnabled && newPassword) ? newPassword : undefined 
    };

    if (editingId) {
      await sheetService.updateEmployee(employeeData);
    } else {
      await sheetService.addEmployee(employeeData);
    }

    refreshData();
    setIsModalOpen(false);
    setLoadingAction(null);

    // Reset form
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewPassword('');
    setEditingId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await sheetService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir. O colaborador não foi encontrado na planilha ou houve um erro de conexão.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
