import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Lock } from 'lucide-react';
import { Employee, Role } from '../types';
import { TEAMS } from '../constants';
import { sheetService } from '../services/sheetService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
}

const EmployeeList: React.FC<EmployeeListProps> = ({ employees, refreshData }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Optimistic UI state
  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  // Form State
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newUsername, setNewUsername] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newPassword, setNewPassword] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState(TEAMS[0]);

  // Helper to determine if credentials are required
  const isAccessControlEnabled = newRole === Role.ADMIN || newRole === Role.LEADER;

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewPassword(''); // Reset password
    setNewRole(Role.EMPLOYEE);
    setNewTeam(TEAMS[0]);
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewUsername(employee.username);
    setNewEmail(employee.email);
    setNewPassword(''); // Don't show existing password, allow overwrite
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoadingAction('save');

    // If regular employee, auto-generate username from email just to satisfy data structure, 
    // but they won't have a password or login ability.
    const finalUsername = isAccessControlEnabled ? newUsername : newEmail.split('@')[0];

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: finalUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      active: true,
      // Only send password if it is an Admin/Leader AND it was typed/required
      password: (isAccessControlEnabled && newPassword) ? newPassword : undefined 
    };

    if (editingId) {
      await sheetService.updateEmployee(employeeData);
    } else {
      await sheetService.addEmployee(employeeData);
    }

    refreshData();
    setIsModalOpen(false);
    setLoadingAction(null);

    // Reset form
    setNewName('');
    setNewUsername('');
    setNewEmail('');
    setNewPassword('');
    setEditingId(null);
  };

  const handleDelete = async (id: string) => {
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await sheetService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir. O colaborador não foi encontrado na planilha ou houve um erro de conexão.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
        <div className="flex gap-2">
          <button 
            onClick={openAddModal}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* List */}
      <div className="bg-white shadow-sm border border-slate-200 rounded-xl overflow-hidden">
        <ul className="divide-y divide-slate-200">
          {filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 hover:bg-slate-50 transition-colors animate-fade-in">
              <div className="flex items-center justify-between">
                <div className="flex items-center min-w-0 gap-4">
                  <div className="h-10 w-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500">
                    <User size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-slate-900 truncate">{employee.name}</p>
                    <p className="text-sm text-slate-500 truncate">{employee.email}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4">
                  <div className="hidden md:flex flex-col items-end">
                    <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium capitalize ${
                      employee.role === Role.ADMIN ? 'bg-purple-100 text-purple-800' :
                      employee.role === Role.LEADER ? 'bg-blue-100 text-blue-800' :
                      'bg-slate-100 text-slate-800'
                    }`}>
                      {employee.role === Role.ADMIN ? <Shield size={10} className="mr-1"/> : <Briefcase size={10} className="mr-1"/>}
                      {employee.role === Role.ADMIN ? 'Administrador' : employee.role === Role.LEADER ? 'Líder' : 'Colaborador'}
                    </span>
                    <span className="text-xs text-slate-400 mt-1">{employee.team}</span>
                  </div>

                  <div className="flex items-center gap-2">
                    <button 
                      onClick={() => openEditModal(employee)}
                      className="text-slate-400 hover:text-indigo-600 transition-colors p-2 rounded-full hover:bg-indigo-50"
                      title="Editar"
                      disabled={loadingAction === employee.id}
                    >
                      <Edit size={18} />
                    </button>
                    <button 
                      onClick={() => handleDelete(employee.id)}
                      className="text-slate-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50"
                      title="Excluir"
                      disabled={loadingAction === employee.id}
                    >
                      {loadingAction === employee.id ? (
                        <Loader2 size={18} className="animate-spin text-red-600" />
                      ) : (
                        <Trash2 size={18} />
                      )}
                    </button>
                  </div>
                </div>
              </div>
            </li>
          ))}
          {filteredEmployees.length === 0 && (
            <li className="p-8 text-center text-slate-500">
              {employees.length > 0 ? 'Nenhum colaborador encontrado com este filtro.' : 'Nenhum colaborador cadastrado.'}
            </li>
          )}
        </ul>
      </div>

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="mb-4">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Editar Colaborador' : 'Adicionar Colaborador'}
              </h3>
              <p className="text-xs text-slate-500">Preencha os dados de perfil.</p>
            </div>

            <form onSubmit={handleSaveEmployee} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
              <div>
                <label className="block text-sm font-medium text-slate-700">Nome Completo</label>
                <input required type="text" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newName} onChange={e => setNewName(e.target.value)} />
              </div>

              <div className="grid grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Equipe</label>
                    <select className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newTeam} onChange={e => setNewTeam(e.target.value)}>
                      {TEAMS.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Permissão</label>
                    <select className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newRole} onChange={e => setNewRole(e.target.value as Role)}>
                      <option value={Role.EMPLOYEE}>Colaborador</option>
                      <option value={Role.LEADER}>Líder</option>
                      <option value={Role.ADMIN}>Administrador</option>
                    </select>
                 </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700">Email</label>
                <input required type="email" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newEmail} onChange={e => setNewEmail(e.target.value)} />
              </div>

              {/* Access Control Section - Only visible for Leaders and Admins */}
              {isAccessControlEnabled && (
                <div className="border-t border-slate-100 pt-4 mt-2 animate-fade-in">
                   <h4 className="text-sm font-bold text-slate-700 mb-3 flex items-center">
                      <Lock size={14} className="mr-1" />
                      Credenciais de Acesso
                   </h4>
                   <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <div>
                          <label className="block text-sm font-medium text-slate-700">Usuário de Login</label>
                          <input 
                            required 
                            type="text" 
                            className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                            value={newUsername} 
                            onChange={e => setNewUsername(e.target.value)} 
                          />
                      </div>
                      <div>
                          <label className="block text-sm font-medium text-slate-700">
                            {editingId ? 'Nova Senha (Opcional)' : 'Senha de Acesso'}
                          </label>
                          <input 
                             type="text" 
                             placeholder={editingId ? "Manter atual" : "Digite a senha"}
                             required={!editingId} // Required only when creating new Admin/Leader
                             className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                             value={newPassword} 
                             onChange={e => setNewPassword(e.target.value)} 
                          />
                          {editingId && <p className="text-[10px] text-slate-400 mt-1">Deixe em branco para não alterar.</p>}
                      </div>
                   </div>
                </div>
              )}

              <div className="flex justify-end gap-3 mt-6 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                <button type="submit" disabled={loadingAction === 'save'} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center">
                  {loadingAction === 'save' && <Loader2 size={16} className="animate-spin mr-2" />}
                  {editingId ? 'Salvar Alterações' : 'Criar Colaborador'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeList;

payload.text:
Para que a funcionalidade de Login e o cadastro de senhas funcionem, você precisa fazer duas coisas: adicionar uma coluna na sua planilha e atualizar o código do **Google Apps Script**.

Aqui está o passo a passo exato:

### 1. Na sua Planilha Google

Você precisa garantir que a aba de colaboradores tenha uma coluna para salvar a senha.

1.  Abra sua planilha.
2.  Vá na aba onde ficam os colaboradores (geralmente chamada de `Employees` ou `Colaboradores`).
3.  Na **primeira linha** (cabeçalho), adicione uma nova coluna chamada exatamente: **`password`**.
    *   *Sugestão:* Coloque ela após o email ou a role.
    *   A ordem das colunas no cabeçalho deve ficar algo como:
        `id | username | name | email | role | team | active | password`

### 2. No Google Apps Script (Extensões > Apps Script)

O código antigo do seu script não sabe ler nem salvar essa nova coluna `password`. Você precisa substituir o código do arquivo `.gs` pelo código abaixo.

Este script atualizado inclui a função `login` (que verifica a senha) e salva a senha quando você cria/edita um administrador ou líder.

**Copie e cole este código no seu Google Apps Script:**

```javascript
// NOME DAS ABAS (Devem ser iguais aos da sua planilha)
const SHEET_EMPLOYEES = "Employees"; 
const SHEET_RECORDS = "Records";

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const data = JSON.parse(e.postData.contents);
    const action = data.action;
    const payload = data.payload;

    let result = {};

    if (action === 'login') {
      result = handleLogin(payload);
    } else if (action === 'getEmployees') {
      result = getData(SHEET_EMPLOYEES);
    } else if (action === 'addEmployee') {
      result = addRow(SHEET_EMPLOYEES, payload);
    } else if (action === 'updateEmployee') {
      result = updateRow(SHEET_EMPLOYEES, payload);
    } else if (action === 'deleteEmployee') {
      result = deleteRow(SHEET_EMPLOYEES, payload.id);
    } else if (action === 'getRecords') {
      result = getData(SHEET_RECORDS);
    } else if (action === 'addRecord') {
      result = addRow(SHEET_RECORDS, payload);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (e) {
    return ContentService.createTextOutput(JSON.stringify({ success: false, error: e.toString() }))
      .setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- FUNÇÃO DE LOGIN ---
function handleLogin(payload) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_EMPLOYEES);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];

  const userIndex = headers.indexOf('username');
  const passIndex = headers.indexOf('password');

  // Mapeia colunas para objeto
  const employees = data.slice(1).map(row => {
    let emp = {};
    headers.forEach((header, i) => emp[header] = row[i]);
    return emp;
  });

  // Busca usuário
  const user = employees.find(e => e.username == payload.username);

  if (!user) {
    return { success: false, message: "Usuário não encontrado." };
  }

  // Verifica se está ativo
  if (String(user.active).toLowerCase() === 'false') {
    return { success: false, message: "Acesso desativado." };
  }

  // Verifica Senha
  // Nota: Se a célula de senha estiver vazia na planilha, permite login sem senha (legado) ou bloqueia.
  // Aqui assumimos que deve bater exatamente.
  if (String(user.password) === String(payload.password)) {
    // Removemos a senha antes de devolver para o front-end por segurança
    delete user.password;
    return { success: true, user: user };
  } else {
    return { success: false, message: "Senha incorreta." };
  }
}

// --- GENERIC CRUD ---

function getData(sheetName) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
  if (!sheet) return []; // Retorna vazio se aba não existir

  const data = sheet.getDataRange().getValues();
  const headers = data[0];

  return data.slice(1).map(row => {
    let obj = {};
    headers.forEach((header, index) => {
      obj[header] = row[index];
    });
    return obj;
  });
}

function addRow(sheetName, payload) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
  if (!sheet) return { success: false, error: "Sheet not found" };

  const headers = sheet.getDataRange().getValues()[0];
  const newRow = headers.map(header => {
    // Se o payload tem o dado, usa. Se não, string vazia.
    // Converte booleans para string para evitar erro
    return payload[header] !== undefined ? payload[header] : "";
  });

  sheet.appendRow(newRow);
  return { success: true };
}

function updateRow(sheetName, payload) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIndex = headers.indexOf('id');

  // Encontra a linha (lembrando que data inclui header, então rowIndex + 1 é a linha da planilha)
  // Mas como estamos iterando data, o índice i do loop corresponde à linha i+1
  for (let i = 1; i < data.length; i++) {
    if (String(data[i][idIndex]) === String(payload.id)) {

      const updatedRow = headers.map((header, colIndex) => {
        // Lógica Especial para Senha:
        // Se for update e o payload não trouxer senha (undefined ou vazia), MANTÉM a antiga
        if (header === 'password') {
           if (payload.password && payload.password !== "") {
             return payload.password;
           } else {
             return data[i][colIndex]; // Mantém valor antigo
           }
        }
        // Para os outros campos, atualiza se existir no payload
        return payload[header] !== undefined ? payload[header] : data[i][colIndex];
      });

      sheet.getRange(i + 1, 1, 1, updatedRow.length).setValues([updatedRow]);
      return { success: true };
    }
  }
  return { success: false, error: "ID not found" };
}

function deleteRow(sheetName, id) {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(sheetName);
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const idIndex = headers.indexOf('id');

  for (let i = 1; i < data.length; i++) {
    if (String(data[i][idIndex]) === String(id)) {
      sheet.deleteRow(i + 1);
      return { success: true };
    }
  }
  return { success: false, error: "ID not found" };
}
```

### 3. IMPORTANTE: Nova Implantação (Deploy)

Sempre que você altera o código do Apps Script, você precisa publicar uma **nova versão**, senão o Front-end continua usando a versão antiga.

1.  No Apps Script, clique no botão azul **Implantar** (Deploy) > **Nova implantação**.
2.  Tipo: **App da Web**.
3.  Descrição: "Adicionado suporte a senha".
4.  Executar como: **Eu**.
5.  Quem pode acessar: **Qualquer pessoa**.
6.  Clique em **Implantar**.
7.  O link gerado será o mesmo se você fizer corretamente, mas se mudar, atualize o `API_URL` no arquivo `services/sheetService.ts`.

