export default EmployeeList;

import { Employee, TimeRecord } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// ============================================================================
// CONFIGURATION
// ============================================================================
// 1. Deploy your Google Apps Script as a Web App.
// 2. Set 'Who has access' to 'Anyone'.
// 3. Paste the Web App URL below inside the quotes.
const API_URL = "https://script.google.com/macros/s/AKfycbxbMu61JDhzemR8_5tp_LpMYSJtfLwDoZcQ3nFHYW5wr3HVu7kdW_bYVtM9o9Qz82rVRw/exec"; 

// --- OFFLINE/DEMO STATE ---
// Used only if API_URL is empty or fails
let localEmployees: Employee[] = [...INITIAL_EMPLOYEES];
let localRecords: TimeRecord[] = [...INITIAL_RECORDS];

export const sheetService = {

  // --- AUTHENTICATION ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {
    // 1. Try Mock Admin for instant access if needed (Emergency Backdoor)
    if (username === 'admin' && password === '123') {
      return { 
          success: true, 
          user: { 
            id: '1', 
            username: 'admin', 
            name: 'Admin Mock', 
            role: 'ADMIN' as any, 
            team: 'RH', 
            company: 'Arca Plast', // Default company for mock admin
            active: true, 
            email: 'admin@test.com' 
          } 
      };
    }

    // 2. Try API (Server-side validation)
    if (API_URL) {
      try {
        const response = await fetch(API_URL, {
          method: 'POST',
          redirect: 'follow',
          cache: 'no-store',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ action: 'login', payload: { username, password } })
        });

        if (response.ok) {
           const data = await response.json();
           if (data.success && data.user) {
             return { success: true, user: data.user };
           } else if (data.success === false) {
             // Server returned explicit failure
             return { success: false, message: data.message || "Credenciais inválidas." };
           }
        }
      } catch (error) {
        console.warn("Login API check failed, attempting fallback to list check.");
      }
    }

    // 3. Fallback: Check local/fetched employees list
    try {
        const employees = await sheetService.getEmployees();
        const foundUser = employees.find(e => e.username === username);

        if (foundUser) {
           // We assume if the user exists in the fallback mode, we let them in IF no password was returned (legacy) 
           // OR if we match the password field if it exists in the data.
           if (foundUser.password && foundUser.password !== password) {
               return { success: false, message: "Senha incorreta." };
           }
           return { success: true, user: foundUser };
        }
    } catch(e) {
        console.error("Fallback login failed", e);
    }

    return { success: false, message: "Usuário não encontrado." };
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    if (!API_URL) {
      console.warn("API_URL not set. Using local mock data.");
      return localEmployees;
    }

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store', // Prevent caching
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getEmployees', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();
      // Ensure we received an array
      if (Array.isArray(data)) {
        return data;
      } else {
        return localEmployees; // Fallback if format is wrong
      }
    } catch (e) {
      console.error("Fetch employees failed:", e);
      return localEmployees;
    }
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    // Optimistic Update (Local)
    localEmployees.push(employee);

    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'addEmployee', payload: employee })
      });
    } catch (e) {
      console.error("Failed to add employee to Sheet:", e);
    }
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    // Optimistic Update (Local)
    const index = localEmployees.findIndex(e => e.id === updatedEmployee.id);
    if (index !== -1) {
      localEmployees[index] = updatedEmployee;
    }

    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'updateEmployee', payload: updatedEmployee })
      });
    } catch (e) {
      console.error("Failed to update employee on Sheet:", e);
    }
  },

  deleteEmployee: async (id: string): Promise<boolean> => {
    // Optimistic Update (Local)
    localEmployees = localEmployees.filter(e => e.id !== id);

    if (!API_URL) return true;

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'deleteEmployee', payload: { id: String(id).trim() } })
      });

      if (!response.ok) return false;

      const result = await response.json();
      if (result && result.success === false) {
          console.error("GAS Error:", result.error);
          return false;
      }

      return true;
    } catch (e) {
      console.error("Failed to delete employee on Sheet:", e);
      return false;
    }
  },

  // --- RECORDS ---
  getRecords: async (): Promise<TimeRecord[]> => {
    if (!API_URL) {
      return localRecords;
    }

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getRecords', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();
      if (Array.isArray(data)) {
        return data;
      } else {
        return localRecords;
      }
    } catch (e) {
      console.error("Fetch records failed:", e);
      return localRecords;
    }
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    localRecords.push(record);

    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
