O erro `TypeError: Cannot read properties of null (reading 'getDataRange')` confirma que o Google Apps Script não está encontrando as abas (páginas) corretas na sua planilha. Isso acontece quando o nome da aba no código não bate exatamente com o nome na planilha (ex: "Sheet1" vs "Colaboradores").

Para corrigir isso definitivamente e remover os dados de teste, siga estes 3 passos:

### Passo 1: Configurar a Planilha Google

1.  Abra sua planilha.
2.  Renomeie a **Página1** (ou Sheet1) para: `Colaboradores` (Exatamente assim, primeira letra maiúscula).
3.  Crie uma nova aba e chame de: `Registros`.
4.  **Crie os Cabeçalhos (Linha 1)** em cada aba:

**Aba `Colaboradores` (Linha 1):**
`id` | `username` | `name` | `role` | `team` | `company` | `active` | `email` | `password`

**Aba `Registros` (Linha 1):**
`id` | `employeeId` | `employeeName` | `date` | `hours` | `minutes` | `type` | `occurrenceType` | `reason` | `createdAt` | `createdBy` | `startTime` | `endTime`

**IMPORTANTE:** Adicione manualmente um usuário na aba `Colaboradores` para você conseguir logar:
*   **id:** `1`
*   **username:** `admin`
*   **name:** `Seu Nome`
*   **role:** `ADMIN`
*   **password:** `123`
*   (Outros campos podem ficar em branco ou preenchidos como preferir).

---

### Passo 2: Atualizar o Google Apps Script

1.  Vá em **Extensões** > **Apps Script**.
2.  Apague **tudo** que estiver lá e cole o código abaixo.
3.  Clique em **Salvar**.
4.  Clique em **Implantar** > **Gerenciar Implantações** > **Editar** (Lápis).
5.  **Versão:** Selecione **"Nova versão"**.
6.  Clique em **Implantar**.

```javascript
// --- CONFIGURAÇÃO ---
const SHEET_EMPLOYEES = "Colaboradores";
const SHEET_RECORDS = "Registros";

function doPost(e) {
  const lock = LockService.getScriptLock();
  lock.tryLock(10000);

  try {
    const ss = SpreadsheetApp.getActiveSpreadsheet();
    const data = JSON.parse(e.postData.contents);
    const action = data.action;
    const payload = data.payload;

    let result = {};

    if (action === 'login') {
      result = handleLogin(ss, payload);
    } else if (action === 'getEmployees') {
      result = getData(ss, SHEET_EMPLOYEES);
    } else if (action === 'addEmployee') {
      result = addRow(ss, SHEET_EMPLOYEES, payload);
    } else if (action === 'updateEmployee') {
      result = updateRow(ss, SHEET_EMPLOYEES, payload);
    } else if (action === 'deleteEmployee') {
      result = deleteRow(ss, SHEET_EMPLOYEES, payload.id);
    } else if (action === 'getRecords') {
      result = getData(ss, SHEET_RECORDS);
    } else if (action === 'addRecord') {
      result = addRow(ss, SHEET_RECORDS, payload);
    }

    return ContentService.createTextOutput(JSON.stringify(result))
      .setMimeType(ContentService.MimeType.JSON);

  } catch (error) {
    return ContentService.createTextOutput(JSON.stringify({ 
      success: false, 
      error: error.toString(),
      stack: error.stack
    })).setMimeType(ContentService.MimeType.JSON);
  } finally {
    lock.releaseLock();
  }
}

// --- FUNÇÕES AUXILIARES ---

function getSheetOrThrow(ss, name) {
  const sheet = ss.getSheetByName(name);
  if (!sheet) throw new Error("Aba não encontrada: " + name + ". Verifique se o nome está exato na planilha.");
  return sheet;
}

function handleLogin(ss, { username, password }) {
  const users = getData(ss, SHEET_EMPLOYEES);
  // Procura usuário (case insensitive para username, mas password deve ser exato ou tratado como string)
  const user = users.find(u => 
    String(u.username).toLowerCase() === String(username).toLowerCase() && 
    String(u.password) == String(password)
  );

  if (user) {
    return { success: true, user: user };
  }
  return { success: false, message: "Credenciais inválidas" };
}

function getData(ss, sheetName) {
  const sheet = getSheetOrThrow(ss, sheetName);
  const rows = sheet.getDataRange().getValues();
  if (rows.length < 2) return []; // Apenas cabeçalho ou vazio

  const headers = rows[0];
  const data = rows.slice(1).map(row => {
    let obj = {};
    headers.forEach((header, index) => {
      // Converte cabeçalho para camelCase se necessário, mas ideal manter simples
      obj[header] = row[index];
    });
    // Converter booleanos strings para true/false reais
    if (obj.active === 'TRUE' || obj.active === true) obj.active = true;
    if (obj.active === 'FALSE' || obj.active === false) obj.active = false;
    return obj;
  });
  return data;
}

function addRow(ss, sheetName, data) {
  const sheet = getSheetOrThrow(ss, sheetName);
  const headers = sheet.getRange(1, 1, 1, sheet.getLastColumn()).getValues()[0];
  const newRow = headers.map(header => {
    // Garante que undefined/null vire string vazia, e booleanos virem strings
    const val = data[header];
    return val === undefined || val === null ? '' : val;
  });
  sheet.appendRow(newRow);
  return { success: true };
}

function updateRow(ss, sheetName, data) {
  const sheet = getSheetOrThrow(ss, sheetName);
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0];
  // Assume que a coluna 'id' é sempre a primeira (índice 0) ou busca pelo nome 'id'
  const idIndex = headers.indexOf('id');

  if (idIndex === -1) throw new Error("Coluna 'id' não encontrada");

  // Encontrar a linha (lembrando que rows inclui header, então +1 para API do Sheet)
  const rowIndex = rows.findIndex(r => String(r[idIndex]) === String(data.id));

  if (rowIndex === -1) return { success: false, message: "ID não encontrado" };

  const rowNumber = rowIndex + 1; // 1-based index

  // Atualiza apenas as colunas enviadas ou reescreve a linha toda?
  // Melhor reescrever mapeando os headers
  const updatedRow = headers.map(header => {
    if (data.hasOwnProperty(header)) {
        return data[header];
    }
    return rows[rowIndex][headers.indexOf(header)]; // Mantém valor antigo se não enviado
  });

  sheet.getRange(rowNumber, 1, 1, updatedRow.length).setValues([updatedRow]);
  return { success: true };
}

function deleteRow(ss, sheetName, id) {
  const sheet = getSheetOrThrow(ss, sheetName);
  const rows = sheet.getDataRange().getValues();
  const headers = rows[0];
  const idIndex = headers.indexOf('id');

  if (idIndex === -1) throw new Error("Coluna 'id' não encontrada");

  // Procura de baixo para cima para deletar com segurança
  for (let i = rows.length - 1; i >= 1; i--) {
    if (String(rows[i][idIndex]) === String(id)) {
      sheet.deleteRow(i + 1);
      return { success: true };
    }
  }
  return { success: false, message: "ID não encontrado" };
}
```

---

### Passo 3: Atualizar o Frontend

Abaixo, atualizo o código do App para remover os dados de teste (como solicitado: "não quero colaborador de teste") e preparar o sistema para usar apenas a planilha real.

**Atenção:** Como removi todos os usuários de teste do código, se você não criar o usuário na planilha (Passo 1), você não conseguirá entrar.

