import { Employee, TimeRecord } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// ============================================================================
// CONFIGURATION
// ============================================================================
// 1. Deploy your Google Apps Script as a Web App.
// 2. Set 'Who has access' to 'Anyone'.
// 3. Paste the Web App URL below inside the quotes.
const API_URL = "https://script.google.com/macros/s/AKfycbxbMu61JDhzemR8_5tp_LpMYSJtfLwDoZcQ3nFHYW5wr3HVu7kdW_bYVtM9o9Qz82rVRw/exec"; 

// --- OFFLINE/DEMO STATE ---
// Used only if API_URL is empty or fails
let localEmployees: Employee[] = [...INITIAL_EMPLOYEES];
let localRecords: TimeRecord[] = [...INITIAL_RECORDS];

export const sheetService = {

  // --- AUTHENTICATION ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {

    // 1. Try API (Server-side validation)
    if (API_URL) {
      try {
        const response = await fetch(API_URL, {
          method: 'POST',
          redirect: 'follow',
          cache: 'no-store',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ action: 'login', payload: { username: username.trim(), password: password.trim() } })
        });

        if (response.ok) {
           const data = await response.json();
           if (data.success && data.user) {
             return { success: true, user: data.user };
           } else if (data.success === false) {
             console.warn("Server Login Failed. Message:", data.message);
             if (data.error) {
                return { success: false, message: "Erro no Servidor: " + data.error };
             }
             return { success: false, message: data.message || "Credenciais inválidas." };
           }
        }
      } catch (error) {
        console.error("Login API check failed", error);
        return { success: false, message: "Erro de conexão com o servidor. Tente novamente." };
      }
    } else {
        return { success: false, message: "URL da API não configurada." };
    }

    return { success: false, message: "Usuário não encontrado." };
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    if (!API_URL) return [];

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store', // Prevent caching
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getEmployees', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();

      // Case 1: Success - Array of employees
      if (Array.isArray(data)) {
        return data;
      } 

      // Case 2: Explicit GAS Error (e.g., sheet not found)
      if (data && data.success === false) {
         console.error("Google Sheets API Error (getEmployees):", data.error || data.message);
         // Return empty array so UI doesn't crash, but logged error helps debug
         return [];
      }

      console.error("Received invalid employees format. Expected Array, got:", JSON.stringify(data));
      return [];

    } catch (e) {
      console.error("Fetch employees failed:", e);
      return [];
    }
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'addEmployee', payload: employee })
      });
    } catch (e) {
      console.error("Failed to add employee to Sheet:", e);
    }
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'updateEmployee', payload: updatedEmployee })
      });
    } catch (e) {
      console.error("Failed to update employee on Sheet:", e);
    }
  },

  deleteEmployee: async (id: string): Promise<boolean> => {
    if (!API_URL) return true;

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'deleteEmployee', payload: { id: String(id).trim() } })
      });

      if (!response.ok) return false;

      const result = await response.json();
      if (result && result.success === false) {
          console.error("GAS Error:", result.error);
          return false;
      }

      return true;
    } catch (e) {
      console.error("Failed to delete employee on Sheet:", e);
      return false;
    }
  },

  // --- RECORDS ---
  getRecords: async (): Promise<TimeRecord[]> => {
    if (!API_URL) return [];

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getRecords', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();

      if (Array.isArray(data)) {
        return data;
      }

      if (data && data.success === false) {
        console.error("Google Sheets API Error (getRecords):", data.error || data.message);
        return [];
      }

      console.error("Received invalid records format:", JSON.stringify(data));
      return [];

    } catch (e) {
      console.error("Fetch records failed:", e);
      return [];
    }
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'addRecord', payload: record })
      });
    } catch (e) {
      console.error("Failed to add record to Sheet:", e);
    }
  },

  updateRecord: async (record: TimeRecord): Promise<void> => {
    if (!API_URL) return;
    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'updateRecord', payload: record })
      });
    } catch (e) {
      console.error("Failed to update record on Sheet:", e);
    }
  },

  deleteRecord: async (id: string): Promise<boolean> => {
    if (!API_URL) return true;
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'deleteRecord', payload: { id: String(id).trim() } })
      });

      if (!response.ok) return false;
      const result = await response.json();
      if (result && result.success === false) return false;
      return true;
    } catch (e) {
      console.error("Failed to delete record on Sheet:", e);
      return false;
    }
  }
};

import React from 'react';
import { LayoutDashboard, FilePlus, Users, FileText, Settings, LogOut } from 'lucide-react';
import { Role, Employee } from '../types';

interface SidebarProps {
  currentUser: Employee;
  currentRole: Role;
  currentPage: string;
  setPage: (page: string) => void;
  onLogout: () => void;
  isOpen: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentUser, currentRole, currentPage, setPage, onLogout, isOpen }) => {

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'form', label: 'Nova Ocorrência', icon: FilePlus, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'employees', label: 'Colaboradores', icon: Users, roles: [Role.ADMIN] },
    { id: 'reports', label: 'Relatórios', icon: FileText, roles: [Role.ADMIN, Role.LEADER] },
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(currentRole));

  // Helper to get First and Last Name
  const getDisplayName = () => {
    if (!currentUser || !currentUser.name) return 'Usuário';
    const parts = currentUser.name.split(' ');
    if (parts.length > 1) {
      // Returns First Name + Last Name (or second word)
      return `${parts[0]} ${parts[parts.length - 1]}`; // Or just parts[1] for strictly second name
    }
    return parts[0];
  };

  // Helper for Initials based on Name
  const getInitials = () => {
     if (!currentUser || !currentUser.name) return 'US';
     const parts = currentUser.name.split(' ');
     if (parts.length > 1) return (parts[0][0] + parts[1][0]).toUpperCase();
     return parts[0].slice(0,2).toUpperCase();
  };

  const roleLabel = currentRole === Role.ADMIN ? 'Administrador' : 'Líder';

  return (
    <div className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static md:inset-0 shadow-xl`}>
      <div className="flex flex-col h-full">
        <div className="p-6 border-b border-slate-700">
          <h1 className="text-xl font-bold tracking-wider uppercase">Hurafy</h1>
          <p className="text-xs text-slate-400 mt-1">Formulário de Ocorrência</p>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          {filteredItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentPage === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setPage(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors duration-200 ${
                  isActive 
                    ? 'bg-indigo-600 text-white shadow-lg' 
                    : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-700">
          <div className="flex items-center space-x-3 px-4 py-3 mb-2">
             <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-xs font-bold shrink-0">
               {getInitials()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-medium truncate" title={currentUser.name}>{getDisplayName()}</p>
               <p className="text-xs text-slate-400">{roleLabel}</p>
             </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center space-x-3 px-4 py-2 text-red-400 hover:bg-red-500/10 hover:text-red-300 rounded-lg transition-colors"
          >
            <LogOut size={18} />
            <span className="text-sm font-medium">Sair / Trocar Perfil</span>
          </button>
        </div>
      </div>
    </div>
  );
};

