    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);

    const tableData = records.map(r => [
      formatDateTime(r.createdAt),
      getEmployeeCompany(r.employeeId),
      r.employeeName,
      getLeaderName(r.createdBy),
      r.occurrenceType || r.type,
      r.reason,
      `${r.hours}h ${r.minutes}m`
    ]);

    autoTable(doc, {
      head: [['Data Reg.', 'Empresa', 'Colaborador', 'Líder', 'Tipo', 'Descrição', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] },
      columnStyles: { 5: { cellWidth: 40 } } 
    });
    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(records.map(r => ({
      Data: formatDateTime(r.createdAt),
      Empresa: getEmployeeCompany(r.employeeId),
      Colaborador: r.employeeName,
      Líder: getLeaderName(r.createdBy),
      'Tipo de Ocorrência': r.occurrenceType,
      'Descrição': r.reason,
      Horas: r.hours,
      Minutos: r.minutes
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  // Prepare display records (All records, sorted by date DESC)
  const displayRecords = [...records].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="space-y-10 animate-fade-in relative">

      <div>
        <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
        <p className="text-slate-500">
           {currentUser.role === Role.ADMIN 
             ? "Gerenciamento completo e auditoria de logs." 
             : "Visualize relatórios e gerencie seus lançamentos."}
        </p>
      </div>

      {/* Reports Actions Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Consolidated Report (Usually just for viewing) */}
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
           <div className="flex items-center gap-3 mb-4">
              <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg"><Users size={20} /></div>
              <h3 className="font-bold text-slate-800">Balanço Consolidado</h3>
           </div>
           <p className="text-sm text-slate-500 mb-4">Exportar resumo de saldos finais.</p>
           {/* Reusing logic from previous implementation for download buttons if needed, or keeping simple here */}
           <div className="text-sm text-slate-400 italic">Disponível na versão completa (Admin).</div>
        </div>

        {/* Detailed Report */}
        <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm">
           <div className="flex items-center gap-3 mb-4">
              <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg"><FileText size={20} /></div>
              <h3 className="font-bold text-slate-800">Extrato Detalhado</h3>
           </div>
           <div className="flex gap-2">
              <button onClick={generateDetailedPDF} className="flex-1 flex items-center justify-center px-3 py-2 border border-slate-200 rounded-lg text-sm text-slate-600 hover:bg-slate-50">
                 <Download size={16} className="mr-2"/> PDF
              </button>
              <button onClick={generateDetailedExcel} className="flex-1 flex items-center justify-center px-3 py-2 border border-slate-200 rounded-lg text-sm text-slate-600 hover:bg-slate-50">
                 <Download size={16} className="mr-2"/> Excel
              </button>
           </div>
        </div>
      </div>

      {/* Detailed Table with Actions */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
