                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700">Justificativa</label>
                     <textarea required rows={3} value={editReason} onChange={e => setEditReason(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/>
                  </div>

                  <div className="flex justify-end gap-3 pt-2">
                     <button type="button" onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                     <button type="submit" disabled={loadingAction === 'modal-save' || !isEditTimeValid} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center">
                        {loadingAction === 'modal-save' ? <Loader2 size={16} className="animate-spin mr-2"/> : <Save size={16} className="mr-2"/>}
                        Salvar Alterações
                     </button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

