import { Employee, TimeRecord } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// ============================================================================
// CONFIGURATION
// ============================================================================
// 1. Deploy your Google Apps Script as a Web App.
// 2. Set 'Who has access' to 'Anyone'.
// 3. Paste the Web App URL below inside the quotes.
const API_URL = "https://script.google.com/macros/s/AKfycbxbMu61JDhzemR8_5tp_LpMYSJtfLwDoZcQ3nFHYW5wr3HVu7kdW_bYVtM9o9Qz82rVRw/exec"; 

// --- OFFLINE/DEMO STATE ---
// Used only if API_URL is empty or fails
let localEmployees: Employee[] = [...INITIAL_EMPLOYEES];
let localRecords: TimeRecord[] = [...INITIAL_RECORDS];

export const sheetService = {

  // --- AUTHENTICATION ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {

    // 1. Try API (Server-side validation)
    if (API_URL) {
      try {
        const response = await fetch(API_URL, {
          method: 'POST',
          redirect: 'follow',
          cache: 'no-store',
          headers: { 'Content-Type': 'text/plain;charset=utf-8' },
          body: JSON.stringify({ action: 'login', payload: { username: username.trim(), password: password.trim() } })
        });

        if (response.ok) {
           const data = await response.json();
           if (data.success && data.user) {
             return { success: true, user: data.user };
           } else if (data.success === false) {
             console.warn("Server Login Failed. Message:", data.message);
             if (data.error) {
                return { success: false, message: "Erro no Servidor: " + data.error };
             }
             return { success: false, message: data.message || "Credenciais inválidas." };
           }
        }
      } catch (error) {
        console.error("Login API check failed", error);
        return { success: false, message: "Erro de conexão com o servidor. Tente novamente." };
      }
    } else {
        return { success: false, message: "URL da API não configurada." };
    }

    return { success: false, message: "Usuário não encontrado." };
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    if (!API_URL) return [];

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store', // Prevent caching
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getEmployees', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();

      // Case 1: Success - Array of employees
      if (Array.isArray(data)) {
        return data;
      } 

      // Case 2: Explicit GAS Error (e.g., sheet not found)
      if (data && data.success === false) {
         console.error("Google Sheets API Error (getEmployees):", data.error || data.message);
         // Return empty array so UI doesn't crash, but logged error helps debug
         return [];
      }

      console.error("Received invalid employees format. Expected Array, got:", JSON.stringify(data));
      return [];

    } catch (e) {
      console.error("Fetch employees failed:", e);
      return [];
    }
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'addEmployee', payload: employee })
      });
    } catch (e) {
      console.error("Failed to add employee to Sheet:", e);
    }
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'updateEmployee', payload: updatedEmployee })
      });
    } catch (e) {
      console.error("Failed to update employee on Sheet:", e);
    }
  },

  deleteEmployee: async (id: string): Promise<boolean> => {
    if (!API_URL) return true;

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'deleteEmployee', payload: { id: String(id).trim() } })
      });

      if (!response.ok) return false;

      const text = await response.text();
      try {
        const result = JSON.parse(text);
        if (result && result.success === false) {
            console.error("GAS Error:", result.error);
            return false;
        }
        return true;
      } catch (e) {
        // If response is not JSON (e.g. empty string or plain text "Success"), but status is 200, assume success
        console.warn("deleteEmployee response was not JSON, assuming success:", text);
        return true;
      }
    } catch (e) {
      console.error("Failed to delete employee on Sheet:", e);
      return false;
    }
  },

  // --- RECORDS ---
  getRecords: async (): Promise<TimeRecord[]> => {
    if (!API_URL) return [];

    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'getRecords', payload: {} })
      });

      if (!response.ok) throw new Error("Network error");

      const data = await response.json();

      if (Array.isArray(data)) {
        return data;
      }

      if (data && data.success === false) {
        console.error("Google Sheets API Error (getRecords):", data.error || data.message);
        return [];
      }

      console.error("Received invalid records format:", JSON.stringify(data));
      return [];

    } catch (e) {
      console.error("Fetch records failed:", e);
      return [];
    }
  },

  addRecord: async (record: TimeRecord): Promise<void> => {
    if (!API_URL) return;

    try {
      await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'addRecord', payload: record })
      });
    } catch (e) {
      console.error("Failed to add record to Sheet:", e);
    }
  },

  updateRecord: async (record: TimeRecord): Promise<boolean> => {
    if (!API_URL) return true;
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'updateRecord', payload: record })
      });

      if (!response.ok) return false;

      const text = await response.text();
      try {
        const data = JSON.parse(text);
        return data.success === true;
      } catch (e) {
        // If parsing fails but request was OK, assume success if backend is quirky
        console.warn("updateRecord response not JSON:", text);
        return true; 
      }
    } catch (e) {
      console.error("Failed to update record on Sheet:", e);
      return false;
    }
  },

  deleteRecord: async (id: string): Promise<boolean> => {
    if (!API_URL) return true;
    try {
      const response = await fetch(API_URL, {
        method: 'POST',
        redirect: 'follow',
        cache: 'no-store',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify({ action: 'deleteRecord', payload: { id: String(id).trim() } })
      });

      if (!response.ok) return false;

      const text = await response.text();
      try {
          const result = JSON.parse(text);
          if (result && result.success === false) return false;
          return true;
      } catch (e) {
          // JSON parsing failed. If status is 200, assume success.
          console.warn("deleteRecord response not JSON, assuming success:", text);
          return true;
      }
    } catch (e) {
      console.error("Failed to delete record on Sheet:", e);
      return false;
    }
  }
};

import React from 'react';
import { FileText, Download, Users } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType, Role } from '../types';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
  currentUser: Employee;
  refreshData: () => void;
}

const Reports: React.FC<ReportsProps> = ({ records, employees, currentUser }) => {

  // --- Helper: Format minutes to HH:MM ---
  const formatTime = (totalMinutes: number) => {
    const hours = Math.floor(Math.abs(totalMinutes) / 60);
    const minutes = Math.abs(totalMinutes) % 60;
    const sign = totalMinutes < 0 ? '-' : '';
    return `${sign}${hours}h ${minutes.toString().padStart(2, '0')}m`;
  };

  // --- Helper: Format Date to PT-BR (Brasília Time) - Date Only ---
  const formatDate = (dateString: string) => {
    if (!dateString) return '-';
    try {
      const date = new Date(dateString);
      // Valid check
      if (isNaN(date.getTime())) return dateString;

      return new Intl.DateTimeFormat('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      }).format(date);
    } catch (error) {
      return dateString;
    }
  };

  // --- Helper: Format DateTime to PT-BR (Brasília Time) - Date & Time ---
  const formatDateTime = (dateString: string) => {
    if (!dateString) return '-';
    try {
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return dateString;

      return new Intl.DateTimeFormat('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
      }).format(date);
    } catch (error) {
      return dateString;
    }
  };

  // --- Helper: Get Leader Name ---
  const getLeaderName = (leaderId: string) => {
    const leader = employees.find(e => e.id === leaderId);
    return leader ? leader.name : 'Desconhecido';
  };

  // --- Helper: Get Company Name by Employee ID ---
  const getEmployeeCompany = (empId: string) => {
    const emp = employees.find(e => e.id === empId);
    return emp ? (emp.company || 'N/A') : '-';
  };

  // --- Helper: Calculate stats per employee ---
  const getConsolidatedData = () => {
    return employees.filter(e => e.active).map(emp => {
      const empRecords = records.filter(r => r.employeeId === emp.id);

      let creditMins = 0;
      let debitMins = 0;

      empRecords.forEach(r => {
        const mins = (r.hours * 60) + r.minutes;
        if (r.type === RecordType.CREDIT) {
          creditMins += mins;
        } else if (r.type === RecordType.DEBIT) {
          debitMins += mins;
        }
        // Neutral is ignored for balance
      });

      const netBalance = creditMins - debitMins;

      return {
        name: emp.name,
        company: emp.company || 'N/A',
        team: emp.team,
        role: emp.role,
        positive: formatTime(creditMins),
        negative: formatTime(debitMins),
        balance: formatTime(netBalance),
        rawBalance: netBalance // for sorting or logic if needed
      };
    }).sort((a, b) => {
      // Sort by Company first, then by Name
      if (a.company !== b.company) return a.company.localeCompare(b.company);
      return a.name.localeCompare(b.name);
    }); 
  };

  // --- DOWNLOAD REPORTS (Existing) ---
  const generateDetailedPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);

    const tableData = displayRecords.map(r => [
      formatDate(r.date),
      getEmployeeCompany(r.employeeId),
      r.employeeName,
      getLeaderName(r.createdBy),
      r.occurrenceType || r.type,
      r.reason,
      `${r.hours}h ${r.minutes}m`
    ]);

    autoTable(doc, {
      head: [['Data', 'Empresa', 'Colaborador', 'Líder', 'Tipo', 'Descrição', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] },
      columnStyles: { 5: { cellWidth: 40 } } 
    });
    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(displayRecords.map(r => ({
      Data: formatDate(r.date),
      Empresa: getEmployeeCompany(r.employeeId),
      Colaborador: r.employeeName,
      Líder: getLeaderName(r.createdBy),
      'Tipo de Ocorrência': r.occurrenceType,
      'Descrição': r.reason,
      Horas: r.hours,
      Minutos: r.minutes
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  const generateGeneralPDF = () => {
    const doc = new jsPDF();
    const data = getConsolidatedData();
    doc.setFontSize(18);
    doc.text('Balanço Geral de Horas por Colaborador', 14, 22);
    doc.setFontSize(11);
    doc.text(`Posição consolidada em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);
    const tableData = data.map(d => [d.company, d.name, d.team, d.positive, d.negative, d.balance]);
    autoTable(doc, {
      head: [['Empresa', 'Colaborador', 'Setor', 'Total Positivo', 'Total Negativo', 'Saldo Líquido']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 9, halign: 'center' },
      columnStyles: { 0: { halign: 'left' }, 1: { halign: 'left' }, 5: { fontStyle: 'bold' } },
      headStyles: { fillColor: [79, 70, 229] },
      didParseCell: (data) => {
        if (data.section === 'body' && data.column.index === 5) {
          const rawValue = data.cell.raw as string;
          if (rawValue.startsWith('-')) {
            data.cell.styles.textColor = [220, 38, 38];
          } else {
            data.cell.styles.textColor = [22, 163, 74];
          }
        }
      }
    });
    doc.save('balanco-geral-consolidado.pdf');
  };

  const generateGeneralExcel = () => {
    const data = getConsolidatedData();
    const ws = XLSX.utils.json_to_sheet(data.map(d => ({
      Empresa: d.company, Colaborador: d.name, Setor: d.team, 'Total Positivo': d.positive, 'Total Negativo': d.negative, 'Saldo Líquido': d.balance
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Saldos Consolidados");
    XLSX.writeFile(wb, "balanco-geral-consolidado.xlsx");
  };

  // Filter records: Leaders only see their own. Admin sees all.
  const displayRecords = records
    .filter(r => {
      if (currentUser.role === Role.ADMIN) return true;
      if (currentUser.role === Role.LEADER) return r.createdBy === currentUser.id;
      return false;
    })
