import React, { useState, useRef, useEffect } from 'react';
import { ChevronDown, Check, Search, X } from 'lucide-react';

interface Option {
  value: string;
  label: string;
  subLabel?: string;
}

interface SearchableSelectProps {
  options: Option[];
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  icon?: React.ElementType;
  className?: string;
}

const SearchableSelect: React.FC<SearchableSelectProps> = ({
  options,
  value,
  onChange,
  placeholder,
  icon: Icon,
  className = ''
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);

  // Find selected option object
  const selectedOption = options.find(opt => opt.value === value);

  // Sync searchTerm with selected value only when closing or initial load
  useEffect(() => {
    if (selectedOption) {
      setSearchTerm(selectedOption.label);
    } else {
      setSearchTerm('');
    }
  }, [selectedOption, value]);

  // Handle click outside to close
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
        // Revert text to selected value if user typed but didn't select
        if (selectedOption) {
            setSearchTerm(selectedOption.label);
        } else {
            setSearchTerm('');
        }
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [selectedOption]);

  const filteredOptions = options.filter(opt =>
    opt.label.toLowerCase().includes(searchTerm.toLowerCase()) ||
    (opt.subLabel && opt.subLabel.toLowerCase().includes(searchTerm.toLowerCase()))
  );

  const handleSelect = (optionValue: string) => {
    onChange(optionValue);
    setIsOpen(false);
  };

  const handleClear = (e: React.MouseEvent) => {
    e.stopPropagation();
    onChange('');
    setSearchTerm('');
    setIsOpen(false);
  };

  return (
    <div className={`relative ${className}`} ref={containerRef}>
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          {Icon ? <Icon className="h-4 w-4 text-slate-400" /> : <Search className="h-4 w-4 text-slate-400" />}
        </div>

        <input
          type="text"
          className={`block w-full pl-10 pr-10 py-2.5 border rounded-lg focus:ring-indigo-500 focus:border-indigo-500 text-sm shadow-sm transition-colors cursor-pointer
            ${isOpen ? 'ring-2 ring-indigo-500 border-indigo-500' : 'border-slate-300'}
            ${value ? 'bg-indigo-50 text-indigo-900 font-medium' : 'bg-white text-slate-700'}
          `}
          placeholder={placeholder}
          value={searchTerm}
          onChange={(e) => {
            setSearchTerm(e.target.value);
            if (!isOpen) setIsOpen(true);
          }}
          onClick={() => {
              setIsOpen(true);
              // Optional: Clear text on click to make search easier? 
              // Better UX: select all text so user can type over or just refine
          }}
          onFocus={(e) => {
              setIsOpen(true);
              e.target.select();
          }}
        />

        <div className="absolute inset-y-0 right-0 pr-2 flex items-center cursor-pointer">
          {value ? (
            <div 
                onClick={handleClear}
                className="p-1 hover:bg-slate-200 rounded-full text-slate-400 hover:text-slate-600 transition-colors"
            >
                <X size={14} />
            </div>
          ) : (
            <ChevronDown className="h-4 w-4 text-slate-400 pointer-events-none" />
          )}
        </div>
      </div>

      {isOpen && (
        <div className="absolute z-50 mt-1 w-full bg-white shadow-xl max-h-60 rounded-lg py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm custom-scrollbar animate-fade-in-up">
          {filteredOptions.length > 0 ? (
            filteredOptions.map((opt) => (
              <div
                key={opt.value}
                onClick={() => handleSelect(opt.value)}
                className={`cursor-pointer select-none relative py-2 pl-3 pr-9 hover:bg-indigo-50 transition-colors
                    ${value === opt.value ? 'bg-indigo-50 text-indigo-700 font-medium' : 'text-slate-900'}
                `}
              >
                <div className="flex flex-col">
                    <span className="block truncate">{opt.label}</span>
                    {opt.subLabel && (
                        <span className="text-xs text-slate-400 font-normal">{opt.subLabel}</span>
                    )}
                </div>

                {value === opt.value && (
                  <span className="absolute inset-y-0 right-0 flex items-center pr-4 text-indigo-600">
                    <Check className="h-4 w-4" aria-hidden="true" />
                  </span>
                )}
              </div>
            ))
          ) : (
            <div className="cursor-default select-none relative py-2 px-4 text-slate-500 text-center text-xs">
              Nenhuma opção encontrada.
            </div>
          )}
        </div>
      )}
    </div>
  );
};

