          <button onClick={generateDetailedExcel} className="flex items-center justify-center px-4 py-4 border border-indigo-200 text-sm font-medium rounded-lg text-indigo-700 bg-white hover:bg-indigo-50 shadow-sm transition-all">
            <Download className="mr-2" size={18} /> Baixar Excel
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
           <h3 className="font-semibold text-slate-700">Registros Encontrados</h3>
           <span className="text-xs text-slate-400">{displayRecords.length} registros</span>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Data</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Colaborador</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Líder</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tipo</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Descrição</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Início</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Fim</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tempo</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {displayRecords.map((record) => {
                const editable = canUserEdit(record);
                return (
                  <tr key={record.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{formatDate(record.date)}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <div className="text-sm text-slate-900">{record.employeeName}</div>
                       <div className="text-xs text-slate-400">{getEmployeeCompany(record.employeeId)}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-indigo-600">{getLeaderName(record.createdBy)}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                          record.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' :
                          record.type === RecordType.DEBIT ? 'bg-red-100 text-red-800' :
                          'bg-slate-100 text-slate-600'
                       }`}>
                          {record.occurrenceType}
                       </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 max-w-xs truncate" title={record.reason}>{record.reason}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500 font-mono">{formatTimeOnly(record.startTime)}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500 font-mono">{formatTimeOnly(record.endTime)}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-700">{record.hours}h {record.minutes}m</td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {editable && (
                        <div className="flex items-center justify-end gap-2">
                          <button 
                            onClick={() => openEditModal(record)}
                            className="text-indigo-600 hover:text-indigo-900 p-1 hover:bg-indigo-50 rounded"
                            title="Editar"
                          >
                            <Edit size={16} />
                          </button>
                          <button 
                            onClick={() => handleDelete(record.id)}
                            className="text-red-600 hover:text-red-900 p-1 hover:bg-red-50 rounded"
                            title="Excluir"
                            disabled={loadingAction === record.id}
                          >
                            {loadingAction === record.id ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {isEditModalOpen && editingRecord && (
         <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800">Editar Lançamento</h3>
                    <p className="text-sm text-slate-500">{editingRecord.employeeName}</p>
                  </div>
                  <button onClick={() => setIsEditModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
               </div>

               <form onSubmit={handleUpdateRecord} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">Data da Ocorrência</label>
                    <input type="date" required value={editDate} onChange={e => setEditDate(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700">Tipo</label>
                     <select value={editOccurrenceType} onChange={e => setEditOccurrenceType(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900">
                        {OCCURRENCE_OPTIONS.map(opt => <option key={opt.label} value={opt.label}>{opt.label}</option>)}
                     </select>
                  </div>

                  <div className="grid grid-cols-2 gap-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
                     <div>
                        <label className="block text-xs font-medium text-slate-500">Início</label>
                        <input type="time" required value={editStartTime} onChange={e => setEditStartTime(e.target.value)} className="w-full mt-1 border border-slate-300 rounded px-2 py-1 bg-white text-slate-900"/>
                     </div>
                     <div>
                        <label className="block text-xs font-medium text-slate-500">Fim</label>
                        <input type="time" required value={editEndTime} onChange={e => setEditEndTime(e.target.value)} className={`w-full mt-1 border rounded px-2 py-1 bg-white text-slate-900 ${!isEditTimeValid ? 'border-red-500' : 'border-slate-300'}`}/>
                     </div>
                     <div className="col-span-2 text-center text-sm font-bold text-indigo-600 border-t border-slate-200 pt-2">
                        {isEditTimeValid ? `${editCalculatedDuration.hours}h ${editCalculatedDuration.minutes}m` : <span className="text-red-500">Horário Inválido</span>}
                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700">Justificativa</label>
                     <textarea required rows={3} value={editReason} onChange={e => setEditReason(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/>
                  </div>

                  <div className="flex justify-end gap-3 pt-2">
                     <button type="button" onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                     <button type="submit" disabled={loadingAction === 'modal-save' || !isEditTimeValid} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center">
                        {loadingAction === 'modal-save' ? <Loader2 size={16} className="animate-spin mr-2"/> : <Save size={16} className="mr-2"/>}
                        Salvar Alterações
                     </button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useEffect } from 'react';
import { FileText, Download, Users, Edit, Trash2, Loader2, Save, X, Check } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType, Role } from '../types';
import { sheetService } from '../services/sheetService';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
  currentUser: Employee;
  refreshData: () => void;
  onUpdateRecord: (record: TimeRecord) => void;
  onDeleteRecord: (id: string) => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const Reports: React.FC<ReportsProps> = ({ records, employees, currentUser, refreshData, onUpdateRecord, onDeleteRecord }) => {
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Success Popup State
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingRecord, setEditingRecord] = useState<TimeRecord | null>(null);
  const [editDate, setEditDate] = useState('');
  const [editStartTime, setEditStartTime] = useState('');
  const [editEndTime, setEditEndTime] = useState('');
  const [editReason, setEditReason] = useState('');
  const [editOccurrenceType, setEditOccurrenceType] = useState('');
  const [editCalculatedDuration, setEditCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isEditTimeValid, setIsEditTimeValid] = useState(true);

  // --- Logic Checks ---
  const canUserEdit = (record: TimeRecord) => {
    // Admin can edit all
    if (currentUser.role === Role.ADMIN) return true;
    // Leader can edit ONLY if they created it
    if (currentUser.role === Role.LEADER && record.createdBy === currentUser.id) return true;
    return false;
  };

  // --- Helper: Format minutes to HH:MM ---
  const formatTime = (totalMinutes: number) => {
    const hours = Math.floor(Math.abs(totalMinutes) / 60);
    const minutes = Math.abs(totalMinutes) % 60;
    const sign = totalMinutes < 0 ? '-' : '';
    return `${sign}${hours}h ${minutes.toString().padStart(2, '0')}m`;
  };

  // --- Helper: Format Date to PT-BR (Brasília Time) - Date Only (Display) ---
  const formatDate = (dateString: string) => {
    if (!dateString) return '-';

    // Fix: Handle YYYY-MM-DD manually to prevent Timezone Day Shift
    // new Date("2024-02-01") creates UTC 00:00, which is previous day 21:00 in Brazil
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
        const [year, month, day] = dateString.split('-');
        return `${day}/${month}/${year}`;
    }

    try {
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return dateString;

      return new Intl.DateTimeFormat('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      }).format(date);
    } catch (error) {
      return dateString;
    }
  };

  // --- Helper: Clean Time String (Extract HH:MM from ISO, raw string or serial number) ---
  const formatTimeOnly = (val?: string | number) => {
    if (val === undefined || val === null || val === '') return '-';

    const strVal = String(val);

    // 1. Handle ISO String (contains 'T'): e.g., 1899-12-30T10:06:28.000Z
    if (strVal.includes('T')) {
        try {
            const date = new Date(strVal);
            if (!isNaN(date.getTime())) {
                // Use Intl with specific timezone to handle historical offsets (LMT) correctly
                // In 1899, Sao Paulo was UTC-03:06:28. 
                // 10:06:28 UTC -> 07:00:00 LMT.
                // This removes the "6 minute" artifact.
                return new Intl.DateTimeFormat('pt-BR', {
                    hour: '2-digit',
                    minute: '2-digit',
                    timeZone: 'America/Sao_Paulo'
                }).format(date);
            }
        } catch (e) {
            console.error("Error parsing ISO time:", e);
        }
        // Fallback if parsing fails but looks like ISO
        const timePart = strVal.split('T')[1];
        return timePart.substring(0, 5);
    }

    // 2. Handle simple HH:MM
    if (strVal.includes(':')) {
        return strVal.substring(0, 5);
    }

    // 3. Handle Excel Serial Number (e.g. 0.333333333 for 08:00)
    if (!isNaN(Number(strVal))) {
       const num = Number(strVal);
       const fraction = num % 1; 
       const totalMinutes = Math.round(fraction * 24 * 60);
       const h = Math.floor(totalMinutes / 60);
       const m = totalMinutes % 60;
       return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
    }

    return strVal.length > 5 ? strVal.substring(0, 5) : strVal;
  };

  // --- Helper: Convert stored date to Input Date YYYY-MM-DD (For Editing) ---
  const safeDateForInput = (dateString: string) => {
    if (!dateString) return '';

    // 1. If already YYYY-MM-DD
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return dateString;

    // 2. If ISO string (contains T)
    if (dateString.includes('T')) {
        return dateString.split('T')[0];
    }

    // 3. Try parsing if it's a valid date object string
    const d = new Date(dateString);
    if (!isNaN(d.getTime())) {
        return d.toISOString().split('T')[0];
    }

    return '';
  };

  // --- Helper: Get Leader Name ---
  const getLeaderName = (leaderId: string) => {
    const leader = employees.find(e => e.id === leaderId);
    return leader ? leader.name : 'Desconhecido';
  };

  // --- Helper: Get Company Name by Employee ID ---
  const getEmployeeCompany = (empId: string) => {
    const emp = employees.find(e => e.id === empId);
    return emp ? (emp.company || 'N/A') : '-';
  };

  // --- Helper: Calculate stats per employee ---
  const getConsolidatedData = () => {
    return employees.filter(e => e.active).map(emp => {
      const empRecords = records.filter(r => r.employeeId === emp.id);

      let creditMins = 0;
      let debitMins = 0;

      empRecords.forEach(r => {
        const mins = (r.hours * 60) + r.minutes;
        if (r.type === RecordType.CREDIT) {
          creditMins += mins;
        } else if (r.type === RecordType.DEBIT) {
          debitMins += mins;
        }
      });

      const netBalance = creditMins - debitMins;

      return {
        name: emp.name,
        company: emp.company || 'N/A',
        team: emp.team,
        role: emp.role,
        positive: formatTime(creditMins),
        negative: formatTime(debitMins),
        balance: formatTime(netBalance),
        rawBalance: netBalance 
      };
    }).sort((a, b) => {
      if (a.company !== b.company) return a.company.localeCompare(b.company);
      return a.name.localeCompare(b.name);
    }); 
  };

  // --- Calculation Logic for Modal ---
  useEffect(() => {
    // Only calculate if both times are present
    if (!editStartTime || !editEndTime) {
      // If times are missing but we are editing, we don't want to zero out the existing hours immediately
      // unless the user is actively changing the time inputs.
      // However, for UX consistency, if inputs are blank, duration is effectively unknown or 0.
      // We rely on openEditModal to set initial values correctly.
      return;
    }

    const [startH, startM] = editStartTime.split(':').map(Number);
    const [endH, endM] = editEndTime.split(':').map(Number);
    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsEditTimeValid(false);
      setEditCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsEditTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setEditCalculatedDuration({ hours: h, minutes: m });
    }
  }, [editStartTime, editEndTime]);

  // --- ACTIONS ---

  const showSuccessPopup = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => {
      setSuccessMessage(null);
    }, 3000);
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Tem certeza que deseja excluir este registro permanentemente?')) return;

    setLoadingAction(id);
    try {
        const success = await sheetService.deleteRecord(id);
        if (success) {
          onDeleteRecord(id);
          showSuccessPopup('Registro excluído com sucesso.');
        } else {
          alert('Erro ao excluir registro na planilha. Tente novamente.');
        }
    } catch (e) {
        alert("Erro de conexão.");
    } finally {
        setLoadingAction(null);
    }
  };

  const openEditModal = (record: TimeRecord) => {
    setEditingRecord(record);

    // Safe parsers for inputs
    setEditDate(safeDateForInput(record.date));

    // Clean and set times for input values
    const cleanStart = formatTimeOnly(record.startTime);
    const cleanEnd = formatTimeOnly(record.endTime);

    setEditStartTime(cleanStart === '-' ? '' : cleanStart);
    setEditEndTime(cleanEnd === '-' ? '' : cleanEnd);

    setEditReason(record.reason);
    setEditOccurrenceType(record.occurrenceType);

    // Initialize duration from record so it displays correctly before any edit
    setEditCalculatedDuration({ hours: record.hours, minutes: record.minutes });
    setIsEditTimeValid(true);

    setIsEditModalOpen(true);
  };

  const handleUpdateRecord = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingRecord || !isEditTimeValid) return;
    if (editCalculatedDuration.hours === 0 && editCalculatedDuration.minutes === 0) {
      alert("Duração inválida.");
      return;
    }

    setLoadingAction('modal-save');

    const option = OCCURRENCE_OPTIONS.find(o => o.label === editOccurrenceType);
    const newType = option ? option.type : RecordType.CREDIT;

    const updatedRecord: TimeRecord = {
      ...editingRecord,
      date: editDate,
      startTime: editStartTime,
      endTime: editEndTime,
      hours: editCalculatedDuration.hours,
      minutes: editCalculatedDuration.minutes,
      reason: editReason,
      occurrenceType: editOccurrenceType,
      type: newType
    };

    try {
        const success = await sheetService.updateRecord(updatedRecord);

        if (success) {
            onUpdateRecord(updatedRecord);
            setIsEditModalOpen(false);
            setEditingRecord(null);
            showSuccessPopup('Registro atualizado com sucesso.');
        } else {
            alert("Falha ao salvar. O servidor não confirmou a alteração.");
        }
    } catch (error) {
        console.error("Error updating record:", error);
        alert("Erro ao conectar com o servidor.");
    } finally {
        setLoadingAction(null);
    }
  };

  // --- GENERATE PDF/EXCEL ---
  const generateDetailedPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);

    const tableData = displayRecords.map(r => [
      formatDate(r.date),
      getEmployeeCompany(r.employeeId),
      r.employeeName,
      getLeaderName(r.createdBy),
      r.occurrenceType || r.type,
      r.reason,
      formatTimeOnly(r.startTime),
      formatTimeOnly(r.endTime),
      `${r.hours}h ${r.minutes}m`
    ]);

    autoTable(doc, {
      head: [['Data', 'Empresa', 'Colaborador', 'Líder', 'Tipo', 'Descrição', 'Início', 'Fim', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] },
      columnStyles: { 5: { cellWidth: 35 } } 
    });
    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(displayRecords.map(r => ({
      Data: formatDate(r.date),
      Empresa: getEmployeeCompany(r.employeeId),
      Colaborador: r.employeeName,
      Líder: getLeaderName(r.createdBy),
      'Tipo de Ocorrência': r.occurrenceType,
      'Descrição': r.reason,
      'Início': formatTimeOnly(r.startTime),
      'Fim': formatTimeOnly(r.endTime),
      Horas: r.hours,
      Minutos: r.minutes
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  const generateGeneralPDF = () => {
    const doc = new jsPDF();
    const data = getConsolidatedData();
    doc.setFontSize(18);
    doc.text('Balanço Geral de Horas por Colaborador', 14, 22);
    doc.setFontSize(11);
    doc.text(`Posição consolidada em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);
    const tableData = data.map(d => [d.company, d.name, d.team, d.positive, d.negative, d.balance]);
    autoTable(doc, {
      head: [['Empresa', 'Colaborador', 'Setor', 'Total Positivo', 'Total Negativo', 'Saldo Líquido']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 9, halign: 'center' },
      columnStyles: { 0: { halign: 'left' }, 1: { halign: 'left' }, 5: { fontStyle: 'bold' } },
      headStyles: { fillColor: [79, 70, 229] },
      didParseCell: (data) => {
        if (data.section === 'body' && data.column.index === 5) {
          const rawValue = data.cell.raw as string;
          if (rawValue.startsWith('-')) {
            data.cell.styles.textColor = [220, 38, 38];
          } else {
            data.cell.styles.textColor = [22, 163, 74];
          }
        }
      }
    });
    doc.save('balanco-geral-consolidado.pdf');
  };

  const generateGeneralExcel = () => {
    const data = getConsolidatedData();
    const ws = XLSX.utils.json_to_sheet(data.map(d => ({
      Empresa: d.company, Colaborador: d.name, Setor: d.team, 'Total Positivo': d.positive, 'Total Negativo': d.negative, 'Saldo Líquido': d.balance
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Saldos Consolidados");
    XLSX.writeFile(wb, "balanco-geral-consolidado.xlsx");
  };

  const displayRecords = records
    .filter(r => {
      if (currentUser.role === Role.ADMIN) return true;
      if (currentUser.role === Role.LEADER) return r.createdBy === currentUser.id;
      return false;
    })
    .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

  return (
    <div className="space-y-10 animate-fade-in relative">

      {/* SUCCESS POPUP MODAL */}
      {successMessage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMessage}</p>
          </div>
        </div>
      )}

      <div>
        <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
        <p className="text-slate-500">
           {currentUser.role === Role.ADMIN 
             ? "Gerenciamento completo e auditoria de logs." 
             : "Visualize relatórios e gerencie seus lançamentos."}
        </p>
      </div>

      {/* ADMIN ONLY: CONSOLIDATED SUMMARY */}
      {currentUser.role === Role.ADMIN && (
        <div className="bg-gradient-to-r from-indigo-50 to-white p-6 rounded-xl border border-indigo-100 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
              <Users size={24} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-800">Balanço Geral (Consolidado)</h3>
              <p className="text-sm text-slate-500">Resumo de saldo final de horas por colaborador e setor.</p>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <button 
              onClick={generateGeneralPDF}
              className="flex items-center justify-center px-4 py-4 border border-transparent text-sm font-medium rounded-lg text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm transition-all"
            >
              <Download className="mr-2" size={18} />
              Baixar Resumo em PDF
            </button>
            <button 
               onClick={generateGeneralExcel}
               className="flex items-center justify-center px-4 py-4 border border-indigo-200 text-sm font-medium rounded-lg text-indigo-700 bg-white hover:bg-indigo-50 shadow-sm transition-all"
            >
              <Download className="mr-2" size={18} />
              Baixar Resumo em Excel
            </button>
          </div>
        </div>
      )}

      {/* DETAILED LOGS & EDITING TABLE */}
      <div className={`p-6 rounded-xl border border-indigo-100 shadow-sm ${currentUser.role === Role.ADMIN ? 'bg-gradient-to-r from-indigo-50 to-white' : 'bg-white'}`}>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
            <FileText size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Extrato de Ocorrências</h3>
            <p className="text-sm text-slate-500">
               {currentUser.role === Role.ADMIN 
                  ? "Lista completa de todos os registros lançados." 
                  : "Lista dos registros lançados por você."}
            </p>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button onClick={generateDetailedPDF} className="flex items-center justify-center px-4 py-4 border border-transparent text-sm font-medium rounded-lg text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm transition-all">
            <Download className="mr-2" size={18} /> Baixar PDF
          </button>
          <button onClick={generateDetailedExcel} className="flex items-center justify-center px-4 py-4 border border-indigo-200 text-sm font-medium rounded-lg text-indigo-700 bg-white hover:bg-indigo-50 shadow-sm transition-all">
            <Download className="mr-2" size={18} /> Baixar Excel
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
           <h3 className="font-semibold text-slate-700">Registros Encontrados</h3>
           <span className="text-xs text-slate-400">{displayRecords.length} registros</span>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Data</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Colaborador</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Líder</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tipo</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Descrição</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Início</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Fim</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tempo</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {displayRecords.map((record) => {
                const editable = canUserEdit(record);
                return (
                  <tr key={record.id} className="hover:bg-slate-50">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{formatDate(record.date)}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <div className="text-sm text-slate-900">{record.employeeName}</div>
                       <div className="text-xs text-slate-400">{getEmployeeCompany(record.employeeId)}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-indigo-600">{getLeaderName(record.createdBy)}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${
                          record.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' :
                          record.type === RecordType.DEBIT ? 'bg-red-100 text-red-800' :
                          'bg-slate-100 text-slate-600'
                       }`}>
                          {record.occurrenceType}
                       </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 max-w-xs truncate" title={record.reason}>{record.reason}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500 font-mono">{formatTimeOnly(record.startTime)}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500 font-mono">{formatTimeOnly(record.endTime)}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-700">{record.hours}h {record.minutes}m</td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {editable && (
                        <div className="flex items-center justify-end gap-2">
                          <button 
                            onClick={() => openEditModal(record)}
                            className="text-indigo-600 hover:text-indigo-900 p-1 hover:bg-indigo-50 rounded"
                            title="Editar"
                          >
                            <Edit size={16} />
                          </button>
                          <button 
                            onClick={() => handleDelete(record.id)}
                            className="text-red-600 hover:text-red-900 p-1 hover:bg-red-50 rounded"
                            title="Excluir"
                            disabled={loadingAction === record.id}
                          >
                            {loadingAction === record.id ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}
                          </button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {isEditModalOpen && editingRecord && (
         <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800">Editar Lançamento</h3>
                    <p className="text-sm text-slate-500">{editingRecord.employeeName}</p>
                  </div>
                  <button onClick={() => setIsEditModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
               </div>

               <form onSubmit={handleUpdateRecord} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
                  <div>
                    <label className="block text-sm font-medium text-slate-700">Data da Ocorrência</label>
                    <input type="date" required value={editDate} onChange={e => setEditDate(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700">Tipo</label>
                     <select value={editOccurrenceType} onChange={e => setEditOccurrenceType(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900">
                        {OCCURRENCE_OPTIONS.map(opt => <option key={opt.label} value={opt.label}>{opt.label}</option>)}
                     </select>
                  </div>

                  <div className="grid grid-cols-2 gap-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
                     <div>
                        <label className="block text-xs font-medium text-slate-500">Início</label>
                        <input type="time" required value={editStartTime} onChange={e => setEditStartTime(e.target.value)} className="w-full mt-1 border border-slate-300 rounded px-2 py-1 bg-white text-slate-900"/>
                     </div>
                     <div>
                        <label className="block text-xs font-medium text-slate-500">Fim</label>
                        <input type="time" required value={editEndTime} onChange={e => setEditEndTime(e.target.value)} className={`w-full mt-1 border rounded px-2 py-1 bg-white text-slate-900 ${!isEditTimeValid ? 'border-red-500' : 'border-slate-300'}`}/>
                     </div>
                     <div className="col-span-2 text-center text-sm font-bold text-indigo-600 border-t border-slate-200 pt-2">
                        {isEditTimeValid ? `${editCalculatedDuration.hours}h ${editCalculatedDuration.minutes}m` : <span className="text-red-500">Horário Inválido</span>}
                     </div>
                  </div>

                  <div>
                     <label className="block text-sm font-medium text-slate-700">Justificativa</label>
                     <textarea required rows={3} value={editReason} onChange={e => setEditReason(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/>
                  </div>

                  <div className="flex justify-end gap-3 pt-2">
                     <button type="button" onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                     <button type="submit" disabled={loadingAction === 'modal-save' || !isEditTimeValid} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center">
                        {loadingAction === 'modal-save' ? <Loader2 size={16} className="animate-spin mr-2"/> : <Save size={16} className="mr-2"/>}
                        Salvar Alterações
                     </button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

export default Reports;

export enum Role {
  ADMIN = 'ADMIN', // HR
  LEADER = 'LEADER',
  EMPLOYEE = 'EMPLOYEE'
}

export enum RecordType {
  CREDIT = 'Positivo',
  DEBIT = 'Negativo',
  NEUTRAL = 'Neutro'
}

export interface Employee {
  id: string;
  username: string;
  password?: string; // Optional because we don't fetch passwords back from server
  name: string;
  role: Role;
  team: string; // Used to link leaders to employees
  company: string; // New field for Company Entity
  active: boolean;
  email: string;
}

export interface Attachment {
  id: string;
  url: string;
  name: string;
}

export interface TimeRecord {
  id: string;
  employeeId: string;
  employeeName: string;
  date: string;
  hours: number;
  minutes: number;
  startTime?: string;
  endTime?: string;
  type: RecordType;
  occurrenceType: string; // The specific dropdown label
  reason: string;
  createdAt: string;
  createdBy: string; // Leader ID
  attachment?: Attachment; // Optional attachment
}

export interface DashboardStats {
  totalEmployees: number;
  totalPositiveHours: number;
  totalNegativeHours: number;
  netBalance: number;
}

import { createClient } from '@supabase/supabase-js';
import { Employee, TimeRecord, Attachment } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// ============================================================================
// SUPABASE CONFIGURATION
// ============================================================================
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_ANON_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// Bucket name for file uploads
const BUCKET_NAME = 'attachments';

export const sheetService = {

  // --- AUTHENTICATION (Simulated via Table Query) ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {
    if (!SUPABASE_URL) return { success: false, message: "Supabase não configurado." };

    try {
      // 1. Find user by username
      const { data: user, error } = await supabase
        .from('employees')
        .select('*')
        .eq('username', username)
        .eq('active', true)
        .single();

      if (error || !user) {
        return { success: false, message: "Usuário não encontrado." };
      }

      // 2. Simple password check (In production, use Supabase Auth or BCrypt)
      // Assuming 'password' column exists in employees table for this legacy migration
      if (user.password !== password) {
        return { success: false, message: "Senha incorreta." };
      }

      return { success: true, user: user as Employee };
    } catch (e) {
      console.error("Login failed:", e);
      return { success: false, message: "Erro de conexão." };
    }
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    if (!SUPABASE_URL) return INITIAL_EMPLOYEES;

    const { data, error } = await supabase
      .from('employees')
      .select('*')
      .order('name');

    if (error) {
      console.error("Error fetching employees:", error);
      return [];
    }
    return data as Employee[];
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    await supabase.from('employees').insert([employee]);
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    const { id, ...updates } = updatedEmployee;
    await supabase.from('employees').update(updates).eq('id', id);
  },

  deleteEmployee: async (id: string): Promise<boolean> => {
    const { error } = await supabase.from('employees').delete().eq('id', id);
    return !error;
  },

  // --- RECORDS (Time Entries) ---
  getRecords: async (): Promise<TimeRecord[]> => {
    if (!SUPABASE_URL) return INITIAL_RECORDS;

    // Fetch time_entries and join attachments
    const { data, error } = await supabase
      .from('time_entries')
      .select(`
        *,
        attachments (
          id,
          file_url,
          file_name
        )
      `)
      .order('timestamp', { ascending: false });

    if (error) {
      console.error("Error fetching records:", error);
      return [];
    }

    // Map SQL structure to App 'TimeRecord' structure
    return data.map((entry: any) => ({
      id: entry.id,
      employeeId: entry.user_id,
      employeeName: entry.employee_name || 'Unknown', // Ideally join employees table too
      date: entry.date, // YYYY-MM-DD
      hours: entry.hours,
      minutes: entry.minutes,
      startTime: entry.start_time,
      endTime: entry.end_time,
      type: entry.entry_type,
      occurrenceType: entry.occurrence_type,
      reason: entry.comments,
      createdAt: entry.created_at,
      createdBy: entry.created_by,
      // Map first attachment if exists
      attachment: entry.attachments && entry.attachments.length > 0 ? {
        id: entry.attachments[0].id,
        url: entry.attachments[0].file_url,
        name: entry.attachments[0].file_name
      } : undefined
    }));
  },

  addRecord: async (record: TimeRecord, attachmentFile?: File): Promise<void> => {
    try {
      // 1. Insert Time Entry
      const { data: entryData, error: entryError } = await supabase
        .from('time_entries')
        .insert([{
          id: record.id,
          user_id: record.employeeId,
          employee_name: record.employeeName, // Denormalized for easier query
          date: record.date,
          hours: record.hours,
          minutes: record.minutes,
          start_time: record.startTime,
          end_time: record.endTime,
          entry_type: record.type, // Credit/Debit
          occurrence_type: record.occurrenceType,
          comments: record.reason,
          created_at: record.createdAt,
          created_by: record.createdBy,
          timestamp: new Date(record.date).toISOString() // For prompt compliance
        }])
        .select()
        .single();

      if (entryError) throw entryError;

      // 2. Upload Attachment if present
      if (attachmentFile && entryData) {
        const fileExt = attachmentFile.name.split('.').pop();
        const fileName = `${record.id}.${fileExt}`;
        const filePath = `${entryData.user_id}/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from(BUCKET_NAME)
          .upload(filePath, attachmentFile);

        if (uploadError) {
           console.error("Error uploading file:", uploadError);
           // Continue to save metadata even if upload fails, or handle error
        } else {
           // Get Public URL
           const { data: { publicUrl } } = supabase.storage
             .from(BUCKET_NAME)
             .getPublicUrl(filePath);

           // 3. Insert Attachment Record
           await supabase
             .from('attachments')
             .insert([{
               entry_id: record.id,
               file_name: attachmentFile.name,
               file_url: publicUrl
             }]);
        }
      }
    } catch (e) {
      console.error("Failed to add record:", e);
      throw e;
    }
  },

  updateRecord: async (record: TimeRecord): Promise<boolean> => {
    const { error } = await supabase
      .from('time_entries')
      .update({
        date: record.date,
        hours: record.hours,
        minutes: record.minutes,
        start_time: record.startTime,
        end_time: record.endTime,
        entry_type: record.type,
        occurrence_type: record.occurrenceType,
        comments: record.reason
      })
      .eq('id', record.id);

    return !error;
  },

  deleteRecord: async (id: string): Promise<boolean> => {
    const { error } = await supabase.from('time_entries').delete().eq('id', id);
    return !error;
  },

  // Expose bucket upload helper directly if needed
  uploadAttachment: async (file: File, path: string) => {
    return await supabase.storage.from(BUCKET_NAME).upload(path, file);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Upload, File as FileIcon, X } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { sheetService } from '../services/sheetService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Attachment State
  const [attachment, setAttachment] = useState<File | null>(null);

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Update Mapped Record Type when Occurrence Selection Changes
  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
  }, [occurrenceType]);

  // Calculate duration whenever times change
  useEffect(() => {
    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);

    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime]);

  // Filter employees
  const availableEmployees = employees;
  const filteredEmployees = availableEmployees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setAttachment(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !reason || !startTime || !endTime || !isTimeValid) return;

    if (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
      alert("A duração deve ser maior que zero.");
      return;
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: calculatedDuration.hours,
      minutes: calculatedDuration.minutes,
      startTime,
      endTime,
      type: mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      // Pass attachment to service (it handles upload)
      await sheetService.addRecord(newRecord, attachment || undefined);

      setSuccess(true);
      onRecordAdded();

      // Reset form
      setSelectedEmployee('');
      setSearchTerm('');
      setStartTime('');
      setEndTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');
      setAttachment(null);

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving record", error);
      alert("Erro ao salvar o registro.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">Ocorrência registrada com sucesso.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Registre o período da ocorrência para cálculo automático.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
                />
              </div>
            </div>

            {/* Type Dropdown */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <div className="relative">
                 <select
                    value={occurrenceType}
                    onChange={(e) => setOccurrenceType(e.target.value)}
                    className="block w-full pl-3 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
                 >
                   {OCCURRENCE_OPTIONS.map((opt) => (
                     <option key={opt.label} value={opt.label}>{opt.label}</option>
                   ))}
                 </select>
               </div>
               {/* Visual Indicator of Effect */}
               <div className={`mt-2 p-2 rounded-lg border text-xs font-semibold flex items-center justify-center ${getTypeStyles(mappedRecordType)}`}>
                  {mappedRecordType === RecordType.CREDIT && <span className="flex items-center"><Check size={14} className="mr-1"/> Adiciona ao Banco de Horas (Crédito)</span>}
                  {mappedRecordType === RecordType.DEBIT && <span className="flex items-center"><AlertTriangle size={14} className="mr-1"/> Desconta do Banco de Horas (Débito)</span>}
                  {mappedRecordType === RecordType.NEUTRAL && <span className="flex items-center"><Info size={14} className="mr-1"/> Informativo (Não altera o saldo)</span>}
               </div>
            </div>

            {/* Time Range Calculation */}
            <div className="col-span-1 md:col-span-2">
              <label className="block text-sm font-medium text-slate-700 mb-2">Período da Atividade</label>
              <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Início/Entrada</label>
                  <input 
                    type="time" 
                    required
                    value={startTime}
                    onChange={(e) => setStartTime(e.target.value)}
                    className="block w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Fim/Saída</label>
                  <input 
                    type="time" 
                    required
                    value={endTime}
                    onChange={(e) => setEndTime(e.target.value)}
                    className={`block w-full px-3 py-2 border rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500 ${!isTimeValid ? 'border-red-500 ring-1 ring-red-500' : 'border-slate-300'}`}
                  />
                </div>

                {/* Duration Result */}
                <div className="col-span-1 sm:col-span-2 mt-2 pt-4 border-t border-slate-200 flex items-center justify-between">
                  <div className="flex items-center text-slate-600">
                    <Calculator size={18} className="mr-2" />
                    <span className="text-sm font-medium">Tempo Calculado:</span>
                  </div>
                  <div className={`text-lg font-bold ${!isTimeValid ? 'text-red-500' : 'text-indigo-600'}`}>
                    {!isTimeValid ? (
                      <span className="text-sm">Horário Inválido</span>
                    ) : (
                      <span>
                        {calculatedDuration.hours}h {calculatedDuration.minutes}m
                      </span>
                    )}
                  </div>
                </div>
              </div>
              {!isTimeValid && (
                <p className="text-xs text-red-500 mt-1">A hora de término deve ser posterior à hora de início.</p>
              )}
            </div>

          </div>

          {/* Reason */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Justificativa</label>
            <textarea
              required
              rows={3}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="Detalhes adicionais..."
              className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
            />
          </div>

          {/* Attachment Upload */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Anexar Comprovante (Opcional)</label>
            <div className="mt-1 flex justify-center px-6 pt-5 pb-6 border-2 border-slate-300 border-dashed rounded-lg bg-slate-50 hover:bg-slate-100 transition-colors">
              <div className="space-y-1 text-center">
                {attachment ? (
                   <div className="flex flex-col items-center">
                      <FileIcon className="mx-auto h-12 w-12 text-indigo-500" />
                      <div className="flex text-sm text-slate-600 mt-2 items-center">
                        <span className="font-medium text-indigo-600">{attachment.name}</span>
                        <button 
                          type="button" 
                          onClick={() => setAttachment(null)} 
                          className="ml-2 text-red-500 hover:text-red-700"
                        >
                          <X size={16} />
                        </button>
                      </div>
                      <p className="text-xs text-slate-500">{(attachment.size / 1024).toFixed(1)} KB</p>
                   </div>
                ) : (
                  <>
                    <Upload className="mx-auto h-12 w-12 text-slate-400" />
                    <div className="flex text-sm text-slate-600 justify-center">
                      <label htmlFor="file-upload" className="relative cursor-pointer bg-white rounded-md font-medium text-indigo-600 hover:text-indigo-500 focus-within:outline-none focus-within:ring-2 focus-within:ring-offset-2 focus-within:ring-indigo-500">
                        <span>Carregar arquivo</span>
                        <input id="file-upload" name="file-upload" type="file" className="sr-only" onChange={handleFileChange} accept="image/*,.pdf" />
                      </label>
                      <p className="pl-1">ou arraste e solte</p>
                    </div>
                    <p className="text-xs text-slate-500">PNG, JPG, PDF até 5MB</p>
                  </>
                )}
              </div>
            </div>
          </div>

          {/* Info Box */}
          <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 flex items-start gap-3">
             <AlertTriangle className="text-blue-500 shrink-0 mt-0.5" size={20} />
             <div className="text-sm text-blue-800">
               <p className="font-semibold">Atenção Líderes:</p>
               <p>O sistema calcula o tempo exato entre a entrada e saída. Certifique-se de descontar intervalos de almoço se necessário, registrando dois períodos separados.</p>
             </div>
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee || !isTimeValid || (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0)}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee || !isTimeValid || (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Salvando...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  Registrar Ocorrência
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

