import { createClient } from '@supabase/supabase-js';
import { Employee, TimeRecord, Attachment } from '../types';
import { INITIAL_EMPLOYEES, INITIAL_RECORDS } from '../constants';

// ============================================================================
// SUPABASE CONFIGURATION
// ============================================================================
const SUPABASE_URL = (import.meta as any).env?.VITE_SUPABASE_URL || process.env.NEXT_PUBLIC_SUPABASE_URL || '';
const SUPABASE_ANON_KEY = (import.meta as any).env?.VITE_SUPABASE_ANON_KEY || process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY || '';

const supabase = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

// Bucket name for file uploads
const BUCKET_NAME = 'attachments';

export const sheetService = {

  // --- AUTHENTICATION (Simulated via Table Query) ---
  login: async (username: string, password: string): Promise<{ success: boolean; user?: Employee; message?: string }> => {
    if (!SUPABASE_URL) return { success: false, message: "Supabase não configurado." };

    try {
      // 1. Find user by username
      const { data: user, error } = await supabase
        .from('employees')
        .select('*')
        .eq('username', username)
        .eq('active', true)
        .single();

      if (error || !user) {
        return { success: false, message: "Usuário não encontrado." };
      }

      // 2. Simple password check (In production, use Supabase Auth or BCrypt)
      // Assuming 'password' column exists in employees table for this legacy migration
      if (user.password !== password) {
        return { success: false, message: "Senha incorreta." };
      }

      return { success: true, user: user as Employee };
    } catch (e) {
      console.error("Login failed:", e);
      return { success: false, message: "Erro de conexão." };
    }
  },

  // --- EMPLOYEES ---
  getEmployees: async (): Promise<Employee[]> => {
    if (!SUPABASE_URL) return INITIAL_EMPLOYEES;

    const { data, error } = await supabase
      .from('employees')
      .select('*')
      .order('name');

    if (error) {
      console.error("Error fetching employees:", error);
      return [];
    }
    return data as Employee[];
  },

  addEmployee: async (employee: Employee): Promise<void> => {
    await supabase.from('employees').insert([employee]);
  },

  updateEmployee: async (updatedEmployee: Employee): Promise<void> => {
    const { id, ...updates } = updatedEmployee;
    await supabase.from('employees').update(updates).eq('id', id);
  },

  deleteEmployee: async (id: string): Promise<boolean> => {
    const { error } = await supabase.from('employees').delete().eq('id', id);
    return !error;
  },

  // --- RECORDS (Time Entries) ---
  getRecords: async (): Promise<TimeRecord[]> => {
    if (!SUPABASE_URL) return INITIAL_RECORDS;

    // Fetch time_entries and join attachments
    const { data, error } = await supabase
      .from('time_entries')
      .select(`
        *,
        attachments (
          id,
          file_url,
          file_name
        )
      `)
      .order('timestamp', { ascending: false });

    if (error) {
      console.error("Error fetching records:", error);
      return [];
    }

    // Map SQL structure to App 'TimeRecord' structure
    return data.map((entry: any) => ({
      id: entry.id,
      employeeId: entry.user_id,
      employeeName: entry.employee_name || 'Unknown', // Ideally join employees table too
      date: entry.date, // YYYY-MM-DD
      hours: entry.hours,
      minutes: entry.minutes,
      startTime: entry.start_time,
      endTime: entry.end_time,
      type: entry.entry_type,
      occurrenceType: entry.occurrence_type,
      reason: entry.comments,
      createdAt: entry.created_at,
      createdBy: entry.created_by,
      // Map first attachment if exists
      attachment: entry.attachments && entry.attachments.length > 0 ? {
        id: entry.attachments[0].id,
        url: entry.attachments[0].file_url,
        name: entry.attachments[0].file_name
      } : undefined
    }));
  },

  addRecord: async (record: TimeRecord, attachmentFile?: File): Promise<void> => {
    try {
      // 1. Insert Time Entry
      const { data: entryData, error: entryError } = await supabase
        .from('time_entries')
        .insert([{
          id: record.id,
          user_id: record.employeeId,
          employee_name: record.employeeName, // Denormalized for easier query
          date: record.date,
          hours: record.hours,
          minutes: record.minutes,
          start_time: record.startTime,
          end_time: record.endTime,
          entry_type: record.type, // Credit/Debit
          occurrence_type: record.occurrenceType,
          comments: record.reason,
          created_at: record.createdAt,
          created_by: record.createdBy,
          timestamp: new Date(record.date).toISOString() // For prompt compliance
        }])
        .select()
        .single();

      if (entryError) throw entryError;

      // 2. Upload Attachment if present
      if (attachmentFile && entryData) {
        const fileExt = attachmentFile.name.split('.').pop();
        const fileName = `${record.id}.${fileExt}`;
        const filePath = `${entryData.user_id}/${fileName}`;

        const { error: uploadError } = await supabase.storage
          .from(BUCKET_NAME)
          .upload(filePath, attachmentFile);

        if (uploadError) {
           console.error("Error uploading file:", uploadError);
           // Continue to save metadata even if upload fails, or handle error
        } else {
           // Get Public URL
           const { data: { publicUrl } } = supabase.storage
             .from(BUCKET_NAME)
             .getPublicUrl(filePath);

           // 3. Insert Attachment Record
           await supabase
             .from('attachments')
             .insert([{
               entry_id: record.id,
               file_name: attachmentFile.name,
               file_url: publicUrl
             }]);
        }
      }
    } catch (e) {
      console.error("Failed to add record:", e);
      throw e;
    }
  },

  updateRecord: async (record: TimeRecord): Promise<boolean> => {
    const { error } = await supabase
      .from('time_entries')
      .update({
        date: record.date,
        hours: record.hours,
        minutes: record.minutes,
        start_time: record.startTime,
        end_time: record.endTime,
        entry_type: record.type,
        occurrence_type: record.occurrenceType,
        comments: record.reason
      })
      .eq('id', record.id);

    return !error;
  },

  deleteRecord: async (id: string): Promise<boolean> => {
    const { error } = await supabase.from('time_entries').delete().eq('id', id);
    return !error;
  },

  // Expose bucket upload helper directly if needed
  uploadAttachment: async (file: File, path: string) => {
    return await supabase.storage.from(BUCKET_NAME).upload(path, file);
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Upload, File as FileIcon, X, Loader2 } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { sheetService } from '../services/sheetService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Attachment State
  const [attachment, setAttachment] = useState<File | null>(null);

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Update Mapped Record Type when Occurrence Selection Changes
  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
  }, [occurrenceType]);

  // Calculate duration whenever times change
  useEffect(() => {
    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);

    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime]);

  // Filter employees
  const availableEmployees = employees;
  const filteredEmployees = availableEmployees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setAttachment(e.target.files[0]);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !reason || !startTime || !endTime || !isTimeValid) return;

    if (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
      alert("A duração deve ser maior que zero.");
      return;
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: calculatedDuration.hours,
      minutes: calculatedDuration.minutes,
      startTime,
      endTime,
      type: mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      // Pass attachment to service (it handles upload)
      await sheetService.addRecord(newRecord, attachment || undefined);

      setSuccess(true);
      onRecordAdded();

      // Reset form
      setSelectedEmployee('');
      setSearchTerm('');
      setStartTime('');
      setEndTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');
      setAttachment(null);

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Error saving record", error);
      alert("Erro ao salvar o registro.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">Ocorrência registrada com sucesso.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Registre o período da ocorrência para cálculo automático.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
