export const firebaseService = {
  auth,
  db,

  // Login com Google
  async signInWithGoogle(): Promise<{ success: boolean; user?: Employee; message?: string }> {
    try {
      const result = await signInWithPopup(auth, googleProvider);
      const user = result.user;

      // Busca ou cria o perfil no Firestore com a regra de ADMIN
      const employeeProfile = await this.getOrCreateProfile(user);

      return { success: true, user: employeeProfile };
    } catch (error: any) {
      console.error("Firebase Login Error:", error);
      return { success: false, message: error.message || "Erro ao conectar com Google." };
    }
  },

  // Verifica se o usuário já existe no Firestore, se não, cria.
  // APLICA REGRA DE NEGÓCIO: ti@arcaplast.com.br é sempre ADMIN na criação.
  async getOrCreateProfile(user: User): Promise<Employee> {
    const userRef = doc(db, 'employees', user.uid);
    const userSnap = await getDoc(userRef);

    if (userSnap.exists()) {
      return userSnap.data() as Employee;
    }

    // --- REGRA DE EXCEÇÃO PARA O DONO DO PROJETO ---
    const email = user.email?.toLowerCase() || '';
    const isSuperAdmin = email === 'ti@arcaplast.com.br';

    // Define Role inicial
    const initialRole = isSuperAdmin ? Role.ADMIN : Role.EMPLOYEE;

    const newEmployee: Employee = {
      id: user.uid,
      name: user.displayName || 'Colaborador',
      email: email,
      username: email.split('@')[0], // Gera username base do email
      role: initialRole,
      team: 'Geral', // Default
      company: 'Arca Plast', // Default
      active: true,
      // Password não é necessário com Auth Provider
    };

    // Salva no Firestore
    await setDoc(userRef, newEmployee);
    return newEmployee;
  }
};

