import { 
  signInWithEmailAndPassword, 
  signOut, 
  User 
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  getDocs, 
  where, 
  orderBy, 
  deleteDoc, 
  updateDoc,
  serverTimestamp 
} from 'firebase/firestore';
import { auth, db } from '../lib/firebase';
import { Employee, Role, TimeRecord } from '../types';

export const firebaseService = {
  auth,
  db,

  // --- AUTHENTICATION ---

  async login(email: string, pass: string): Promise<{ success: boolean; user?: Employee; message?: string }> {
    try {
      if (!auth) {
         throw new Error("Serviço de autenticação não está pronto.");
      }

      const userCredential = await signInWithEmailAndPassword(auth, email, pass);
      const profile = await this.getOrCreateProfile(userCredential.user);
      return { success: true, user: profile };
    } catch (error: any) {
      console.error("Login Error:", error);
      let msg = "Erro ao realizar login.";

      if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found') {
        msg = "E-mail ou senha inválidos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas. Tente novamente mais tarde.";
      } else if (error.code === 'auth/network-request-failed') {
        msg = "Erro de conexão. Verifique sua internet.";
      }

      return { success: false, message: msg };
    }
  },

  async logout(): Promise<void> {
    if (auth) await signOut(auth);
  },

  // --- USER PROFILE ---

  async getUserProfile(uid: string): Promise<Employee | null> {
    try {
      const docRef = doc(db, 'employees', uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? (docSnap.data() as Employee) : null;
    } catch (e) {
      console.error("Erro ao buscar perfil:", e);
      return null;
    }
  },

  async getOrCreateProfile(user: User, name?: string): Promise<Employee> {
    const email = user.email?.toLowerCase() || '';
    const isSuperAdmin = email === 'ti@arcaplast.com.br';

    const existingProfile = await this.getUserProfile(user.uid);

    if (existingProfile) {
      if (isSuperAdmin && existingProfile.role !== Role.ADMIN) {
        console.log("Atualizando permissão de Super Admin...");
        const updated = { ...existingProfile, role: Role.ADMIN };
        await setDoc(doc(db, 'employees', user.uid), updated, { merge: true });
        return updated;
      }
      return existingProfile;
    }

    console.log("Criando novo perfil para:", email);
    const newEmployee: Employee = {
      id: user.uid,
      name: name || user.displayName || 'Colaborador',
      email: email,
      username: email.split('@')[0],
      role: isSuperAdmin ? Role.ADMIN : Role.EMPLOYEE,
      team: 'Geral',
      company: 'Arca Plast',
      active: true
    };

    await setDoc(doc(db, 'employees', user.uid), newEmployee);
    return newEmployee;
  },

  // --- EMPLOYEES CRUD ---

  // Função alias para satisfazer a solicitação específica, mas reutiliza getEmployees
  // pois os dados de usuários estão na coleção 'employees'
  async getAllUsers(): Promise<Employee[]> {
    return this.getEmployees();
  },

  async getEmployees(): Promise<Employee[]> {
    try {
      const q = query(collection(db, 'employees'), orderBy('name'));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => doc.data() as Employee);
    } catch (e) {
      console.error("Error fetching employees:", e);
      return [];
    }
  },

  async updateUserRole(uid: string, newRole: Role): Promise<boolean> {
    try {
      const docRef = doc(db, 'employees', uid);
      await updateDoc(docRef, { role: newRole });
      return true;
    } catch (e) {
      console.error("Erro ao atualizar cargo:", e);
      return false;
    }
  },

  async addEmployee(employee: Employee): Promise<void> {
    await setDoc(doc(db, 'employees', employee.id), employee);
  },

  async updateEmployee(employee: Employee): Promise<void> {
    const { id, ...data } = employee;
    await updateDoc(doc(db, 'employees', id), data as any);
  },

  async deleteEmployee(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'employees', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  // --- TIME RECORDS CRUD ---

  async saveTimeRecord(record: TimeRecord): Promise<void> {
    // Garante que o timestamp é do servidor para evitar fraudes de horário local
    await setDoc(doc(db, 'time_records', record.id), {
      ...record,
      timestamp: serverTimestamp() // Importante: Data de criação segura
    });
  },

  async getRecords(): Promise<TimeRecord[]> {
    try {
      const q = query(collection(db, 'time_records'), orderBy('date', 'desc'));
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error("Error fetching records:", e);
      return [];
    }
  },

  // Novo método para buscar registros de um usuário específico
  async getUserRecords(userId: string): Promise<TimeRecord[]> {
    try {
      const q = query(
        collection(db, 'time_records'), 
        where('employeeId', '==', userId),
        orderBy('date', 'desc')
      );
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error(`Error fetching records for user ${userId}:`, e);
      return [];
    }
  },

  async updateRecord(record: TimeRecord): Promise<boolean> {
    try {
      const { id, ...data } = record;
      await updateDoc(doc(db, 'time_records', id), data as any);
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  async deleteRecord(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'time_records', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  }
};

import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Building2, Save } from 'lucide-react';
import { Employee, Role } from '../types';
import { TEAMS, COMPANIES } from '../constants';
import { firebaseService } from '../services/firebaseService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
  currentUser: Employee; // Adicionado para verificação de segurança na UI
}

const EmployeeList: React.FC<EmployeeListProps> = ({ employees, refreshData, currentUser }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Optimistic UI state
  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  // Form State for Add/Edit Modal
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState(TEAMS[0]);
  const [newCompany, setNewCompany] = useState(COMPANIES[0]);

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase()) ||
      e.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const handleRoleChange = async (userId: string, newRole: Role) => {
    if (userId === currentUser.id) {
        alert("Você não pode alterar seu próprio cargo nesta tela.");
        return;
    }
    setLoadingAction(`role-${userId}`);
    try {
        const success = await firebaseService.updateUserRole(userId, newRole);
        if (success) {
            refreshData();
        } else {
            alert("Erro ao atualizar cargo.");
        }
    } catch (error) {
        console.error("Erro ao mudar role:", error);
    } finally {
        setLoadingAction(null);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewEmail('');
    setNewRole(Role.EMPLOYEE);
    setNewTeam(TEAMS[0]);
    setNewCompany(COMPANIES[0]);
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewEmail(employee.email || '');
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setNewCompany(employee.company || COMPANIES[0]);
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoadingAction('save');

    // Gerador de username simples
    let finalUsername = '';
    if (newEmail && newEmail.includes('@')) {
         finalUsername = newEmail.split('@')[0];
    } else {
         const cleanName = newName.toLowerCase().trim().split(' ');
         finalUsername = cleanName[0];
    }

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: finalUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      company: newCompany,
      active: true,
    };

    try {
      if (editingId) {
        await firebaseService.updateEmployee(employeeData);
      } else {
        await firebaseService.addEmployee(employeeData);
      }
      refreshData();
      setIsModalOpen(false);
    } catch (error) {
      console.error("Error saving employee:", error);
      alert("Erro ao salvar.");
    } finally {
      setLoadingAction(null);
      setEditingId(null);
    }
  };

  const handleDelete = async (id: string) => {
    if (id === currentUser.id) {
        alert("Você não pode excluir sua própria conta.");
        return;
    }
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await firebaseService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir do banco de dados.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  const isAdmin = currentUser.role === Role.ADMIN;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
           <p className="text-sm text-slate-500">
             {employees.length} usuários cadastrados
           </p>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={openAddModal}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome, email ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* List */}
      <div className="bg-white shadow-sm border border-slate-200 rounded-xl overflow-hidden">
        {employees.length === 0 ? (
           <div className="p-10 flex flex-col items-center justify-center text-slate-400">
              <Loader2 className="w-8 h-8 animate-spin mb-2" />
              <p>Carregando colaboradores...</p>
           </div>
        ) : (
        <ul className="divide-y divide-slate-200">
          {filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 hover:bg-slate-50 transition-colors animate-fade-in">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">

                {/* User Info */}
                <div className="flex items-center min-w-0 gap-4 flex-1">
                  <div className="h-10 w-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 shrink-0">
                    <User size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-slate-900 truncate flex items-center gap-2">
                      {employee.name}
                      {employee.id === currentUser.id && <span className="text-xs bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full">Você</span>}
                    </p>
                    <p className="text-xs text-slate-500 flex items-center mt-0.5">
                       <Building2 size={10} className="mr-1" />
                       {employee.company || 'Empresa não informada'} • {employee.team}
                    </p>
                    <p className="text-xs text-slate-400 mt-0.5">{employee.email || 'Sem email vinculado'}</p>
                  </div>
                </div>

                {/* Actions & Role Management */}
                <div className="flex items-center gap-4 justify-between md:justify-end w-full md:w-auto">

                  {/* Role Selector (Admin Only) or Badge */}
                  <div className="flex flex-col items-end min-w-[140px]">
                    {isAdmin ? (
                        <div className="relative">
                            <select 
                                value={employee.role}
                                disabled={loadingAction === `role-${employee.id}` || employee.id === currentUser.id}
                                onChange={(e) => handleRoleChange(employee.id, e.target.value as Role)}
                                className={`appearance-none block w-full pl-3 pr-8 py-1.5 text-xs font-medium rounded-full border focus:outline-none focus:ring-2 focus:ring-offset-1 transition-colors cursor-pointer
                                    ${employee.role === Role.ADMIN ? 'bg-purple-50 text-purple-700 border-purple-200 focus:ring-purple-500' : 
                                      employee.role === Role.LEADER ? 'bg-blue-50 text-blue-700 border-blue-200 focus:ring-blue-500' : 
                                      'bg-slate-50 text-slate-700 border-slate-200 focus:ring-slate-500'}
                                    ${loadingAction === `role-${employee.id}` ? 'opacity-50' : ''}
                                `}
                            >
                                <option value={Role.EMPLOYEE}>Colaborador</option>
                                <option value={Role.LEADER}>Líder</option>
                                <option value={Role.ADMIN}>Administrador</option>
                            </select>
                            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                                {loadingAction === `role-${employee.id}` ? (
                                    <Loader2 size={12} className="animate-spin" />
                                ) : (
                                    <svg className="h-3 w-3 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" fillRule="evenodd"></path></svg>
                                )}
                            </div>
                        </div>
                    ) : (
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium capitalize ${
                          employee.role === Role.ADMIN ? 'bg-purple-100 text-purple-800' :
                          employee.role === Role.LEADER ? 'bg-blue-100 text-blue-800' :
                          'bg-slate-100 text-slate-800'
                        }`}>
                          {employee.role === Role.ADMIN ? <Shield size={10} className="mr-1"/> : <Briefcase size={10} className="mr-1"/>}
                          {employee.role === Role.ADMIN ? 'Administrador' : employee.role === Role.LEADER ? 'Líder' : 'Colaborador'}
                        </span>
                    )}
                  </div>

                  {/* Edit/Delete Buttons (Admin Only) */}
                  {isAdmin && (
                      <div className="flex items-center gap-1 border-l border-slate-200 pl-3 ml-2">
                        <button 
                          onClick={() => openEditModal(employee)}
                          className="text-slate-400 hover:text-indigo-600 transition-colors p-2 rounded-full hover:bg-indigo-50"
                          title="Editar Detalhes"
                          disabled={loadingAction !== null}
                        >
                          <Edit size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(employee.id)}
                          className={`text-slate-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50 ${employee.id === currentUser.id ? 'opacity-20 cursor-not-allowed' : ''}`}
                          title="Excluir"
                          disabled={loadingAction !== null || employee.id === currentUser.id}
                        >
                          {loadingAction === employee.id ? (
                            <Loader2 size={18} className="animate-spin text-red-600" />
                          ) : (
                            <Trash2 size={18} />
                          )}
                        </button>
                      </div>
                  )}
                </div>
              </div>
            </li>
          ))}
          {filteredEmployees.length === 0 && (
            <li className="p-8 text-center text-slate-500">
              Nenhum colaborador encontrado com este filtro.
            </li>
          )}
        </ul>
        )}
      </div>

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="mb-4">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Editar Colaborador' : 'Pré-cadastrar Colaborador'}
              </h3>
              <p className="text-xs text-slate-500">
                  {editingId ? 'Atualizar dados cadastrais.' : 'Cria um perfil que será vinculado quando o usuário fizer login.'}
              </p>
            </div>

            <form onSubmit={handleSaveEmployee} className="space-y-4 overflow-y-auto pr-3 custom-scrollbar flex-1 min-h-0">
              <div>
                <label className="block text-sm font-medium text-slate-700">Nome Completo</label>
                <input required type="text" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newName} onChange={e => setNewName(e.target.value)} />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700">Email <span className="text-slate-400 text-xs">(Vinculação Google/Firebase)</span></label>
                <input 
                  type="email" 
                  required
                  placeholder="email@arcaplast.com.br"
                  className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                  value={newEmail} 
                  onChange={e => setNewEmail(e.target.value)} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Empresa</label>
                    <select className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newCompany} onChange={e => setNewCompany(e.target.value)}>
                      {COMPANIES.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Equipe</label>
                    <select className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newTeam} onChange={e => setNewTeam(e.target.value)}>
                      {TEAMS.map(t => <option key={t} value={t}>{t}</option>)}
                    </select>
                 </div>
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                <button type="submit" disabled={loadingAction === 'save'} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center">
                  {loadingAction === 'save' && <Loader2 size={16} className="animate-spin mr-2" />}
                  {editingId ? 'Salvar Alterações' : 'Criar Perfil'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeList;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TimeEntryForm from './components/TimeEntryForm';
import EmployeeList from './components/EmployeeList';
import Reports from './components/Reports';
import Login from './components/Login';
import { Role, Employee, TimeRecord } from './types';
import { firebaseService } from './services/firebaseService';
import { Menu } from 'lucide-react';
import { onAuthStateChanged } from 'firebase/auth';

const App: React.FC = () => {
  // Debug Log
  useEffect(() => {
    console.log("🚀 App Component Mounted");
  }, []);

  // Application State
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [records, setRecords] = useState<TimeRecord[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Authentication State
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);

  // Load User Session Persistent
  useEffect(() => {
    // Check if auth is initialized safely
    if (!firebaseService.auth) {
      const msg = "Firebase Auth service not initialized. Verifique as configurações.";
      console.error(msg);
      setInitError(msg);
      setAuthChecked(true);
      return;
    }

    try {
      const unsubscribe = onAuthStateChanged(firebaseService.auth, async (user) => {
        console.log("Auth State Changed:", user ? `User: ${user.email}` : "No User");

        if (user) {
          try {
            const profile = await firebaseService.getOrCreateProfile(user);
            setCurrentUser(profile);
          } catch (e: any) {
            console.error("Error loading profile:", e);
            setInitError("Erro ao carregar perfil do usuário: " + e.message);
            setCurrentUser(null);
          }
        } else {
          setCurrentUser(null);
        }
        setAuthChecked(true);
      }, (error) => {
        console.error("Auth Subscription Error:", error);
        setInitError("Erro na conexão com autenticação.");
        setAuthChecked(true);
      });

      return () => unsubscribe();
    } catch (error: any) {
       console.error("Critical error setting up auth listener:", error);
       setInitError(error.message);
       setAuthChecked(true);
    }
  }, []);

  // Load Data function
  const fetchData = async () => {
    if (currentUser) {
      try {
        console.log("Fetching data from Firestore...");
        const emps = await firebaseService.getEmployees();
        const recs = await firebaseService.getRecords();

        setEmployees(emps);
        setRecords(recs);
        console.log("Data fetched successfully:", { employees: emps.length, records: recs.length });
      } catch (e) {
        console.error("Error fetching data:", e);
      }
    }
  };

  useEffect(() => {
    if (currentUser) {
      fetchData();
    }
  }, [currentUser]);

  const handleLoginSuccess = (user: Employee) => {
    setCurrentUser(user);
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    setCurrentUser(null);
    setEmployees([]);
    setRecords([]);
  };

  // Optimistic Update Helpers
  const handleLocalRecordUpdate = (updatedRecord: TimeRecord) => {
    setRecords(prevRecords => 
      prevRecords.map(r => r.id === updatedRecord.id ? updatedRecord : r)
    );
  };

  const handleLocalRecordDelete = (recordId: string) => {
    setRecords(prevRecords => prevRecords.filter(r => r.id !== recordId));
  };

  if (initError) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-red-50 p-4 text-center">
        <div className="bg-white p-6 rounded-lg shadow-lg max-w-md">
          <h2 className="text-red-600 text-xl font-bold mb-2">Erro de Inicialização</h2>
          <p className="text-slate-600">{initError}</p>
          <button 
            onClick={() => window.location.reload()}
            className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700"
          >
            Tentar Novamente
          </button>
        </div>
      </div>
    );
  }

  if (!authChecked) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-slate-100 space-y-4">
         <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
         <p className="text-slate-500 font-medium">Conectando ao banco de dados...</p>
      </div>
    );
  }

  // If not logged in, show Login Screen
  if (!currentUser) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  // Render Page Content based on route
  const renderContent = () => {
    try {
      switch (currentPage) {
        case 'dashboard':
          return <Dashboard records={records} employees={employees} />;
        case 'form':
          return <TimeEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} />;
        case 'employees':
          return currentUser.role === Role.ADMIN ? 
            <EmployeeList 
              employees={employees} 
              refreshData={fetchData} 
              currentUser={currentUser}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado. Esta área é restrita ao RH.</div>;
        case 'reports':
          return (currentUser.role === Role.ADMIN || currentUser.role === Role.LEADER) ? 
            <Reports 
              records={records} 
              employees={employees} 
              currentUser={currentUser} 
              refreshData={fetchData} 
              onUpdateRecord={handleLocalRecordUpdate}
              onDeleteRecord={handleLocalRecordDelete}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
        default:
          return <Dashboard records={records} employees={employees} />;
      }
    } catch (e) {
      console.error("Error rendering page content:", e);
      return <div className="p-4 text-red-500">Erro ao carregar conteúdo da página. Verifique o console.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-40 bg-slate-900 text-white p-4 flex justify-between items-center shadow-md">
         <span className="font-bold">Hurafy</span>
         <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
           <Menu size={24} />
         </button>
      </div>

      <Sidebar 
        currentUser={currentUser}
        currentRole={currentUser.role} 
        currentPage={currentPage} 
        setPage={(page) => {
          setCurrentPage(page);
          setIsSidebarOpen(false);
        }}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full pt-16 md:pt-0">
        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

