             <p className="text-sm">Clique no botão para importar a lista inicial de colaboradores.</p>
           </div>
        </div>
        <button 
          onClick={handleImport}
          disabled={importing}
          className={`
            font-bold py-3 px-6 rounded-lg shadow-lg flex items-center transition-all
            ${importStatus === 'success' ? 'bg-green-600 text-white' : 
