import { 
  signInWithEmailAndPassword, 
  signOut, 
  User 
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  getDocs, 
  where, 
  orderBy, 
  deleteDoc, 
  updateDoc,
  serverTimestamp,
  writeBatch
} from 'firebase/firestore';
import { auth, db } from '../lib/firebase';
import { Employee, Role, TimeRecord, RecordType } from '../types';

export const firebaseService = {
  auth,
  db,

  // --- AUTHENTICATION ---

  async login(email: string, pass: string): Promise<{ success: boolean; user?: Employee; message?: string }> {
    try {
      if (!auth) {
         throw new Error("Serviço de autenticação não está pronto.");
      }

      const userCredential = await signInWithEmailAndPassword(auth, email, pass);
      const profile = await this.getOrCreateProfile(userCredential.user);
      return { success: true, user: profile };
    } catch (error: any) {
      console.error("Login Error:", error);
      let msg = "Erro ao realizar login.";

      if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found') {
        msg = "E-mail ou senha inválidos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas. Tente novamente mais tarde.";
      } else if (error.code === 'auth/network-request-failed') {
        msg = "Erro de conexão. Verifique sua internet.";
      }

      return { success: false, message: msg };
    }
  },

  async logout(): Promise<void> {
    if (auth) await signOut(auth);
  },

  // --- USER PROFILE ---

  async getUserProfile(uid: string): Promise<Employee | null> {
    try {
      const docRef = doc(db, 'employees', uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? (docSnap.data() as Employee) : null;
    } catch (e) {
      console.error("Erro ao buscar perfil:", e);
      return null;
    }
  },

  async getOrCreateProfile(user: User, name?: string): Promise<Employee> {
    const email = user.email?.toLowerCase() || '';
    const isSuperAdmin = email === 'ti@arcaplast.com.br';

    // Tenta buscar pelo UID primeiro (Login padrão)
    let existingProfile = await this.getUserProfile(user.uid);

    // Se não achar pelo UID, tenta buscar pelo username (caso tenha sido importado via CSV e seja o primeiro login)
    if (!existingProfile && email) {
        const username = email.split('@')[0];
        const docRefUser = doc(db, 'employees', username);
        const docSnapUser = await getDoc(docRefUser);

        if (docSnapUser.exists()) {
            console.log("Perfil encontrado via username (importado). Vinculando UID...");
            existingProfile = docSnapUser.data() as Employee;
        }
    }

    if (existingProfile) {
      if (isSuperAdmin && existingProfile.role !== Role.ADMIN) {
        console.log("Atualizando permissão de Super Admin...");
        const updated = { ...existingProfile, role: Role.ADMIN };
        await setDoc(doc(db, 'employees', user.uid), updated, { merge: true });
        return updated;
      }
      return existingProfile;
    }

    console.log("Criando novo perfil para:", email);
    const newEmployee: Employee = {
      id: user.uid,
      name: name || user.displayName || 'Colaborador',
      email: email,
      username: email.split('@')[0],
      role: isSuperAdmin ? Role.ADMIN : Role.EMPLOYEE,
      team: 'Geral',
      company: 'Arca Plast',
      active: true
    };

    await setDoc(doc(db, 'employees', user.uid), newEmployee);
    return newEmployee;
  },

  // --- EMPLOYEES CRUD ---

  async getAllUsers(): Promise<Employee[]> {
    return this.getEmployees();
  },

  async getEmployees(): Promise<Employee[]> {
    try {
      const q = query(collection(db, 'employees'), orderBy('name'));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => doc.data() as Employee);
    } catch (e) {
      console.error("Error fetching employees:", e);
      return [];
    }
  },

  // Função robusta para deletar todos os usuários exceto TI e usuário atual
  async deleteAllEmployees(currentUserEmail: string): Promise<boolean> {
    console.log("🚀 LIMPEZA INICIADA...");

    try {
      const q = query(collection(db, 'employees'));
      const querySnapshot = await getDocs(q);

      const batch = writeBatch(db);
      let deleteCount = 0;

      querySnapshot.forEach((doc) => {
        const data = doc.data() as Employee;
        const email = data.email?.toLowerCase();

        // Proteção Crítica: Não apagar o Admin TI e nem o usuário que está logado executando a ação
        if (email === 'ti@arcaplast.com.br' || email === currentUserEmail?.toLowerCase()) {
          console.log(`🛡️ Protegendo usuário admin: ${data.name} (${email})`);
          return;
        }

        console.log(`🗑️ Agendando exclusão: ${data.name} (${doc.id})`);
        batch.delete(doc.ref);
        deleteCount++;
      });

      if (deleteCount > 0) {
        await batch.commit();
        console.log(`✅ LIMPEZA CONCLUÍDA! ${deleteCount} colaboradores removidos.`);
        return true;
      } else {
        console.log("ℹ️ Nenhum colaborador elegível para remoção encontrado.");
        return true;
      }
    } catch (error) {
      console.error("❌ Erro fatal ao limpar banco:", error);
      throw error;
    }
  },

  async importUsersFromCSV(usersList: any[]) {
    return this.importAllColaboradores(usersList);
  },

  async importAllColaboradores(usersList: any[]) {
    console.log(`🚀 Iniciando importação em lote de ${usersList.length} registros...`);
    try {
      const batch = writeBatch(db);
      let count = 0;

      usersList.forEach((user, index) => {
        if (!user.id || !user.name) {
          console.warn(`Linha ${index + 1} ignorada: ID ou Nome faltando.`);
          return;
        }

        // Garante que o ID não tenha espaços ou caracteres inválidos para documento
        const safeId = user.id.trim().toLowerCase();
        const userRef = doc(db, 'employees', safeId);

        // Mapeia os campos do CSV para a estrutura da interface Employee
        const userData = {
          id: safeId,
          username: safeId,
          name: user.name,
          email: `${safeId}@arcaplast.com.br`, 
          role: user.role,
          team: user.department, 
          department: user.department,
          company: user.company,
          active: true,
          canLogin: user.role === 'ADMIN' || user.role === 'LEADER',
          updatedAt: serverTimestamp()
        };

        console.log(`📄 Processando linha ${index + 1}: ${user.name}`);
        batch.set(userRef, userData, { merge: true });
        count++;
      });

      if (count > 0) {
        await batch.commit();
        console.log("✅ Lote (batch) enviado com sucesso ao Firebase!");
        return true;
      } else {
        console.log("⚠️ Nenhum registro válido para importar.");
        return false;
      }
    } catch (error) {
      console.error("❌ Erro detalhado na importação:", error);
      throw error;
    }
  },

  async updateUserRole(uid: string, newRole: Role): Promise<boolean> {
    try {
      const docRef = doc(db, 'employees', uid);
      await updateDoc(docRef, { role: newRole });
      return true;
    } catch (e) {
      console.error("Erro ao atualizar cargo:", e);
      return false;
    }
  },

  async addEmployee(employee: Employee): Promise<void> {
    await setDoc(doc(db, 'employees', employee.id), employee);
  },

  async updateEmployee(employee: Employee): Promise<void> {
    const { id, ...data } = employee;
    await updateDoc(doc(db, 'employees', id), data as any);
  },

  async deleteEmployee(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'employees', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  // --- TIME RECORDS CRUD ---

  async saveTimeRecord(record: TimeRecord): Promise<void> {
    await setDoc(doc(db, 'time_records', record.id), {
      ...record,
      timestamp: serverTimestamp()
    });
  },

  // Nova função para lançamentos manuais do RH
  async saveManualOccurrence(occurrenceData: any): Promise<void> {
    try {
      // Reutiliza a estrutura de TimeRecord, mas mapeia campos específicos se necessário
      // occurrenceData já deve vir formatado ou podemos formatar aqui
      await setDoc(doc(db, 'time_records', occurrenceData.id), {
        ...occurrenceData,
        timestamp: serverTimestamp()
      });
      console.log("✅ Ocorrência manual salva com sucesso.");
    } catch (e) {
      console.error("Erro ao salvar ocorrência manual:", e);
      throw e;
    }
  },

  async getRecords(): Promise<TimeRecord[]> {
    try {
      const q = query(collection(db, 'time_records'), orderBy('date', 'desc'));
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error("Error fetching records:", e);
      return [];
    }
  },

  async getUserRecords(userId: string): Promise<TimeRecord[]> {
    try {
      const q = query(
        collection(db, 'time_records'), 
        where('employeeId', '==', userId),
        orderBy('date', 'desc')
      );
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error(`Error fetching records for user ${userId}:`, e);
      return [];
    }
  },

  async updateRecord(record: TimeRecord): Promise<boolean> {
    try {
      const { id, ...data } = record;
      await updateDoc(doc(db, 'time_records', id), data as any);
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  async deleteRecord(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'time_records', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  }
};

import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend 
} from 'recharts';
import { Clock, Users, TrendingUp, TrendingDown, Info, Filter, X, Briefcase, Building2 } from 'lucide-react';
import { TimeRecord, Employee, RecordType } from '../types';

interface DashboardProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, employees }) => {
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');
  const [selectedEmpId, setSelectedEmpId] = useState<string>('');

  // --- EXISTING DASHBOARD LOGIC ---

  // 1. Extract Unique Companies
  const companies = useMemo(() => {
    const unique = new Set(employees.map(e => e.company).filter(Boolean));
    return Array.from(unique).sort();
  }, [employees]);

  // 2. Extract Available Teams (Filtered by selected Company)
  const availableTeams = useMemo(() => {
    let filtered = employees;
    if (selectedCompany) {
      filtered = filtered.filter(e => e.company === selectedCompany);
    }
    const unique = new Set(filtered.map(e => e.team).filter(Boolean));
    return Array.from(unique).sort();
  }, [employees, selectedCompany]);

  // 3. Filter Available Employees (Filtered by Company AND Team)
  const availableEmployees = useMemo(() => {
    let result = employees;
    if (selectedCompany) {
      result = result.filter(e => e.company === selectedCompany);
    }
    if (selectedTeam) {
      result = result.filter(e => e.team === selectedTeam);
    }
    return result;
  }, [employees, selectedCompany, selectedTeam]);

  // 4. Filter Records based on the filtered employees
  const filteredRecords = useMemo(() => {
    // Começamos com os registros reais vindos do Firebase
    let result = records || [];

    // Get valid employee IDs based on current filters (Company/Team)
    const validEmployeeIds = availableEmployees.map(e => e.id);

    // First, filter records to only show those belonging to the currently filtered employee pool
    result = result.filter(r => validEmployeeIds.includes(r.employeeId));

    // Finally, if a specific employee is selected, filter just for them
    if (selectedEmpId) {
      result = result.filter(r => r.employeeId === selectedEmpId);
    }

    return result;
  }, [records, availableEmployees, selectedEmpId]);

  // Handle Changes
  const handleCompanyChange = (company: string) => {
    setSelectedCompany(company);
    setSelectedTeam(''); // Reset team when company changes
    setSelectedEmpId(''); // Reset employee
  };

  const handleTeamChange = (team: string) => {
    setSelectedTeam(team);
    setSelectedEmpId(''); // Reset employee when team changes
  };

  // 5. Calculate stats
  const stats = useMemo(() => {
    let totalMinutes = 0;
    let positiveMins = 0;
    let negativeMins = 0;
    let neutralCount = 0;

    filteredRecords.forEach(r => {
      const mins = (r.hours * 60) + r.minutes;
      if (r.type === RecordType.CREDIT) {
        positiveMins += mins;
        totalMinutes += mins;
      } else if (r.type === RecordType.DEBIT) {
        negativeMins += mins;
        totalMinutes -= mins;
      } else {
        neutralCount++;
      }
    });

    const isPositive = totalMinutes >= 0;
    const absTotalMinutes = Math.abs(totalMinutes);

    // Calculate Active Employee Count based on current filter scope
    let activeCount = 0;
    if (selectedEmpId) {
      activeCount = 1;
    } else {
      activeCount = availableEmployees.filter(e => e.active).length;
    }

    return {
      balance: `${isPositive ? '' : '-'}${Math.floor(absTotalMinutes / 60)}:${(absTotalMinutes % 60).toString().padStart(2, '0')}`,
      positive: Math.floor(positiveMins / 60) + 'h ' + (positiveMins % 60) + 'm',
      negative: Math.floor(negativeMins / 60) + 'h ' + (negativeMins % 60) + 'm',
      neutralCount,
      employeeCount: activeCount,
      isPositive
    };
  }, [filteredRecords, availableEmployees, selectedEmpId]);

  // 6. Data for CHART 1: BY COMPANY (Always visible/aggregated)
  const companyChartData = useMemo(() => {
    const dataMap: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};

    // Usa records filtrados pelos critérios atuais
    filteredRecords.forEach(r => {
      const emp = employees.find(e => e.id === r.employeeId);
      const groupKey = emp ? emp.company : 'Desconhecido';

      const hours = r.hours + (r.minutes / 60);

      if (!dataMap[groupKey]) {
        dataMap[groupKey] = { name: groupKey, horasPositivas: 0, horasNegativas: 0 };
      }

      if (r.type === RecordType.CREDIT) {
        dataMap[groupKey].horasPositivas += hours;
      } else if (r.type === RecordType.DEBIT) {
        dataMap[groupKey].horasNegativas += hours;
      }
    });
    return Object.values(dataMap);
  }, [filteredRecords, employees]);

  // 7. Data for CHART 2: BY SECTOR (Drilldown: Team -> Employee)
  const drillDownChartData = useMemo(() => {
    const dataMap: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};

    filteredRecords.forEach(r => {
      let groupKey = '';

      if (selectedEmpId) {
         // If single employee selected, breakdown by OccurrenceType
         groupKey = r.occurrenceType || 'Geral';
      } else if (selectedTeam) {
         // Viewing a Team: Group by Employee Name
         groupKey = r.employeeName;
      } else {
         // Global or Company View: Group by Team
         const emp = employees.find(e => e.id === r.employeeId);
         groupKey = emp ? emp.team : 'Outros'; 
      }

      const hours = r.hours + (r.minutes / 60);

      if (!dataMap[groupKey]) {
        dataMap[groupKey] = { name: groupKey, horasPositivas: 0, horasNegativas: 0 };
      }

      if (r.type === RecordType.CREDIT) {
        dataMap[groupKey].horasPositivas += hours;
      } else if (r.type === RecordType.DEBIT) {
        dataMap[groupKey].horasNegativas += hours;
      }
    });

    return Object.values(dataMap);
  }, [filteredRecords, employees, selectedTeam, selectedEmpId]);

  const typeData = [
    { name: 'Horas Positivas', value: parseFloat(stats.positive.split('h')[0]) },
    { name: 'Horas Negativas', value: parseFloat(stats.negative.split('h')[0]) }
  ];

  const COLORS = ['#10b981', '#ef4444'];

  const getDashboardTitle = () => {
    if (selectedEmpId) return 'Visão Individual';
    if (selectedTeam) return `Setor: ${selectedTeam}`;
    if (selectedCompany) return `Empresa: ${selectedCompany}`;
    return 'Visão Geral (Holding)';
  };

  const getDashboardSubtitle = () => {
    if (selectedEmpId) return `Analisando saldo de: ${employees.find(e => e.id === selectedEmpId)?.name}`;
    if (selectedTeam) return 'Acompanhamento de banco de horas da equipe';
    if (selectedCompany) return 'Visão consolidada da empresa';
    return 'Acompanhamento global de todas as empresas';
  };

  return (
    <div className="space-y-6 animate-fade-in">

      {/* Header with Filters */}
      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-slate-800">
            {getDashboardTitle()}
          </h2>
          <p className="text-sm text-slate-500">
            {getDashboardSubtitle()}
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">

          {/* Company Filter */}
          <div className="relative min-w-[200px]">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Building2 className="h-4 w-4 text-slate-400" />
            </div>
            <select
              value={selectedCompany}
              onChange={(e) => handleCompanyChange(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-indigo-500 focus:border-indigo-500 text-sm text-slate-700 shadow-sm"
            >
              <option value="">Todas Empresas</option>
              {companies.map(company => (
                <option key={company} value={company}>{company}</option>
              ))}
            </select>
            {selectedCompany && (
              <button 
                onClick={() => handleCompanyChange('')}
                className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
                title="Limpar empresa"
              >
                <X size={14} />
              </button>
            )}
            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
              <Filter className="h-4 w-4 text-slate-400" />
            </div>
          </div>

          {/* Team Filter */}
          <div className="relative min-w-[200px]">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Briefcase className="h-4 w-4 text-slate-400" />
            </div>
            <select
              value={selectedTeam}
              onChange={(e) => handleTeamChange(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-indigo-500 focus:border-indigo-500 text-sm text-slate-700 shadow-sm"
            >
              <option value="">Todos Setores</option>
              {availableTeams.map(team => (
                <option key={team} value={team}>{team}</option>
              ))}
            </select>
            {selectedTeam && (
              <button 
                onClick={() => handleTeamChange('')}
                className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
                title="Limpar setor"
              >
                <X size={14} />
              </button>
            )}
            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
              <Filter className="h-4 w-4 text-slate-400" />
            </div>
          </div>

          {/* Employee Filter */}
          <div className="relative min-w-[240px]">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Users className="h-4 w-4 text-slate-400" />
            </div>
            <select
              value={selectedEmpId}
              onChange={(e) => setSelectedEmpId(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-indigo-500 focus:border-indigo-500 text-sm text-slate-700 shadow-sm"
            >
              <option value="">{selectedTeam ? 'Todos da Equipe' : 'Todos Colaboradores'}</option>
              {availableEmployees.map(emp => (
                <option key={emp.id} value={emp.id}>
                  {emp.name}
                </option>
              ))}
            </select>
            {selectedEmpId && (
              <button 
                onClick={() => setSelectedEmpId('')}
                className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
                title="Limpar colaborador"
              >
                <X size={14} />
              </button>
            )}
             <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
              <Filter className="h-4 w-4 text-slate-400" />
            </div>
          </div>
        </div>
      </div>

      {/* Stats Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-indigo-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Saldo {selectedEmpId ? 'Atual' : (selectedTeam ? 'do Setor' : (selectedCompany ? 'da Empresa' : 'Global'))}</p>
              <h3 className={`text-2xl font-bold mt-1 ${stats.isPositive ? 'text-emerald-600' : 'text-red-600'}`}>
                {stats.balance} h
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${stats.isPositive ? 'bg-emerald-100 text-emerald-600' : 'bg-red-100 text-red-600'}`}>
              <Clock size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId ? 'Saldo líquido do colaborador' : 'Saldo líquido acumulado'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-blue-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Colaboradores</p>
              <h3 className="text-2xl font-bold mt-1 text-slate-800">{stats.employeeCount}</h3>
            </div>
            <div className="p-2 rounded-lg bg-blue-100 text-blue-600">
              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId 
              ? 'Visualizando 1 colaborador' 
              : 'Ativos neste filtro'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-emerald-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Positivo</p>
              <h3 className="text-2xl font-bold mt-1 text-emerald-600">+{stats.positive}</h3>
            </div>
            <div className="p-2 rounded-lg bg-emerald-100 text-emerald-600">
              <TrendingUp size={20} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-red-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Negativo</p>
              <h3 className="text-2xl font-bold mt-1 text-red-600">-{stats.negative}</h3>
            </div>
            <div className="p-2 rounded-lg bg-red-100 text-red-600">
              <TrendingDown size={20} />
            </div>
          </div>
        </div>
      </div>

      {stats.neutralCount > 0 && (
         <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 flex items-center text-slate-600">
            <Info className="w-5 h-5 mr-2" />
            <span className="text-sm">
              Existem {stats.neutralCount} registros informativos (Atestados, Exames, etc) neste filtro.
            </span>
         </div>
      )}

      {/* Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        {/* Chart 1: Company Overview */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Horas por Empresa</h3>
          <div className="h-80 w-full">
            {companyChartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={companyChartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }} barGap={8}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis 
                    dataKey="name" 
                    tick={{fill: '#64748b', fontSize: 11}} 
                    axisLine={false} 
                    tickLine={false} 
                    interval={0}
                  />
                  <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{fill: '#f1f5f9'}}
                  />
                  <Legend />
                  <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#10b981" radius={[4, 4, 0, 0]} maxBarSize={50} />
                  <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} maxBarSize={50} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full w-full flex items-center justify-center text-slate-400">
                Sem dados suficientes para exibir o gráfico.
              </div>
            )}
          </div>
        </div>

        {/* Chart 3: Proportion Pie Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">Proporção Geral (Crédito vs Débito)</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Chart 2: Sector/Employee Drilldown - Full Width */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-2">
          <h3 className="text-lg font-semibold text-slate-800 mb-4">
             {selectedEmpId 
               ? 'Detalhe do Colaborador (Por Tipo)' 
               : selectedTeam 
                 ? 'Horas por Colaborador (Neste Setor)' 
                 : 'Horas por Setor'}
          </h3>
          <div className="h-96 w-full">
            {drillDownChartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={drillDownChartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }} barGap={4}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis 
                    dataKey="name" 
                    tick={{fill: '#64748b', fontSize: 11}} 
                    axisLine={false} 
                    tickLine={false} 
                    interval={0}
                    angle={drillDownChartData.length > 8 ? -45 : 0}
                    textAnchor={drillDownChartData.length > 8 ? 'end' : 'middle'}
                    height={drillDownChartData.length > 8 ? 60 : 30}
                  />
                  <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{fill: '#f1f5f9'}}
                  />
                  <Legend />
                  <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#10b981" radius={[4, 4, 0, 0]} maxBarSize={60} />
                  <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} maxBarSize={60} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full w-full flex items-center justify-center text-slate-400">
                Sem dados neste filtro.
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useRef, useEffect } from 'react';
import { Save, User, ChevronDown, Check, Loader2, ClipboardList, AlertCircle } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface ManualEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const MANUAL_OCCURRENCE_OPTIONS = [
  { label: 'Falta', type: RecordType.DEBIT },
  { label: 'Atestado', type: RecordType.NEUTRAL },
  { label: 'Suspensão', type: RecordType.DEBIT },
  { label: 'Hora Extra', type: RecordType.CREDIT },
  { label: 'Saída Antecipada', type: RecordType.DEBIT },
];

const ManualEntryForm: React.FC<ManualEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);

  const [occurrenceType, setOccurrenceType] = useState<string>('Falta');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.DEBIT);
  const [observations, setObservations] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const option = MANUAL_OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
  }, [occurrenceType]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!selectedEmployee || !date || !observations) {
        setError("Preencha todos os campos obrigatórios.");
        return;
    }

    if (hours === 0 && minutes === 0 && occurrenceType !== 'Atestado') {
       setError("Informe a quantidade de horas/minutos.");
       return;
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    // Objeto de registro manual
    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: Number(hours),
      minutes: Number(minutes),
      // Não temos startTime/endTime em lançamentos manuais de quantidade
      startTime: '', 
      endTime: '',
      type: mappedRecordType,
      occurrenceType,
      reason: observations, // Mapeando observações para reason
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      await firebaseService.saveManualOccurrence(newRecord);

      setSuccess(true);
      onRecordAdded();

      // Reset form parcial
      setSelectedEmployee('');
      setSearchTerm('');
      setObservations('');
      setHours(0);
      setMinutes(0);
      setOccurrenceType('Falta');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar lançamento manual:", error);
      setError("Erro ao salvar no banco de dados.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-fade-in">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Lançamento Efetuado!</h3>
            <p className="text-slate-600 text-center">Ocorrência registrada no histórico do colaborador.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-slate-800 p-6 text-white border-b border-slate-700">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-slate-700 rounded-lg">
                <ClipboardList className="w-6 h-6 text-indigo-400" />
             </div>
             <div>
                <h2 className="text-xl font-bold">Lançamento Manual (RH)</h2>
                <p className="text-slate-400 text-sm mt-1">Registre faltas, atestados ou ajustes administrativos.</p>
             </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          {error && (
             <div className="bg-red-50 text-red-600 p-3 rounded-lg flex items-center text-sm">
                <AlertCircle size={16} className="mr-2" />
                {error}
             </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Pesquisar por nome..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team} - {emp.company})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <input
                type="date"
                required
                value={date}
                onChange={(e) => setDate(e.target.value)}
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
              />
            </div>

            {/* Type Dropdown */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <select
                  value={occurrenceType}
                  onChange={(e) => setOccurrenceType(e.target.value)}
                  className="block w-full px-3 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
               >
                 {MANUAL_OCCURRENCE_OPTIONS.map((opt) => (
                   <option key={opt.label} value={opt.label}>{opt.label}</option>
                 ))}
               </select>
               <div className={`mt-2 text-xs font-semibold ${mappedRecordType === RecordType.CREDIT ? 'text-green-600' : mappedRecordType === RecordType.DEBIT ? 'text-red-600' : 'text-slate-500'}`}>
                  {mappedRecordType === RecordType.CREDIT ? 'Adiciona Saldo (+)' : mappedRecordType === RecordType.DEBIT ? 'Desconta Saldo (-)' : 'Informativo (Neutro)'}
               </div>
            </div>

            {/* Hours/Minutes Input */}
            <div className="col-span-1 md:col-span-2">
               <label className="block text-sm font-medium text-slate-700 mb-2">Quantidade de Tempo</label>
               <div className="flex gap-4">
                  <div className="flex-1">
                     <label className="block text-xs text-slate-500 mb-1">Horas</label>
                     <input 
                       type="number" 
                       min="0"
                       value={hours}
                       onChange={(e) => setHours(Number(e.target.value))}
                       className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 text-slate-900 focus:ring-indigo-500"
                     />
                  </div>
                  <div className="flex-1">
                     <label className="block text-xs text-slate-500 mb-1">Minutos</label>
                     <input 
                       type="number" 
                       min="0"
                       max="59"
                       value={minutes}
                       onChange={(e) => setMinutes(Number(e.target.value))}
                       className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 text-slate-900 focus:ring-indigo-500"
                     />
                  </div>
               </div>
            </div>

          </div>

          {/* Observations */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Observações / Motivo</label>
            <textarea
              required
              rows={3}
              value={observations}
              onChange={(e) => setObservations(e.target.value)}
              placeholder="Descreva o motivo..."
              className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-800 hover:bg-slate-900 focus:ring-2 focus:ring-offset-2 focus:ring-slate-500'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Processando...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  Salvar Lançamento Manual
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ManualEntryForm;

import React from 'react';
import { LayoutDashboard, FilePlus, Users, FileText, Settings, LogOut, ClipboardList } from 'lucide-react';
import { Role, Employee } from '../types';

interface SidebarProps {
  currentUser: Employee;
  currentRole: Role;
  currentPage: string;
  setPage: (page: string) => void;
  onLogout: () => void;
  isOpen: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentUser, currentRole, currentPage, setPage, onLogout, isOpen }) => {

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'form', label: 'Nova Ocorrência', icon: FilePlus, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'manual-entry', label: 'Lançamento Manual', icon: ClipboardList, roles: [Role.ADMIN] }, // Nova rota
    { id: 'employees', label: 'Colaboradores', icon: Users, roles: [Role.ADMIN] },
    { id: 'reports', label: 'Relatórios', icon: FileText, roles: [Role.ADMIN, Role.LEADER] },
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(currentRole));

  // Helper to get First and Last Name
  const getDisplayName = () => {
    if (!currentUser || !currentUser.name) return 'Usuário';
    const parts = currentUser.name.split(' ');
    if (parts.length > 1) {
      // Returns First Name + Last Name (or second word)
      return `${parts[0]} ${parts[parts.length - 1]}`; // Or just parts[1] for strictly second name
    }
    return parts[0];
  };

  // Helper for Initials based on Name
  const getInitials = () => {
     if (!currentUser || !currentUser.name) return 'US';
     const parts = currentUser.name.split(' ');
     if (parts.length > 1) return (parts[0][0] + parts[1][0]).toUpperCase();
     return parts[0].slice(0,2).toUpperCase();
  };

  const roleLabel = currentRole === Role.ADMIN ? 'Administrador' : 'Líder';

  return (
    <div className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static md:inset-0 shadow-xl`}>
      <div className="flex flex-col h-full">
        <div className="p-6 border-b border-slate-700">
          <h1 className="text-xl font-bold tracking-wider uppercase">Hurafy</h1>
          <p className="text-xs text-slate-400 mt-1">Formulário de Ocorrência</p>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          {filteredItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentPage === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setPage(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors duration-200 ${
                  isActive 
                    ? 'bg-indigo-600 text-white shadow-lg' 
                    : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-700">
          <div className="flex items-center space-x-3 px-4 py-3 mb-2">
             <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-xs font-bold shrink-0">
               {getInitials()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-medium truncate" title={currentUser.name}>{getDisplayName()}</p>
               <p className="text-xs text-slate-400">{roleLabel}</p>
             </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center space-x-3 px-4 py-2 text-red-400 hover:bg-red-500/10 hover:text-red-300 rounded-lg transition-colors"
          >
            <LogOut size={18} />
            <span className="text-sm font-medium">Sair / Trocar Perfil</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TimeEntryForm from './components/TimeEntryForm';
import ManualEntryForm from './components/ManualEntryForm';
import EmployeeList from './components/EmployeeList';
import Reports from './components/Reports';
import Login from './components/Login';
import { Role, Employee, TimeRecord } from './types';
import { firebaseService } from './services/firebaseService';
import { Menu } from 'lucide-react';
import { onAuthStateChanged } from 'firebase/auth';

// Expose service to window for console scripts
(window as any).firebaseService = firebaseService;

const App: React.FC = () => {
  // Debug Log
  useEffect(() => {
    console.log("🚀 App Component Mounted");
  }, []);

  // Application State
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [records, setRecords] = useState<TimeRecord[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Authentication State
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);

  // Load User Session Persistent
  useEffect(() => {
    // Check if auth is initialized safely
    if (!firebaseService.auth) {
      const msg = "Firebase Auth service not initialized. Verifique as configurações.";
      console.error(msg);
      setInitError(msg);
      setAuthChecked(true);
      return;
    }

    try {
      const unsubscribe = onAuthStateChanged(firebaseService.auth, async (user) => {
        console.log("Auth State Changed:", user ? `User: ${user.email}` : "No User");

        if (user) {
          try {
            const profile = await firebaseService.getOrCreateProfile(user);
            setCurrentUser(profile);
          } catch (e: any) {
            console.error("Error loading profile:", e);
            setInitError("Erro ao carregar perfil do usuário: " + e.message);
            setCurrentUser(null);
          }
        } else {
          setCurrentUser(null);
        }
        setAuthChecked(true);
      }, (error) => {
        console.error("Auth Subscription Error:", error);
        setInitError("Erro na conexão com autenticação.");
        setAuthChecked(true);
      });

      return () => unsubscribe();
    } catch (error: any) {
       console.error("Critical error setting up auth listener:", error);
       setInitError(error.message);
       setAuthChecked(true);
    }
  }, []);

  // Load Data function
  const fetchData = async () => {
    if (currentUser) {
      try {
        console.log("Fetching data from Firestore...");
        const emps = await firebaseService.getEmployees();
        const recs = await firebaseService.getRecords();

        setEmployees(emps);
        setRecords(recs);
        console.log("Data fetched successfully:", { employees: emps.length, records: recs.length });
      } catch (e) {
        console.error("Error fetching data:", e);
      }
    }
  };

  useEffect(() => {
    if (currentUser) {
      fetchData();
    }
  }, [currentUser]);

  const handleLoginSuccess = (user: Employee) => {
    setCurrentUser(user);
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    setCurrentUser(null);
    setEmployees([]);
    setRecords([]);
  };

  // Optimistic Update Helpers
  const handleLocalRecordUpdate = (updatedRecord: TimeRecord) => {
    setRecords(prevRecords => 
      prevRecords.map(r => r.id === updatedRecord.id ? updatedRecord : r)
    );
  };

  const handleLocalRecordDelete = (recordId: string) => {
    setRecords(prevRecords => prevRecords.filter(r => r.id !== recordId));
  };

  if (initError) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-red-50 p-4 text-center">
        <div className="bg-white p-6 rounded-lg shadow-lg max-w-md">
          <h2 className="text-red-600 text-xl font-bold mb-2">Erro de Inicialização</h2>
          <p className="text-slate-600">{initError}</p>
          <button 
            onClick={() => window.location.reload()}
            className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700"
          >
            Tentar Novamente
          </button>
        </div>
      </div>
    );
  }

  if (!authChecked) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-slate-100 space-y-4">
         <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
         <p className="text-slate-500 font-medium">Conectando ao banco de dados...</p>
      </div>
    );
  }

  // If not logged in, show Login Screen
  if (!currentUser) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  // Render Page Content based on route
  const renderContent = () => {
    try {
      switch (currentPage) {
        case 'dashboard':
          return <Dashboard records={records} employees={employees} />;
        case 'form':
          return <TimeEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} />;
        case 'manual-entry':
           return currentUser.role === Role.ADMIN ? 
             <ManualEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} /> :
             <div className="text-center p-10 text-slate-500">Acesso negado. Apenas Admin.</div>;
        case 'employees':
          return currentUser.role === Role.ADMIN ? 
            <EmployeeList 
              employees={employees} 
              refreshData={fetchData} 
              currentUser={currentUser}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado. Esta área é restrita ao RH.</div>;
        case 'reports':
          return (currentUser.role === Role.ADMIN || currentUser.role === Role.LEADER) ? 
            <Reports 
              records={records} 
              employees={employees} 
              currentUser={currentUser} 
              refreshData={fetchData} 
              onUpdateRecord={handleLocalRecordUpdate}
              onDeleteRecord={handleLocalRecordDelete}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
        default:
          return <Dashboard records={records} employees={employees} />;
      }
    } catch (e) {
      console.error("Error rendering page content:", e);
      return <div className="p-4 text-red-500">Erro ao carregar conteúdo da página. Verifique o console.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-40 bg-slate-900 text-white p-4 flex justify-between items-center shadow-md">
         <span className="font-bold">Hurafy</span>
         <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
           <Menu size={24} />
         </button>
      </div>

      <Sidebar 
        currentUser={currentUser}
        currentRole={currentUser.role} 
        currentPage={currentPage} 
        setPage={(page) => {
          setCurrentPage(page);
          setIsSidebarOpen(false);
        }}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full pt-16 md:pt-0">
        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Save, User, ChevronDown, Check, Loader2, ClipboardList, AlertCircle } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface ManualEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const MANUAL_OCCURRENCE_OPTIONS = [
  { label: 'Ajuste de Ponto (Esquecimento)', type: RecordType.CREDIT },
  { label: 'Trabalho Externo', type: RecordType.CREDIT },
  { label: 'Hora Extra', type: RecordType.CREDIT },
  { label: 'Falta Não Justificada', type: RecordType.DEBIT },
  { label: 'Suspensão', type: RecordType.DEBIT },
  { label: 'Saída Antecipada', type: RecordType.DEBIT },
  { label: 'Atestado Médico', type: RecordType.NEUTRAL },
  { label: 'Falta Justificada', type: RecordType.NEUTRAL },
];

const ManualEntryForm: React.FC<ManualEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);

  // Define o valor inicial com o primeiro item da lista atualizada
  const [occurrenceType, setOccurrenceType] = useState<string>(MANUAL_OCCURRENCE_OPTIONS[0].label);
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(MANUAL_OCCURRENCE_OPTIONS[0].type);
  const [observations, setObservations] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    const option = MANUAL_OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
  }, [occurrenceType]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (!selectedEmployee || !date || !observations) {
        setError("Preencha todos os campos obrigatórios.");
        return;
    }

    // Validação de tempo (exceto para tipos neutros que podem ser apenas informativos, mas geralmente exigem tempo para ajuste de banco se for o caso)
    // Se for 'Ajuste de Ponto' ou 'Trabalho Externo', exige tempo pois é Crédito.
    if (hours === 0 && minutes === 0 && mappedRecordType !== RecordType.NEUTRAL) {
       setError("Informe a quantidade de horas/minutos para este tipo de lançamento.");
       return;
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    // Objeto de registro manual
    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date,
      hours: Number(hours),
      minutes: Number(minutes),
      // Não temos startTime/endTime em lançamentos manuais de quantidade
      startTime: '', 
      endTime: '',
      type: mappedRecordType,
      occurrenceType,
      reason: observations, // Mapeando observações para reason
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id
    };

    try {
      await firebaseService.saveManualOccurrence(newRecord);

      setSuccess(true);
      onRecordAdded();

      // Reset form parcial
      setSelectedEmployee('');
      setSearchTerm('');
      setObservations('');
      setHours(0);
      setMinutes(0);
      // Mantém o tipo selecionado ou volta pro padrão

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar lançamento manual:", error);
      setError("Erro ao salvar no banco de dados.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-3xl mx-auto animate-fade-in">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Lançamento Efetuado!</h3>
            <p className="text-slate-600 text-center">Ocorrência registrada no histórico do colaborador.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-slate-800 p-6 text-white border-b border-slate-700">
          <div className="flex items-center gap-3">
             <div className="p-2 bg-slate-700 rounded-lg">
                <ClipboardList className="w-6 h-6 text-indigo-400" />
             </div>
             <div>
                <h2 className="text-xl font-bold">Lançamento Manual (RH)</h2>
                <p className="text-slate-400 text-sm mt-1">Registre ajustes, faltas ou trabalhos externos.</p>
             </div>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          {error && (
             <div className="bg-red-50 text-red-600 p-3 rounded-lg flex items-center text-sm">
                <AlertCircle size={16} className="mr-2" />
                {error}
             </div>
          )}

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Pesquisar por nome..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team} - {emp.company})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <input
                type="date"
                required
                value={date}
                onChange={(e) => setDate(e.target.value)}
                className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
              />
            </div>

            {/* Type Dropdown */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <select
                  value={occurrenceType}
                  onChange={(e) => setOccurrenceType(e.target.value)}
                  className="block w-full px-3 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
               >
                 {MANUAL_OCCURRENCE_OPTIONS.map((opt) => (
                   <option key={opt.label} value={opt.label}>{opt.label}</option>
                 ))}
               </select>
               <div className={`mt-2 text-xs font-semibold ${mappedRecordType === RecordType.CREDIT ? 'text-green-600' : mappedRecordType === RecordType.DEBIT ? 'text-red-600' : 'text-slate-500'}`}>
                  {mappedRecordType === RecordType.CREDIT ? 'Adiciona Saldo (+)' : mappedRecordType === RecordType.DEBIT ? 'Desconta Saldo (-)' : 'Informativo (Neutro)'}
               </div>
            </div>

            {/* Hours/Minutes Input */}
            <div className="col-span-1 md:col-span-2">
               <label className="block text-sm font-medium text-slate-700 mb-2">Quantidade de Tempo</label>
               <div className="flex gap-4">
                  <div className="flex-1">
                     <label className="block text-xs text-slate-500 mb-1">Horas</label>
                     <input 
                       type="number" 
                       min="0"
                       value={hours}
                       onChange={(e) => setHours(Number(e.target.value))}
                       className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 text-slate-900 focus:ring-indigo-500"
                     />
                  </div>
                  <div className="flex-1">
                     <label className="block text-xs text-slate-500 mb-1">Minutos</label>
                     <input 
                       type="number" 
                       min="0"
                       max="59"
                       value={minutes}
                       onChange={(e) => setMinutes(Number(e.target.value))}
                       className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 text-slate-900 focus:ring-indigo-500"
                     />
                  </div>
               </div>
            </div>

          </div>

          {/* Observations */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">Observações / Motivo</label>
            <textarea
              required
              rows={3}
              value={observations}
              onChange={(e) => setObservations(e.target.value)}
              placeholder="Descreva o motivo (obrigatório)..."
              className="block w-full px-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee ? 'bg-slate-400 cursor-not-allowed' : 'bg-slate-800 hover:bg-slate-900 focus:ring-2 focus:ring-offset-2 focus:ring-slate-500'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Processando...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  Salvar Lançamento Manual
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

