import React from 'react';
import { LayoutDashboard, FilePlus, Users, FileText, LogOut } from 'lucide-react';
import { Role, Employee } from '../types';

interface SidebarProps {
  currentUser: Employee;
  currentRole: Role;
  currentPage: string;
  setPage: (page: string) => void;
  onLogout: () => void;
  isOpen: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentUser, currentRole, currentPage, setPage, onLogout, isOpen }) => {

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'form', label: 'Nova Ocorrência', icon: FilePlus, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'employees', label: 'Colaboradores', icon: Users, roles: [Role.ADMIN] },
    { id: 'reports', label: 'Relatórios', icon: FileText, roles: [Role.ADMIN, Role.LEADER] },
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(currentRole));

  // Helper to get First and Last Name
  const getDisplayName = () => {
    if (!currentUser || !currentUser.name) return 'Usuário';
    const parts = currentUser.name.split(' ');
    if (parts.length > 1) {
      // Returns First Name + Last Name (or second word)
      return `${parts[0]} ${parts[parts.length - 1]}`; // Or just parts[1] for strictly second name
    }
    return parts[0];
  };

  // Helper for Initials based on Name
  const getInitials = () => {
     if (!currentUser || !currentUser.name) return 'US';
     const parts = currentUser.name.split(' ');
     if (parts.length > 1) return (parts[0][0] + parts[1][0]).toUpperCase();
     return parts[0].slice(0,2).toUpperCase();
  };

  const roleLabel = currentRole === Role.ADMIN ? 'Administrador' : 'Líder';

  return (
    <div className={`fixed inset-y-0 left-0 z-50 w-64 bg-slate-900 text-white transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static md:inset-0 shadow-xl`}>
      <div className="flex flex-col h-full">
        <div className="p-6 border-b border-slate-700">
          <h1 className="text-xl font-bold tracking-wider uppercase">Hurafy</h1>
          <p className="text-xs text-slate-400 mt-1">Formulário de Ocorrência</p>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          {filteredItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentPage === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setPage(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3 rounded-lg transition-colors duration-200 ${
                  isActive 
                    ? 'bg-indigo-600 text-white shadow-lg' 
                    : 'text-slate-300 hover:bg-slate-800 hover:text-white'
                }`}
              >
                <Icon size={20} />
                <span className="font-medium">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-700">
          <div className="flex items-center space-x-3 px-4 py-3 mb-2">
             <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-xs font-bold shrink-0">
               {getInitials()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-medium truncate" title={currentUser.name}>{getDisplayName()}</p>
               <p className="text-xs text-slate-400">{roleLabel}</p>
             </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center space-x-3 px-4 py-2 text-red-400 hover:bg-red-500/10 hover:text-red-300 rounded-lg transition-colors"
          >
            <LogOut size={18} />
            <span className="text-sm font-medium">Sair / Trocar Perfil</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Loader2 } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Verifica se é uma regularização de ausência (impacto zero)
  const isAbsenceAdjustment = occurrenceType === 'Ausência de Batida';

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Set current user default selection logic
  useEffect(() => {
    if (currentUser.role === Role.EMPLOYEE) {
       setSelectedEmployee(currentUser.id);
       setSearchTerm(currentUser.name);
    }
  }, [currentUser]);

  // Update Mapped Record Type when Occurrence Selection Changes
  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
  }, [occurrenceType]);

  // Calculate duration whenever times change
  useEffect(() => {
    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);

    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime]);

  const availableEmployees = employees;

  const filteredEmployees = availableEmployees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !reason || !startTime || !endTime || !isTimeValid) return;

    if (!isAbsenceAdjustment && calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
      alert("A duração deve ser maior que zero.");
      return;
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    // Objeto de registro conforme estrutura do Firestore
    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date, 
      // Regra de Negócio: Se for ausência de batida, salva 0h e 0m independente do horário informado
      hours: isAbsenceAdjustment ? 0 : calculatedDuration.hours,
      minutes: isAbsenceAdjustment ? 0 : calculatedDuration.minutes,
      startTime,
      endTime,
      type: isAbsenceAdjustment ? RecordType.NEUTRAL : mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id,
      // Flag de ajuste
      isAdjustment: isAbsenceAdjustment ? true : undefined
    };

    try {
      await firebaseService.saveTimeRecord(newRecord);

      setSuccess(true);
      onRecordAdded();

      if (currentUser.role !== Role.EMPLOYEE) {
         setSelectedEmployee('');
         setSearchTerm('');
      }
      setStartTime('');
      setEndTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar batida:", error);
      alert("Falha na comunicação com o servidor. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">Registro salvo no banco de dados.</p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Os dados serão sincronizados com o servidor.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  disabled={currentUser.role === Role.EMPLOYEE}
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''} ${currentUser.role === Role.EMPLOYEE ? 'bg-slate-100 cursor-not-allowed text-slate-500' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && currentUser.role !== Role.EMPLOYEE && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
                />
              </div>
            </div>

            {/* Type Dropdown */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <div className="relative">
                 <select
                    value={occurrenceType}
                    onChange={(e) => setOccurrenceType(e.target.value)}
                    className="block w-full pl-3 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
                 >
                   {OCCURRENCE_OPTIONS.map((opt) => (
                     <option key={opt.label} value={opt.label}>{opt.label}</option>
                   ))}
                 </select>
               </div>

               {/* Visual Indicator of Effect */}
               <div className={`mt-2 p-2 rounded-lg border text-xs font-semibold flex items-center justify-center ${getTypeStyles(mappedRecordType)}`}>
                  {mappedRecordType === RecordType.CREDIT && <span className="flex items-center"><Check size={14} className="mr-1"/> Adiciona ao Banco de Horas (Crédito)</span>}
                  {mappedRecordType === RecordType.DEBIT && <span className="flex items-center"><AlertTriangle size={14} className="mr-1"/> Desconta do Banco de Horas (Débito)</span>}
                  {mappedRecordType === RecordType.NEUTRAL && <span className="flex items-center"><Info size={14} className="mr-1"/> Informativo (Não altera o saldo)</span>}
               </div>

                {/* Nota de Ajuste de Ausência */}
                {isAbsenceAdjustment && (
                  <div className="mt-3 bg-blue-50 border border-blue-200 rounded-lg p-3 text-sm text-blue-700 animate-fade-in">
                    <p className="font-bold flex items-center mb-1"><Info size={16} className="mr-2"/> Nota Informativa:</p>
                    <p>Este registro serve apenas para regularizar seu histórico e <strong>não gera crédito/débito de horas</strong> (Impacto Zero).</p>
                  </div>
                )}
            </div>

            {/* Time Range Calculation */}
            <div className="col-span-1 md:col-span-2">
              <label className="block text-sm font-medium text-slate-700 mb-2">Período da Atividade</label>
              <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Início/Entrada</label>
                  <input 
                    type="time" 
                    required
                    value={startTime}
                    onChange={(e) => setStartTime(e.target.value)}
                    className="block w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500"
                  />
                </div>
                <div>
                  <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Fim/Saída</label>
                  <input 
                    type="time" 
                    required
                    value={endTime}
                    onChange={(e) => setEndTime(e.target.value)}
                    className={`block w-full px-3 py-2 border rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500 ${!isTimeValid ? 'border-red-500 ring-1 ring-red-500' : 'border-slate-300'}`}
                  />
                </div>

                {/* Duration Result */}
                <div className="col-span-1 sm:col-span-2 mt-2 pt-4 border-t border-slate-200 flex items-center justify-between">
                  <div className="flex items-center text-slate-600">
                    <Calculator size={18} className="mr-2" />
                    <span className="text-sm font-medium">Tempo Calculado:</span>
                  </div>
                  <div className={`text-lg font-bold ${!isTimeValid ? 'text-red-500' : 'text-indigo-600'}`}>
                    {!isTimeValid ? (
                      <span className="text-sm">Horário Inválido</span>
                    ) : (
                      <span>
                        {isAbsenceAdjustment ? (
                           <span className="text-slate-500">0h 0m (Ajuste)</span>
                        ) : (
                           <span>{calculatedDuration.hours}h {calculatedDuration.minutes}m</span>
                        )}
                      </span>
                    )}
                  </div>
                </div>
              </div>
              {!isTimeValid && (
                <p className="text-xs text-red-500 mt-1">A hora de término deve ser posterior à hora de início.</p>
              )}
            </div>

          </div>

          {/* Reason */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Justificativa {isAbsenceAdjustment && <span className="text-red-500">*</span>}
            </label>
            <textarea
              required
              rows={3}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={isAbsenceAdjustment ? "Explique o motivo do esquecimento da batida..." : "Detalhes adicionais..."}
              className={`block w-full px-3 py-3 border rounded-lg bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900 ${isAbsenceAdjustment && !reason ? 'border-amber-300 ring-1 ring-amber-300' : 'border-slate-300'}`}
            />
            {isAbsenceAdjustment && (
               <p className="text-xs text-slate-500 mt-1">A justificativa é obrigatória para ausência de batida.</p>
            )}
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee || !isTimeValid || (!isAbsenceAdjustment && calculatedDuration.hours === 0 && calculatedDuration.minutes === 0)}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee || !isTimeValid || (!isAbsenceAdjustment && calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Salvando no Firebase...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  Registrar Batida
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TimeEntryForm;

import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TimeEntryForm from './components/TimeEntryForm';
import EmployeeList from './components/EmployeeList';
import Reports from './components/Reports';
import Login from './components/Login';
import { Role, Employee, TimeRecord } from './types';
import { firebaseService } from './services/firebaseService';
import { Menu } from 'lucide-react';
import { onAuthStateChanged } from 'firebase/auth';

// Expose service to window for console scripts
(window as any).firebaseService = firebaseService;

const App: React.FC = () => {
  // Debug Log
  useEffect(() => {
    console.log("🚀 App Component Mounted");
  }, []);

  // Application State
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [records, setRecords] = useState<TimeRecord[]>([]);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Authentication State
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);

  // Load User Session Persistent
  useEffect(() => {
    // Check if auth is initialized safely
    if (!firebaseService.auth) {
      const msg = "Firebase Auth service not initialized. Verifique as configurações.";
      console.error(msg);
      setInitError(msg);
      setAuthChecked(true);
      return;
    }

    try {
      const unsubscribe = onAuthStateChanged(firebaseService.auth, async (user) => {
        console.log("Auth State Changed:", user ? `User: ${user.email}` : "No User");

        if (user) {
          try {
            const profile = await firebaseService.getOrCreateProfile(user);
            setCurrentUser(profile);
          } catch (e: any) {
            console.error("Error loading profile:", e);
            setInitError("Erro ao carregar perfil do usuário: " + e.message);
            setCurrentUser(null);
          }
        } else {
          setCurrentUser(null);
        }
        setAuthChecked(true);
      }, (error) => {
        console.error("Auth Subscription Error:", error);
        setInitError("Erro na conexão com autenticação.");
        setAuthChecked(true);
      });

      return () => unsubscribe();
    } catch (error: any) {
       console.error("Critical error setting up auth listener:", error);
       setInitError(error.message);
       setAuthChecked(true);
    }
  }, []);

  // Load Data function
  const fetchData = async () => {
    if (currentUser) {
      try {
        console.log("Fetching data from Firestore...");
        const emps = await firebaseService.getEmployees();
        const recs = await firebaseService.getRecords();

        setEmployees(emps);
        setRecords(recs);
        console.log("Data fetched successfully:", { employees: emps.length, records: recs.length });
      } catch (e) {
        console.error("Error fetching data:", e);
      }
    }
  };

  useEffect(() => {
    if (currentUser) {
      fetchData();
    }
  }, [currentUser]);

  const handleLoginSuccess = (user: Employee) => {
    setCurrentUser(user);
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    setCurrentUser(null);
    setEmployees([]);
    setRecords([]);
  };

  // Optimistic Update Helpers
  const handleLocalRecordUpdate = (updatedRecord: TimeRecord) => {
    setRecords(prevRecords => 
      prevRecords.map(r => r.id === updatedRecord.id ? updatedRecord : r)
    );
  };

  const handleLocalRecordDelete = (recordId: string) => {
    setRecords(prevRecords => prevRecords.filter(r => r.id !== recordId));
  };

  if (initError) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-red-50 p-4 text-center">
        <div className="bg-white p-6 rounded-lg shadow-lg max-w-md">
          <h2 className="text-red-600 text-xl font-bold mb-2">Erro de Inicialização</h2>
          <p className="text-slate-600">{initError}</p>
          <button 
            onClick={() => window.location.reload()}
            className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700"
          >
            Tentar Novamente
          </button>
        </div>
      </div>
    );
  }

  if (!authChecked) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-slate-100 space-y-4">
         <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
         <p className="text-slate-500 font-medium">Conectando ao banco de dados...</p>
      </div>
    );
  }

  // If not logged in, show Login Screen
  if (!currentUser) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  // Render Page Content based on route
  const renderContent = () => {
    try {
      switch (currentPage) {
        case 'dashboard':
          return <Dashboard records={records} employees={employees} />;
        case 'form':
          return <TimeEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} />;
        case 'employees':
          return currentUser.role === Role.ADMIN ? 
            <EmployeeList 
              employees={employees} 
              refreshData={fetchData} 
              currentUser={currentUser}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado. Esta área é restrita ao RH.</div>;
        case 'reports':
          return (currentUser.role === Role.ADMIN || currentUser.role === Role.LEADER) ? 
            <Reports 
              records={records} 
              employees={employees} 
              currentUser={currentUser} 
              refreshData={fetchData} 
              onUpdateRecord={handleLocalRecordUpdate}
              onDeleteRecord={handleLocalRecordDelete}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
        default:
          return <Dashboard records={records} employees={employees} />;
      }
    } catch (e) {
      console.error("Error rendering page content:", e);
      return <div className="p-4 text-red-500">Erro ao carregar conteúdo da página. Verifique o console.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-40 bg-slate-900 text-white p-4 flex justify-between items-center shadow-md">
         <span className="font-bold">Hurafy</span>
         <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
           <Menu size={24} />
         </button>
      </div>

      <Sidebar 
        currentUser={currentUser}
        currentRole={currentUser.role} 
        currentPage={currentPage} 
        setPage={(page) => {
          setCurrentPage(page);
          setIsSidebarOpen(false);
        }}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full pt-16 md:pt-0">
        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Loader2, ShieldAlert } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  // New state specifically for single-time entry (Ausência)
  const [absenceTime, setAbsenceTime] = useState('');

  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Verifica se é uma regularização de ausência (impacto zero)
  const isAbsenceAdjustment = occurrenceType === 'Ausência de Batida';

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Set current user default selection logic
  useEffect(() => {
    if (currentUser.role === Role.EMPLOYEE) {
       setSelectedEmployee(currentUser.id);
       setSearchTerm(currentUser.name);
    }
  }, [currentUser]);

  // Update Mapped Record Type when Occurrence Selection Changes
  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
    // Limpa campos de tempo ao trocar o tipo para evitar confusão
    setStartTime('');
    setEndTime('');
    setAbsenceTime('');
    setCalculatedDuration({ hours: 0, minutes: 0 });
    setIsTimeValid(true);
  }, [occurrenceType]);

  // Calculate duration whenever standard times change
  useEffect(() => {
    if (isAbsenceAdjustment) {
        // Se for ausência, a duração é sempre 0
        setCalculatedDuration({ hours: 0, minutes: 0 });
        setIsTimeValid(!!absenceTime);
        return;
    }

    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);

    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime, absenceTime, isAbsenceAdjustment]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validação Básica
    if (!selectedEmployee || !date || !reason) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    // Validação Específica para Ausência
    if (isAbsenceAdjustment) {
        if (!absenceTime) {
            alert("Informe o horário do esquecimento.");
            return;
        }
        if (reason.trim().length < 5) {
            alert("A justificativa é obrigatória e deve ser detalhada para regularizações.");
            return;
        }
    } else {
        // Validação Padrão
        if (!startTime || !endTime || !isTimeValid) {
            alert("Verifique os horários de início e fim.");
            return;
        }
        if (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
            alert("A duração deve ser maior que zero.");
            return;
        }
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    // Configura os horários baseados no tipo
    // REGRA DE NEGÓCIO: Se for Ausência, Entrada = Saída (Saldo 0)
    const finalStartTime = isAbsenceAdjustment ? absenceTime : startTime;
    const finalEndTime = isAbsenceAdjustment ? absenceTime : endTime;

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date, 
      hours: isAbsenceAdjustment ? 0 : calculatedDuration.hours,
      minutes: isAbsenceAdjustment ? 0 : calculatedDuration.minutes,
      startTime: finalStartTime,
      endTime: finalEndTime,
      type: isAbsenceAdjustment ? RecordType.NEUTRAL : mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id,
      isAdjustment: isAbsenceAdjustment ? true : undefined,
      status: isAbsenceAdjustment ? 'regularized' : undefined
    };

    try {
      await firebaseService.saveTimeRecord(newRecord);

      setSuccess(true);
      onRecordAdded();

      // Reset Form
      if (currentUser.role !== Role.EMPLOYEE) {
         setSelectedEmployee('');
         setSearchTerm('');
      }
      setStartTime('');
      setEndTime('');
      setAbsenceTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar batida:", error);
      alert("Falha na comunicação com o servidor. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">
              {isAbsenceAdjustment 
                ? 'Regularização registrada. Saldo inalterado.' 
                : 'Registro salvo no banco de dados.'}
            </p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Os dados serão sincronizados com o servidor.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  disabled={currentUser.role === Role.EMPLOYEE}
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''} ${currentUser.role === Role.EMPLOYEE ? 'bg-slate-100 cursor-not-allowed text-slate-500' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && currentUser.role !== Role.EMPLOYEE && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
                />
              </div>
            </div>

            {/* Type Dropdown */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <div className="relative">
                 <select
                    value={occurrenceType}
                    onChange={(e) => setOccurrenceType(e.target.value)}
                    className="block w-full pl-3 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
                 >
                   {OCCURRENCE_OPTIONS.map((opt) => (
                     <option key={opt.label} value={opt.label}>{opt.label}</option>
                   ))}
                 </select>
               </div>

               {/* Visual Indicator of Effect */}
               <div className={`mt-2 p-2 rounded-lg border text-xs font-semibold flex items-center justify-center ${getTypeStyles(mappedRecordType)}`}>
                  {mappedRecordType === RecordType.CREDIT && <span className="flex items-center"><Check size={14} className="mr-1"/> Adiciona ao Banco de Horas (Crédito)</span>}
                  {mappedRecordType === RecordType.DEBIT && <span className="flex items-center"><AlertTriangle size={14} className="mr-1"/> Desconta do Banco de Horas (Débito)</span>}
                  {mappedRecordType === RecordType.NEUTRAL && <span className="flex items-center"><Info size={14} className="mr-1"/> Informativo (Não altera o saldo)</span>}
               </div>
            </div>

            {/* Conditional Time Inputs */}
            {isAbsenceAdjustment ? (
                // --- MODO REGULARIZAÇÃO (AUSÊNCIA) ---
                <div className="col-span-1 md:col-span-2 animate-fade-in">
                    <label className="block text-sm font-medium text-slate-700 mb-2">Horário do Esquecimento</label>

                    <div className="bg-amber-50 p-4 rounded-xl border border-amber-200">
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="w-full md:w-1/2">
                                <label className="block text-xs font-semibold text-amber-700 mb-1">Hora da Batida</label>
                                <input 
                                  type="time" 
                                  required
                                  value={absenceTime}
                                  onChange={(e) => setAbsenceTime(e.target.value)}
                                  className="block w-full px-3 py-3 border border-amber-300 rounded-lg bg-white text-slate-900 focus:ring-amber-500 focus:border-amber-500 text-lg font-medium"
                                />
                            </div>

                            <div className="w-full md:w-1/2 flex items-start gap-3 text-sm text-amber-800">
                                <ShieldAlert className="shrink-0 w-8 h-8 text-amber-600" />
                                <div>
                                    <p className="font-bold">Regularização Detectada</p>
                                    <p className="text-xs mt-1">
                                        O sistema registrará <strong>entrada e saída simultâneas</strong> no horário informado para manter seu saldo inalterado.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                // --- MODO PADRÃO (INTERVALO) ---
                <div className="col-span-1 md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-2">Período da Atividade</label>
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Início/Entrada</label>
                      <input 
                        type="time" 
                        required
                        value={startTime}
                        onChange={(e) => setStartTime(e.target.value)}
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Fim/Saída</label>
                      <input 
                        type="time" 
                        required
                        value={endTime}
                        onChange={(e) => setEndTime(e.target.value)}
                        className={`block w-full px-3 py-2 border rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500 ${!isTimeValid ? 'border-red-500 ring-1 ring-red-500' : 'border-slate-300'}`}
                      />
                    </div>

                    {/* Duration Result */}
                    <div className="col-span-1 sm:col-span-2 mt-2 pt-4 border-t border-slate-200 flex items-center justify-between">
                      <div className="flex items-center text-slate-600">
                        <Calculator size={18} className="mr-2" />
                        <span className="text-sm font-medium">Tempo Calculado:</span>
                      </div>
                      <div className={`text-lg font-bold ${!isTimeValid ? 'text-red-500' : 'text-indigo-600'}`}>
                        {!isTimeValid ? (
                          <span className="text-sm">Horário Inválido</span>
                        ) : (
                           <span>{calculatedDuration.hours}h {calculatedDuration.minutes}m</span>
                        )}
                      </div>
                    </div>
                  </div>
                  {!isTimeValid && (
                    <p className="text-xs text-red-500 mt-1">A hora de término deve ser posterior à hora de início.</p>
                  )}
                </div>
            )}

          </div>

          {/* Reason */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Justificativa {isAbsenceAdjustment && <span className="text-red-500">* (Obrigatório)</span>}
            </label>
            <textarea
              required
              rows={3}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={isAbsenceAdjustment ? "Explique detalhadamente o motivo do esquecimento..." : "Detalhes adicionais..."}
              className={`block w-full px-3 py-3 border rounded-lg bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900 ${isAbsenceAdjustment && !reason ? 'border-amber-300 ring-1 ring-amber-300' : 'border-slate-300'}`}
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee || (!isAbsenceAdjustment && !isTimeValid)}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee || (!isAbsenceAdjustment && !isTimeValid) ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Salvando no Firebase...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  {isAbsenceAdjustment ? 'Regularizar Ponto' : 'Registrar Batida'}
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TimeEntryForm;

