import { 
  signInWithEmailAndPassword, 
  signOut, 
  User 
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  getDocs, 
  where, 
  orderBy, 
  deleteDoc, 
  updateDoc,
  serverTimestamp,
  writeBatch
} from 'firebase/firestore';
import { auth, db } from '../lib/firebase';
import { Employee, Role, TimeRecord, RecordType } from '../types';

export const firebaseService = {
  auth,
  db,

  // --- AUTHENTICATION ---

  async login(email: string, pass: string): Promise<{ success: boolean; user?: Employee; message?: string }> {
    try {
      if (!auth) {
         throw new Error("Serviço de autenticação não está pronto.");
      }

      const userCredential = await signInWithEmailAndPassword(auth, email, pass);
      const profile = await this.getOrCreateProfile(userCredential.user);
      return { success: true, user: profile };
    } catch (error: any) {
      console.error("Login Error:", error);
      let msg = "Erro ao realizar login.";

      if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found') {
        msg = "E-mail ou senha inválidos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas. Tente novamente mais tarde.";
      } else if (error.code === 'auth/network-request-failed') {
        msg = "Erro de conexão. Verifique sua internet.";
      }

      return { success: false, message: msg };
    }
  },

  async logout(): Promise<void> {
    if (auth) await signOut(auth);
  },

  // --- USER PROFILE ---

  async getUserProfile(uid: string): Promise<Employee | null> {
    try {
      const docRef = doc(db, 'employees', uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? (docSnap.data() as Employee) : null;
    } catch (e) {
      console.error("Erro ao buscar perfil:", e);
      return null;
    }
  },

  async getOrCreateProfile(user: User, name?: string): Promise<Employee> {
    const email = user.email?.toLowerCase() || '';
    const isSuperAdmin = email === 'ti@arcaplast.com.br';

    // Tenta buscar pelo UID primeiro (Login padrão)
    let existingProfile = await this.getUserProfile(user.uid);

    // Se não achar pelo UID, tenta buscar pelo username (caso tenha sido importado via CSV e seja o primeiro login)
    if (!existingProfile && email) {
        const username = email.split('@')[0];
        const docRefUser = doc(db, 'employees', username);
        const docSnapUser = await getDoc(docRefUser);

        if (docSnapUser.exists()) {
            console.log("Perfil encontrado via username (importado). Vinculando UID...");
            existingProfile = docSnapUser.data() as Employee;
        }
    }

    if (existingProfile) {
      if (isSuperAdmin && existingProfile.role !== Role.ADMIN) {
        console.log("Atualizando permissão de Super Admin...");
        const updated = { ...existingProfile, role: Role.ADMIN };
        await setDoc(doc(db, 'employees', user.uid), updated, { merge: true });
        return updated;
      }
      return existingProfile;
    }

    console.log("Criando novo perfil para:", email);
    const newEmployee: Employee = {
      id: user.uid,
      name: name || user.displayName || 'Colaborador',
      email: email,
      username: email.split('@')[0],
      role: isSuperAdmin ? Role.ADMIN : Role.EMPLOYEE,
      team: 'Geral',
      company: 'Arca Plast',
      active: true
    };

    await setDoc(doc(db, 'employees', user.uid), newEmployee);
    return newEmployee;
  },

  // --- EMPLOYEES CRUD ---

  async getAllUsers(): Promise<Employee[]> {
    return this.getEmployees();
  },

  async getEmployees(): Promise<Employee[]> {
    try {
      const q = query(collection(db, 'employees'), orderBy('name'));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => doc.data() as Employee);
    } catch (e) {
      console.error("Error fetching employees:", e);
      return [];
    }
  },

  // Função robusta para deletar todos os usuários exceto TI e usuário atual
  async deleteAllEmployees(currentUserEmail: string): Promise<boolean> {
    console.log("🚀 LIMPEZA INICIADA...");

    try {
      const q = query(collection(db, 'employees'));
      const querySnapshot = await getDocs(q);

      const batch = writeBatch(db);
      let deleteCount = 0;

      querySnapshot.forEach((doc) => {
        const data = doc.data() as Employee;
        const email = data.email?.toLowerCase();

        // Proteção Crítica: Não apagar o Admin TI e nem o usuário que está logado executando a ação
        if (email === 'ti@arcaplast.com.br' || email === currentUserEmail?.toLowerCase()) {
          console.log(`🛡️ Protegendo usuário admin: ${data.name} (${email})`);
          return;
        }

        console.log(`🗑️ Agendando exclusão: ${data.name} (${doc.id})`);
        batch.delete(doc.ref);
        deleteCount++;
      });

      if (deleteCount > 0) {
        await batch.commit();
        console.log(`✅ LIMPEZA CONCLUÍDA! ${deleteCount} colaboradores removidos.`);
        return true;
      } else {
        console.log("ℹ️ Nenhum colaborador elegível para remoção encontrado.");
        return true;
      }
    } catch (error) {
      console.error("❌ Erro fatal ao limpar banco:", error);
      throw error;
    }
  },

  async importUsersFromCSV(usersList: any[]) {
    return this.importAllColaboradores(usersList);
  },

  async importAllColaboradores(usersList: any[]) {
    console.log(`🚀 Iniciando importação em lote de ${usersList.length} registros...`);
    try {
      const batch = writeBatch(db);
      let count = 0;

      usersList.forEach((user, index) => {
        if (!user.id || !user.name) {
          console.warn(`Linha ${index + 1} ignorada: ID ou Nome faltando.`);
          return;
        }

        // Garante que o ID não tenha espaços ou caracteres inválidos para documento
        const safeId = user.id.trim().toLowerCase();
        const userRef = doc(db, 'employees', safeId);

        // Mapeia os campos do CSV para a estrutura da interface Employee
        const userData = {
          id: safeId,
          username: safeId,
          name: user.name,
          email: `${safeId}@arcaplast.com.br`, 
          role: user.role,
          team: user.department, 
          department: user.department,
          company: user.company,
          active: true,
          canLogin: user.role === 'ADMIN' || user.role === 'LEADER',
          updatedAt: serverTimestamp()
        };

        console.log(`📄 Processando linha ${index + 1}: ${user.name}`);
        batch.set(userRef, userData, { merge: true });
        count++;
      });

      if (count > 0) {
        await batch.commit();
        console.log("✅ Lote (batch) enviado com sucesso ao Firebase!");
        return true;
      } else {
        console.log("⚠️ Nenhum registro válido para importar.");
        return false;
      }
    } catch (error) {
      console.error("❌ Erro detalhado na importação:", error);
      throw error;
    }
  },

  async updateUserRole(uid: string, newRole: Role): Promise<boolean> {
    try {
      const docRef = doc(db, 'employees', uid);
      await updateDoc(docRef, { role: newRole });
      return true;
    } catch (e) {
      console.error("Erro ao atualizar cargo:", e);
      return false;
    }
  },

  async addEmployee(employee: Employee): Promise<void> {
    await setDoc(doc(db, 'employees', employee.id), employee);
  },

  async updateEmployee(employee: Employee): Promise<void> {
    const { id, ...data } = employee;
    await updateDoc(doc(db, 'employees', id), data as any);
  },

  async deleteEmployee(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'employees', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  // --- TIME RECORDS CRUD ---

  async saveTimeRecord(record: TimeRecord): Promise<void> {
    await setDoc(doc(db, 'time_records', record.id), {
      ...record,
      timestamp: serverTimestamp()
    });
  },

  // Nova função para lançamentos manuais do RH
  async saveManualOccurrence(occurrenceData: any): Promise<void> {
    try {
      // Reutiliza a estrutura de TimeRecord, mas mapeia campos específicos se necessário
      // occurrenceData já deve vir formatado ou podemos formatar aqui
      await setDoc(doc(db, 'time_records', occurrenceData.id), {
        ...occurrenceData,
        timestamp: serverTimestamp()
      });
      console.log("✅ Ocorrência manual salva com sucesso.");
    } catch (e) {
      console.error("Erro ao salvar ocorrência manual:", e);
      throw e;
    }
  },

  // --- GRAVAÇÃO EM LOTE (BULK) ---
  async saveBulkOccurrences(records: TimeRecord[]): Promise<{ success: boolean; count: number }> {
    console.log(`🚀 Iniciando gravação em massa de ${records.length} registros...`);
    try {
      // Firebase suporta máximo de 500 operações por lote.
      // Vamos dividir em chunks se necessário.
      const CHUNK_SIZE = 450; 
      const chunks = [];

      for (let i = 0; i < records.length; i += CHUNK_SIZE) {
        chunks.push(records.slice(i, i + CHUNK_SIZE));
      }

      let totalCommitted = 0;

      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(record => {
           const docRef = doc(db, 'time_records', record.id);
           batch.set(docRef, {
             ...record,
             timestamp: serverTimestamp()
           });
        });
        await batch.commit();
        totalCommitted += chunk.length;
        console.log(`✅ Lote de ${chunk.length} registros processado.`);
      }

      return { success: true, count: totalCommitted };
    } catch (error) {
      console.error("❌ Erro na gravação em massa:", error);
      throw error;
    }
  },

  async getRecords(): Promise<TimeRecord[]> {
    try {
      const q = query(collection(db, 'time_records'), orderBy('date', 'desc'));
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error("Error fetching records:", e);
      return [];
    }
  },

  async getUserRecords(userId: string): Promise<TimeRecord[]> {
    try {
      const q = query(
        collection(db, 'time_records'), 
        where('employeeId', '==', userId),
        orderBy('date', 'desc')
      );
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error(`Error fetching records for user ${userId}:`, e);
      return [];
    }
  },

  async updateRecord(record: TimeRecord): Promise<boolean> {
    try {
      const { id, ...data } = record;
      await updateDoc(doc(db, 'time_records', id), data as any);
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  async deleteRecord(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'time_records', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  }
};

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, Filter, Calendar, CheckSquare, Square, 
  Save, Loader2, Building2, Briefcase, Check, AlertCircle 
} from 'lucide-react';
import { Employee, RecordType, TimeRecord } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface BulkOccurrenceProps {
  employees: Employee[];
  currentUser: Employee;
  onRecordsAdded: () => void;
}

const BULK_TYPES = [
  { label: 'Falta', type: RecordType.DEBIT },
  { label: 'Atestado Médico', type: RecordType.NEUTRAL },
  { label: 'Feriado', type: RecordType.NEUTRAL },
  { label: 'Suspensão', type: RecordType.DEBIT },
  { label: 'Treinamento', type: RecordType.CREDIT },
  { label: 'Recesso', type: RecordType.NEUTRAL },
];

const BulkOccurrence: React.FC<BulkOccurrenceProps> = ({ employees, currentUser, onRecordsAdded }) => {
  // Filters
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');

  // Selection
  const [selectedUserIds, setSelectedUserIds] = useState<Set<string>>(new Set());

  // Form Data
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [occurrenceLabel, setOccurrenceLabel] = useState(BULK_TYPES[0].label);
  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);
  const [observation, setObservation] = useState('');

  // Status
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // Derived Filters
  const companies = useMemo(() => Array.from(new Set(employees.map(e => e.company).filter(Boolean))).sort(), [employees]);

  const teams = useMemo(() => {
    let filtered = employees;
    if (selectedCompany) filtered = filtered.filter(e => e.company === selectedCompany);
    return Array.from(new Set(filtered.map(e => e.team).filter(Boolean))).sort();
  }, [employees, selectedCompany]);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => {
      const matchCompany = selectedCompany ? e.company === selectedCompany : true;
      const matchTeam = selectedTeam ? e.team === selectedTeam : true;
      return matchCompany && matchTeam && e.active;
    });
  }, [employees, selectedCompany, selectedTeam]);

  // Handlers
  const handleSelectAll = () => {
    if (selectedUserIds.size === filteredEmployees.length) {
      setSelectedUserIds(new Set()); // Deselect all
    } else {
      setSelectedUserIds(new Set(filteredEmployees.map(e => e.id))); // Select all visible
    }
  };

  const handleToggleUser = (id: string) => {
    const newSet = new Set(selectedUserIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedUserIds(newSet);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUserIds.size === 0) {
      alert("Selecione pelo menos um colaborador.");
      return;
    }
    if (!observation) {
      alert("A observação é obrigatória para lançamentos em massa.");
      return;
    }

    setLoading(true);

    try {
      const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
      const recordType = typeObj ? typeObj.type : RecordType.NEUTRAL;

      // Create Records Array
      const recordsToSave: TimeRecord[] = Array.from(selectedUserIds).map(userId => {
        const emp = employees.find(e => e.id === userId);
        return {
          id: uuidv4(),
          employeeId: userId,
          employeeName: emp?.name || 'Desconhecido',
          date: date,
          hours: Number(hours),
          minutes: Number(minutes),
          startTime: '', // Não aplicável em massa geralmente
          endTime: '',   // Não aplicável em massa geralmente
          type: recordType,
          occurrenceType: occurrenceLabel,
          reason: observation,
          createdAt: new Date().toISOString(),
          createdBy: currentUser.id,
          // Se for Feriado/Atestado/Recesso com horas 0, é informativo (Neutro)
          // Se tiver horas, impacta o saldo conforme o recordType definido acima.
        };
      });

      const result = await firebaseService.saveBulkOccurrences(recordsToSave);

      if (result.success) {
        setSuccessMsg(`Lançamento concluído com sucesso para ${result.count} colaboradores!`);
        onRecordsAdded();

        // Reset Logic
        setSelectedUserIds(new Set());
        setObservation('');
        setHours(0);
        setMinutes(0);

        setTimeout(() => setSuccessMsg(null), 5000);
      }
    } catch (error) {
      console.error(error);
      alert("Erro ao processar lançamento em massa.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">

      {successMsg && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-md w-full mx-4">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMsg}</p>
          </div>
        </div>
      )}

      <div className="flex items-center gap-3">
        <div className="p-3 bg-purple-100 text-purple-700 rounded-xl">
          <Users size={28} />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Lançamento em Massa (RH)</h2>
          <p className="text-slate-500">Aplique ocorrências (feriados, faltas coletivas) para múltiplos colaboradores.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* LEFT COLUMN: SELECTION LIST */}
        <div className="lg:col-span-2 bg-white rounded-xl shadow-sm border border-slate-200 flex flex-col h-[600px]">

          {/* Filters Header */}
          <div className="p-4 border-b border-slate-200 space-y-4 bg-slate-50 rounded-t-xl">
            <div className="flex gap-4">
              <div className="flex-1 relative">
                 <Building2 className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedCompany} 
                   onChange={e => setSelectedCompany(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-purple-500 focus:border-purple-500"
                 >
                   <option value="">Todas as Empresas</option>
                   {companies.map(c => <option key={c} value={c}>{c}</option>)}
                 </select>
              </div>
              <div className="flex-1 relative">
                 <Briefcase className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedTeam} 
                   onChange={e => setSelectedTeam(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-purple-500 focus:border-purple-500"
                 >
                   <option value="">Todos os Setores</option>
                   {teams.map(t => <option key={t} value={t}>{t}</option>)}
                 </select>
              </div>
            </div>

            <div className="flex justify-between items-center pt-2">
              <span className="text-sm font-semibold text-slate-700">
                {filteredEmployees.length} Colaboradores listados
              </span>
              <button 
                onClick={handleSelectAll}
                className="text-sm text-purple-600 font-medium hover:text-purple-800 flex items-center gap-1"
              >
                {selectedUserIds.size === filteredEmployees.length && filteredEmployees.length > 0 ? (
                  <><CheckSquare size={16}/> Desmarcar Todos</>
                ) : (
                  <><Square size={16}/> Selecionar Todos</>
                )}
              </button>
            </div>
          </div>

          {/* List Area */}
          <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
            {filteredEmployees.length > 0 ? (
              <div className="space-y-1">
                {filteredEmployees.map(emp => {
                  const isSelected = selectedUserIds.has(emp.id);
                  return (
                    <div 
                      key={emp.id}
                      onClick={() => handleToggleUser(emp.id)}
                      className={`flex items-center p-3 rounded-lg cursor-pointer transition-colors ${isSelected ? 'bg-purple-50 border border-purple-200' : 'hover:bg-slate-50 border border-transparent'}`}
                    >
                      <div className={`mr-4 ${isSelected ? 'text-purple-600' : 'text-slate-300'}`}>
                        {isSelected ? <CheckSquare size={20} /> : <Square size={20} />}
                      </div>
                      <div>
                        <p className={`text-sm font-medium ${isSelected ? 'text-purple-900' : 'text-slate-700'}`}>{emp.name}</p>
                        <p className="text-xs text-slate-500">{emp.company} - {emp.team}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="h-full flex items-center justify-center text-slate-400">
                Nenhum colaborador encontrado com os filtros atuais.
              </div>
            )}
          </div>

          <div className="p-3 bg-slate-50 border-t border-slate-200 text-center text-xs text-slate-500 rounded-b-xl">
             {selectedUserIds.size} colaboradores selecionados
          </div>
        </div>

        {/* RIGHT COLUMN: FORM ACTION */}
        <div className="bg-white rounded-xl shadow-lg border border-purple-100 p-6 h-fit sticky top-6">
          <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
             <Filter className="mr-2 text-purple-600" size={20}/>
             Detalhes do Lançamento
          </h3>

          <form onSubmit={handleSubmit} className="space-y-5">

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Data da Ocorrência</label>
              <div className="relative">
                 <Calendar className="absolute left-3 top-3 text-slate-400 w-5 h-5" />
                 <input 
                   type="date" 
                   required
                   value={date}
                   onChange={e => setDate(e.target.value)}
                   className="block w-full pl-10 px-3 py-2.5 border border-slate-300 rounded-lg focus:ring-purple-500 focus:border-purple-500 bg-slate-50"
                 />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Tipo de Ocorrência</label>
              <select 
                value={occurrenceLabel}
                onChange={e => setOccurrenceLabel(e.target.value)}
                className="block w-full px-3 py-2.5 border border-slate-300 rounded-lg focus:ring-purple-500 focus:border-purple-500 bg-slate-50"
              >
                {BULK_TYPES.map(t => <option key={t.label} value={t.label}>{t.label}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Impacto (Horas/Minutos)</label>
              <div className="grid grid-cols-2 gap-3">
                 <div>
                    <span className="text-xs text-slate-500">Horas</span>
                    <input 
                      type="number" 
                      min="0" 
                      value={hours}
                      onChange={e => setHours(Number(e.target.value))}
                      className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-purple-500 bg-slate-50"
                    />
                 </div>
                 <div>
                    <span className="text-xs text-slate-500">Minutos</span>
                    <input 
                      type="number" 
                      min="0" max="59"
                      value={minutes}
                      onChange={e => setMinutes(Number(e.target.value))}
                      className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-purple-500 bg-slate-50"
                    />
                 </div>
              </div>
              <p className="text-xs text-slate-400 mt-1">Deixe zerado se for apenas informativo.</p>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Observação Coletiva</label>
              <textarea 
                required
                rows={3}
                value={observation}
                onChange={e => setObservation(e.target.value)}
                placeholder="Ex: Feriado Nacional, Treinamento de Segurança..."
                className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-purple-500 bg-slate-50"
              />
            </div>

            <div className="pt-2">
              <button
                type="submit"
                disabled={loading || selectedUserIds.size === 0}
                className={`w-full flex justify-center py-3 px-4 border border-transparent rounded-xl shadow-md text-base font-bold text-white transition-all ${
                  loading || selectedUserIds.size === 0
                    ? 'bg-slate-300 cursor-not-allowed' 
                    : 'bg-purple-600 hover:bg-purple-700 transform hover:-translate-y-0.5'
                }`}
              >
                {loading ? (
                  <span className="flex items-center">
                    <Loader2 className="animate-spin -ml-1 mr-2 h-5 w-5" />
                    Aplicando...
                  </span>
                ) : (
                  <span className="flex items-center">
                    <Save className="mr-2" size={20} />
                    Aplicar para {selectedUserIds.size} pessoas
                  </span>
                )}
              </button>
            </div>
          </form>
        </div>

      </div>
    </div>
  );
};

