export default BulkOccurrence;

import { 
  signInWithEmailAndPassword, 
  signOut, 
  User 
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  getDocs, 
  where, 
  orderBy, 
  deleteDoc, 
  updateDoc,
  serverTimestamp,
  writeBatch
} from 'firebase/firestore';
import { auth, db } from '../lib/firebase';
import { Employee, Role, TimeRecord, RecordType } from '../types';

export const firebaseService = {
  auth,
  db,

  // --- AUTHENTICATION ---

  async login(email: string, pass: string): Promise<{ success: boolean; user?: Employee; message?: string }> {
    try {
      if (!auth) {
         throw new Error("Serviço de autenticação não está pronto.");
      }

      const userCredential = await signInWithEmailAndPassword(auth, email, pass);
      const profile = await this.getOrCreateProfile(userCredential.user);
      return { success: true, user: profile };
    } catch (error: any) {
      console.error("Login Error:", error);
      let msg = "Erro ao realizar login.";

      if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found') {
        msg = "E-mail ou senha inválidos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas. Tente novamente mais tarde.";
      } else if (error.code === 'auth/network-request-failed') {
        msg = "Erro de conexão. Verifique sua internet.";
      }

      return { success: false, message: msg };
    }
  },

  async logout(): Promise<void> {
    if (auth) await signOut(auth);
  },

  // --- USER PROFILE ---

  async getUserProfile(uid: string): Promise<Employee | null> {
    try {
      const docRef = doc(db, 'employees', uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? (docSnap.data() as Employee) : null;
    } catch (e) {
      console.error("Erro ao buscar perfil:", e);
      return null;
    }
  },

  async getOrCreateProfile(user: User, name?: string): Promise<Employee> {
    const email = user.email?.toLowerCase() || '';
    const isSuperAdmin = email === 'ti@arcaplast.com.br';

    // Tenta buscar pelo UID primeiro (Login padrão)
    let existingProfile = await this.getUserProfile(user.uid);

    // Se não achar pelo UID, tenta buscar pelo username (caso tenha sido importado via CSV e seja o primeiro login)
    if (!existingProfile && email) {
        const username = email.split('@')[0];
        const docRefUser = doc(db, 'employees', username);
        const docSnapUser = await getDoc(docRefUser);

        if (docSnapUser.exists()) {
            console.log("Perfil encontrado via username (importado). Vinculando UID...");
            existingProfile = docSnapUser.data() as Employee;
        }
    }

    if (existingProfile) {
      if (isSuperAdmin && existingProfile.role !== Role.ADMIN) {
        console.log("Atualizando permissão de Super Admin...");
        const updated = { ...existingProfile, role: Role.ADMIN };
        await setDoc(doc(db, 'employees', user.uid), updated, { merge: true });
        return updated;
      }
      return existingProfile;
    }

    console.log("Criando novo perfil para:", email);
    const newEmployee: Employee = {
      id: user.uid,
      name: name || user.displayName || 'Colaborador',
      email: email,
      username: email.split('@')[0],
      role: isSuperAdmin ? Role.ADMIN : Role.EMPLOYEE,
      team: 'Geral',
      company: 'Arca Plast',
      active: true
    };

    await setDoc(doc(db, 'employees', user.uid), newEmployee);
    return newEmployee;
  },

  // --- EMPLOYEES CRUD ---

  async getAllUsers(): Promise<Employee[]> {
    return this.getEmployees();
  },

  async getEmployees(): Promise<Employee[]> {
    try {
      const q = query(collection(db, 'employees'), orderBy('name'));
      const querySnapshot = await getDocs(q);
      return querySnapshot.docs.map(doc => doc.data() as Employee);
    } catch (e) {
      console.error("Error fetching employees:", e);
      return [];
    }
  },

  // Função robusta para deletar todos os usuários exceto TI e usuário atual
  async deleteAllEmployees(currentUserEmail: string): Promise<boolean> {
    console.log("🚀 LIMPEZA INICIADA...");

    try {
      const q = query(collection(db, 'employees'));
      const querySnapshot = await getDocs(q);

      const batch = writeBatch(db);
      let deleteCount = 0;

      querySnapshot.forEach((doc) => {
        const data = doc.data() as Employee;
        const email = data.email?.toLowerCase();

        // Proteção Crítica: Não apagar o Admin TI e nem o usuário que está logado executando a ação
        if (email === 'ti@arcaplast.com.br' || email === currentUserEmail?.toLowerCase()) {
          console.log(`🛡️ Protegendo usuário admin: ${data.name} (${email})`);
          return;
        }

        console.log(`🗑️ Agendando exclusão: ${data.name} (${doc.id})`);
        batch.delete(doc.ref);
        deleteCount++;
      });

      if (deleteCount > 0) {
        await batch.commit();
        console.log(`✅ LIMPEZA CONCLUÍDA! ${deleteCount} colaboradores removidos.`);
        return true;
      } else {
        console.log("ℹ️ Nenhum colaborador elegível para remoção encontrado.");
        return true;
      }
    } catch (error) {
      console.error("❌ Erro fatal ao limpar banco:", error);
      throw error;
    }
  },

  async importUsersFromCSV(usersList: any[]) {
    return this.importAllColaboradores(usersList);
  },

  async importAllColaboradores(usersList: any[]) {
    console.log(`🚀 Iniciando importação em lote de ${usersList.length} registros...`);
    try {
      const batch = writeBatch(db);
      let count = 0;

      usersList.forEach((user, index) => {
        if (!user.id || !user.name) {
          console.warn(`Linha ${index + 1} ignorada: ID ou Nome faltando.`);
          return;
        }

        // Garante que o ID não tenha espaços ou caracteres inválidos para documento
        const safeId = user.id.trim().toLowerCase();
        const userRef = doc(db, 'employees', safeId);

        // Mapeia os campos do CSV para a estrutura da interface Employee
        const userData = {
          id: safeId,
          username: safeId,
          name: user.name,
          email: `${safeId}@arcaplast.com.br`, 
          role: user.role,
          team: user.department, 
          department: user.department,
          company: user.company,
          active: true,
          canLogin: user.role === 'ADMIN' || user.role === 'LEADER',
          updatedAt: serverTimestamp()
        };

        console.log(`📄 Processando linha ${index + 1}: ${user.name}`);
        batch.set(userRef, userData, { merge: true });
        count++;
      });

      if (count > 0) {
        await batch.commit();
        console.log("✅ Lote (batch) enviado com sucesso ao Firebase!");
        return true;
      } else {
        console.log("⚠️ Nenhum registro válido para importar.");
        return false;
      }
    } catch (error) {
      console.error("❌ Erro detalhado na importação:", error);
      throw error;
    }
  },

  async updateUserRole(uid: string, newRole: Role): Promise<boolean> {
    try {
      const docRef = doc(db, 'employees', uid);
      await updateDoc(docRef, { role: newRole });
      return true;
    } catch (e) {
      console.error("Erro ao atualizar cargo:", e);
      return false;
    }
  },

  async addEmployee(employee: Employee): Promise<void> {
    await setDoc(doc(db, 'employees', employee.id), employee);
  },

  async updateEmployee(employee: Employee): Promise<void> {
    const { id, ...data } = employee;
    await updateDoc(doc(db, 'employees', id), data as any);
  },

  async deleteEmployee(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'employees', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  // --- TIME RECORDS CRUD ---

  async saveTimeRecord(record: TimeRecord): Promise<void> {
    await setDoc(doc(db, 'time_records', record.id), {
      ...record,
      timestamp: serverTimestamp()
    });
  },

  // Nova função para lançamentos manuais do RH
  async saveManualOccurrence(occurrenceData: any): Promise<void> {
    try {
      // Reutiliza a estrutura de TimeRecord, mas mapeia campos específicos se necessário
      // occurrenceData já deve vir formatado ou podemos formatar aqui
      await setDoc(doc(db, 'time_records', occurrenceData.id), {
        ...occurrenceData,
        timestamp: serverTimestamp()
      });
      console.log("✅ Ocorrência manual salva com sucesso.");
    } catch (e) {
      console.error("Erro ao salvar ocorrência manual:", e);
      throw e;
    }
  },

  // --- GRAVAÇÃO EM LOTE (BULK) ---
  async saveBulkOccurrences(records: TimeRecord[]): Promise<{ success: boolean; count: number }> {
    console.log(`🚀 Iniciando gravação em massa de ${records.length} registros...`);
    try {
      // Firebase suporta máximo de 500 operações por lote.
      // Vamos dividir em chunks se necessário.
      const CHUNK_SIZE = 450; 
      const chunks = [];

      for (let i = 0; i < records.length; i += CHUNK_SIZE) {
        chunks.push(records.slice(i, i + CHUNK_SIZE));
      }

      let totalCommitted = 0;

      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(record => {
           const docRef = doc(db, 'time_records', record.id);
           batch.set(docRef, {
             ...record,
             timestamp: serverTimestamp()
           });
        });
        await batch.commit();
        totalCommitted += chunk.length;
        console.log(`✅ Lote de ${chunk.length} registros processado.`);
      }

      return { success: true, count: totalCommitted };
    } catch (error) {
      console.error("❌ Erro na gravação em massa:", error);
      throw error;
    }
  },

  // EXCLUSÃO EM LOTE (POR BATCH_ID)
  async deleteBatchRecords(batchId: string): Promise<{ success: boolean; count: number }> {
    console.log(`🗑️ Iniciando exclusão do lote ${batchId}...`);
    try {
      const q = query(collection(db, 'time_records'), where('batchId', '==', batchId));
      const querySnapshot = await getDocs(q);

      const recordsToDelete = querySnapshot.docs;

      if (recordsToDelete.length === 0) return { success: true, count: 0 };

      const CHUNK_SIZE = 450; 
      const chunks = [];

      for (let i = 0; i < recordsToDelete.length; i += CHUNK_SIZE) {
        chunks.push(recordsToDelete.slice(i, i + CHUNK_SIZE));
      }

      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(docSnap => {
           batch.delete(docSnap.ref);
        });
        await batch.commit();
      }

      console.log(`✅ Exclusão em lote concluída: ${recordsToDelete.length} removidos.`);
      return { success: true, count: recordsToDelete.length };

    } catch (error) {
      console.error("❌ Erro na exclusão em massa:", error);
      return { success: false, count: 0 };
    }
  },

  // ATUALIZAÇÃO EM LOTE (POR BATCH_ID)
  async updateBatchRecords(batchId: string, updateData: Partial<TimeRecord>): Promise<{ success: boolean; count: number }> {
    console.log(`✏️ Iniciando atualização do lote ${batchId}...`);
    try {
       const q = query(collection(db, 'time_records'), where('batchId', '==', batchId));
       const querySnapshot = await getDocs(q);

       const recordsToUpdate = querySnapshot.docs;

       if (recordsToUpdate.length === 0) return { success: true, count: 0 };

       const CHUNK_SIZE = 450;
       const chunks = [];

       for (let i = 0; i < recordsToUpdate.length; i += CHUNK_SIZE) {
         chunks.push(recordsToUpdate.slice(i, i + CHUNK_SIZE));
       }

       for (const chunk of chunks) {
         const batch = writeBatch(db);
         chunk.forEach(docSnap => {
            batch.update(docSnap.ref, updateData as any);
         });
         await batch.commit();
       }

       console.log(`✅ Atualização em lote concluída: ${recordsToUpdate.length} atualizados.`);
       return { success: true, count: recordsToUpdate.length };
    } catch (error) {
       console.error("❌ Erro na atualização em massa:", error);
       return { success: false, count: 0 };
    }
  },

  async getRecords(): Promise<TimeRecord[]> {
    try {
      const q = query(collection(db, 'time_records'), orderBy('date', 'desc'));
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error("Error fetching records:", e);
      return [];
    }
  },

  async getUserRecords(userId: string): Promise<TimeRecord[]> {
    try {
      const q = query(
        collection(db, 'time_records'), 
        where('employeeId', '==', userId),
        orderBy('date', 'desc')
      );
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error(`Error fetching records for user ${userId}:`, e);
      return [];
    }
  },

  async updateRecord(record: TimeRecord): Promise<boolean> {
    try {
      const { id, ...data } = record;
      await updateDoc(doc(db, 'time_records', id), data as any);
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  async deleteRecord(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'time_records', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { FileText, Download, Users, Edit, Trash2, Loader2, Save, X, Check, Layers, ChevronDown, ChevronRight, AlertTriangle } from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType, Role } from '../types';
import { firebaseService } from '../services/firebaseService';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
  currentUser: Employee;
  refreshData: () => void;
  onUpdateRecord: (record: TimeRecord) => void;
  onDeleteRecord: (id: string) => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const Reports: React.FC<ReportsProps> = ({ records, employees, currentUser, refreshData, onUpdateRecord, onDeleteRecord }) => {
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Success Popup State
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Expanded Batches State
  const [expandedBatches, setExpandedBatches] = useState<Set<string>>(new Set());

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingRecord, setEditingRecord] = useState<TimeRecord | null>(null);
  const [isBatchEdit, setIsBatchEdit] = useState(false); // Flag para edição em lote
  const [editDate, setEditDate] = useState('');
  const [editStartTime, setEditStartTime] = useState('');
  const [editEndTime, setEditEndTime] = useState('');
  const [editReason, setEditReason] = useState('');
  const [editOccurrenceType, setEditOccurrenceType] = useState('');
  const [editCalculatedDuration, setEditCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isEditTimeValid, setIsEditTimeValid] = useState(true);

  // --- Logic Checks ---
  const canUserEdit = (record: TimeRecord) => {
    // Admin can edit all
    if (currentUser.role === Role.ADMIN) return true;
    // Leader can edit ONLY if they created it
    if (currentUser.role === Role.LEADER && record.createdBy === currentUser.id) return true;
    return false;
  };

  // --- Helper: Format minutes to HH:MM ---
  const formatTime = (totalMinutes: number) => {
    const hours = Math.floor(Math.abs(totalMinutes) / 60);
    const minutes = Math.abs(totalMinutes) % 60;
    const sign = totalMinutes < 0 ? '-' : '';
    return `${sign}${hours}h ${minutes.toString().padStart(2, '0')}m`;
  };

  // --- Helper: Format Date ---
  const formatDate = (dateString: string) => {
    if (!dateString) return '-';
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
        const [year, month, day] = dateString.split('-');
        return `${day}/${month}/${year}`;
    }
    try {
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return dateString;
      return new Intl.DateTimeFormat('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      }).format(date);
    } catch (error) {
      return dateString;
    }
  };

  const formatTimeOnly = (val?: string | number) => {
    if (val === undefined || val === null || val === '') return '-';
    const strVal = String(val);
    if (strVal.includes('T')) return strVal.split('T')[1].substring(0, 5);
    if (strVal.includes(':')) return strVal.substring(0, 5);
    return strVal.length > 5 ? strVal.substring(0, 5) : strVal;
  };

  const safeDateForInput = (dateString: string) => {
    if (!dateString) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return dateString;
    if (dateString.includes('T')) return dateString.split('T')[0];
    const d = new Date(dateString);
    if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
    return '';
  };

  const getLeaderName = (leaderId: string) => {
    const leader = employees.find(e => e.id === leaderId);
    return leader ? leader.name : 'Desconhecido';
  };

  const getEmployeeCompany = (empId: string) => {
    const emp = employees.find(e => e.id === empId);
    return emp ? (emp.company || 'N/A') : '-';
  };

  const getConsolidatedData = () => {
    return employees.filter(e => e.active).map(emp => {
      const empRecords = records.filter(r => r.employeeId === emp.id);
      let creditMins = 0;
      let debitMins = 0;
      empRecords.forEach(r => {
        const mins = (r.hours * 60) + r.minutes;
        if (r.type === RecordType.CREDIT) creditMins += mins;
        else if (r.type === RecordType.DEBIT) debitMins += mins;
      });
      const netBalance = creditMins - debitMins;
      return {
        name: emp.name,
        company: emp.company || 'N/A',
        team: emp.team,
        role: emp.role,
        positive: formatTime(creditMins),
        negative: formatTime(debitMins),
        balance: formatTime(netBalance),
        rawBalance: netBalance 
      };
    }).sort((a, b) => {
      if (a.company !== b.company) return a.company.localeCompare(b.company);
      return a.name.localeCompare(b.name);
    }); 
  };

  useEffect(() => {
    if (!editStartTime || !editEndTime) return;
    const [startH, startM] = editStartTime.split(':').map(Number);
    const [endH, endM] = editEndTime.split(':').map(Number);
    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsEditTimeValid(false);
      setEditCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsEditTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setEditCalculatedDuration({ hours: h, minutes: m });
    }
  }, [editStartTime, editEndTime]);

  const showSuccessPopup = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => {
      setSuccessMessage(null);
    }, 3000);
  };

  const handleDelete = async (id: string, batchId?: string) => {
    // Se tiver batchId, pergunta se quer excluir o lote
    if (batchId) {
        if (!confirm(`⚠️ Atenção: Este registro faz parte de um Lançamento em Massa.\n\nDeseja excluir TODOS os registros deste lote?`)) return;

        setLoadingAction(`batch-${batchId}`);
        try {
           const result = await firebaseService.deleteBatchRecords(batchId);
           if (result.success) {
               refreshData(); // Recarrega tudo
               showSuccessPopup(`Lote excluído! ${result.count} registros removidos.`);
           } else {
               alert("Erro ao excluir lote.");
           }
        } catch(e) {
            console.error(e);
            alert("Erro ao processar exclusão.");
        } finally {
            setLoadingAction(null);
        }
        return;
    }

    // Exclusão Individual
    if (!confirm('Tem certeza que deseja excluir este registro permanentemente?')) return;
    setLoadingAction(id);
    try {
        const success = await firebaseService.deleteRecord(id);
        if (success) {
          onDeleteRecord(id);
          showSuccessPopup('Registro excluído com sucesso.');
        } else {
          alert('Erro ao excluir registro.');
        }
    } catch (e) {
        alert("Erro de conexão.");
    } finally {
        setLoadingAction(null);
    }
  };

  const openEditModal = (record: TimeRecord, isBatch: boolean = false) => {
    setEditingRecord(record);
    setIsBatchEdit(isBatch);

    setEditDate(safeDateForInput(record.date));
    const cleanStart = formatTimeOnly(record.startTime);
    const cleanEnd = formatTimeOnly(record.endTime);
    setEditStartTime(cleanStart === '-' ? '' : cleanStart);
    setEditEndTime(cleanEnd === '-' ? '' : cleanEnd);
    setEditReason(record.reason);
    setEditOccurrenceType(record.occurrenceType);
    setEditCalculatedDuration({ hours: record.hours, minutes: record.minutes });
    setIsEditTimeValid(true);
    setIsEditModalOpen(true);
  };

  const handleUpdateRecord = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingRecord || !isEditTimeValid) return;
    if (editCalculatedDuration.hours === 0 && editCalculatedDuration.minutes === 0) {
      alert("Duração inválida.");
      return;
    }

    setLoadingAction('modal-save');
    const option = OCCURRENCE_OPTIONS.find(o => o.label === editOccurrenceType);
    const newType = option ? option.type : RecordType.CREDIT;

    const updateData: Partial<TimeRecord> = {
      date: editDate,
      startTime: editStartTime,
      endTime: editEndTime,
      hours: editCalculatedDuration.hours,
      minutes: editCalculatedDuration.minutes,
      reason: editReason,
      occurrenceType: editOccurrenceType,
      type: newType
    };

    try {
        if (isBatchEdit && editingRecord.batchId) {
            // Atualização em Lote
            const result = await firebaseService.updateBatchRecords(editingRecord.batchId, updateData);
            if (result.success) {
                refreshData();
                showSuccessPopup(`Lote atualizado! ${result.count} registros alterados.`);
            } else {
                alert("Falha ao atualizar lote.");
            }
        } else {
            // Atualização Individual
            const updatedRecord = { ...editingRecord, ...updateData };
            const success = await firebaseService.updateRecord(updatedRecord);
            if (success) {
                onUpdateRecord(updatedRecord);
                showSuccessPopup('Registro atualizado com sucesso.');
            } else {
                alert("Falha ao salvar no banco.");
            }
        }
        setIsEditModalOpen(false);
        setEditingRecord(null);
    } catch (error) {
        console.error("Error updating record:", error);
        alert("Erro ao conectar com o servidor.");
    } finally {
        setLoadingAction(null);
    }
  };

  // --- Process Data for Display (Filtering & Grouping) ---
  const { processedRecords, batchMap } = useMemo(() => {
    // 1. Filtragem por Permissão
    let filtered = records.filter(r => {
      if (currentUser.role === Role.ADMIN) return true;
      if (currentUser.role === Role.LEADER) return r.createdBy === currentUser.id;
      return false;
    });

    // 2. Ordenação por Data (Decrescente)
    filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    // 3. Estrutura de Agrupamento
    // Lista final para renderização (pode conter Record Individual ou BatchLeader)
    const viewList: any[] = [];
    // Mapa para guardar os filhos de cada batch
    const batches: Record<string, TimeRecord[]> = {};
    const seenBatches = new Set<string>();

    filtered.forEach(record => {
       if (record.batchId) {
          if (!batches[record.batchId]) {
             batches[record.batchId] = [];
          }
          batches[record.batchId].push(record);

          if (!seenBatches.has(record.batchId)) {
             // É o primeiro deste lote que encontramos, então criamos um "Líder Visual"
             viewList.push({ ...record, isBatchLeader: true });
             seenBatches.add(record.batchId);
          }
       } else {
          // Registro individual normal
          viewList.push(record);
       }
    });

    return { processedRecords: viewList, batchMap: batches };
  }, [records, currentUser]);

  const toggleBatch = (batchId: string) => {
     const newSet = new Set(expandedBatches);
     if (newSet.has(batchId)) newSet.delete(batchId);
     else newSet.add(batchId);
     setExpandedBatches(newSet);
  };

  // --- PDF/Excel Generation functions preserved for functionality ---
  const generateDetailedPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);
    const tableData = records.map(r => [ // Exporta TODOS (sem agrupar no PDF) para detalhe real
      formatDate(r.date), getEmployeeCompany(r.employeeId), r.employeeName, getLeaderName(r.createdBy), r.occurrenceType || r.type, r.reason, formatTimeOnly(r.startTime), formatTimeOnly(r.endTime), `${r.hours}h ${r.minutes}m`
    ]);
    autoTable(doc, {
      head: [['Data', 'Empresa', 'Colaborador', 'Líder', 'Tipo', 'Descrição', 'Início', 'Fim', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] },
      columnStyles: { 5: { cellWidth: 35 } } 
    });
    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(records.map(r => ({
      Data: formatDate(r.date), Empresa: getEmployeeCompany(r.employeeId), Colaborador: r.employeeName, Líder: getLeaderName(r.createdBy), 'Tipo de Ocorrência': r.occurrenceType, 'Descrição': r.reason, 'Início': formatTimeOnly(r.startTime), 'Fim': formatTimeOnly(r.endTime), Horas: r.hours, Minutos: r.minutes
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  const generateGeneralPDF = () => {
    const doc = new jsPDF();
    const data = getConsolidatedData();
    doc.setFontSize(18);
    doc.text('Balanço Geral de Horas por Colaborador', 14, 22);
    doc.setFontSize(11);
    doc.text(`Posição consolidada em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);
    const tableData = data.map(d => [d.company, d.name, d.team, d.positive, d.negative, d.balance]);
    autoTable(doc, {
      head: [['Empresa', 'Colaborador', 'Setor', 'Total Positivo', 'Total Negativo', 'Saldo Líquido']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 9, halign: 'center' },
      columnStyles: { 0: { halign: 'left' }, 1: { halign: 'left' }, 5: { fontStyle: 'bold' } },
      headStyles: { fillColor: [79, 70, 229] },
    });
    doc.save('balanco-geral-consolidado.pdf');
  };

  const generateGeneralExcel = () => {
    const data = getConsolidatedData();
    const ws = XLSX.utils.json_to_sheet(data.map(d => ({
      Empresa: d.company, Colaborador: d.name, Setor: d.team, 'Total Positivo': d.positive, 'Total Negativo': d.negative, 'Saldo Líquido': d.balance
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Saldos Consolidados");
    XLSX.writeFile(wb, "balanco-geral-consolidado.xlsx");
  };

  return (
    <div className="space-y-10 animate-fade-in relative">
      {successMessage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMessage}</p>
          </div>
        </div>
      )}

      <div>
        <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
        <p className="text-slate-500">
           {currentUser.role === Role.ADMIN 
             ? "Gerenciamento completo e auditoria de logs." 
             : "Visualize relatórios e gerencie seus lançamentos."}
        </p>
      </div>

      {currentUser.role === Role.ADMIN && (
        <div className="bg-gradient-to-r from-indigo-50 to-white p-6 rounded-xl border border-indigo-100 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
              <Users size={24} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-800">Balanço Geral (Consolidado)</h3>
              <p className="text-sm text-slate-500">Resumo de saldo final de horas por colaborador e setor.</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <button onClick={generateGeneralPDF} className="flex items-center justify-center px-4 py-4 border border-transparent text-sm font-medium rounded-lg text-white bg-indigo-600 hover:bg-indigo-700 shadow-sm transition-all"><Download className="mr-2" size={18} /> Baixar Resumo em PDF</button>
            <button onClick={generateGeneralExcel} className="flex items-center justify-center px-4 py-4 border border-indigo-200 text-sm font-medium rounded-lg text-indigo-700 bg-white hover:bg-indigo-50 shadow-sm transition-all"><Download className="mr-2" size={18} /> Baixar Resumo em Excel</button>
          </div>
        </div>
      )}

      <div className={`p-6 rounded-xl border border-indigo-100 shadow-sm ${currentUser.role === Role.ADMIN ? 'bg-gradient-to-r from-indigo-50 to-white' : 'bg-white'}`}>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
            <FileText size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Extrato de Ocorrências</h3>
            <p className="text-sm text-slate-500">{currentUser.role === Role.ADMIN ? "Lista completa de todos os registros lançados." : "Lista dos registros lançados por você."}</p>
