                           <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                              {editable && (
                                <div className="flex items-center justify-end gap-2">
                                  <button onClick={() => openEditModal(item, true)} className="text-indigo-600 hover:text-indigo-900 p-1.5 hover:bg-indigo-50 rounded-lg flex items-center gap-1 border border-transparent hover:border-indigo-100 transition-all" title="Editar Lote Completo">
                                    <Edit size={16} />
                                  </button>
                                  <button 
                                    onClick={() => handleDelete(item.id, item.batchId)} 
                                    className="text-red-600 hover:text-red-900 p-1.5 hover:bg-red-50 rounded-lg flex items-center gap-1 border border-transparent hover:border-red-100 transition-all" 
                                    title="Excluir Lote Completo"
                                    disabled={loadingAction === `batch-${item.batchId}`}
                                  >
                                    {loadingAction === `batch-${item.batchId}` ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}
                                  </button>
                                </div>
                              )}
                           </td>
                        </tr>
                        {/* Filhos do Lote (Expandidos) */}
                        {isExpanded && batchMap[item.batchId].map((child: TimeRecord) => (
                           <tr key={child.id} className="bg-slate-50/50 hover:bg-slate-100 animate-fade-in">
                              <td className="px-6 py-3 whitespace-nowrap text-xs text-slate-400 pl-12 border-l-4 border-l-transparent">↳</td>
                              <td className="px-6 py-3 whitespace-nowrap">
                                 <div className="text-sm text-slate-700">{child.employeeName}</div>
                                 <div className="text-xs text-slate-400">{getEmployeeCompany(child.employeeId)}</div>
                              </td>
                              <td className="px-6 py-3 whitespace-nowrap text-xs text-slate-400">Ver Lote</td>
                              <td className="px-6 py-3 text-xs text-slate-400 italic">Ver Lote</td>
                              <td className="px-6 py-3 whitespace-nowrap text-xs text-slate-500 font-mono">
                                 {child.hours}h {child.minutes}m
                              </td>
                              <td className="px-6 py-3 whitespace-nowrap text-right text-xs">
                                 <span className="text-slate-300 select-none">Vinculado ao Lote</span>
                              </td>
                           </tr>
                        ))}
                     </React.Fragment>
                   );
                }

                // --- LINHA INDIVIDUAL (NORMAL) ---
                return (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{formatDate(item.date)}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <div className="text-sm text-slate-900">{item.employeeName}</div>
                       <div className="text-xs text-slate-400">{getEmployeeCompany(item.employeeId)}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${item.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' : item.type === RecordType.DEBIT ? 'bg-red-100 text-red-800' : 'bg-slate-100 text-slate-600'}`}>{item.occurrenceType}</span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 max-w-xs truncate" title={item.reason}>{item.reason}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-700">{item.hours}h {item.minutes}m</td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {editable && (
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={() => openEditModal(item)} className="text-indigo-600 hover:text-indigo-900 p-1 hover:bg-indigo-50 rounded" title="Editar"><Edit size={16} /></button>
                          <button onClick={() => handleDelete(item.id)} className="text-red-600 hover:text-red-900 p-1 hover:bg-red-50 rounded" title="Excluir" disabled={loadingAction === item.id}>{loadingAction === item.id ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}</button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {isEditModalOpen && editingRecord && (
         <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        {isBatchEdit ? <><Layers size={20} className="text-purple-600"/> Editar Lote Completo</> : 'Editar Lançamento'}
                    </h3>
                    {isBatchEdit ? (
                        <p className="text-sm text-purple-600 mt-1 font-medium bg-purple-50 px-2 py-1 rounded-lg inline-block">
                            Alterações serão aplicadas para todos os colaboradores deste lote.
                        </p>
                    ) : (
                        <p className="text-sm text-slate-500">{editingRecord.employeeName}</p>
                    )}
                  </div>
                  <button onClick={() => setIsEditModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
               </div>
               <form onSubmit={handleUpdateRecord} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
                  <div><label className="block text-sm font-medium text-slate-700">Data da Ocorrência</label><input type="date" required value={editDate} onChange={e => setEditDate(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/></div>
                  <div><label className="block text-sm font-medium text-slate-700">Tipo</label><select value={editOccurrenceType} onChange={e => setEditOccurrenceType(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900">{OCCURRENCE_OPTIONS.map(opt => <option key={opt.label} value={opt.label}>{opt.label}</option>)}</select></div>
                  <div className="grid grid-cols-2 gap-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
                     <div><label className="block text-xs font-medium text-slate-500">Início</label><input type="time" value={editStartTime} onChange={e => setEditStartTime(e.target.value)} className="w-full mt-1 border border-slate-300 rounded px-2 py-1 bg-white text-slate-900"/></div>
                     <div><label className="block text-xs font-medium text-slate-500">Fim</label><input type="time" value={editEndTime} onChange={e => setEditEndTime(e.target.value)} className={`w-full mt-1 border rounded px-2 py-1 bg-white text-slate-900 ${!isEditTimeValid ? 'border-red-500' : 'border-slate-300'}`}/></div>
                     <div className="col-span-2 text-center text-sm font-bold text-indigo-600 border-t border-slate-200 pt-2">{isEditTimeValid ? `${editCalculatedDuration.hours}h ${editCalculatedDuration.minutes}m` : <span className="text-red-500">Horário Inválido</span>}</div>
                  </div>
                  <div><label className="block text-sm font-medium text-slate-700">Justificativa</label><textarea required rows={3} value={editReason} onChange={e => setEditReason(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/></div>
                  <div className="flex justify-end gap-3 pt-2">
                     <button type="button" onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                     <button type="submit" disabled={loadingAction === 'modal-save' || !isEditTimeValid} className={`px-4 py-2 text-white rounded-lg flex items-center shadow-lg ${isBatchEdit ? 'bg-purple-600 hover:bg-purple-700' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
                        {loadingAction === 'modal-save' ? <Loader2 size={16} className="animate-spin mr-2"/> : <Save size={16} className="mr-2"/>}
                        {isBatchEdit ? 'Atualizar Lote' : 'Salvar Alterações'}
                     </button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

export default Reports;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, Filter, Calendar, CheckSquare, Square, 
  Save, Loader2, Building2, Briefcase, Check, AlertCircle 
} from 'lucide-react';
import { Employee, RecordType, TimeRecord } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface BulkOccurrenceProps {
  employees: Employee[];
  currentUser: Employee;
  onRecordsAdded: () => void;
}

const BULK_TYPES = [
  { label: 'Falta', type: RecordType.DEBIT },
  { label: 'Atestado Médico', type: RecordType.NEUTRAL },
  { label: 'Feriado', type: RecordType.NEUTRAL },
  { label: 'Suspensão', type: RecordType.DEBIT },
  { label: 'Treinamento', type: RecordType.CREDIT },
  { label: 'Recesso', type: RecordType.NEUTRAL },
];

const BulkOccurrence: React.FC<BulkOccurrenceProps> = ({ employees, currentUser, onRecordsAdded }) => {
  // Filters
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');

  // Selection
  const [selectedUserIds, setSelectedUserIds] = useState<Set<string>>(new Set());

  // Form Data
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [occurrenceLabel, setOccurrenceLabel] = useState(BULK_TYPES[0].label);
  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);
  const [observation, setObservation] = useState('');

  // Status
  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  // Derived Filters
  const companies = useMemo(() => Array.from(new Set(employees.map(e => e.company).filter(Boolean))).sort(), [employees]);

  const teams = useMemo(() => {
    let filtered = employees;
    if (selectedCompany) filtered = filtered.filter(e => e.company === selectedCompany);
    return Array.from(new Set(filtered.map(e => e.team).filter(Boolean))).sort();
  }, [employees, selectedCompany]);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => {
      const matchCompany = selectedCompany ? e.company === selectedCompany : true;
      const matchTeam = selectedTeam ? e.team === selectedTeam : true;
      return matchCompany && matchTeam && e.active;
    });
  }, [employees, selectedCompany, selectedTeam]);

  // Handlers
  const handleSelectAll = () => {
    if (selectedUserIds.size === filteredEmployees.length) {
      setSelectedUserIds(new Set()); // Deselect all
    } else {
      setSelectedUserIds(new Set(filteredEmployees.map(e => e.id))); // Select all visible
    }
  };

  const handleToggleUser = (id: string) => {
    const newSet = new Set(selectedUserIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedUserIds(newSet);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUserIds.size === 0) {
      alert("Selecione pelo menos um colaborador.");
      return;
    }
    if (!observation) {
      alert("A observação é obrigatória para lançamentos em massa.");
      return;
    }

    setLoading(true);

    try {
      const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
      const recordType = typeObj ? typeObj.type : RecordType.NEUTRAL;

      // Gera um ID único para este lote (Batch ID)
      const batchId = uuidv4();

      // Create Records Array
      const recordsToSave: TimeRecord[] = Array.from(selectedUserIds).map(userId => {
        const emp = employees.find(e => e.id === userId);
        return {
          id: uuidv4(),
          batchId: batchId, // Atribui o ID do lote
          employeeId: userId,
          employeeName: emp?.name || 'Desconhecido',
          date: date,
          hours: Number(hours),
          minutes: Number(minutes),
          startTime: '', // Não aplicável em massa geralmente
          endTime: '',   // Não aplicável em massa geralmente
          type: recordType,
          occurrenceType: occurrenceLabel,
          reason: observation,
          createdAt: new Date().toISOString(),
          createdBy: currentUser.id,
        };
      });

      const result = await firebaseService.saveBulkOccurrences(recordsToSave);

      if (result.success) {
        setSuccessMsg(`Lançamento concluído com sucesso para ${result.count} colaboradores!`);
        onRecordsAdded();

        // Reset Logic
        setSelectedUserIds(new Set());
        setObservation('');
        setHours(0);
        setMinutes(0);

        setTimeout(() => setSuccessMsg(null), 5000);
      }
    } catch (error) {
      console.error(error);
      alert("Erro ao processar lançamento em massa.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">

      {successMsg && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-md w-full mx-4">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMsg}</p>
          </div>
        </div>
      )}

      <div className="flex items-center gap-3">
        <div className="p-3 bg-purple-100 text-purple-700 rounded-xl">
          <Users size={28} />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Lançamento em Massa (RH)</h2>
          <p className="text-slate-500">Aplique ocorrências (feriados, faltas coletivas) para múltiplos colaboradores.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* LEFT COLUMN: SELECTION LIST */}
        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col h-[600px]">

          {/* Filters Header */}
          <div className="p-4 border-b border-slate-200 space-y-4 bg-slate-50/50 rounded-t-2xl">
            <div className="flex gap-4">
              <div className="flex-1 relative">
                 <Building2 className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedCompany} 
                   onChange={e => setSelectedCompany(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-purple-500 focus:border-purple-500 transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todas as Empresas</option>
                   {companies.map(c => <option key={c} value={c}>{c}</option>)}
                 </select>
              </div>
              <div className="flex-1 relative">
                 <Briefcase className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedTeam} 
                   onChange={e => setSelectedTeam(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-purple-500 focus:border-purple-500 transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todos os Setores</option>
                   {teams.map(t => <option key={t} value={t}>{t}</option>)}
                 </select>
              </div>
            </div>

            <div className="flex justify-between items-center pt-2">
              <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                {filteredEmployees.length} Colaboradores
              </span>
              <button 
                onClick={handleSelectAll}
                className="text-sm text-purple-600 font-medium hover:text-purple-800 flex items-center gap-1 transition-colors"
              >
                {selectedUserIds.size === filteredEmployees.length && filteredEmployees.length > 0 ? (
                  <><CheckSquare size={16}/> Desmarcar Todos</>
                ) : (
                  <><Square size={16}/> Selecionar Todos</>
                )}
              </button>
            </div>
          </div>

          {/* List Area */}
          <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
            {filteredEmployees.length > 0 ? (
              <div className="space-y-1">
                {filteredEmployees.map(emp => {
                  const isSelected = selectedUserIds.has(emp.id);
                  return (
                    <div 
                      key={emp.id}
                      onClick={() => handleToggleUser(emp.id)}
                      className={`flex items-center p-3 rounded-xl cursor-pointer transition-all ${isSelected ? 'bg-purple-50 border border-purple-200' : 'hover:bg-slate-50 border border-transparent'}`}
                    >
                      <div className={`mr-4 transition-colors ${isSelected ? 'text-purple-600' : 'text-slate-300'}`}>
                        {isSelected ? <CheckSquare size={20} /> : <Square size={20} />}
                      </div>
                      <div>
                        <p className={`text-sm font-medium ${isSelected ? 'text-purple-900' : 'text-slate-700'}`}>{emp.name}</p>
                        <p className="text-xs text-slate-500">{emp.company} - {emp.team}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Nenhum colaborador encontrado com os filtros atuais.
              </div>
            )}
          </div>

          <div className="p-3 bg-slate-50 border-t border-slate-200 text-center text-xs text-slate-500 rounded-b-2xl">
             {selectedUserIds.size} selecionados
          </div>
        </div>

        {/* RIGHT COLUMN: FORM ACTION */}
        <div className="bg-white rounded-2xl shadow-lg border border-slate-200 p-6 h-fit sticky top-6">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
             <Filter className="mr-2 text-indigo-600" size={20}/>
             Detalhes do Lançamento
          </h3>

          <form onSubmit={handleSubmit} className="space-y-5">

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Data da Ocorrência</label>
              <div className="relative">
                 <Calendar className="absolute left-3 top-3 text-slate-400 w-4 h-4" />
                 <input 
                   type="date" 
                   required
                   value={date}
                   onChange={e => setDate(e.target.value)}
                   className="block w-full pl-9 px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                 />
              </div>
            </div>

            <div>
