  // --- TIME RECORDS CRUD ---

  async saveTimeRecord(record: TimeRecord): Promise<void> {
    await setDoc(doc(db, 'time_records', record.id), {
      ...record,
      timestamp: serverTimestamp()
    });
  },

  // Nova função para lançamentos manuais do RH
  async saveManualOccurrence(occurrenceData: any): Promise<void> {
    try {
      await setDoc(doc(db, 'time_records', occurrenceData.id), {
        ...occurrenceData,
        timestamp: serverTimestamp()
      });
      console.log("✅ Ocorrência manual salva com sucesso.");
    } catch (e) {
      console.error("Erro ao salvar ocorrência manual:", e);
      throw e;
    }
  },

  // --- GRAVAÇÃO EM LOTE (BULK) ---
  async saveBulkOccurrences(records: TimeRecord[]): Promise<{ success: boolean; count: number }> {
    console.log(`🚀 Iniciando gravação em massa de ${records.length} registros...`);
    try {
      const CHUNK_SIZE = 450; 
      const chunks = [];

      for (let i = 0; i < records.length; i += CHUNK_SIZE) {
        chunks.push(records.slice(i, i + CHUNK_SIZE));
      }

      let totalCommitted = 0;

      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(record => {
           const docRef = doc(db, 'time_records', record.id);
           batch.set(docRef, {
             ...record,
             timestamp: serverTimestamp()
           });
        });
        await batch.commit();
        totalCommitted += chunk.length;
        console.log(`✅ Lote de ${chunk.length} registros processado.`);
      }

      return { success: true, count: totalCommitted };
    } catch (error) {
      console.error("❌ Erro na gravação em massa:", error);
      throw error;
    }
  },

  // EXCLUSÃO EM LOTE (POR BATCH_ID)
  async deleteBatchRecords(batchId: string): Promise<{ success: boolean; count: number }> {
    console.log(`🗑️ Iniciando exclusão do lote ${batchId}...`);
    try {
      const q = query(collection(db, 'time_records'), where('batchId', '==', batchId));
      const querySnapshot = await getDocs(q);

      const recordsToDelete = querySnapshot.docs;

      if (recordsToDelete.length === 0) return { success: true, count: 0 };

      const CHUNK_SIZE = 450; 
      const chunks = [];

      for (let i = 0; i < recordsToDelete.length; i += CHUNK_SIZE) {
        chunks.push(recordsToDelete.slice(i, i + CHUNK_SIZE));
      }

      for (const chunk of chunks) {
        const batch = writeBatch(db);
        chunk.forEach(docSnap => {
           batch.delete(docSnap.ref);
        });
        await batch.commit();
      }

      console.log(`✅ Exclusão em lote concluída: ${recordsToDelete.length} removidos.`);
      return { success: true, count: recordsToDelete.length };

    } catch (error) {
      console.error("❌ Erro na exclusão em massa:", error);
      return { success: false, count: 0 };
    }
  },

  // ATUALIZAÇÃO EM LOTE (POR BATCH_ID)
  async updateBatchRecords(batchId: string, updateData: Partial<TimeRecord>): Promise<{ success: boolean; count: number }> {
    console.log(`✏️ Iniciando atualização do lote ${batchId}...`);
    try {
       const q = query(collection(db, 'time_records'), where('batchId', '==', batchId));
       const querySnapshot = await getDocs(q);

       const recordsToUpdate = querySnapshot.docs;

       if (recordsToUpdate.length === 0) return { success: true, count: 0 };

       const CHUNK_SIZE = 450;
       const chunks = [];

       for (let i = 0; i < recordsToUpdate.length; i += CHUNK_SIZE) {
         chunks.push(recordsToUpdate.slice(i, i + CHUNK_SIZE));
       }

       for (const chunk of chunks) {
         const batch = writeBatch(db);
         chunk.forEach(docSnap => {
            batch.update(docSnap.ref, updateData as any);
         });
         await batch.commit();
       }

       console.log(`✅ Atualização em lote concluída: ${recordsToUpdate.length} atualizados.`);
       return { success: true, count: recordsToUpdate.length };
    } catch (error) {
       console.error("❌ Erro na atualização em massa:", error);
       return { success: false, count: 0 };
    }
  },

  async getRecords(): Promise<TimeRecord[]> {
    try {
      const q = query(collection(db, 'time_records'), orderBy('date', 'desc'));
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error("Error fetching records:", e);
      return [];
    }
  },

  async getUserRecords(userId: string): Promise<TimeRecord[]> {
    try {
      const q = query(
        collection(db, 'time_records'), 
        where('employeeId', '==', userId),
        orderBy('date', 'desc')
      );
      const querySnapshot = await getDocs(q);

      return querySnapshot.docs.map(doc => {
        const data = doc.data();
        const { timestamp, ...recordData } = data; 
        return recordData as TimeRecord;
      });
    } catch (e) {
      console.error(`Error fetching records for user ${userId}:`, e);
      return [];
    }
  },

  async updateRecord(record: TimeRecord): Promise<boolean> {
    try {
      const { id, ...data } = record;
      await updateDoc(doc(db, 'time_records', id), data as any);
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  },

  async deleteRecord(id: string): Promise<boolean> {
    try {
      await deleteDoc(doc(db, 'time_records', id));
      return true;
    } catch (e) {
      console.error(e);
      return false;
    }
  }
};

import React, { useState } from 'react';
import { 
  Building2, 
  Briefcase, 
  Plus, 
  Trash2, 
  Edit2, 
  Save, 
  X, 
  Loader2, 
  Settings as SettingsIcon 
} from 'lucide-react';
import { AppSetting } from '../types';
import { firebaseService } from '../services/firebaseService';

interface SettingsProps {
  companies: AppSetting[];
  teams: AppSetting[];
  refreshData: () => void;
}

const ManageList = ({ 
  title, 
  icon: Icon, 
  items, 
  collectionName, 
  refreshData,
  deleteWarning 
}: { 
  title: string; 
  icon: any; 
  items: AppSetting[]; 
  collectionName: 'settings_companies' | 'settings_areas';
  refreshData: () => void;
  deleteWarning?: string;
}) => {
  const [newItemName, setNewItemName] = useState('');
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItemName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.addSettingItem(collectionName, newItemName.trim());
      setNewItemName('');
      refreshData();
    } catch (error) {
      alert("Erro ao adicionar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (item: AppSetting) => {
    setEditingId(item.id);
    setEditName(item.name);
  };

  const handleUpdate = async () => {
    if (!editingId || !editName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.updateSettingItem(collectionName, editingId, editName.trim());
      setEditingId(null);
      refreshData();
    } catch (error) {
      alert("Erro ao atualizar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (deleteWarning) {
        if (!confirm(deleteWarning)) return;
    } else {
        if (!confirm("Tem certeza que deseja remover este item?")) return;
    }

    setLoading(true);
    try {
      await firebaseService.deleteSettingItem(collectionName, id);
      refreshData();
    } catch (error) {
      alert("Erro ao excluir item.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[500px]">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-slate-800 font-bold">
          <Icon size={20} className="text-indigo-600" />
          {title}
        </div>
        <span className="text-xs bg-slate-200 text-slate-600 px-2 py-1 rounded-full">{items.length}</span>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
        {items.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm">
                <p>Nenhum item cadastrado.</p>
            </div>
        )}
        {items.map(item => (
          <div key={item.id} className="group flex items-center justify-between p-3 rounded-lg hover:bg-slate-50 border border-transparent hover:border-slate-100 transition-all">
            {editingId === item.id ? (
              <div className="flex flex-1 items-center gap-2">
                 <input 
                   autoFocus
                   type="text" 
                   value={editName}
                   onChange={e => setEditName(e.target.value)}
                   className="flex-1 text-sm border rounded px-2 py-1 focus:ring-2 focus:ring-indigo-500 outline-none"
                 />
                 <button onClick={handleUpdate} className="p-1 text-green-600 hover:bg-green-50 rounded"><Save size={16}/></button>
                 <button onClick={() => setEditingId(null)} className="p-1 text-slate-400 hover:bg-slate-50 rounded"><X size={16}/></button>
              </div>
            ) : (
              <>
                <span className="text-sm font-medium text-slate-700">{item.name}</span>
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                    onClick={() => handleEdit(item)}
                    className="p-1.5 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors" 
                    title="Editar"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button 
                    onClick={() => handleDelete(item.id)}
                    className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors" 
                    title="Excluir"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </>
            )}
          </div>
        ))}
      </div>

      {/* Footer Add Form */}
      <div className="p-4 border-t border-slate-100 bg-slate-50">
        <form onSubmit={handleAdd} className="flex gap-2">
          <input 
            type="text" 
            placeholder="Adicionar novo..." 
            value={newItemName}
            onChange={e => setNewItemName(e.target.value)}
            disabled={loading}
            className="flex-1 text-sm border border-slate-300 rounded-lg px-3 py-2 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500"
          />
          <button 
            type="submit" 
            disabled={loading || !newItemName.trim()}
            className="bg-indigo-600 hover:bg-indigo-700 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {loading ? <Loader2 size={20} className="animate-spin" /> : <Plus size={20} />}
          </button>
        </form>
      </div>
    </div>
  );
};

const Settings: React.FC<SettingsProps> = ({ companies, teams, refreshData }) => {
  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center gap-3">
        <div className="p-3 bg-indigo-100 text-indigo-700 rounded-xl">
          <SettingsIcon size={28} />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Configurações do Sistema</h2>
          <p className="text-slate-500">Gerencie as listas de empresas e áreas utilizadas no sistema.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <ManageList 
          title="Empresas" 
          icon={Building2} 
          items={companies} 
          collectionName="settings_companies"
          refreshData={refreshData}
          deleteWarning="Tem certeza que deseja remover esta empresa? Colaboradores vinculados podem ficar com dados inconsistentes."
        />
        <ManageList 
          title="Áreas / Setores" 
          icon={Briefcase} 
          items={teams} 
          collectionName="settings_areas"
          refreshData={refreshData}
          deleteWarning="Certifique-se de que não há colaboradores vinculados a esta área antes de excluir."
        />
      </div>
    </div>
  );
};

