import React, { useState, useEffect } from 'react';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TimeEntryForm from './components/TimeEntryForm';
import EmployeeList from './components/EmployeeList';
import Reports from './components/Reports';
import BulkOccurrence from './components/BulkOccurrence';
import Settings from './components/Settings';
import Login from './components/Login';
import { Role, Employee, TimeRecord, AppSetting } from './types';
import { firebaseService } from './services/firebaseService';
import { Menu } from 'lucide-react';
import { onAuthStateChanged } from 'firebase/auth';

// Expose service to window for console scripts
(window as any).firebaseService = firebaseService;

const App: React.FC = () => {
  // Debug Log
  useEffect(() => {
    console.log("🚀 App Component Mounted");
  }, []);

  // Application State
  const [currentPage, setCurrentPage] = useState('dashboard');
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [records, setRecords] = useState<TimeRecord[]>([]);

  // Settings State (Dynamic Lists)
  const [companies, setCompanies] = useState<AppSetting[]>([]);
  const [teams, setTeams] = useState<AppSetting[]>([]);

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  // Authentication State
  const [currentUser, setCurrentUser] = useState<Employee | null>(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [initError, setInitError] = useState<string | null>(null);

  // Load User Session Persistent
  useEffect(() => {
    // Check if auth is initialized safely
    if (!firebaseService.auth) {
      const msg = "Firebase Auth service not initialized. Verifique as configurações.";
      console.error(msg);
      setInitError(msg);
      setAuthChecked(true);
      return;
    }

    try {
      const unsubscribe = onAuthStateChanged(firebaseService.auth, async (user) => {
        console.log("Auth State Changed:", user ? `User: ${user.email}` : "No User");

        if (user) {
          try {
            const profile = await firebaseService.getOrCreateProfile(user);
            setCurrentUser(profile);
          } catch (e: any) {
            console.error("Error loading profile:", e);
            setInitError("Erro ao carregar perfil do usuário: " + e.message);
            setCurrentUser(null);
          }
        } else {
          setCurrentUser(null);
        }
        setAuthChecked(true);
      }, (error) => {
        console.error("Auth Subscription Error:", error);
        setInitError("Erro na conexão com autenticação.");
        setAuthChecked(true);
      });

      return () => unsubscribe();
    } catch (error: any) {
       console.error("Critical error setting up auth listener:", error);
       setInitError(error.message);
       setAuthChecked(true);
    }
  }, []);

  // Load Data function
  const fetchData = async () => {
    if (currentUser) {
      try {
        console.log("Fetching data from Firestore...");

        // Fetch Parallel
        const [emps, recs, comps, areas] = await Promise.all([
           firebaseService.getEmployees(),
           firebaseService.getRecords(),
           firebaseService.getSettingsList('settings_companies'),
           firebaseService.getSettingsList('settings_areas')
        ]);

        setEmployees(emps);
        setRecords(recs);
        setCompanies(comps);
        setTeams(areas);

        console.log("Data fetched successfully:", { 
          employees: emps.length, 
          records: recs.length,
          companies: comps.length,
          areas: areas.length
        });
      } catch (e) {
        console.error("Error fetching data:", e);
      }
    }
  };

  useEffect(() => {
    if (currentUser) {
      fetchData();
    }
  }, [currentUser]);

  const handleLoginSuccess = (user: Employee) => {
    setCurrentUser(user);
    setCurrentPage('dashboard');
  };

  const handleLogout = async () => {
    await firebaseService.logout();
    setCurrentUser(null);
    setEmployees([]);
    setRecords([]);
  };

  // Optimistic Update Helpers
  const handleLocalRecordUpdate = (updatedRecord: TimeRecord) => {
    setRecords(prevRecords => 
      prevRecords.map(r => r.id === updatedRecord.id ? updatedRecord : r)
    );
  };

  const handleLocalRecordDelete = (recordId: string) => {
    setRecords(prevRecords => prevRecords.filter(r => r.id !== recordId));
  };

  if (initError) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-red-50 p-4 text-center">
        <div className="bg-white p-6 rounded-lg shadow-lg max-w-md">
          <h2 className="text-red-600 text-xl font-bold mb-2">Erro de Inicialização</h2>
          <p className="text-slate-600">{initError}</p>
          <button 
            onClick={() => window.location.reload()}
            className="mt-4 px-4 py-2 bg-indigo-600 text-white rounded hover:bg-indigo-700"
          >
            Tentar Novamente
          </button>
        </div>
      </div>
    );
  }

  if (!authChecked) {
    return (
      <div className="h-screen flex flex-col items-center justify-center bg-slate-100 space-y-4">
         <div className="w-10 h-10 border-4 border-indigo-600 border-t-transparent rounded-full animate-spin"></div>
         <p className="text-slate-500 font-medium">Conectando ao banco de dados...</p>
      </div>
    );
  }

  // If not logged in, show Login Screen
  if (!currentUser) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  // Render Page Content based on route
  const renderContent = () => {
    try {
      switch (currentPage) {
        case 'dashboard':
          return <Dashboard records={records} employees={employees} />;
        case 'form':
          return <TimeEntryForm currentUser={currentUser} employees={employees} onRecordAdded={fetchData} />;
        case 'bulk':
          return currentUser.role === Role.ADMIN ? 
            <BulkOccurrence 
              employees={employees} 
              currentUser={currentUser} 
              onRecordsAdded={fetchData} 
              companyList={companies}
              teamList={teams}
            /> : <div className="p-10 text-center text-slate-500">Acesso Restrito ao RH.</div>;
        case 'employees':
          return currentUser.role === Role.ADMIN ? 
            <EmployeeList 
              employees={employees} 
              refreshData={fetchData} 
              currentUser={currentUser}
              companyList={companies}
              teamList={teams}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado. Esta área é restrita ao RH.</div>;
        case 'reports':
          return (currentUser.role === Role.ADMIN || currentUser.role === Role.LEADER) ? 
            <Reports 
              records={records} 
              employees={employees} 
              currentUser={currentUser} 
              refreshData={fetchData} 
              onUpdateRecord={handleLocalRecordUpdate}
              onDeleteRecord={handleLocalRecordDelete}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
        case 'settings':
          return currentUser.role === Role.ADMIN ? 
            <Settings 
               companies={companies}
               teams={teams}
               employees={employees} // Passed for migration logic
               refreshData={fetchData}
            /> : 
            <div className="text-center p-10 text-slate-500">Acesso negado.</div>;
        default:
          return <Dashboard records={records} employees={employees} />;
      }
    } catch (e) {
      console.error("Error rendering page content:", e);
      return <div className="p-4 text-red-500">Erro ao carregar conteúdo da página. Verifique o console.</div>;
    }
  };

  return (
    <div className="flex h-screen bg-slate-100 overflow-hidden">
      {/* Mobile Header */}
      <div className="md:hidden fixed w-full top-0 z-40 bg-slate-900 text-white p-4 flex justify-between items-center shadow-md">
         <span className="font-bold">Hurafy</span>
         <button onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
           <Menu size={24} />
         </button>
      </div>

      <Sidebar 
        currentUser={currentUser}
        currentRole={currentUser.role} 
        currentPage={currentPage} 
        setPage={(page) => {
          setCurrentPage(page);
          setIsSidebarOpen(false);
        }}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
      />

      <main className="flex-1 overflow-auto w-full pt-16 md:pt-0">
        <div className="p-6 md:p-10 max-w-7xl mx-auto">
          {renderContent()}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { 
  Building2, 
  Briefcase, 
  Plus, 
  Trash2, 
  Edit2, 
  Save, 
  X, 
  Loader2, 
  Settings as SettingsIcon,
  RefreshCw
} from 'lucide-react';
import { AppSetting, Employee } from '../types';
import { firebaseService } from '../services/firebaseService';

interface SettingsProps {
  companies: AppSetting[];
  teams: AppSetting[];
  employees: Employee[];
  refreshData: () => void;
}

// Default Constants for fallback/initial migration
const DEFAULT_COMPANIES = ['Arca Plast', 'Arca Mania', 'Rearca', 'Taex Transportadora'];
const DEFAULT_TEAMS = [
  'Embalagem', 'Engenharia', 'Estoque', 'Excelência Operacional', 'Financeiro', 
  'Gente e Gestão', 'Gestão', 'Gestão da Produção', 'Gestão Estratégica', 
  'Injeção', 'Logística', 'Manutenção', 'Marketing', 'Mercado', 
  'Serviços Gerais', 'Sopro', 'Suprimentos', 'TI'
];

const ManageList = ({ 
  title, 
  icon: Icon, 
  items, 
  collectionName, 
  refreshData,
  deleteWarning 
}: { 
  title: string; 
  icon: any; 
  items: AppSetting[]; 
  collectionName: 'settings_companies' | 'settings_areas';
  refreshData: () => void;
  deleteWarning?: string;
}) => {
  const [newItemName, setNewItemName] = useState('');
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItemName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.addSettingItem(collectionName, newItemName.trim());
      setNewItemName('');
      refreshData();
    } catch (error) {
      alert("Erro ao adicionar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (item: AppSetting) => {
    setEditingId(item.id);
    setEditName(item.name);
  };

  const handleUpdate = async () => {
    if (!editingId || !editName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.updateSettingItem(collectionName, editingId, editName.trim());
      setEditingId(null);
      refreshData();
    } catch (error) {
      alert("Erro ao atualizar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (deleteWarning) {
        if (!confirm(deleteWarning)) return;
    } else {
        if (!confirm("Tem certeza que deseja remover este item?")) return;
    }

    setLoading(true);
    try {
      await firebaseService.deleteSettingItem(collectionName, id);
      refreshData();
    } catch (error) {
      alert("Erro ao excluir item.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[500px]">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-slate-800 font-bold">
          <Icon size={20} className="text-indigo-600" />
          {title}
        </div>
        <span className="text-xs bg-slate-200 text-slate-600 px-2 py-1 rounded-full">{items.length}</span>
      </div>

      {/* List */}
      <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
        {items.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm">
                <p>Nenhum item cadastrado.</p>
            </div>
        )}
        {items.map(item => (
          <div key={item.id} className="group flex items-center justify-between p-3 rounded-lg hover:bg-slate-50 border border-transparent hover:border-slate-100 transition-all">
            {editingId === item.id ? (
              <div className="flex flex-1 items-center gap-2">
                 <input 
                   autoFocus
                   type="text" 
                   value={editName}
                   onChange={e => setEditName(e.target.value)}
                   className="flex-1 text-sm border rounded px-2 py-1 focus:ring-2 focus:ring-indigo-500 outline-none"
                 />
                 <button onClick={handleUpdate} className="p-1 text-green-600 hover:bg-green-50 rounded"><Save size={16}/></button>
                 <button onClick={() => setEditingId(null)} className="p-1 text-slate-400 hover:bg-slate-50 rounded"><X size={16}/></button>
              </div>
            ) : (
              <>
                <span className="text-sm font-medium text-slate-700">{item.name}</span>
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                    onClick={() => handleEdit(item)}
                    className="p-1.5 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors" 
                    title="Editar"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button 
                    onClick={() => handleDelete(item.id)}
                    className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors" 
                    title="Excluir"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </>
            )}
          </div>
        ))}
      </div>

      {/* Footer Add Form */}
      <div className="p-4 border-t border-slate-100 bg-slate-50">
        <form onSubmit={handleAdd} className="flex gap-2">
          <input 
            type="text" 
            placeholder="Adicionar novo..." 
            value={newItemName}
            onChange={e => setNewItemName(e.target.value)}
            disabled={loading}
            className="flex-1 text-sm border border-slate-300 rounded-lg px-3 py-2 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 bg-white text-slate-900"
          />
          <button 
            type="submit" 
            disabled={loading || !newItemName.trim()}
            className="bg-indigo-600 hover:bg-indigo-700 text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {loading ? <Loader2 size={20} className="animate-spin" /> : <Plus size={20} />}
          </button>
        </form>
      </div>
    </div>
  );
};

const Settings: React.FC<SettingsProps> = ({ companies, teams, employees, refreshData }) => {
  const [isMigrating, setIsMigrating] = useState(false);

  // Auto-Migration Logic
  useEffect(() => {
    const performMigration = async () => {
       // Only run if lists are empty and we have valid employees data (or at least valid defaults)
       const needsCompanyMigration = companies.length === 0;
       const needsTeamMigration = teams.length === 0;

       if (!needsCompanyMigration && !needsTeamMigration) return;

       setIsMigrating(true);
       console.log("🔄 Iniciando migração automática de configurações...");

       try {
          const uniqueCompanies = new Set(DEFAULT_COMPANIES);
          const uniqueTeams = new Set(DEFAULT_TEAMS);

          // Extract from existing employees
          if (employees.length > 0) {
             employees.forEach(emp => {
                if (emp.company) uniqueCompanies.add(emp.company.trim());
                if (emp.team) uniqueTeams.add(emp.team.trim());
             });
          }

          const promises = [];

          if (needsCompanyMigration) {
             for (const comp of uniqueCompanies) {
                if (comp) promises.push(firebaseService.addSettingItem('settings_companies', comp));
             }
          }

          if (needsTeamMigration) {
             for (const team of uniqueTeams) {
                if (team) promises.push(firebaseService.addSettingItem('settings_areas', team));
             }
          }

          await Promise.all(promises);
          console.log("✅ Migração concluída.");
          refreshData();

       } catch (error) {
          console.error("Erro na migração automática:", error);
       } finally {
          setIsMigrating(false);
       }
    };

    // Small timeout to allow render then migrate
    const timer = setTimeout(() => {
        performMigration();
    }, 1000);

    return () => clearTimeout(timer);
  }, [companies.length, teams.length, employees]); // Dependencies ensure it runs when data is available but empty

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
            <div className="p-3 bg-indigo-100 text-indigo-700 rounded-xl">
            <SettingsIcon size={28} />
            </div>
            <div>
            <h2 className="text-2xl font-bold text-slate-800">Configurações do Sistema</h2>
            <p className="text-slate-500">Gerencie as listas de empresas e áreas utilizadas no sistema.</p>
            </div>
        </div>

        {isMigrating && (
            <div className="flex items-center gap-2 text-indigo-600 bg-indigo-50 px-4 py-2 rounded-lg border border-indigo-100">
                <Loader2 size={18} className="animate-spin" />
                <span className="text-sm font-medium">Sincronizando listas padrão...</span>
            </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <ManageList 
          title="Empresas" 
          icon={Building2} 
          items={companies} 
          collectionName="settings_companies"
          refreshData={refreshData}
          deleteWarning="Tem certeza que deseja remover esta empresa? Colaboradores vinculados podem ficar com dados inconsistentes."
        />
        <ManageList 
          title="Áreas / Setores" 
          icon={Briefcase} 
          items={teams} 
          collectionName="settings_areas"
          refreshData={refreshData}
          deleteWarning="Certifique-se de que não há colaboradores vinculados a esta área antes de excluir."
        />
      </div>
    </div>
  );
};

export default Settings;

import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Building2 } from 'lucide-react';
import { Employee, Role, AppSetting } from '../types';
import { firebaseService } from '../services/firebaseService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
  currentUser: Employee; 
  companyList: AppSetting[];
  teamList: AppSetting[];
}

const EmployeeList: React.FC<EmployeeListProps> = ({ 
  employees, 
  refreshData, 
  currentUser,
  companyList,
  teamList
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Optimistic UI state
  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  // Form State for Add/Edit Modal
  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState('');
  const [newCompany, setNewCompany] = useState('');

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase()) ||
      e.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const handleRoleChange = async (userId: string, newRole: Role) => {
    if (userId === currentUser.id) {
        alert("Você não pode alterar seu próprio cargo nesta tela.");
        return;
    }
    setLoadingAction(`role-${userId}`);
    try {
        const success = await firebaseService.updateUserRole(userId, newRole);
        if (success) {
            refreshData();
        } else {
            alert("Erro ao atualizar cargo.");
        }
    } catch (error) {
        console.error("Erro ao mudar role:", error);
    } finally {
        setLoadingAction(null);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewEmail('');
    setNewRole(Role.EMPLOYEE);
    // Tenta pegar o primeiro valor da lista dinâmica ou vazio, mas preferimos vazio para forçar seleção
    setNewTeam('');
    setNewCompany('');
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewEmail(employee.email || '');
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setNewCompany(employee.company || '');
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCompany || !newTeam) {
        alert("Por favor, selecione uma Empresa e uma Equipe (Área). Se as listas estiverem vazias, vá em Configurações.");
        return;
    }
    setLoadingAction('save');

    // Gerador de username simples
    let finalUsername = '';
    if (newEmail && newEmail.includes('@')) {
         finalUsername = newEmail.split('@')[0];
    } else {
         const cleanName = newName.toLowerCase().trim().split(' ');
         finalUsername = cleanName[0];
    }

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: finalUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      company: newCompany,
      active: true,
    };

    try {
      if (editingId) {
        await firebaseService.updateEmployee(employeeData);
      } else {
        await firebaseService.addEmployee(employeeData);
      }
      refreshData();
      setIsModalOpen(false);
    } catch (error) {
      console.error("Error saving employee:", error);
      alert("Erro ao salvar.");
    } finally {
      setLoadingAction(null);
      setEditingId(null);
    }
  };

  const handleDelete = async (id: string) => {
    if (id === currentUser.id) {
        alert("Você não pode excluir sua própria conta.");
        return;
    }
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await firebaseService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir do banco de dados.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  const isAdmin = currentUser.role === Role.ADMIN;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
           <p className="text-sm text-slate-500">
             {employees.length} usuários cadastrados
           </p>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={openAddModal}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      {/* Search Bar */}
      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome, email ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      {/* List */}
      <div className="bg-white shadow-sm border border-slate-200 rounded-xl overflow-hidden">
        {employees.length === 0 ? (
           <div className="p-10 flex flex-col items-center justify-center text-slate-400">
              <Loader2 className="w-8 h-8 animate-spin mb-2" />
              <p>Carregando colaboradores...</p>
           </div>
        ) : (
        <ul className="divide-y divide-slate-200">
          {filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 hover:bg-slate-50 transition-colors animate-fade-in">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">

                {/* User Info */}
                <div className="flex items-center min-w-0 gap-4 flex-1">
                  <div className="h-10 w-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 shrink-0">
                    <User size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-slate-900 truncate flex items-center gap-2">
                      {employee.name}
                      {employee.id === currentUser.id && <span className="text-xs bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full">Você</span>}
                    </p>
                    <p className="text-xs text-slate-500 flex items-center mt-0.5">
                       <Building2 size={10} className="mr-1" />
                       {employee.company || 'Empresa não informada'} • {employee.team}
                    </p>
                    <p className="text-xs text-slate-400 mt-0.5">{employee.email || 'Sem email vinculado'}</p>
                  </div>
                </div>

                {/* Actions & Role Management */}
                <div className="flex items-center gap-4 justify-between md:justify-end w-full md:w-auto">

                  {/* Role Selector (Admin Only) or Badge */}
                  <div className="flex flex-col items-end min-w-[140px]">
                    {isAdmin ? (
                        <div className="relative">
                            <select 
                                value={employee.role}
                                disabled={loadingAction === `role-${employee.id}` || employee.id === currentUser.id}
                                onChange={(e) => handleRoleChange(employee.id, e.target.value as Role)}
                                className={`appearance-none block w-full pl-3 pr-8 py-1.5 text-xs font-medium rounded-full border focus:outline-none focus:ring-2 focus:ring-offset-1 transition-colors cursor-pointer text-slate-900
                                    ${employee.role === Role.ADMIN ? 'bg-purple-50 text-purple-700 border-purple-200 focus:ring-purple-500' : 
                                      employee.role === Role.LEADER ? 'bg-blue-50 text-blue-700 border-blue-200 focus:ring-blue-500' : 
                                      'bg-slate-50 text-slate-700 border-slate-200 focus:ring-slate-500'}
                                    ${loadingAction === `role-${employee.id}` ? 'opacity-50' : ''}
                                `}
                            >
                                <option value={Role.EMPLOYEE}>Colaborador</option>
                                <option value={Role.LEADER}>Líder</option>
                                <option value={Role.ADMIN}>Administrador</option>
                            </select>
                            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                                {loadingAction === `role-${employee.id}` ? (
                                    <Loader2 size={12} className="animate-spin" />
                                ) : (
                                    <svg className="h-3 w-3 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" fillRule="evenodd"></path></svg>
                                )}
                            </div>
                        </div>
                    ) : (
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium capitalize ${
                          employee.role === Role.ADMIN ? 'bg-purple-100 text-purple-800' :
                          employee.role === Role.LEADER ? 'bg-blue-100 text-blue-800' :
                          'bg-slate-100 text-slate-800'
                        }`}>
                          {employee.role === Role.ADMIN ? <Shield size={10} className="mr-1"/> : <Briefcase size={10} className="mr-1"/>}
                          {employee.role === Role.ADMIN ? 'Administrador' : employee.role === Role.LEADER ? 'Líder' : 'Colaborador'}
                        </span>
                    )}
                  </div>

                  {/* Edit/Delete Buttons (Admin Only) */}
                  {isAdmin && (
                      <div className="flex items-center gap-1 border-l border-slate-200 pl-3 ml-2">
                        <button 
                          onClick={() => openEditModal(employee)}
                          className="text-slate-400 hover:text-indigo-600 transition-colors p-2 rounded-full hover:bg-indigo-50"
                          title="Editar Detalhes"
                          disabled={loadingAction !== null}
                        >
                          <Edit size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(employee.id)}
                          className={`text-slate-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50 ${employee.id === currentUser.id ? 'opacity-20 cursor-not-allowed' : ''}`}
                          title="Excluir"
                          disabled={loadingAction !== null || employee.id === currentUser.id}
                        >
                          {loadingAction === employee.id ? (
                            <Loader2 size={18} className="animate-spin text-red-600" />
                          ) : (
                            <Trash2 size={18} />
                          )}
                        </button>
                      </div>
                  )}
                </div>
              </div>
            </li>
          ))}
          {filteredEmployees.length === 0 && (
            <li className="p-8 text-center text-slate-500">
              Nenhum colaborador encontrado com este filtro.
            </li>
          )}
        </ul>
        )}
      </div>

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="mb-4">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Editar Colaborador' : 'Pré-cadastrar Colaborador'}
              </h3>
              <p className="text-xs text-slate-500">
                  {editingId ? 'Atualizar dados cadastrais.' : 'Cria um perfil que será vinculado quando o usuário fizer login.'}
              </p>
            </div>

            <form onSubmit={handleSaveEmployee} className="space-y-4 overflow-y-auto pr-3 custom-scrollbar flex-1 min-h-0">
              <div>
                <label className="block text-sm font-medium text-slate-700">Nome Completo</label>
                <input required type="text" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newName} onChange={e => setNewName(e.target.value)} />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700">Email <span className="text-slate-400 text-xs">(Vinculação Google/Firebase)</span></label>
                <input 
                  type="email" 
                  required
                  placeholder="email@arcaplast.com.br"
                  className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                  value={newEmail} 
                  onChange={e => setNewEmail(e.target.value)} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Empresa</label>
                    <select 
                      className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                      value={newCompany} 
                      onChange={e => setNewCompany(e.target.value)}
                    >
                      <option value="">Selecione...</option>
                      {companyList.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                    </select>
                    {companyList.length === 0 && <span className="text-xs text-red-500">Nenhuma empresa cadastrada. Vá em Configurações.</span>}
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Equipe (Área)</label>
                    <select 
                      className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                      value={newTeam} 
                      onChange={e => setNewTeam(e.target.value)}
                    >
                      <option value="">Selecione...</option>
                      {teamList.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                    </select>
                    {teamList.length === 0 && <span className="text-xs text-red-500">Nenhuma área cadastrada. Vá em Configurações.</span>}
                 </div>
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                <button type="submit" disabled={loadingAction === 'save'} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center">
                  {loadingAction === 'save' && <Loader2 size={16} className="animate-spin mr-2" />}
                  {editingId ? 'Salvar Alterações' : 'Criar Perfil'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

