  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto', type: RecordType.NEUTRAL },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  // New state specifically for single-time entry (Ausência)
  const [absenceTime, setAbsenceTime] = useState('');

  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  // Verifica se é uma regularização ou ajuste de ponto (permite saldo zero)
  const isAbsenceAdjustment = ['Ausência de Batida', 'Ajuste de Ponto'].includes(occurrenceType);

  // Close dropdown when clicking outside
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Set current user default selection logic
  useEffect(() => {
    if (currentUser.role === Role.EMPLOYEE) {
       setSelectedEmployee(currentUser.id);
       setSearchTerm(currentUser.name);
    }
  }, [currentUser]);

  // Update Mapped Record Type when Occurrence Selection Changes
  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
    // Limpa campos de tempo ao trocar o tipo para evitar confusão
    setStartTime('');
    setEndTime('');
    setAbsenceTime('');
    setCalculatedDuration({ hours: 0, minutes: 0 });
    setIsTimeValid(true);
  }, [occurrenceType]);

  // Calculate duration whenever standard times change
  useEffect(() => {
    // 1. Lógica Específica para "Ausência de Batida" ou "Ajuste de Ponto"
    if (isAbsenceAdjustment) {
        setCalculatedDuration({ hours: 0, minutes: 0 });

        // Se estiver usando o modo de campo único (Ausência)
        if (absenceTime) {
            setIsTimeValid(true);
            return;
        }

        // Se estiver usando campos de Início e Fim (fallback ou Ajuste)
        if (startTime && endTime) {
             const [startH, startM] = startTime.split(':').map(Number);
             const [endH, endM] = endTime.split(':').map(Number);
             const startTotalMins = startH * 60 + startM;
             const endTotalMins = endH * 60 + endM;

             // IMPORTANTE: Permite horários iguais para Ajuste de Ponto (Saldo Zero)
             if (startTotalMins === endTotalMins) {
                 setIsTimeValid(true);
                 return;
             }

             // Se for menor, é inválido mesmo em ajuste
             if (endTotalMins < startTotalMins) {
                 setIsTimeValid(false);
                 return;
             }

             setIsTimeValid(true);
             return;
        }

        // Se nada estiver preenchido, marca como inválido mas silencia até o submit
        setIsTimeValid(false); 
        return;
    }

    // 2. Lógica Padrão (Outros Tipos - Crédito/Débito)
    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);

    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    // Para outros tipos, a hora final DEVE ser maior que a inicial
    if (endTotalMins <= startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime, absenceTime, isAbsenceAdjustment]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validação Básica
    if (!selectedEmployee || !date || !reason) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    // Validação Específica para Ajustes
    if (isAbsenceAdjustment) {
        // Verifica se tem horário preenchido (seja no campo único ou nos campos duplos)
        const hasSpecificTime = !!absenceTime;
        const hasRange = !!(startTime && endTime);

        if (!hasSpecificTime && !hasRange) {
            alert("Informe o horário.");
            return;
        }

        if (hasRange && startTime === endTime) {
           // Válido para ajuste de ponto zero
        } else if (hasRange && !isTimeValid) {
           alert("Horário inválido.");
           return;
        }

        if (reason.trim().length < 5) {
            alert("A justificativa é obrigatória e deve ser detalhada.");
            return;
        }
    } else {
        // Validação Padrão
        if (!startTime || !endTime || !isTimeValid) {
            alert("Verifique os horários de início e fim.");
            return;
        }
        if (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
            alert("A duração deve ser maior que zero.");
            return;
        }
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);

    // Configura os horários baseados no tipo
    // REGRA: Se for Ausência/Ajuste e usou campo único, usa ele para ambos.
    const effectiveTime = absenceTime || startTime;

    // Se for Ajuste/Ausência e usou range e tempos são iguais, ok.
    const finalStartTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : startTime;
    const finalEndTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : endTime;

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date, 
      hours: isAbsenceAdjustment ? 0 : calculatedDuration.hours,
      minutes: isAbsenceAdjustment ? 0 : calculatedDuration.minutes,
      startTime: finalStartTime,
      endTime: finalEndTime,
      type: isAbsenceAdjustment ? RecordType.NEUTRAL : mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id,
      isAdjustment: isAbsenceAdjustment ? true : undefined,
      status: isAbsenceAdjustment ? 'regularized' : undefined
    };

    try {
      await firebaseService.saveTimeRecord(newRecord);

      setSuccess(true);
      onRecordAdded();

      // Reset Form
      if (currentUser.role !== Role.EMPLOYEE) {
         setSelectedEmployee('');
         setSearchTerm('');
      }
      setStartTime('');
      setEndTime('');
      setAbsenceTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');

      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar batida:", error);
      alert("Falha na comunicação com o servidor. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in">

      {/* SUCCESS POPUP MODAL */}
      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">
              {isAbsenceAdjustment 
                ? 'Ajuste registrado. Saldo inalterado.' 
                : 'Registro salvo no banco de dados.'}
            </p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Os dados serão sincronizados com o servidor.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {/* Employee Autocomplete */}
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  disabled={currentUser.role === Role.EMPLOYEE}
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-green-500 ring-1 ring-green-500 bg-green-50' : ''} ${currentUser.role === Role.EMPLOYEE ? 'bg-slate-100 cursor-not-allowed text-slate-500' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-green-600 bg-green-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {/* Dropdown List */}
              {isDropdownOpen && currentUser.role !== Role.EMPLOYEE && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            {/* Date */}
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
                />
              </div>
            </div>

            {/* Type Dropdown */}
            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <div className="relative">
                 <select
                    value={occurrenceType}
                    onChange={(e) => setOccurrenceType(e.target.value)}
                    className="block w-full pl-3 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
                 >
                   {OCCURRENCE_OPTIONS.map((opt) => (
                     <option key={opt.label} value={opt.label}>{opt.label}</option>
                   ))}
                 </select>
               </div>

               {/* Visual Indicator of Effect */}
               <div className={`mt-2 p-2 rounded-lg border text-xs font-semibold flex items-center justify-center ${getTypeStyles(mappedRecordType)}`}>
                  {mappedRecordType === RecordType.CREDIT && <span className="flex items-center"><Check size={14} className="mr-1"/> Adiciona ao Banco de Horas (Crédito)</span>}
                  {mappedRecordType === RecordType.DEBIT && <span className="flex items-center"><AlertTriangle size={14} className="mr-1"/> Desconta do Banco de Horas (Débito)</span>}
                  {mappedRecordType === RecordType.NEUTRAL && <span className="flex items-center"><Info size={14} className="mr-1"/> Informativo / Neutro (0h)</span>}
               </div>
            </div>

            {/* Conditional Time Inputs */}
            {occurrenceType === 'Ausência de Batida' ? (
                // --- MODO REGULARIZAÇÃO (AUSÊNCIA - CAMPO ÚNICO) ---
                <div className="col-span-1 md:col-span-2 animate-fade-in">
                    <label className="block text-sm font-medium text-slate-700 mb-2">Horário do Esquecimento</label>

                    <div className="bg-amber-50 p-4 rounded-xl border border-amber-200">
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="w-full md:w-1/2">
                                <label className="block text-xs font-semibold text-amber-700 mb-1">Hora da Batida</label>
                                <input 
                                  type="time" 
                                  required
                                  value={absenceTime}
                                  onChange={(e) => setAbsenceTime(e.target.value)}
                                  className="block w-full px-3 py-3 border border-amber-300 rounded-lg bg-white text-slate-900 focus:ring-amber-500 focus:border-amber-500 text-lg font-medium"
                                />
                            </div>

                            <div className="w-full md:w-1/2 flex items-start gap-3 text-sm text-amber-800">
                                <ShieldAlert className="shrink-0 w-8 h-8 text-amber-600" />
                                <div>
                                    <p className="font-bold">Regularização Detectada</p>
                                    <p className="text-xs mt-1">
                                        O sistema registrará <strong>entrada e saída simultâneas</strong> no horário informado para manter seu saldo inalterado.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                // --- MODO PADRÃO (INTERVALO) E AJUSTE DE PONTO ---
                <div className="col-span-1 md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-2">Período da Atividade</label>
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Início/Entrada</label>
                      <input 
                        type="time" 
                        required
                        value={startTime}
                        onChange={(e) => setStartTime(e.target.value)}
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Fim/Saída</label>
                      <input 
                        type="time" 
                        required
                        value={endTime}
                        onChange={(e) => setEndTime(e.target.value)}
                        className={`block w-full px-3 py-2 border rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500 ${!isTimeValid ? 'border-red-500 ring-1 ring-red-500' : 'border-slate-300'}`}
                      />
                    </div>

                    {/* Duration Result */}
                    <div className="col-span-1 sm:col-span-2 mt-2 pt-4 border-t border-slate-200 flex items-center justify-between">
                      <div className="flex items-center text-slate-600">
                        <Calculator size={18} className="mr-2" />
                        <span className="text-sm font-medium">Tempo Calculado:</span>
                      </div>
                      <div className={`text-lg font-bold ${!isTimeValid ? 'text-red-500' : 'text-indigo-600'}`}>
                        {!isTimeValid ? (
                          <span className="text-sm">Horário Inválido</span>
                        ) : (
                           <span>{calculatedDuration.hours}h {calculatedDuration.minutes}m</span>
                        )}
                      </div>
                    </div>
                  </div>
                  {!isTimeValid && !isAbsenceAdjustment && (
                    <p className="text-xs text-red-500 mt-1">A hora de término deve ser posterior à hora de início.</p>
                  )}
                </div>
            )}

          </div>

          {/* Reason */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Justificativa {isAbsenceAdjustment && <span className="text-red-500">* (Obrigatório)</span>}
            </label>
            <textarea
              required
              rows={3}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={isAbsenceAdjustment ? "Explique detalhadamente o motivo do ajuste..." : "Detalhes adicionais..."}
              className={`block w-full px-3 py-3 border rounded-lg bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900 ${isAbsenceAdjustment && !reason ? 'border-amber-300 ring-1 ring-amber-300' : 'border-slate-300'}`}
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee || (!isAbsenceAdjustment && !isTimeValid)}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee || (!isAbsenceAdjustment && !isTimeValid) ? 'bg-slate-400 cursor-not-allowed' : 'bg-indigo-600 hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Salvando no Firebase...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  {isAbsenceAdjustment ? 'Registrar Ajuste' : 'Registrar Batida'}
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TimeEntryForm;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  FileText, Users, Edit, Trash2, Loader2, Save, X, Check, Layers, ChevronDown, ChevronRight, AlertTriangle, FileSpreadsheet
} from 'lucide-react';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import * as XLSX from 'xlsx';
import { TimeRecord, Employee, RecordType, Role } from '../types';
import { firebaseService } from '../services/firebaseService';

interface ReportsProps {
  records: TimeRecord[];
  employees: Employee[];
  currentUser: Employee;
  refreshData: () => void;
  onUpdateRecord: (record: TimeRecord) => void;
  onDeleteRecord: (id: string) => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const Reports: React.FC<ReportsProps> = ({ records, employees, currentUser, refreshData, onUpdateRecord, onDeleteRecord }) => {
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  // Success Popup State
  const [successMessage, setSuccessMessage] = useState<string | null>(null);

  // Expanded Batches State
  const [expandedBatches, setExpandedBatches] = useState<Set<string>>(new Set());

  // Edit Modal State
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingRecord, setEditingRecord] = useState<TimeRecord | null>(null);
  const [isBatchEdit, setIsBatchEdit] = useState(false); // Flag para edição em lote
  const [editDate, setEditDate] = useState('');
  const [editStartTime, setEditStartTime] = useState('');
  const [editEndTime, setEditEndTime] = useState('');
  const [editReason, setEditReason] = useState('');
  const [editOccurrenceType, setEditOccurrenceType] = useState('');
  const [editCalculatedDuration, setEditCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isEditTimeValid, setIsEditTimeValid] = useState(true);

  // --- Logic Checks ---
  const canUserEdit = (record: TimeRecord) => {
    // Admin can edit all
    if (currentUser.role === Role.ADMIN) return true;
    // Leader can edit ONLY if they created it
    if (currentUser.role === Role.LEADER && record.createdBy === currentUser.id) return true;
    return false;
  };

  // --- Helper: Format minutes to HH:MM ---
  const formatTime = (totalMinutes: number) => {
    const hours = Math.floor(Math.abs(totalMinutes) / 60);
    const minutes = Math.abs(totalMinutes) % 60;
    const sign = totalMinutes < 0 ? '-' : '';
    return `${sign}${hours}h ${minutes.toString().padStart(2, '0')}m`;
  };

  // --- Helper: Format Date ---
  const formatDate = (dateString: string) => {
    if (!dateString) return '-';
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) {
        const [year, month, day] = dateString.split('-');
        return `${day}/${month}/${year}`;
    }
    try {
      const date = new Date(dateString);
      if (isNaN(date.getTime())) return dateString;
      return new Intl.DateTimeFormat('pt-BR', {
        timeZone: 'America/Sao_Paulo',
        day: '2-digit',
        month: '2-digit',
        year: 'numeric'
      }).format(date);
    } catch (error) {
      return dateString;
    }
  };

  const formatTimeOnly = (val?: string | number) => {
    if (val === undefined || val === null || val === '') return '-';
    const strVal = String(val);
    if (strVal.includes('T')) return strVal.split('T')[1].substring(0, 5);
    if (strVal.includes(':')) return strVal.substring(0, 5);
    return strVal.length > 5 ? strVal.substring(0, 5) : strVal;
  };

  const safeDateForInput = (dateString: string) => {
    if (!dateString) return '';
    if (/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return dateString;
    if (dateString.includes('T')) return dateString.split('T')[0];
    const d = new Date(dateString);
    if (!isNaN(d.getTime())) return d.toISOString().split('T')[0];
    return '';
  };

  const getLeaderName = (leaderId: string) => {
    const leader = employees.find(e => e.id === leaderId);
    return leader ? leader.name : 'Desconhecido';
  };

  const getEmployeeCompany = (empId: string) => {
    const emp = employees.find(e => e.id === empId);
    return emp ? (emp.company || 'N/A') : '-';
  };

  const getConsolidatedData = () => {
    return employees.filter(e => e.active).map(emp => {
      const empRecords = records.filter(r => r.employeeId === emp.id);
      let creditMins = 0;
      let debitMins = 0;
      empRecords.forEach(r => {
        const mins = (r.hours * 60) + r.minutes;
        if (r.type === RecordType.CREDIT) creditMins += mins;
        else if (r.type === RecordType.DEBIT) debitMins += mins;
      });
      const netBalance = creditMins - debitMins;
      return {
        name: emp.name,
        company: emp.company || 'N/A',
        team: emp.team,
        role: emp.role,
        positive: formatTime(creditMins),
        negative: formatTime(debitMins),
        balance: formatTime(netBalance),
        rawBalance: netBalance 
      };
    }).sort((a, b) => {
      if (a.company !== b.company) return a.company.localeCompare(b.company);
      return a.name.localeCompare(b.name);
    }); 
  };

  useEffect(() => {
    if (!editStartTime || !editEndTime) return;
    const [startH, startM] = editStartTime.split(':').map(Number);
    const [endH, endM] = editEndTime.split(':').map(Number);
    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsEditTimeValid(false);
      setEditCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsEditTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setEditCalculatedDuration({ hours: h, minutes: m });
    }
  }, [editStartTime, editEndTime]);

  const showSuccessPopup = (message: string) => {
    setSuccessMessage(message);
    setTimeout(() => {
      setSuccessMessage(null);
    }, 3000);
  };

  const handleDelete = async (id: string, batchId?: string) => {
    // Se tiver batchId, pergunta se quer excluir o lote
    if (batchId) {
        if (!confirm(`⚠️ Atenção: Este registro faz parte de um Lançamento em Massa.\n\nDeseja excluir TODOS os registros deste lote?`)) return;

        setLoadingAction(`batch-${batchId}`);
        try {
           const result = await firebaseService.deleteBatchRecords(batchId);
           if (result.success) {
               refreshData(); // Recarrega tudo
               showSuccessPopup(`Lote excluído! ${result.count} registros removidos.`);
           } else {
               alert("Erro ao excluir lote.");
           }
        } catch(e) {
            console.error(e);
            alert("Erro ao processar exclusão.");
        } finally {
            setLoadingAction(null);
        }
        return;
    }

    // Exclusão Individual
    if (!confirm('Tem certeza que deseja excluir este registro permanentemente?')) return;
    setLoadingAction(id);
    try {
        const success = await firebaseService.deleteRecord(id);
        if (success) {
          onDeleteRecord(id);
          showSuccessPopup('Registro excluído com sucesso.');
        } else {
          alert('Erro ao excluir registro.');
        }
    } catch (e) {
        alert("Erro de conexão.");
    } finally {
        setLoadingAction(null);
    }
  };

  const openEditModal = (record: TimeRecord, isBatch: boolean = false) => {
    setEditingRecord(record);
    setIsBatchEdit(isBatch);

    setEditDate(safeDateForInput(record.date));
    const cleanStart = formatTimeOnly(record.startTime);
    const cleanEnd = formatTimeOnly(record.endTime);
    setEditStartTime(cleanStart === '-' ? '' : cleanStart);
    setEditEndTime(cleanEnd === '-' ? '' : cleanEnd);
    setEditReason(record.reason);
    setEditOccurrenceType(record.occurrenceType);
    setEditCalculatedDuration({ hours: record.hours, minutes: record.minutes });
    setIsEditTimeValid(true);
    setIsEditModalOpen(true);
  };

  const handleUpdateRecord = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingRecord || !isEditTimeValid) return;
    if (editCalculatedDuration.hours === 0 && editCalculatedDuration.minutes === 0) {
      alert("Duração inválida.");
      return;
    }

    setLoadingAction('modal-save');
    const option = OCCURRENCE_OPTIONS.find(o => o.label === editOccurrenceType);
    const newType = option ? option.type : RecordType.CREDIT;

    const updateData: Partial<TimeRecord> = {
      date: editDate,
      startTime: editStartTime,
      endTime: editEndTime,
      hours: editCalculatedDuration.hours,
      minutes: editCalculatedDuration.minutes,
      reason: editReason,
      occurrenceType: editOccurrenceType,
      type: newType
    };

    try {
        if (isBatchEdit && editingRecord.batchId) {
            // Atualização em Lote
            const result = await firebaseService.updateBatchRecords(editingRecord.batchId, updateData);
            if (result.success) {
                refreshData();
                showSuccessPopup(`Lote atualizado! ${result.count} registros alterados.`);
            } else {
                alert("Falha ao atualizar lote.");
            }
        } else {
            // Atualização Individual
            const updatedRecord = { ...editingRecord, ...updateData };
            const success = await firebaseService.updateRecord(updatedRecord);
            if (success) {
                onUpdateRecord(updatedRecord);
                showSuccessPopup('Registro atualizado com sucesso.');
            } else {
                alert("Falha ao salvar no banco.");
            }
        }
        setIsEditModalOpen(false);
        setEditingRecord(null);
    } catch (error) {
        console.error("Error updating record:", error);
        alert("Erro ao conectar com o servidor.");
    } finally {
        setLoadingAction(null);
    }
  };

  // --- Process Data for Display (Filtering & Grouping) ---
  const { processedRecords, batchMap } = useMemo(() => {
    // 1. Filtragem por Permissão
    let filtered = records.filter(r => {
      if (currentUser.role === Role.ADMIN) return true;
      if (currentUser.role === Role.LEADER) return r.createdBy === currentUser.id;
      return false;
    });

    // 2. Ordenação por Data (Decrescente)
    filtered.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

    // 3. Estrutura de Agrupamento
    // Lista final para renderização (pode conter Record Individual ou BatchLeader)
    const viewList: any[] = [];
    // Mapa para guardar os filhos de cada batch
    const batches: Record<string, TimeRecord[]> = {};
    const seenBatches = new Set<string>();

    filtered.forEach(record => {
       if (record.batchId) {
          if (!batches[record.batchId]) {
             batches[record.batchId] = [];
          }
          batches[record.batchId].push(record);

          if (!seenBatches.has(record.batchId)) {
             // É o primeiro deste lote que encontramos, então criamos um "Líder Visual"
             viewList.push({ ...record, isBatchLeader: true });
             seenBatches.add(record.batchId);
          }
       } else {
          // Registro individual normal
          viewList.push(record);
       }
    });

    return { processedRecords: viewList, batchMap: batches };
  }, [records, currentUser]);

  const toggleBatch = (batchId: string) => {
     const newSet = new Set(expandedBatches);
     if (newSet.has(batchId)) newSet.delete(batchId);
     else newSet.add(batchId);
     setExpandedBatches(newSet);
  };

  // --- PDF/Excel Generation functions preserved for functionality ---
  const generateDetailedPDF = () => {
    const doc = new jsPDF();
    doc.setFontSize(18);
    doc.text('Extrato Detalhado de Ocorrências', 14, 22);
    doc.setFontSize(11);
    doc.text(`Gerado em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);
    const tableData = records.map(r => [ // Exporta TODOS (sem agrupar no PDF) para detalhe real
      formatDate(r.date), getEmployeeCompany(r.employeeId), r.employeeName, getLeaderName(r.createdBy), r.occurrenceType || r.type, r.reason, formatTimeOnly(r.startTime), formatTimeOnly(r.endTime), `${r.hours}h ${r.minutes}m`
    ]);
    autoTable(doc, {
      head: [['Data', 'Empresa', 'Colaborador', 'Líder', 'Tipo', 'Descrição', 'Início', 'Fim', 'Tempo']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 8 },
      headStyles: { fillColor: [71, 85, 105] },
      columnStyles: { 5: { cellWidth: 35 } } 
    });
    doc.save('extrato-detalhado.pdf');
  };

  const generateDetailedExcel = () => {
    const ws = XLSX.utils.json_to_sheet(records.map(r => ({
      Data: formatDate(r.date), Empresa: getEmployeeCompany(r.employeeId), Colaborador: r.employeeName, Líder: getLeaderName(r.createdBy), 'Tipo de Ocorrência': r.occurrenceType, 'Descrição': r.reason, 'Início': formatTimeOnly(r.startTime), 'Fim': formatTimeOnly(r.endTime), Horas: r.hours, Minutos: r.minutes
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Extrato Detalhado");
    XLSX.writeFile(wb, "extrato-detalhado.xlsx");
  };

  const generateGeneralPDF = () => {
    const doc = new jsPDF();
    const data = getConsolidatedData();
    doc.setFontSize(18);
    doc.text('Balanço Geral de Horas por Colaborador', 14, 22);
    doc.setFontSize(11);
    doc.text(`Posição consolidada em: ${new Date().toLocaleDateString('pt-BR')}`, 14, 30);
    const tableData = data.map(d => [d.company, d.name, d.team, d.positive, d.negative, d.balance]);
    autoTable(doc, {
      head: [['Empresa', 'Colaborador', 'Setor', 'Total Positivo', 'Total Negativo', 'Saldo Líquido']],
      body: tableData,
      startY: 40,
      styles: { fontSize: 9, halign: 'center' },
      columnStyles: { 0: { halign: 'left' }, 1: { halign: 'left' }, 5: { fontStyle: 'bold' } },
      headStyles: { fillColor: [79, 70, 229] },
    });
    doc.save('balanco-geral-consolidado.pdf');
  };

  const generateGeneralExcel = () => {
    const data = getConsolidatedData();
    const ws = XLSX.utils.json_to_sheet(data.map(d => ({
      Empresa: d.company, Colaborador: d.name, Setor: d.team, 'Total Positivo': d.positive, 'Total Negativo': d.negative, 'Saldo Líquido': d.balance
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Saldos Consolidados");
    XLSX.writeFile(wb, "balanco-geral-consolidado.xlsx");
  };

  return (
    <div className="space-y-10 animate-fade-in relative">
      {successMessage && (
        <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMessage}</p>
          </div>
        </div>
      )}

      <div>
        <h2 className="text-2xl font-bold text-slate-800">Central de Relatórios</h2>
        <p className="text-slate-500">
           {currentUser.role === Role.ADMIN 
             ? "Gerenciamento completo e auditoria de logs." 
             : "Visualize relatórios e gerencie seus lançamentos."}
        </p>
      </div>

      {currentUser.role === Role.ADMIN && (
        <div className="bg-gradient-to-r from-indigo-50 to-white p-6 rounded-xl border border-indigo-100 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
              <Users size={24} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-800">Balanço Geral (Consolidado)</h3>
              <p className="text-sm text-slate-500">Resumo de saldo final de horas por colaborador e setor.</p>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <button 
              onClick={generateGeneralPDF} 
              className="flex items-center justify-center px-6 py-4 border border-transparent text-sm font-bold rounded-xl text-white bg-rose-600 hover:bg-rose-700 hover:-translate-y-0.5 shadow-sm transition-all"
            >
              <FileText className="mr-2" size={20} /> 
              Resumo em PDF
            </button>
            <button 
              onClick={generateGeneralExcel} 
              className="flex items-center justify-center px-6 py-4 border border-transparent text-sm font-bold rounded-xl text-white bg-emerald-600 hover:bg-emerald-700 hover:-translate-y-0.5 shadow-sm transition-all"
            >
              <FileSpreadsheet className="mr-2" size={20} /> 
              Resumo em Excel
            </button>
          </div>
        </div>
      )}

      <div className={`p-6 rounded-xl border border-indigo-100 shadow-sm ${currentUser.role === Role.ADMIN ? 'bg-gradient-to-r from-indigo-50 to-white' : 'bg-white'}`}>
        <div className="flex items-center gap-3 mb-6">
          <div className="p-2 bg-indigo-100 text-indigo-700 rounded-lg">
            <FileText size={24} />
          </div>
          <div>
            <h3 className="text-lg font-bold text-slate-800">Extrato de Ocorrências</h3>
            <p className="text-sm text-slate-500">{currentUser.role === Role.ADMIN ? "Lista completa de todos os registros lançados." : "Lista dos registros lançados por você."}</p>
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <button 
            onClick={generateDetailedPDF} 
            className="flex items-center justify-center px-6 py-4 border border-transparent text-sm font-bold rounded-xl text-white bg-rose-600 hover:bg-rose-700 hover:-translate-y-0.5 shadow-sm transition-all"
          >
            <FileText className="mr-2" size={20} /> 
            Extrato em PDF
          </button>
          <button 
            onClick={generateDetailedExcel} 
            className="flex items-center justify-center px-6 py-4 border border-transparent text-sm font-bold rounded-xl text-white bg-emerald-600 hover:bg-emerald-700 hover:-translate-y-0.5 shadow-sm transition-all"
          >
            <FileSpreadsheet className="mr-2" size={20} /> 
            Extrato em Excel
          </button>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden mt-8">
        <div className="px-6 py-4 border-b border-slate-200 bg-slate-50 flex justify-between items-center">
           <h3 className="font-semibold text-slate-700">Registros Encontrados</h3>
           <span className="text-xs text-slate-400">{records.length} ocorrências totais</span>
        </div>
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Data</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Colaborador / Lote</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tipo</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Descrição</th>
                <th className="px-6 py-3 text-left text-xs font-medium text-slate-500 uppercase tracking-wider">Tempo</th>
                <th className="px-6 py-3 text-right text-xs font-medium text-slate-500 uppercase tracking-wider">Ações</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {processedRecords.map((item) => {
                const isBatchRow = item.isBatchLeader === true;
                const batchCount = isBatchRow ? batchMap[item.batchId]?.length : 0;
                const isExpanded = isBatchRow && expandedBatches.has(item.batchId);
                const editable = canUserEdit(item);

                // --- LINHA DE GRUPO (BATCH) ---
                if (isBatchRow) {
                   return (
                     <React.Fragment key={`batch-${item.batchId}`}>
                        <tr className="bg-purple-50/50 hover:bg-purple-50 border-l-4 border-l-purple-500">
                           <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-800">{formatDate(item.date)}</td>
                           <td className="px-6 py-4">
                              <div className="flex items-center gap-2">
                                <button onClick={() => toggleBatch(item.batchId)} className="p-1 rounded hover:bg-purple-200 text-purple-700 transition-colors">
                                   {isExpanded ? <ChevronDown size={18}/> : <ChevronRight size={18}/>}
                                </button>
                                <div>
                                   <div className="flex items-center gap-2 text-sm font-bold text-purple-900">
                                      <Layers size={16} /> Lançamento em Massa
                                   </div>
                                   <div className="text-xs text-purple-600 font-medium mt-0.5">
                                      {batchCount} colaboradores afetados
                                   </div>
                                </div>
                              </div>
                           </td>
                           <td className="px-6 py-4 whitespace-nowrap">
                              <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full bg-purple-100 text-purple-800 border border-purple-200`}>
                                 {item.occurrenceType} (Lote)
                              </span>
                           </td>
                           <td className="px-6 py-4 text-sm text-slate-600 max-w-xs truncate font-medium italic">
                              {item.reason}
                           </td>
                           <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-700">
                              {item.hours}h {item.minutes}m <span className="text-xs font-normal text-slate-400">(cada)</span>
                           </td>
                           <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                              {editable && (
                                <div className="flex items-center justify-end gap-2">
                                  <button onClick={() => openEditModal(item, true)} className="text-indigo-600 hover:text-indigo-900 p-1.5 hover:bg-indigo-50 rounded-lg flex items-center gap-1 border border-transparent hover:border-indigo-100 transition-all" title="Editar Lote Completo">
                                    <Edit size={16} />
                                  </button>
                                  <button 
                                    onClick={() => handleDelete(item.id, item.batchId)} 
                                    className="text-red-600 hover:text-red-900 p-1.5 hover:bg-red-50 rounded-lg flex items-center gap-1 border border-transparent hover:border-red-100 transition-all" 
                                    title="Excluir Lote Completo"
                                    disabled={loadingAction === `batch-${item.batchId}`}
                                  >
                                    {loadingAction === `batch-${item.batchId}` ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}
                                  </button>
                                </div>
                              )}
                           </td>
                        </tr>
                        {/* Filhos do Lote (Expandidos) */}
                        {isExpanded && batchMap[item.batchId].map((child: TimeRecord) => (
                           <tr key={child.id} className="bg-slate-50/50 hover:bg-slate-100 animate-fade-in">
                              <td className="px-6 py-3 whitespace-nowrap text-xs text-slate-400 pl-12 border-l-4 border-l-transparent">↳</td>
                              <td className="px-6 py-3 whitespace-nowrap">
                                 <div className="text-sm text-slate-700">{child.employeeName}</div>
                                 <div className="text-xs text-slate-400">{getEmployeeCompany(child.employeeId)}</div>
                              </td>
                              <td className="px-6 py-3 whitespace-nowrap text-xs text-slate-400">Ver Lote</td>
                              <td className="px-6 py-3 text-xs text-slate-400 italic">Ver Lote</td>
                              <td className="px-6 py-3 whitespace-nowrap text-xs text-slate-500 font-mono">
                                 {child.hours}h {child.minutes}m
                              </td>
                              <td className="px-6 py-3 whitespace-nowrap text-right text-xs">
                                 <span className="text-slate-300 select-none">Vinculado ao Lote</span>
                              </td>
                           </tr>
                        ))}
                     </React.Fragment>
                   );
                }

                // --- LINHA INDIVIDUAL (NORMAL) ---
                return (
                  <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-900">{formatDate(item.date)}</td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <div className="text-sm text-slate-900">{item.employeeName}</div>
                       <div className="text-xs text-slate-400">{getEmployeeCompany(item.employeeId)}</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                       <span className={`inline-flex px-2 py-1 text-xs font-semibold rounded-full ${item.type === RecordType.CREDIT ? 'bg-green-100 text-green-800' : item.type === RecordType.DEBIT ? 'bg-red-100 text-red-800' : 'bg-slate-100 text-slate-600'}`}>{item.occurrenceType}</span>
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500 max-w-xs truncate" title={item.reason}>{item.reason}</td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-700">{item.hours}h {item.minutes}m</td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {editable && (
                        <div className="flex items-center justify-end gap-2">
                          <button onClick={() => openEditModal(item)} className="text-indigo-600 hover:text-indigo-900 p-1 hover:bg-indigo-50 rounded" title="Editar"><Edit size={16} /></button>
                          <button onClick={() => handleDelete(item.id)} className="text-red-600 hover:text-red-900 p-1 hover:bg-red-50 rounded" title="Excluir" disabled={loadingAction === item.id}>{loadingAction === item.id ? <Loader2 size={16} className="animate-spin"/> : <Trash2 size={16} />}</button>
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>

      {isEditModalOpen && editingRecord && (
         <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-xl shadow-2xl max-w-lg w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
               <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 className="text-xl font-bold text-slate-800 flex items-center gap-2">
                        {isBatchEdit ? <><Layers size={20} className="text-purple-600"/> Editar Lote Completo</> : 'Editar Lançamento'}
                    </h3>
                    {isBatchEdit ? (
                        <p className="text-sm text-purple-600 mt-1 font-medium bg-purple-50 px-2 py-1 rounded-lg inline-block">
                            Alterações serão aplicadas para todos os colaboradores deste lote.
                        </p>
                    ) : (
                        <p className="text-sm text-slate-500">{editingRecord.employeeName}</p>
                    )}
                  </div>
                  <button onClick={() => setIsEditModalOpen(false)} className="text-slate-400 hover:text-slate-600"><X size={20}/></button>
               </div>
               <form onSubmit={handleUpdateRecord} className="space-y-4 overflow-y-auto pr-2 custom-scrollbar">
                  <div><label className="block text-sm font-medium text-slate-700">Data da Ocorrência</label><input type="date" required value={editDate} onChange={e => setEditDate(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/></div>
                  <div><label className="block text-sm font-medium text-slate-700">Tipo</label><select value={editOccurrenceType} onChange={e => setEditOccurrenceType(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900">{OCCURRENCE_OPTIONS.map(opt => <option key={opt.label} value={opt.label}>{opt.label}</option>)}</select></div>
                  <div className="grid grid-cols-2 gap-4 bg-slate-50 p-3 rounded-lg border border-slate-200">
                     <div><label className="block text-xs font-medium text-slate-500">Início</label><input type="time" value={editStartTime} onChange={e => setEditStartTime(e.target.value)} className="w-full mt-1 border border-slate-300 rounded px-2 py-1 bg-white text-slate-900"/></div>
                     <div><label className="block text-xs font-medium text-slate-500">Fim</label><input type="time" value={editEndTime} onChange={e => setEditEndTime(e.target.value)} className={`w-full mt-1 border rounded px-2 py-1 bg-white text-slate-900 ${!isEditTimeValid ? 'border-red-500' : 'border-slate-300'}`}/></div>
                     <div className="col-span-2 text-center text-sm font-bold text-indigo-600 border-t border-slate-200 pt-2">{isEditTimeValid ? `${editCalculatedDuration.hours}h ${editCalculatedDuration.minutes}m` : <span className="text-red-500">Horário Inválido</span>}</div>
                  </div>
                  <div><label className="block text-sm font-medium text-slate-700">Justificativa</label><textarea required rows={3} value={editReason} onChange={e => setEditReason(e.target.value)} className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 bg-slate-50 text-slate-900"/></div>
                  <div className="flex justify-end gap-3 pt-2">
                     <button type="button" onClick={() => setIsEditModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                     <button type="submit" disabled={loadingAction === 'modal-save' || !isEditTimeValid} className={`px-4 py-2 text-white rounded-lg flex items-center shadow-lg ${isBatchEdit ? 'bg-purple-600 hover:bg-purple-700' : 'bg-indigo-600 hover:bg-indigo-700'}`}>
                        {loadingAction === 'modal-save' ? <Loader2 size={16} className="animate-spin mr-2"/> : <Save size={16} className="mr-2"/>}
                        {isBatchEdit ? 'Atualizar Lote' : 'Salvar Alterações'}
                     </button>
                  </div>
               </form>
            </div>
         </div>
      )}
    </div>
  );
};

export default Reports;

import React from 'react';
import { LayoutDashboard, FilePlus, Users, FileText, LogOut, Layers, Settings } from 'lucide-react';
import { Role, Employee } from '../types';

interface SidebarProps {
  currentUser: Employee;
  currentRole: Role;
  currentPage: string;
  setPage: (page: string) => void;
  onLogout: () => void;
  isOpen: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ currentUser, currentRole, currentPage, setPage, onLogout, isOpen }) => {

  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'reports', label: 'Relatórios', icon: FileText, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'form', label: 'Nova Ocorrência', icon: FilePlus, roles: [Role.ADMIN, Role.LEADER] },
    { id: 'bulk', label: 'Lançamento em Massa', icon: Layers, roles: [Role.ADMIN] },
    { id: 'employees', label: 'Colaboradores', icon: Users, roles: [Role.ADMIN] },
    { id: 'settings', label: 'Configurações', icon: Settings, roles: [Role.ADMIN] },
  ];

  const filteredItems = menuItems.filter(item => item.roles.includes(currentRole));

  const getDisplayName = () => {
    if (!currentUser || !currentUser.name) return 'Usuário';
    const parts = currentUser.name.split(' ');
    if (parts.length > 1) {
      return `${parts[0]} ${parts[parts.length - 1]}`;
    }
    return parts[0];
  };

  const getInitials = () => {
     if (!currentUser || !currentUser.name) return 'US';
     const parts = currentUser.name.split(' ');
     if (parts.length > 1) return (parts[0][0] + parts[1][0]).toUpperCase();
     return parts[0].slice(0,2).toUpperCase();
  };

  const roleLabel = currentRole === Role.ADMIN ? 'Administrador' : 'Líder';

  return (
    <div className={`fixed inset-y-0 left-0 z-50 w-72 bg-[#002244] text-white transform transition-transform duration-300 ease-in-out ${isOpen ? 'translate-x-0' : '-translate-x-full'} md:translate-x-0 md:static md:inset-0 shadow-xl flex flex-col`}>
      <div className="flex flex-col h-full">
        <div className="p-6 border-b border-white/10">
          <h1 className="text-xl font-bold tracking-wider uppercase text-white">Hurafy</h1>
          <p className="text-xs text-slate-300 mt-1">Formulário de Ocorrência</p>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto custom-scrollbar">
          {filteredItems.map((item) => {
            const Icon = item.icon;
            const isActive = currentPage === item.id;
            return (
              <button
                key={item.id}
                onClick={() => setPage(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3 transition-all duration-200 group ${
                  isActive 
                    ? 'bg-white/10 text-white border-l-4 border-[#69BE28] rounded-r-lg' 
                    : 'text-slate-400 hover:bg-white/5 hover:text-white rounded-lg'
                }`}
              >
                <div className="flex items-center justify-center w-6 h-6 shrink-0">
                    <Icon size={20} className={`${isActive ? 'text-[#69BE28]' : 'text-slate-400 group-hover:text-white'}`} />
                </div>
                <span className="font-medium text-sm whitespace-nowrap overflow-hidden text-ellipsis">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-white/10">
          <div className="flex items-center space-x-3 px-4 py-3 mb-2 bg-[#001830] rounded-xl border border-white/5">
             <div className="w-9 h-9 rounded-full bg-[#69BE28] flex items-center justify-center text-xs font-bold shrink-0 text-[#002244] shadow-md">
               {getInitials()}
             </div>
             <div className="overflow-hidden">
               <p className="text-sm font-semibold truncate text-white" title={currentUser.name}>{getDisplayName()}</p>
               <p className="text-[10px] uppercase tracking-wider text-[#69BE28]">{roleLabel}</p>
             </div>
          </div>
          <button 
            onClick={onLogout}
            className="w-full flex items-center space-x-3 px-4 py-2.5 text-red-400 hover:bg-red-500/10 hover:text-red-300 rounded-lg transition-colors mt-1"
          >
            <LogOut size={18} className="shrink-0" />
            <span className="text-sm font-medium">Sair do Sistema</span>
          </button>
        </div>
      </div>
    </div>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { AlertCircle, Lock, Mail, ShieldCheck } from 'lucide-react';
import { firebaseService } from '../services/firebaseService';
import { Employee } from '../types';

interface LoginProps {
  onLoginSuccess: (user: Employee) => void;
}

const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const result = await firebaseService.login(email, password);

      if (result.success && result.user) {
        onLoginSuccess(result.user);
      } else {
        setError(result.message || 'Credenciais inválidas.');
      }
    } catch (err: any) {
      setError('Erro inesperado. Verifique o console.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200">
        <div className="bg-[#002244] p-8 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
          <h1 className="text-3xl font-bold text-white tracking-wider uppercase relative z-10">Hurafy</h1>
          <p className="text-[#69BE28] mt-2 text-sm relative z-10 font-medium">Banco de Horas Digital</p>
        </div>

        <div className="p-8 space-y-6">
          <div className="text-center">
            <div className="mx-auto w-12 h-12 bg-slate-100 text-[#002244] rounded-full flex items-center justify-center mb-4 border border-slate-200">
               <ShieldCheck size={24} />
            </div>
            <h2 className="text-xl font-semibold text-slate-800">Acesso ao Sistema</h2>
            <p className="text-sm text-slate-500 mt-1">Entre com seu login corporativo</p>
          </div>

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg flex items-center text-sm animate-fade-in">
              <AlertCircle size={16} className="mr-2 shrink-0" />
              {error}
            </div>
          )}

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">E-mail</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Mail className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm"
                  placeholder="seu.email@arcaplast.com.br"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Senha</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Lock className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:ring-2 focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm"
                  placeholder="••••••••"
                />
              </div>
            </div>

            <button
              type="submit"
              disabled={loading}
              className={`w-full flex items-center justify-center py-3.5 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white bg-[#69BE28] hover:bg-[#529620] transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-[#69BE28] ${
                loading ? 'opacity-70 cursor-not-allowed' : ''
              }`}
            >
              {loading ? (
                <div className="flex items-center">
                   <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin mr-2"></div>
                   Acessando...
                </div>
              ) : (
                'Entrar'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Loader2, ShieldAlert } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto', type: RecordType.NEUTRAL },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [absenceTime, setAbsenceTime] = useState('');

  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const isAbsenceAdjustment = ['Ausência de Batida', 'Ajuste de Ponto'].includes(occurrenceType);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (currentUser.role === Role.EMPLOYEE) {
       setSelectedEmployee(currentUser.id);
       setSearchTerm(currentUser.name);
    }
  }, [currentUser]);

  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
    setStartTime('');
    setEndTime('');
    setAbsenceTime('');
    setCalculatedDuration({ hours: 0, minutes: 0 });
    setIsTimeValid(true);
  }, [occurrenceType]);

  useEffect(() => {
    if (isAbsenceAdjustment) {
        setCalculatedDuration({ hours: 0, minutes: 0 });
        if (absenceTime) {
            setIsTimeValid(true);
            return;
        }
        if (startTime && endTime) {
             const [startH, startM] = startTime.split(':').map(Number);
             const [endH, endM] = endTime.split(':').map(Number);
             const startTotalMins = startH * 60 + startM;
             const endTotalMins = endH * 60 + endM;

             if (startTotalMins === endTotalMins) {
                 setIsTimeValid(true);
                 return;
             }
             if (endTotalMins < startTotalMins) {
                 setIsTimeValid(false);
                 return;
             }
             setIsTimeValid(true);
             return;
        }
        setIsTimeValid(false); 
        return;
    }

    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);
    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins <= startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime, absenceTime, isAbsenceAdjustment]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !reason) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    if (isAbsenceAdjustment) {
        const hasSpecificTime = !!absenceTime;
        const hasRange = !!(startTime && endTime);

        if (!hasSpecificTime && !hasRange) {
            alert("Informe o horário.");
            return;
        }

        if (hasRange && startTime === endTime) {
        } else if (hasRange && !isTimeValid) {
           alert("Horário inválido.");
           return;
        }

        if (reason.trim().length < 5) {
            alert("A justificativa é obrigatória e deve ser detalhada.");
            return;
        }
    } else {
        if (!startTime || !endTime || !isTimeValid) {
            alert("Verifique os horários de início e fim.");
            return;
        }
        if (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
            alert("A duração deve ser maior que zero.");
            return;
        }
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);
    const finalStartTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : startTime;
    const finalEndTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : endTime;

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date, 
      hours: isAbsenceAdjustment ? 0 : calculatedDuration.hours,
      minutes: isAbsenceAdjustment ? 0 : calculatedDuration.minutes,
      startTime: finalStartTime,
      endTime: finalEndTime,
      type: isAbsenceAdjustment ? RecordType.NEUTRAL : mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id,
      isAdjustment: isAbsenceAdjustment ? true : undefined,
      status: isAbsenceAdjustment ? 'regularized' : undefined
    };

    try {
      await firebaseService.saveTimeRecord(newRecord);
      setSuccess(true);
      onRecordAdded();
      if (currentUser.role !== Role.EMPLOYEE) {
         setSelectedEmployee('');
         setSearchTerm('');
      }
      setStartTime('');
      setEndTime('');
      setAbsenceTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');
      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar batida:", error);
      alert("Falha na comunicação com o servidor. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-[#69BE28]/10 text-[#69BE28] border-[#69BE28]/20';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in">

      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-[#69BE28]/20 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-[#69BE28]" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">
              {isAbsenceAdjustment 
                ? 'Ajuste registrado. Saldo inalterado.' 
                : 'Registro salvo no banco de dados.'}
            </p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-[#002244] p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6 text-[#69BE28]" />
            Nova Ocorrência
          </h2>
          <p className="text-slate-300 text-sm mt-1">Os dados serão sincronizados com o servidor.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  disabled={currentUser.role === Role.EMPLOYEE}
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-[#69BE28] ring-1 ring-[#69BE28] bg-[#69BE28]/5' : ''} ${currentUser.role === Role.EMPLOYEE ? 'bg-slate-100 cursor-not-allowed text-slate-500' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-[#69BE28] bg-[#69BE28]/10 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {isDropdownOpen && currentUser.role !== Role.EMPLOYEE && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-[#002244]' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-[#69BE28]">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm text-slate-900"
                />
              </div>
            </div>

            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <div className="relative">
                 <select
                    value={occurrenceType}
                    onChange={(e) => setOccurrenceType(e.target.value)}
                    className="block w-full pl-3 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
                 >
                   {OCCURRENCE_OPTIONS.map((opt) => (
                     <option key={opt.label} value={opt.label}>{opt.label}</option>
                   ))}
                 </select>
               </div>

               <div className={`mt-2 p-2 rounded-lg border text-xs font-semibold flex items-center justify-center ${getTypeStyles(mappedRecordType)}`}>
                  {mappedRecordType === RecordType.CREDIT && <span className="flex items-center"><Check size={14} className="mr-1"/> Adiciona ao Banco de Horas (Crédito)</span>}
                  {mappedRecordType === RecordType.DEBIT && <span className="flex items-center"><AlertTriangle size={14} className="mr-1"/> Desconta do Banco de Horas (Débito)</span>}
                  {mappedRecordType === RecordType.NEUTRAL && <span className="flex items-center"><Info size={14} className="mr-1"/> Informativo / Neutro (0h)</span>}
               </div>
            </div>

            {occurrenceType === 'Ausência de Batida' ? (
                <div className="col-span-1 md:col-span-2 animate-fade-in">
                    <label className="block text-sm font-medium text-slate-700 mb-2">Horário do Esquecimento</label>

                    <div className="bg-amber-50 p-4 rounded-xl border border-amber-200">
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="w-full md:w-1/2">
                                <label className="block text-xs font-semibold text-amber-700 mb-1">Hora da Batida</label>
                                <input 
                                  type="time" 
                                  required
                                  value={absenceTime}
                                  onChange={(e) => setAbsenceTime(e.target.value)}
                                  className="block w-full px-3 py-3 border border-amber-300 rounded-lg bg-white text-slate-900 focus:ring-amber-500 focus:border-amber-500 text-lg font-medium"
                                />
                            </div>

                            <div className="w-full md:w-1/2 flex items-start gap-3 text-sm text-amber-800">
                                <ShieldAlert className="shrink-0 w-8 h-8 text-amber-600" />
                                <div>
                                    <p className="font-bold">Regularização Detectada</p>
                                    <p className="text-xs mt-1">
                                        O sistema registrará <strong>entrada e saída simultâneas</strong> no horário informado para manter seu saldo inalterado.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="col-span-1 md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-2">Período da Atividade</label>
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Início/Entrada</label>
                      <input 
                        type="time" 
                        required
                        value={startTime}
                        onChange={(e) => setStartTime(e.target.value)}
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:ring-[#69BE28] focus:border-[#69BE28]"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Fim/Saída</label>
                      <input 
                        type="time" 
                        required
                        value={endTime}
                        onChange={(e) => setEndTime(e.target.value)}
                        className={`block w-full px-3 py-2 border rounded-lg bg-white text-slate-900 focus:ring-[#69BE28] focus:border-[#69BE28] ${!isTimeValid ? 'border-red-500 ring-1 ring-red-500' : 'border-slate-300'}`}
                      />
                    </div>

                    <div className="col-span-1 sm:col-span-2 mt-2 pt-4 border-t border-slate-200 flex items-center justify-between">
                      <div className="flex items-center text-slate-600">
                        <Calculator size={18} className="mr-2" />
                        <span className="text-sm font-medium">Tempo Calculado:</span>
                      </div>
                      <div className={`text-lg font-bold ${!isTimeValid ? 'text-red-500' : 'text-[#002244]'}`}>
                        {!isTimeValid ? (
                          <span className="text-sm">Horário Inválido</span>
                        ) : (
                           <span>{calculatedDuration.hours}h {calculatedDuration.minutes}m</span>
                        )}
                      </div>
                    </div>
                  </div>
                  {!isTimeValid && !isAbsenceAdjustment && (
                    <p className="text-xs text-red-500 mt-1">A hora de término deve ser posterior à hora de início.</p>
                  )}
                </div>
            )}

          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Justificativa {isAbsenceAdjustment && <span className="text-red-500">* (Obrigatório)</span>}
            </label>
            <textarea
              required
              rows={3}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={isAbsenceAdjustment ? "Explique detalhadamente o motivo do ajuste..." : "Detalhes adicionais..."}
              className={`block w-full px-3 py-3 border rounded-lg bg-slate-50 focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm text-slate-900 ${isAbsenceAdjustment && !reason ? 'border-amber-300 ring-1 ring-amber-300' : 'border-slate-300'}`}
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading || !selectedEmployee || (!isAbsenceAdjustment && !isTimeValid)}
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${loading || !selectedEmployee || (!isAbsenceAdjustment && !isTimeValid) ? 'bg-slate-400 cursor-not-allowed' : 'bg-[#69BE28] hover:bg-[#529620] focus:ring-2 focus:ring-offset-2 focus:ring-[#69BE28]'}`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Salvando no Firebase...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  {isAbsenceAdjustment ? 'Registrar Ajuste' : 'Registrar Batida'}
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TimeEntryForm;

import React, { useMemo, useState } from 'react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend 
} from 'recharts';
import { Clock, Users, TrendingUp, TrendingDown, Info, Filter, X, Briefcase, Building2 } from 'lucide-react';
import { TimeRecord, Employee, RecordType } from '../types';

interface DashboardProps {
  records: TimeRecord[];
  employees: Employee[];
}

const Dashboard: React.FC<DashboardProps> = ({ records, employees }) => {
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');
  const [selectedEmpId, setSelectedEmpId] = useState<string>('');

  const companies = useMemo(() => {
    const unique = new Set(employees.map(e => e.company).filter(Boolean));
    return Array.from(unique).sort();
  }, [employees]);

  const availableTeams = useMemo(() => {
    let filtered = employees;
    if (selectedCompany) {
      filtered = filtered.filter(e => e.company === selectedCompany);
    }
    const unique = new Set(filtered.map(e => e.team).filter(Boolean));
    return Array.from(unique).sort();
  }, [employees, selectedCompany]);

  const availableEmployees = useMemo(() => {
    let result = employees;
    if (selectedCompany) {
      result = result.filter(e => e.company === selectedCompany);
    }
    if (selectedTeam) {
      result = result.filter(e => e.team === selectedTeam);
    }
    return result;
  }, [employees, selectedCompany, selectedTeam]);

  const filteredRecords = useMemo(() => {
    let result = records || [];
    const validEmployeeIds = availableEmployees.map(e => e.id);
    result = result.filter(r => validEmployeeIds.includes(r.employeeId));
    if (selectedEmpId) {
      result = result.filter(r => r.employeeId === selectedEmpId);
    }
    return result;
  }, [records, availableEmployees, selectedEmpId]);

  const handleCompanyChange = (company: string) => {
    setSelectedCompany(company);
    setSelectedTeam('');
    setSelectedEmpId('');
  };

  const handleTeamChange = (team: string) => {
    setSelectedTeam(team);
    setSelectedEmpId('');
  };

  const stats = useMemo(() => {
    let totalMinutes = 0;
    let positiveMins = 0;
    let negativeMins = 0;
    let neutralCount = 0;

    filteredRecords.forEach(r => {
      const mins = (r.hours * 60) + r.minutes;
      if (r.type === RecordType.CREDIT) {
        positiveMins += mins;
        totalMinutes += mins;
      } else if (r.type === RecordType.DEBIT) {
        negativeMins += mins;
        totalMinutes -= mins;
      } else {
        neutralCount++;
      }
    });

    const isPositive = totalMinutes >= 0;
    const absTotalMinutes = Math.abs(totalMinutes);
    let activeCount = 0;
    if (selectedEmpId) {
      activeCount = 1;
    } else {
      activeCount = availableEmployees.filter(e => e.active).length;
    }

    return {
      balance: `${isPositive ? '' : '-'}${Math.floor(absTotalMinutes / 60)}:${(absTotalMinutes % 60).toString().padStart(2, '0')}`,
      positive: Math.floor(positiveMins / 60) + 'h ' + (positiveMins % 60) + 'm',
      negative: Math.floor(negativeMins / 60) + 'h ' + (negativeMins % 60) + 'm',
      neutralCount,
      employeeCount: activeCount,
      isPositive
    };
  }, [filteredRecords, availableEmployees, selectedEmpId]);

  const companyChartData = useMemo(() => {
    const dataMap: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};
    filteredRecords.forEach(r => {
      const emp = employees.find(e => e.id === r.employeeId);
      const groupKey = emp ? emp.company : 'Desconhecido';
      const hours = r.hours + (r.minutes / 60);
      if (!dataMap[groupKey]) {
        dataMap[groupKey] = { name: groupKey, horasPositivas: 0, horasNegativas: 0 };
      }
      if (r.type === RecordType.CREDIT) {
        dataMap[groupKey].horasPositivas += hours;
      } else if (r.type === RecordType.DEBIT) {
        dataMap[groupKey].horasNegativas += hours;
      }
    });
    return Object.values(dataMap);
  }, [filteredRecords, employees]);

  const drillDownChartData = useMemo(() => {
    const dataMap: Record<string, { name: string, horasPositivas: number, horasNegativas: number }> = {};
    filteredRecords.forEach(r => {
      let groupKey = '';
      if (selectedEmpId) {
         groupKey = r.occurrenceType || 'Geral';
      } else if (selectedTeam) {
         groupKey = r.employeeName;
      } else {
         const emp = employees.find(e => e.id === r.employeeId);
         groupKey = emp ? emp.team : 'Outros'; 
      }
      const hours = r.hours + (r.minutes / 60);
      if (!dataMap[groupKey]) {
        dataMap[groupKey] = { name: groupKey, horasPositivas: 0, horasNegativas: 0 };
      }
      if (r.type === RecordType.CREDIT) {
        dataMap[groupKey].horasPositivas += hours;
      } else if (r.type === RecordType.DEBIT) {
        dataMap[groupKey].horasNegativas += hours;
      }
    });
    return Object.values(dataMap);
  }, [filteredRecords, employees, selectedTeam, selectedEmpId]);

  const typeData = [
    { name: 'Horas Positivas', value: parseFloat(stats.positive.split('h')[0]) },
    { name: 'Horas Negativas', value: parseFloat(stats.negative.split('h')[0]) }
  ];

  // Action Green (#69BE28) and Red (#ef4444)
  const COLORS = ['#69BE28', '#ef4444'];

  const getDashboardTitle = () => {
    if (selectedEmpId) return 'Visão Individual';
    if (selectedTeam) return `Setor: ${selectedTeam}`;
    if (selectedCompany) return `Empresa: ${selectedCompany}`;
    return 'Visão Geral (Holding)';
  };

  const getDashboardSubtitle = () => {
    if (selectedEmpId) return `Analisando saldo de: ${employees.find(e => e.id === selectedEmpId)?.name}`;
    if (selectedTeam) return 'Acompanhamento de banco de horas da equipe';
    if (selectedCompany) return 'Visão consolidada da empresa';
    return 'Acompanhamento global de todas as empresas';
  };

  return (
    <div className="space-y-6 animate-fade-in">

      <div className="flex flex-col xl:flex-row xl:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold text-[#002244]">
            {getDashboardTitle()}
          </h2>
          <p className="text-sm text-slate-500">
            {getDashboardSubtitle()}
          </p>
        </div>

        <div className="flex flex-col sm:flex-row gap-3">

          <div className="relative min-w-[200px]">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Building2 className="h-4 w-4 text-slate-400" />
            </div>
            <select
              value={selectedCompany}
              onChange={(e) => handleCompanyChange(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-[#69BE28] focus:border-[#69BE28] text-sm text-slate-700 shadow-sm"
            >
              <option value="">Todas Empresas</option>
              {companies.map(company => (
                <option key={company} value={company}>{company}</option>
              ))}
            </select>
            {selectedCompany && (
              <button 
                onClick={() => handleCompanyChange('')}
                className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
                title="Limpar empresa"
              >
                <X size={14} />
              </button>
            )}
            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
              <Filter className="h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="relative min-w-[200px]">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Briefcase className="h-4 w-4 text-slate-400" />
            </div>
            <select
              value={selectedTeam}
              onChange={(e) => handleTeamChange(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-[#69BE28] focus:border-[#69BE28] text-sm text-slate-700 shadow-sm"
            >
              <option value="">Todos Setores</option>
              {availableTeams.map(team => (
                <option key={team} value={team}>{team}</option>
              ))}
            </select>
            {selectedTeam && (
              <button 
                onClick={() => handleTeamChange('')}
                className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
                title="Limpar setor"
              >
                <X size={14} />
              </button>
            )}
            <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
              <Filter className="h-4 w-4 text-slate-400" />
            </div>
          </div>

          <div className="relative min-w-[240px]">
            <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
              <Users className="h-4 w-4 text-slate-400" />
            </div>
            <select
              value={selectedEmpId}
              onChange={(e) => setSelectedEmpId(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-slate-300 rounded-lg bg-white focus:ring-[#69BE28] focus:border-[#69BE28] text-sm text-slate-700 shadow-sm"
            >
              <option value="">{selectedTeam ? 'Todos da Equipe' : 'Todos Colaboradores'}</option>
              {availableEmployees.map(emp => (
                <option key={emp.id} value={emp.id}>
                  {emp.name}
                </option>
              ))}
            </select>
            {selectedEmpId && (
              <button 
                onClick={() => setSelectedEmpId('')}
                className="absolute inset-y-0 right-8 pr-2 flex items-center text-slate-400 hover:text-slate-600"
                title="Limpar colaborador"
              >
                <X size={14} />
              </button>
            )}
             <div className="absolute inset-y-0 right-0 flex items-center px-2 pointer-events-none">
              <Filter className="h-4 w-4 text-slate-400" />
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-[#69BE28]/50">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Saldo {selectedEmpId ? 'Atual' : (selectedTeam ? 'do Setor' : (selectedCompany ? 'da Empresa' : 'Global'))}</p>
              <h3 className={`text-2xl font-bold mt-1 ${stats.isPositive ? 'text-[#69BE28]' : 'text-red-600'}`}>
                {stats.balance} h
              </h3>
            </div>
            <div className={`p-2 rounded-lg ${stats.isPositive ? 'bg-[#69BE28]/10 text-[#69BE28]' : 'bg-red-100 text-red-600'}`}>
              <Clock size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId ? 'Saldo líquido do colaborador' : 'Saldo líquido acumulado'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-blue-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Colaboradores</p>
              <h3 className="text-2xl font-bold mt-1 text-[#002244]">{stats.employeeCount}</h3>
            </div>
            <div className="p-2 rounded-lg bg-blue-100 text-blue-600">
              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId 
              ? 'Visualizando 1 colaborador' 
              : 'Ativos neste filtro'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-[#69BE28]/50">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Positivo</p>
              <h3 className="text-2xl font-bold mt-1 text-[#69BE28]">+{stats.positive}</h3>
            </div>
            <div className="p-2 rounded-lg bg-[#69BE28]/10 text-[#69BE28]">
              <TrendingUp size={20} />
            </div>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 transition-all hover:border-red-200">
          <div className="flex justify-between items-start">
            <div>
              <p className="text-sm font-medium text-slate-500">Total Negativo</p>
              <h3 className="text-2xl font-bold mt-1 text-red-600">-{stats.negative}</h3>
            </div>
            <div className="p-2 rounded-lg bg-red-100 text-red-600">
              <TrendingDown size={20} />
            </div>
          </div>
        </div>
      </div>

      {stats.neutralCount > 0 && (
         <div className="bg-slate-50 border border-slate-200 rounded-lg p-4 flex items-center text-slate-600">
            <Info className="w-5 h-5 mr-2" />
            <span className="text-sm">
              Existem {stats.neutralCount} registros informativos (Atestados, Exames, etc) neste filtro.
            </span>
         </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-[#002244] mb-4">Horas por Empresa</h3>
          <div className="h-80 w-full">
            {companyChartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={companyChartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }} barGap={8}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis 
                    dataKey="name" 
                    tick={{fill: '#64748b', fontSize: 11}} 
                    axisLine={false} 
                    tickLine={false} 
                    interval={0}
                  />
                  <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{fill: '#f1f5f9'}}
                  />
                  <Legend />
                  <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#69BE28" radius={[4, 4, 0, 0]} maxBarSize={50} />
                  <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} maxBarSize={50} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full w-full flex items-center justify-center text-slate-400">
                Sem dados suficientes para exibir o gráfico.
              </div>
            )}
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
          <h3 className="text-lg font-semibold text-[#002244] mb-4">Proporção Geral (Crédito vs Débito)</h3>
          <div className="h-80 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={typeData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  fill="#8884d8"
                  paddingAngle={5}
                  dataKey="value"
                >
                  {typeData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend verticalAlign="bottom" height={36}/>
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-2">
          <h3 className="text-lg font-semibold text-[#002244] mb-4">
             {selectedEmpId 
               ? 'Detalhe do Colaborador (Por Tipo)' 
               : selectedTeam 
                 ? 'Horas por Colaborador (Neste Setor)' 
                 : 'Horas por Setor'}
          </h3>
          <div className="h-96 w-full">
            {drillDownChartData.length > 0 ? (
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={drillDownChartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }} barGap={4}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis 
                    dataKey="name" 
                    tick={{fill: '#64748b', fontSize: 11}} 
                    axisLine={false} 
                    tickLine={false} 
                    interval={0}
                    angle={drillDownChartData.length > 8 ? -45 : 0}
                    textAnchor={drillDownChartData.length > 8 ? 'end' : 'middle'}
                    height={drillDownChartData.length > 8 ? 60 : 30}
                  />
                  <YAxis tick={{fill: '#64748b'}} axisLine={false} tickLine={false} />
                  <Tooltip 
                    contentStyle={{ backgroundColor: '#fff', borderRadius: '8px', border: '1px solid #e2e8f0', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                    cursor={{fill: '#f1f5f9'}}
                  />
                  <Legend />
                  <Bar dataKey="horasPositivas" name="Horas Positivas" fill="#69BE28" radius={[4, 4, 0, 0]} maxBarSize={60} />
                  <Bar dataKey="horasNegativas" name="Horas Negativas" fill="#ef4444" radius={[4, 4, 0, 0]} maxBarSize={60} />
                </BarChart>
              </ResponsiveContainer>
            ) : (
              <div className="h-full w-full flex items-center justify-center text-slate-400">
                Sem dados neste filtro.
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Building2 } from 'lucide-react';
import { Employee, Role, AppSetting } from '../types';
import { firebaseService } from '../services/firebaseService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
  currentUser: Employee; 
  companyList: AppSetting[];
  teamList: AppSetting[];
}

const EmployeeList: React.FC<EmployeeListProps> = ({ 
  employees, 
  refreshData, 
  currentUser,
  companyList,
  teamList
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState('');
  const [newCompany, setNewCompany] = useState('');

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase()) ||
      e.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const handleRoleChange = async (userId: string, newRole: Role) => {
    if (userId === currentUser.id) {
        alert("Você não pode alterar seu próprio cargo nesta tela.");
        return;
    }
    setLoadingAction(`role-${userId}`);
    try {
        const success = await firebaseService.updateUserRole(userId, newRole);
        if (success) {
            refreshData();
        } else {
            alert("Erro ao atualizar cargo.");
        }
    } catch (error) {
        console.error("Erro ao mudar role:", error);
    } finally {
        setLoadingAction(null);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewEmail('');
    setNewRole(Role.EMPLOYEE);
    setNewTeam('');
    setNewCompany('');
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewEmail(employee.email || '');
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setNewCompany(employee.company || '');
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCompany || !newTeam) {
        alert("Por favor, selecione uma Empresa e uma Equipe (Área). Se as listas estiverem vazias, vá em Configurações.");
        return;
    }
    setLoadingAction('save');

    let finalUsername = '';
    if (newEmail && newEmail.includes('@')) {
         finalUsername = newEmail.split('@')[0];
    } else {
         const cleanName = newName.toLowerCase().trim().split(' ');
         finalUsername = cleanName[0];
    }

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: finalUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      company: newCompany,
      active: true,
    };

    try {
      if (editingId) {
        await firebaseService.updateEmployee(employeeData);
      } else {
        await firebaseService.addEmployee(employeeData);
      }
      refreshData();
      setIsModalOpen(false);
    } catch (error) {
      console.error("Error saving employee:", error);
      alert("Erro ao salvar.");
    } finally {
      setLoadingAction(null);
      setEditingId(null);
    }
  };

  const handleDelete = async (id: string) => {
    if (id === currentUser.id) {
        alert("Você não pode excluir sua própria conta.");
        return;
    }
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await firebaseService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir do banco de dados.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  const isAdmin = currentUser.role === Role.ADMIN;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-[#002244]">Gestão de Colaboradores</h2>
           <p className="text-sm text-slate-500">
             {employees.length} usuários cadastrados
           </p>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={openAddModal}
            className="bg-[#69BE28] text-white px-4 py-2 rounded-lg hover:bg-[#529620] flex items-center transition-colors shadow-sm font-bold"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome, email ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-[#69BE28] focus:border-[#69BE28] sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="bg-white shadow-sm border border-slate-200 rounded-xl overflow-hidden">
        {employees.length === 0 ? (
           <div className="p-10 flex flex-col items-center justify-center text-slate-400">
              <Loader2 className="w-8 h-8 animate-spin mb-2" />
              <p>Carregando colaboradores...</p>
           </div>
        ) : (
        <ul className="divide-y divide-slate-200">
          {filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 hover:bg-slate-50 transition-colors animate-fade-in">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">

                <div className="flex items-center min-w-0 gap-4 flex-1">
                  <div className="h-10 w-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 shrink-0">
                    <User size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-slate-900 truncate flex items-center gap-2">
                      {employee.name}
                      {employee.id === currentUser.id && <span className="text-xs bg-[#002244]/10 text-[#002244] px-2 py-0.5 rounded-full">Você</span>}
                    </p>
                    <p className="text-xs text-slate-500 flex items-center mt-0.5">
                       <Building2 size={10} className="mr-1" />
                       {employee.company || 'Empresa não informada'} • {employee.team}
                    </p>
                    <p className="text-xs text-slate-400 mt-0.5">{employee.email || 'Sem email vinculado'}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4 justify-between md:justify-end w-full md:w-auto">

                  <div className="flex flex-col items-end min-w-[140px]">
                    {isAdmin ? (
                        <div className="relative">
                            <select 
                                value={employee.role}
                                disabled={loadingAction === `role-${employee.id}` || employee.id === currentUser.id}
                                onChange={(e) => handleRoleChange(employee.id, e.target.value as Role)}
                                className={`appearance-none block w-full pl-3 pr-8 py-1.5 text-xs font-medium rounded-full border focus:outline-none focus:ring-2 focus:ring-offset-1 transition-colors cursor-pointer text-slate-900
                                    ${employee.role === Role.ADMIN ? 'bg-purple-50 text-purple-700 border-purple-200 focus:ring-purple-500' : 
                                      employee.role === Role.LEADER ? 'bg-blue-50 text-blue-700 border-blue-200 focus:ring-blue-500' : 
                                      'bg-slate-50 text-slate-700 border-slate-200 focus:ring-slate-500'}
                                    ${loadingAction === `role-${employee.id}` ? 'opacity-50' : ''}
                                `}
                            >
                                <option value={Role.EMPLOYEE}>Colaborador</option>
                                <option value={Role.LEADER}>Líder</option>
                                <option value={Role.ADMIN}>Administrador</option>
                            </select>
                            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                                {loadingAction === `role-${employee.id}` ? (
                                    <Loader2 size={12} className="animate-spin" />
                                ) : (
                                    <svg className="h-3 w-3 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" fillRule="evenodd"></path></svg>
                                )}
                            </div>
                        </div>
                    ) : (
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium capitalize ${
                          employee.role === Role.ADMIN ? 'bg-purple-100 text-purple-800' :
                          employee.role === Role.LEADER ? 'bg-blue-100 text-blue-800' :
                          'bg-slate-100 text-slate-800'
                        }`}>
                          {employee.role === Role.ADMIN ? <Shield size={10} className="mr-1"/> : <Briefcase size={10} className="mr-1"/>}
                          {employee.role === Role.ADMIN ? 'Administrador' : employee.role === Role.LEADER ? 'Líder' : 'Colaborador'}
                        </span>
                    )}
                  </div>

                  {isAdmin && (
                      <div className="flex items-center gap-1 border-l border-slate-200 pl-3 ml-2">
                        <button 
                          onClick={() => openEditModal(employee)}
                          className="text-slate-400 hover:text-[#002244] transition-colors p-2 rounded-full hover:bg-slate-100"
                          title="Editar Detalhes"
                          disabled={loadingAction !== null}
                        >
                          <Edit size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(employee.id)}
                          className={`text-slate-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50 ${employee.id === currentUser.id ? 'opacity-20 cursor-not-allowed' : ''}`}
                          title="Excluir"
                          disabled={loadingAction !== null || employee.id === currentUser.id}
                        >
                          {loadingAction === employee.id ? (
                            <Loader2 size={18} className="animate-spin text-red-600" />
                          ) : (
                            <Trash2 size={18} />
                          )}
                        </button>
                      </div>
                  )}
                </div>
              </div>
            </li>
          ))}
          {filteredEmployees.length === 0 && (
            <li className="p-8 text-center text-slate-500">
              Nenhum colaborador encontrado com este filtro.
            </li>
          )}
        </ul>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="mb-4">
              <h3 className="text-xl font-bold text-[#002244]">
                {editingId ? 'Editar Colaborador' : 'Pré-cadastrar Colaborador'}
              </h3>
              <p className="text-xs text-slate-500">
                  {editingId ? 'Atualizar dados cadastrais.' : 'Cria um perfil que será vinculado quando o usuário fizer login.'}
              </p>
            </div>

            <form onSubmit={handleSaveEmployee} className="space-y-4 overflow-y-auto pr-3 custom-scrollbar flex-1 min-h-0">
              <div>
                <label className="block text-sm font-medium text-slate-700">Nome Completo</label>
                <input required type="text" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-[#69BE28] focus:border-[#69BE28] bg-slate-50 text-slate-900" value={newName} onChange={e => setNewName(e.target.value)} />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700">Email <span className="text-slate-400 text-xs">(Vinculação Google/Firebase)</span></label>
                <input 
                  type="email" 
                  required
                  placeholder="email@arcaplast.com.br"
                  className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-[#69BE28] focus:border-[#69BE28] bg-slate-50 text-slate-900" 
                  value={newEmail} 
                  onChange={e => setNewEmail(e.target.value)} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Empresa</label>
                    <select 
                      className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-[#69BE28] focus:border-[#69BE28] bg-slate-50 text-slate-900" 
                      value={newCompany} 
                      onChange={e => setNewCompany(e.target.value)}
                    >
                      <option value="">Selecione...</option>
                      {companyList.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                    </select>
                    {companyList.length === 0 && <span className="text-xs text-red-500">Nenhuma empresa cadastrada. Vá em Configurações.</span>}
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Equipe (Área)</label>
                    <select 
                      className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-[#69BE28] focus:border-[#69BE28] bg-slate-50 text-slate-900" 
                      value={newTeam} 
                      onChange={e => setNewTeam(e.target.value)}
                    >
                      <option value="">Selecione...</option>
                      {teamList.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                    </select>
                    {teamList.length === 0 && <span className="text-xs text-red-500">Nenhuma área cadastrada. Vá em Configurações.</span>}
                 </div>
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                <button type="submit" disabled={loadingAction === 'save'} className="px-4 py-2 bg-[#69BE28] text-white rounded-lg hover:bg-[#529620] flex items-center font-bold">
                  {loadingAction === 'save' && <Loader2 size={16} className="animate-spin mr-2" />}
                  {editingId ? 'Salvar Alterações' : 'Criar Perfil'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeList;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, Filter, Calendar, CheckSquare, Square, 
  Save, Loader2, Building2, Briefcase, Check, AlertCircle 
} from 'lucide-react';
import { Employee, RecordType, TimeRecord, AppSetting } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface BulkOccurrenceProps {
  employees: Employee[];
  currentUser: Employee;
  onRecordsAdded: () => void;
  companyList: AppSetting[];
  teamList: AppSetting[];
}

const BULK_TYPES = [
  { label: 'BH Positivo (Crédito)', type: RecordType.CREDIT },
  { label: 'BH Negativo (Débito)', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto (Manual)', type: RecordType.NEUTRAL },
];

const BulkOccurrence: React.FC<BulkOccurrenceProps> = ({ 
  employees, 
  currentUser, 
  onRecordsAdded,
  companyList,
  teamList
}) => {
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');
  const [selectedUserIds, setSelectedUserIds] = useState<Set<string>>(new Set());

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [occurrenceLabel, setOccurrenceLabel] = useState(BULK_TYPES[0].label);
  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);
  const [observation, setObservation] = useState('');

  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => {
      const matchCompany = selectedCompany ? e.company === selectedCompany : true;
      const matchTeam = selectedTeam ? e.team === selectedTeam : true;
      return matchCompany && matchTeam && e.active;
    });
  }, [employees, selectedCompany, selectedTeam]);

  const handleSelectAll = () => {
    if (selectedUserIds.size === filteredEmployees.length) {
      setSelectedUserIds(new Set()); 
    } else {
      setSelectedUserIds(new Set(filteredEmployees.map(e => e.id))); 
    }
  };

  const handleToggleUser = (id: string) => {
    const newSet = new Set(selectedUserIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedUserIds(newSet);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUserIds.size === 0) {
      alert("Selecione pelo menos um colaborador.");
      return;
    }
    if (!observation) {
      alert("A observação é obrigatória para lançamentos em massa.");
      return;
    }

    setLoading(true);

    try {
      const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
      const recordType = typeObj ? typeObj.type : RecordType.NEUTRAL;
      const batchId = uuidv4();

      const recordsToSave: TimeRecord[] = Array.from(selectedUserIds).map(userId => {
        const emp = employees.find(e => e.id === userId);
        return {
          id: uuidv4(),
          batchId: batchId,
          employeeId: userId,
          employeeName: emp?.name || 'Desconhecido',
          date: date,
          hours: Number(hours),
          minutes: Number(minutes),
          startTime: '', 
          endTime: '',   
          type: recordType,
          occurrenceType: occurrenceLabel,
          reason: observation,
          createdAt: new Date().toISOString(),
          createdBy: currentUser.id,
        };
      });

      const result = await firebaseService.saveBulkOccurrences(recordsToSave);

      if (result.success) {
        setSuccessMsg(`Lançamento concluído com sucesso para ${result.count} colaboradores!`);
        onRecordsAdded();

        setSelectedUserIds(new Set());
        setObservation('');
        setHours(0);
        setMinutes(0);

        setTimeout(() => setSuccessMsg(null), 5000);
      }
    } catch (error) {
      console.error(error);
      alert("Erro ao processar lançamento em massa.");
    } finally {
      setLoading(false);
    }
  };

  const getSelectedTypeImpact = () => {
    const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
    if (!typeObj) return null;
    if (typeObj.type === RecordType.CREDIT) return <span className="text-[#69BE28] font-medium text-xs ml-2">(Adiciona Horas)</span>;
    if (typeObj.type === RecordType.DEBIT) return <span className="text-red-600 font-medium text-xs ml-2">(Desconta Horas)</span>;
    return <span className="text-slate-500 font-medium text-xs ml-2">(Apenas Histórico)</span>;
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">

      {successMsg && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-md w-full mx-4">
            <div className="h-16 w-16 bg-[#69BE28]/20 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-[#69BE28]" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMsg}</p>
          </div>
        </div>
      )}

      <div className="flex items-center gap-3">
        <div className="p-3 bg-[#002244]/10 text-[#002244] rounded-xl">
          <Users size={28} />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-[#002244]">Lançamento em Massa (RH)</h2>
          <p className="text-slate-500">Aplique ocorrências para múltiplos colaboradores de uma só vez.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col h-[600px]">

          <div className="p-4 border-b border-slate-200 space-y-4 bg-slate-50/50 rounded-t-2xl">
            <div className="flex gap-4">
              <div className="flex-1 relative">
                 <Building2 className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedCompany} 
                   onChange={e => setSelectedCompany(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-[#69BE28] focus:border-[#69BE28] transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todas as Empresas</option>
                   {companyList.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                 </select>
              </div>
              <div className="flex-1 relative">
                 <Briefcase className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedTeam} 
                   onChange={e => setSelectedTeam(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-[#69BE28] focus:border-[#69BE28] transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todos os Setores</option>
