import React, { useState, useEffect } from 'react';
import { 
  Building2, 
  Briefcase, 
  Plus, 
  Trash2, 
  Edit2, 
  Save, 
  X, 
  Loader2, 
  Settings as SettingsIcon,
  RefreshCw
} from 'lucide-react';
import { AppSetting, Employee } from '../types';
import { firebaseService } from '../services/firebaseService';

interface SettingsProps {
  companies: AppSetting[];
  teams: AppSetting[];
  employees: Employee[];
  refreshData: () => void;
}

const DEFAULT_COMPANIES = ['Arca Plast', 'Arca Mania', 'Rearca', 'Taex Transportadora'];
const DEFAULT_TEAMS = [
  'Embalagem', 'Engenharia', 'Estoque', 'Excelência Operacional', 'Financeiro', 
  'Gente e Gestão', 'Gestão', 'Gestão da Produção', 'Gestão Estratégica', 
  'Injeção', 'Logística', 'Manutenção', 'Marketing', 'Mercado', 
  'Serviços Gerais', 'Sopro', 'Suprimentos', 'TI'
];

const ManageList = ({ 
  title, 
  icon: Icon, 
  items, 
  collectionName, 
  refreshData,
  deleteWarning 
}: { 
  title: string; 
  icon: any; 
  items: AppSetting[]; 
  collectionName: 'settings_companies' | 'settings_areas';
  refreshData: () => void;
  deleteWarning?: string;
}) => {
  const [newItemName, setNewItemName] = useState('');
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItemName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.addSettingItem(collectionName, newItemName.trim());
      setNewItemName('');
      refreshData();
    } catch (error) {
      alert("Erro ao adicionar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (item: AppSetting) => {
    setEditingId(item.id);
    setEditName(item.name);
  };

  const handleUpdate = async () => {
    if (!editingId || !editName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.updateSettingItem(collectionName, editingId, editName.trim());
      setEditingId(null);
      refreshData();
    } catch (error) {
      alert("Erro ao atualizar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (deleteWarning) {
        if (!confirm(deleteWarning)) return;
    } else {
        if (!confirm("Tem certeza que deseja remover este item?")) return;
    }

    setLoading(true);
    try {
      await firebaseService.deleteSettingItem(collectionName, id);
      refreshData();
    } catch (error) {
      alert("Erro ao excluir item.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[500px]">
      <div className="p-4 border-b border-slate-100 bg-slate-50 flex items-center justify-between">
        <div className="flex items-center gap-2 text-slate-800 font-bold">
          <Icon size={20} className="text-[#002244]" />
          {title}
        </div>
        <span className="text-xs bg-slate-200 text-slate-600 px-2 py-1 rounded-full">{items.length}</span>
      </div>

      <div className="flex-1 overflow-y-auto custom-scrollbar p-2 space-y-2">
        {items.length === 0 && (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm">
                <p>Nenhum item cadastrado.</p>
            </div>
        )}
        {items.map(item => (
          <div key={item.id} className="group flex items-center justify-between p-3 rounded-lg hover:bg-slate-50 border border-transparent hover:border-slate-100 transition-all">
            {editingId === item.id ? (
              <div className="flex flex-1 items-center gap-2">
                 <input 
                   autoFocus
                   type="text" 
                   value={editName}
                   onChange={e => setEditName(e.target.value)}
                   className="flex-1 text-sm border rounded px-2 py-1 focus:ring-2 focus:ring-[#69BE28] outline-none bg-white text-slate-900"
                 />
                 <button onClick={handleUpdate} className="p-1 text-[#69BE28] hover:bg-[#69BE28]/10 rounded"><Save size={16}/></button>
                 <button onClick={() => setEditingId(null)} className="p-1 text-slate-400 hover:bg-slate-50 rounded"><X size={16}/></button>
              </div>
            ) : (
              <>
                <span className="text-sm font-medium text-slate-700">{item.name}</span>
                <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button 
                    onClick={() => handleEdit(item)}
                    className="p-1.5 text-blue-500 hover:bg-blue-50 rounded-lg transition-colors" 
                    title="Editar"
                  >
                    <Edit2 size={16} />
                  </button>
                  <button 
                    onClick={() => handleDelete(item.id)}
                    className="p-1.5 text-red-500 hover:bg-red-50 rounded-lg transition-colors" 
                    title="Excluir"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              </>
            )}
          </div>
        ))}
      </div>

      <div className="p-4 border-t border-slate-100 bg-slate-50">
        <form onSubmit={handleAdd} className="flex gap-2">
          <input 
            type="text" 
            placeholder="Adicionar novo..." 
            value={newItemName}
            onChange={e => setNewItemName(e.target.value)}
            disabled={loading}
            className="flex-1 text-sm border border-slate-300 rounded-lg px-3 py-2 focus:outline-none focus:border-[#69BE28] focus:ring-1 focus:ring-[#69BE28] bg-white text-slate-900"
          />
          <button 
            type="submit" 
            disabled={loading || !newItemName.trim()}
            className="bg-[#69BE28] hover:bg-[#529620] text-white p-2 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
          >
            {loading ? <Loader2 size={20} className="animate-spin" /> : <Plus size={20} />}
          </button>
        </form>
      </div>
    </div>
  );
};

const Settings: React.FC<SettingsProps> = ({ companies, teams, employees, refreshData }) => {
  const [isMigrating, setIsMigrating] = useState(false);

  useEffect(() => {
    const performMigration = async () => {
       const needsCompanyMigration = companies.length === 0;
       const needsTeamMigration = teams.length === 0;

       if (!needsCompanyMigration && !needsTeamMigration) return;

       setIsMigrating(true);
       console.log("🔄 Iniciando Auto-Hidratação de configurações...");

       try {
          const uniqueCompanies = new Set(DEFAULT_COMPANIES);
          const uniqueTeams = new Set(DEFAULT_TEAMS);

          if (employees.length > 0) {
             employees.forEach(emp => {
                if (emp.company && emp.company.trim()) uniqueCompanies.add(emp.company.trim());
                if (emp.team && emp.team.trim()) uniqueTeams.add(emp.team.trim());
             });
          }

          const promises = [];

          if (needsCompanyMigration) {
             for (const comp of uniqueCompanies) {
                if (comp) promises.push(firebaseService.addSettingItem('settings_companies', comp));
             }
          }

          if (needsTeamMigration) {
             for (const team of uniqueTeams) {
                if (team) promises.push(firebaseService.addSettingItem('settings_areas', team));
             }
          }

          if (promises.length > 0) {
            await Promise.all(promises);
            refreshData(); 
          }

       } catch (error) {
          console.error("Erro na migração automática:", error);
       } finally {
          setIsMigrating(false);
       }
    };

    const timer = setTimeout(() => {
        performMigration();
    }, 1500);

    return () => clearTimeout(timer);
  }, [companies.length, teams.length, employees]); 

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-3">
            <div className="p-3 bg-[#002244]/10 text-[#002244] rounded-xl">
            <SettingsIcon size={28} />
            </div>
            <div>
            <h2 className="text-2xl font-bold text-[#002244]">Configurações do Sistema</h2>
            <p className="text-slate-500">Gerencie as listas de empresas e áreas utilizadas no sistema.</p>
            </div>
        </div>

        {isMigrating && (
            <div className="flex items-center gap-2 text-[#002244] bg-slate-100 px-4 py-2 rounded-lg border border-slate-200 animate-pulse">
                <RefreshCw size={18} className="animate-spin" />
                <span className="text-sm font-medium">Sincronizando dados existentes...</span>
            </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <ManageList 
          title="Empresas" 
          icon={Building2} 
          items={companies} 
          collectionName="settings_companies"
          refreshData={refreshData}
          deleteWarning="Tem certeza que deseja remover esta empresa? Colaboradores vinculados podem ficar com dados inconsistentes."
        />
        <ManageList 
          title="Áreas / Setores" 
          icon={Briefcase} 
          items={teams} 
          collectionName="settings_areas"
          refreshData={refreshData}
          deleteWarning="Certifique-se de que não há colaboradores vinculados a esta área antes de excluir."
        />
      </div>
    </div>
  );
};

