        </p>
      </div>

      {currentUser.role === Role.ADMIN && (
        <div className="bg-gradient-to-r from-slate-50 to-white p-6 rounded-xl border border-slate-200 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-2 bg-[#002244]/10 text-[#002244] rounded-lg">
              <Users size={24} />
            </div>
            <div>
              <h3 className="text-lg font-bold text-slate-800">Balanço Geral (Consolidado)</h3>
