import React, { useState } from 'react';
import { Plus, Trash2, Search, User, Shield, Briefcase, Edit, Loader2, Building2 } from 'lucide-react';
import { Employee, Role, AppSetting } from '../types';
import { firebaseService } from '../services/firebaseService';
import { v4 as uuidv4 } from 'uuid';

interface EmployeeListProps {
  employees: Employee[];
  refreshData: () => void;
  currentUser: Employee; 
  companyList: AppSetting[];
  teamList: AppSetting[];
}

const EmployeeList: React.FC<EmployeeListProps> = ({ 
  employees, 
  refreshData, 
  currentUser,
  companyList,
  teamList
}) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [loadingAction, setLoadingAction] = useState<string | null>(null);

  const [deletedIds, setDeletedIds] = useState<Set<string>>(new Set());

  const [editingId, setEditingId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [newEmail, setNewEmail] = useState('');
  const [newRole, setNewRole] = useState<Role>(Role.EMPLOYEE);
  const [newTeam, setNewTeam] = useState('');
  const [newCompany, setNewCompany] = useState('');

  const filteredEmployees = employees.filter(e => {
    if (deletedIds.has(e.id)) return false;
    return (
      e.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      e.team.toLowerCase().includes(searchTerm.toLowerCase()) ||
      e.email.toLowerCase().includes(searchTerm.toLowerCase())
    );
  });

  const handleRoleChange = async (userId: string, newRole: Role) => {
    if (userId === currentUser.id) {
        alert("Você não pode alterar seu próprio cargo nesta tela.");
        return;
    }
    setLoadingAction(`role-${userId}`);
    try {
        const success = await firebaseService.updateUserRole(userId, newRole);
        if (success) {
            refreshData();
        } else {
            alert("Erro ao atualizar cargo.");
        }
    } catch (error) {
        console.error("Erro ao mudar role:", error);
    } finally {
        setLoadingAction(null);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    setNewName('');
    setNewEmail('');
    setNewRole(Role.EMPLOYEE);
    setNewTeam('');
    setNewCompany('');
    setIsModalOpen(true);
  };

  const openEditModal = (employee: Employee) => {
    setEditingId(employee.id);
    setNewName(employee.name);
    setNewEmail(employee.email || '');
    setNewRole(employee.role);
    setNewTeam(employee.team);
    setNewCompany(employee.company || '');
    setIsModalOpen(true);
  };

  const handleSaveEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newCompany || !newTeam) {
        alert("Por favor, selecione uma Empresa e uma Equipe (Área). Se as listas estiverem vazias, vá em Configurações.");
        return;
    }
    setLoadingAction('save');

    let finalUsername = '';
    if (newEmail && newEmail.includes('@')) {
         finalUsername = newEmail.split('@')[0];
    } else {
         const cleanName = newName.toLowerCase().trim().split(' ');
         finalUsername = cleanName[0];
    }

    const employeeData: Employee = {
      id: editingId || uuidv4(),
      username: finalUsername,
      name: newName,
      email: newEmail,
      role: newRole,
      team: newTeam,
      company: newCompany,
      active: true,
    };

    try {
      if (editingId) {
        await firebaseService.updateEmployee(employeeData);
      } else {
        await firebaseService.addEmployee(employeeData);
      }
      refreshData();
      setIsModalOpen(false);
    } catch (error) {
      console.error("Error saving employee:", error);
      alert("Erro ao salvar.");
    } finally {
      setLoadingAction(null);
      setEditingId(null);
    }
  };

  const handleDelete = async (id: string) => {
    if (id === currentUser.id) {
        alert("Você não pode excluir sua própria conta.");
        return;
    }
    if (confirm('Tem certeza que deseja remover este colaborador?')) {
      setLoadingAction(id);
      setDeletedIds(prev => new Set(prev).add(id));
      const success = await firebaseService.deleteEmployee(id);

      if (success) {
        refreshData();
      } else {
        alert("Erro ao excluir do banco de dados.");
        setDeletedIds(prev => {
           const newSet = new Set(prev);
           newSet.delete(id);
           return newSet;
        });
      }
      setLoadingAction(null);
    }
  };

  const isAdmin = currentUser.role === Role.ADMIN;

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div>
           <h2 className="text-2xl font-bold text-slate-800">Gestão de Colaboradores</h2>
           <p className="text-sm text-slate-500">
             {employees.length} usuários cadastrados
           </p>
        </div>

        <div className="flex gap-2">
          <button 
            onClick={openAddModal}
            className="bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 flex items-center transition-colors shadow-sm font-bold"
          >
            <Plus size={20} className="mr-2" />
            Novo Colaborador
          </button>
        </div>
      </div>

      <div className="relative">
        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-slate-400" />
        </div>
        <input
          type="text"
          placeholder="Buscar por nome, email ou equipe..."
          className="block w-full pl-10 pr-3 py-3 border border-slate-200 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:placeholder-slate-500 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm shadow-sm"
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
        />
      </div>

      <div className="bg-white shadow-sm border border-slate-200 rounded-xl overflow-hidden">
        {employees.length === 0 ? (
           <div className="p-10 flex flex-col items-center justify-center text-slate-400">
              <Loader2 className="w-8 h-8 animate-spin mb-2" />
              <p>Carregando colaboradores...</p>
           </div>
        ) : (
        <ul className="divide-y divide-slate-200">
          {filteredEmployees.map((employee) => (
            <li key={employee.id} className="p-4 hover:bg-slate-50 transition-colors animate-fade-in">
              <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">

                <div className="flex items-center min-w-0 gap-4 flex-1">
                  <div className="h-10 w-10 rounded-full bg-slate-200 flex items-center justify-center text-slate-500 shrink-0">
                    <User size={20} />
                  </div>
                  <div className="min-w-0">
                    <p className="text-sm font-semibold text-slate-900 truncate flex items-center gap-2">
                      {employee.name}
                      {employee.id === currentUser.id && <span className="text-xs bg-indigo-100 text-indigo-700 px-2 py-0.5 rounded-full">Você</span>}
                    </p>
                    <p className="text-xs text-slate-500 flex items-center mt-0.5">
                       <Building2 size={10} className="mr-1" />
                       {employee.company || 'Empresa não informada'} • {employee.team}
                    </p>
                    <p className="text-xs text-slate-400 mt-0.5">{employee.email || 'Sem email vinculado'}</p>
                  </div>
                </div>

                <div className="flex items-center gap-4 justify-between md:justify-end w-full md:w-auto">

                  <div className="flex flex-col items-end min-w-[140px]">
                    {isAdmin ? (
                        <div className="relative">
                            <select 
                                value={employee.role}
                                disabled={loadingAction === `role-${employee.id}` || employee.id === currentUser.id}
                                onChange={(e) => handleRoleChange(employee.id, e.target.value as Role)}
                                className={`appearance-none block w-full pl-3 pr-8 py-1.5 text-xs font-medium rounded-full border focus:outline-none focus:ring-2 focus:ring-offset-1 transition-colors cursor-pointer text-slate-900
                                    ${employee.role === Role.ADMIN ? 'bg-purple-50 text-purple-700 border-purple-200 focus:ring-purple-500' : 
                                      employee.role === Role.LEADER ? 'bg-blue-50 text-blue-700 border-blue-200 focus:ring-blue-500' : 
                                      'bg-slate-50 text-slate-700 border-slate-200 focus:ring-slate-500'}
                                    ${loadingAction === `role-${employee.id}` ? 'opacity-50' : ''}
                                `}
                            >
                                <option value={Role.EMPLOYEE}>Colaborador</option>
                                <option value={Role.LEADER}>Líder</option>
                                <option value={Role.ADMIN}>Administrador</option>
                            </select>
                            <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center px-2 text-gray-500">
                                {loadingAction === `role-${employee.id}` ? (
                                    <Loader2 size={12} className="animate-spin" />
                                ) : (
                                    <svg className="h-3 w-3 fill-current" viewBox="0 0 20 20"><path d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z" clipRule="evenodd" fillRule="evenodd"></path></svg>
                                )}
                            </div>
                        </div>
                    ) : (
                        <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium capitalize ${
                          employee.role === Role.ADMIN ? 'bg-purple-100 text-purple-800' :
                          employee.role === Role.LEADER ? 'bg-blue-100 text-blue-800' :
                          'bg-slate-100 text-slate-800'
                        }`}>
                          {employee.role === Role.ADMIN ? <Shield size={10} className="mr-1"/> : <Briefcase size={10} className="mr-1"/>}
                          {employee.role === Role.ADMIN ? 'Administrador' : employee.role === Role.LEADER ? 'Líder' : 'Colaborador'}
                        </span>
                    )}
                  </div>

                  {isAdmin && (
                      <div className="flex items-center gap-1 border-l border-slate-200 pl-3 ml-2">
                        <button 
                          onClick={() => openEditModal(employee)}
                          className="text-slate-400 hover:text-indigo-600 transition-colors p-2 rounded-full hover:bg-slate-100"
                          title="Editar Detalhes"
                          disabled={loadingAction !== null}
                        >
                          <Edit size={18} />
                        </button>
                        <button 
                          onClick={() => handleDelete(employee.id)}
                          className={`text-slate-400 hover:text-red-600 transition-colors p-2 rounded-full hover:bg-red-50 ${employee.id === currentUser.id ? 'opacity-20 cursor-not-allowed' : ''}`}
                          title="Excluir"
                          disabled={loadingAction !== null || employee.id === currentUser.id}
                        >
                          {loadingAction === employee.id ? (
                            <Loader2 size={18} className="animate-spin text-red-600" />
                          ) : (
                            <Trash2 size={18} />
                          )}
                        </button>
                      </div>
                  )}
                </div>
              </div>
            </li>
          ))}
          {filteredEmployees.length === 0 && (
            <li className="p-8 text-center text-slate-500">
              Nenhum colaborador encontrado com este filtro.
            </li>
          )}
        </ul>
        )}
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl shadow-2xl max-w-md w-full p-6 animate-fade-in-up flex flex-col max-h-[90vh]">
            <div className="mb-4">
              <h3 className="text-xl font-bold text-slate-800">
                {editingId ? 'Editar Colaborador' : 'Pré-cadastrar Colaborador'}
              </h3>
              <p className="text-xs text-slate-500">
                  {editingId ? 'Atualizar dados cadastrais.' : 'Cria um perfil que será vinculado quando o usuário fizer login.'}
              </p>
            </div>

            <form onSubmit={handleSaveEmployee} className="space-y-4 overflow-y-auto pr-3 custom-scrollbar flex-1 min-h-0">
              <div>
                <label className="block text-sm font-medium text-slate-700">Nome Completo</label>
                <input required type="text" className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" value={newName} onChange={e => setNewName(e.target.value)} />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700">Email <span className="text-slate-400 text-xs">(Vinculação Google/Firebase)</span></label>
                <input 
                  type="email" 
                  required
                  placeholder="email@arcaplast.com.br"
                  className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                  value={newEmail} 
                  onChange={e => setNewEmail(e.target.value)} 
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Empresa</label>
                    <select 
                      className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                      value={newCompany} 
                      onChange={e => setNewCompany(e.target.value)}
                    >
                      <option value="">Selecione...</option>
                      {companyList.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                    </select>
                    {companyList.length === 0 && <span className="text-xs text-red-500">Nenhuma empresa cadastrada. Vá em Configurações.</span>}
                 </div>
                 <div>
                    <label className="block text-sm font-medium text-slate-700">Equipe (Área)</label>
                    <select 
                      className="mt-1 block w-full border border-slate-300 rounded-lg px-3 py-2 shadow-sm focus:ring-indigo-500 focus:border-indigo-500 bg-slate-50 text-slate-900" 
                      value={newTeam} 
                      onChange={e => setNewTeam(e.target.value)}
                    >
                      <option value="">Selecione...</option>
                      {teamList.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                    </select>
                    {teamList.length === 0 && <span className="text-xs text-red-500">Nenhuma área cadastrada. Vá em Configurações.</span>}
                 </div>
              </div>

              <div className="flex justify-end gap-3 mt-6 pt-2">
                <button type="button" onClick={() => setIsModalOpen(false)} className="px-4 py-2 text-slate-700 hover:bg-slate-100 rounded-lg">Cancelar</button>
                <button type="submit" disabled={loadingAction === 'save'} className="px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 flex items-center font-bold">
                  {loadingAction === 'save' && <Loader2 size={16} className="animate-spin mr-2" />}
                  {editingId ? 'Salvar Alterações' : 'Criar Perfil'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default EmployeeList;

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, Filter, Calendar, CheckSquare, Square, 
  Save, Loader2, Building2, Briefcase, Check, AlertCircle 
} from 'lucide-react';
import { Employee, RecordType, TimeRecord, AppSetting } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface BulkOccurrenceProps {
  employees: Employee[];
  currentUser: Employee;
  onRecordsAdded: () => void;
  companyList: AppSetting[];
  teamList: AppSetting[];
}

const BULK_TYPES = [
  { label: 'BH Positivo (Crédito)', type: RecordType.CREDIT },
  { label: 'BH Negativo (Débito)', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto (Manual)', type: RecordType.NEUTRAL },
];

const BulkOccurrence: React.FC<BulkOccurrenceProps> = ({ 
  employees, 
  currentUser, 
  onRecordsAdded,
  companyList,
  teamList
}) => {
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');
  const [selectedUserIds, setSelectedUserIds] = useState<Set<string>>(new Set());

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [occurrenceLabel, setOccurrenceLabel] = useState(BULK_TYPES[0].label);
  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);
  const [observation, setObservation] = useState('');

  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => {
      const matchCompany = selectedCompany ? e.company === selectedCompany : true;
      const matchTeam = selectedTeam ? e.team === selectedTeam : true;
      return matchCompany && matchTeam && e.active;
    });
  }, [employees, selectedCompany, selectedTeam]);

  const handleSelectAll = () => {
    if (selectedUserIds.size === filteredEmployees.length) {
      setSelectedUserIds(new Set()); 
    } else {
      setSelectedUserIds(new Set(filteredEmployees.map(e => e.id))); 
    }
  };

  const handleToggleUser = (id: string) => {
    const newSet = new Set(selectedUserIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedUserIds(newSet);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUserIds.size === 0) {
      alert("Selecione pelo menos um colaborador.");
      return;
    }
    if (!observation) {
      alert("A observação é obrigatória para lançamentos em massa.");
      return;
    }

    setLoading(true);

    try {
      const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
      const recordType = typeObj ? typeObj.type : RecordType.NEUTRAL;
      const batchId = uuidv4();

      const recordsToSave: TimeRecord[] = Array.from(selectedUserIds).map(userId => {
        const emp = employees.find(e => e.id === userId);
        return {
          id: uuidv4(),
          batchId: batchId,
          employeeId: userId,
          employeeName: emp?.name || 'Desconhecido',
          date: date,
          hours: Number(hours),
          minutes: Number(minutes),
          startTime: '', 
          endTime: '',   
          type: recordType,
          occurrenceType: occurrenceLabel,
          reason: observation,
          createdAt: new Date().toISOString(),
          createdBy: currentUser.id,
        };
      });

      const result = await firebaseService.saveBulkOccurrences(recordsToSave);

      if (result.success) {
        setSuccessMsg(`Lançamento concluído com sucesso para ${result.count} colaboradores!`);
        onRecordsAdded();

        setSelectedUserIds(new Set());
        setObservation('');
        setHours(0);
        setMinutes(0);

        setTimeout(() => setSuccessMsg(null), 5000);
      }
    } catch (error) {
      console.error(error);
      alert("Erro ao processar lançamento em massa.");
    } finally {
      setLoading(false);
    }
  };

  const getSelectedTypeImpact = () => {
    const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
    if (!typeObj) return null;
    if (typeObj.type === RecordType.CREDIT) return <span className="text-emerald-600 font-medium text-xs ml-2">(Adiciona Horas)</span>;
    if (typeObj.type === RecordType.DEBIT) return <span className="text-red-600 font-medium text-xs ml-2">(Desconta Horas)</span>;
    return <span className="text-slate-500 font-medium text-xs ml-2">(Apenas Histórico)</span>;
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">

      {successMsg && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-md w-full mx-4">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMsg}</p>
          </div>
        </div>
      )}

      <div className="flex items-center gap-3">
        <div className="p-3 bg-indigo-100 text-indigo-700 rounded-xl">
          <Users size={28} />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Lançamento em Massa (RH)</h2>
          <p className="text-slate-500">Aplique ocorrências para múltiplos colaboradores de uma só vez.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col h-[600px]">

          <div className="p-4 border-b border-slate-200 space-y-4 bg-slate-50/50 rounded-t-2xl">
            <div className="flex gap-4">
              <div className="flex-1 relative">
                 <Building2 className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedCompany} 
                   onChange={e => setSelectedCompany(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-indigo-500 focus:border-indigo-500 transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todas as Empresas</option>
                   {companyList.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                 </select>
              </div>
              <div className="flex-1 relative">
                 <Briefcase className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedTeam} 
                   onChange={e => setSelectedTeam(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-indigo-500 focus:border-indigo-500 transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todos os Setores</option>
                   {teamList.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                 </select>
              </div>
            </div>

            <div className="flex justify-between items-center pt-2">
              <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                {filteredEmployees.length} Colaboradores
              </span>
              <button 
                onClick={handleSelectAll}
                className="text-sm text-indigo-600 font-medium hover:text-indigo-800 flex items-center gap-1 transition-colors"
              >
                {selectedUserIds.size === filteredEmployees.length && filteredEmployees.length > 0 ? (
                  <><CheckSquare size={16}/> Desmarcar Todos</>
                ) : (
                  <><Square size={16}/> Selecionar Todos</>
                )}
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
            {filteredEmployees.length > 0 ? (
              <div className="space-y-1">
                {filteredEmployees.map(emp => {
                  const isSelected = selectedUserIds.has(emp.id);
                  return (
                    <div 
                      key={emp.id}
                      onClick={() => handleToggleUser(emp.id)}
                      className={`flex items-center p-3 rounded-xl cursor-pointer transition-all ${isSelected ? 'bg-indigo-50 border border-indigo-200' : 'hover:bg-slate-50 border border-transparent'}`}
                    >
                      <div className={`mr-4 transition-colors ${isSelected ? 'text-indigo-600' : 'text-slate-300'}`}>
                        {isSelected ? <CheckSquare size={20} /> : <Square size={20} />}
                      </div>
                      <div>
                        <p className={`text-sm font-medium ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{emp.name}</p>
                        <p className="text-xs text-slate-500">{emp.company} - {emp.team}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Nenhum colaborador encontrado com os filtros atuais.
              </div>
            )}
          </div>

          <div className="p-3 bg-slate-50 border-t border-slate-200 text-center text-xs text-slate-500 rounded-b-2xl">
             {selectedUserIds.size} selecionados
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-lg border border-slate-200 p-6 h-fit sticky top-6">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
             <Filter className="mr-2 text-indigo-600" size={20}/>
             Detalhes do Lançamento
          </h3>

          <form onSubmit={handleSubmit} className="space-y-5">

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Data da Ocorrência</label>
              <div className="relative">
                 <Calendar className="absolute left-3 top-3 text-slate-400 w-4 h-4" />
                 <input 
                   type="date" 
                   required
                   value={date}
                   onChange={e => setDate(e.target.value)}
                   className="block w-full pl-9 px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                 />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Tipo de Ocorrência {getSelectedTypeImpact()}
              </label>
              <select 
                value={occurrenceLabel}
                onChange={e => setOccurrenceLabel(e.target.value)}
                className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 text-sm transition-all shadow-sm"
              >
                {BULK_TYPES.map(t => <option key={t.label} value={t.label}>{t.label}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Impacto (Opcional)</label>
              <div className="grid grid-cols-2 gap-3">
                 <div>
                    <input 
                      type="number" 
                      min="0" 
                      value={hours}
                      onChange={e => setHours(Number(e.target.value))}
                      placeholder="0"
                      className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                    />
                    <span className="text-[10px] text-slate-400 mt-1 block text-center uppercase tracking-wide">Horas</span>
                 </div>
                 <div>
                    <input 
                      type="number" 
                      min="0" max="59"
                      value={minutes}
                      onChange={e => setMinutes(Number(e.target.value))}
                      placeholder="0"
                      className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                    />
                     <span className="text-[10px] text-slate-400 mt-1 block text-center uppercase tracking-wide">Minutos</span>
                 </div>
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Observação Coletiva</label>
              <textarea 
                required
                rows={3}
                value={observation}
                onChange={e => setObservation(e.target.value)}
                placeholder="Justificativa para o lançamento em lote..."
                className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all resize-none shadow-sm"
              />
            </div>

            <div className="pt-4">
              <button
                type="submit"
                disabled={loading || selectedUserIds.size === 0}
                className={`w-full flex justify-center py-3.5 px-4 border border-transparent rounded-xl shadow-lg text-sm font-bold transition-all duration-300 ${
                  loading || selectedUserIds.size === 0
                    ? 'bg-slate-300 text-slate-500 cursor-not-allowed shadow-none' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:-translate-y-0.5 shadow-md'
                }`}
              >
                {loading ? (
                  <span className="flex items-center">
                    <Loader2 className="animate-spin -ml-1 mr-2 h-5 w-5" />
                    Processando...
                  </span>
                ) : (
                  <span className="flex items-center">
                    <Save className="mr-2" size={18} />
                    {selectedUserIds.size > 0 ? `Lançar para ${selectedUserIds.size} colaboradores` : 'Selecione Colaboradores'}
                  </span>
                )}
              </button>
            </div>
          </form>
        </div>

      </div>
    </div>
  );
};

