import React, { useState, useEffect } from 'react';
import { AlertCircle, Lock, Mail, ShieldCheck, CheckCircle } from 'lucide-react';
import { firebaseService } from '../services/firebaseService';
import { Employee } from '../types';

interface LoginProps {
  onLoginSuccess: (user: Employee) => void;
}

const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [resetLoading, setResetLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // Limpa mensagens automaticamente após 5 segundos
  useEffect(() => {
    if (error || successMsg) {
      const timer = setTimeout(() => {
        setError('');
        setSuccessMsg('');
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [error, successMsg]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }

    setLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      const result = await firebaseService.login(email, password);

      if (result.success && result.user) {
        onLoginSuccess(result.user);
      } else {
        setError(result.message || 'Credenciais inválidas.');
      }
    } catch (err: any) {
      setError('Erro inesperado. Verifique o console.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!email) {
      setError('Por favor, digite seu e-mail no campo acima para recuperar a senha.');
      return;
    }

    setResetLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      const result = await firebaseService.sendPasswordReset(email);
      if (result.success) {
        setSuccessMsg(result.message);
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Erro ao enviar solicitação.');
    } finally {
      setResetLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200">
        <div className="bg-slate-900 p-8 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
          <h1 className="text-3xl font-bold text-white tracking-wider uppercase relative z-10">Hurafy</h1>
          <p className="text-indigo-300 mt-2 text-sm relative z-10 font-medium">Banco de Horas Digital</p>
        </div>

        <div className="p-8 space-y-6">
          <div className="text-center">
            <div className="mx-auto w-12 h-12 bg-slate-100 text-slate-700 rounded-full flex items-center justify-center mb-4 border border-slate-200">
               <ShieldCheck size={24} />
            </div>
            <h2 className="text-xl font-semibold text-slate-800">Acesso ao Sistema</h2>
            <p className="text-sm text-slate-500 mt-1">Entre com seu login corporativo</p>
          </div>

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg flex items-center text-sm animate-fade-in">
              <AlertCircle size={16} className="mr-2 shrink-0" />
              {error}
            </div>
          )}

          {successMsg && (
            <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg flex items-center text-sm animate-fade-in">
              <CheckCircle size={16} className="mr-2 shrink-0" />
              {successMsg}
            </div>
          )}

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">E-mail</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Mail className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                  placeholder="seu.email@arcaplast.com.br"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Senha</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Lock className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                  placeholder="••••••••"
                />
              </div>
              <div className="flex justify-end mt-2">
                <button
                  type="button"
                  onClick={handleForgotPassword}
                  disabled={resetLoading || loading}
                  className="text-sm text-slate-400 hover:text-indigo-600 hover:underline transition-colors focus:outline-none"
                >
                  {resetLoading ? 'Enviando solicitação...' : 'Esqueceu sua senha?'}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading || resetLoading}
              className={`w-full flex items-center justify-center py-3.5 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white bg-indigo-600 hover:bg-indigo-700 transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${
                (loading || resetLoading) ? 'opacity-70 cursor-not-allowed' : ''
              }`}
            >
              {loading ? (
                <div className="flex items-center">
                   <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin mr-2"></div>
                   Acessando...
                </div>
              ) : (
                'Entrar'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useEffect } from 'react';
import { 
  Building2, 
  Briefcase, 
  Plus, 
  Trash2, 
  Edit2, 
  Save, 
  X, 
  Loader2, 
  Settings as SettingsIcon,
  RefreshCw,
  Search
} from 'lucide-react';
import { AppSetting, Employee } from '../types';
import { firebaseService } from '../services/firebaseService';

interface SettingsProps {
  companies: AppSetting[];
  teams: AppSetting[];
  employees: Employee[];
  refreshData: () => void;
}

const DEFAULT_COMPANIES = ['Arca Plast', 'Arca Mania', 'Rearca', 'Taex Transportadora'];
const DEFAULT_TEAMS = [
  'Embalagem', 'Engenharia', 'Estoque', 'Excelência Operacional', 'Financeiro', 
  'Gente e Gestão', 'Gestão', 'Gestão da Produção', 'Gestão Estratégica', 
  'Injeção', 'Logística', 'Manutenção', 'Marketing', 'Mercado', 
  'Serviços Gerais', 'Sopro', 'Suprimentos', 'TI'
];

const ManageList = ({ 
  title, 
  subtitle,
  icon: Icon, 
  items, 
  collectionName, 
  refreshData,
  deleteWarning 
}: { 
  title: string; 
  subtitle: string;
  icon: any; 
  items: AppSetting[]; 
  collectionName: 'settings_companies' | 'settings_areas';
  refreshData: () => void;
  deleteWarning?: string;
}) => {
  const [newItemName, setNewItemName] = useState('');
  const [loading, setLoading] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [filter, setFilter] = useState('');

  const filteredItems = items.filter(i => i.name.toLowerCase().includes(filter.toLowerCase()));

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newItemName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.addSettingItem(collectionName, newItemName.trim());
      setNewItemName('');
      refreshData();
    } catch (error) {
      alert("Erro ao adicionar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleEdit = (item: AppSetting) => {
    setEditingId(item.id);
    setEditName(item.name);
  };

  const handleUpdate = async () => {
    if (!editingId || !editName.trim()) return;
    setLoading(true);
    try {
      await firebaseService.updateSettingItem(collectionName, editingId, editName.trim());
      setEditingId(null);
      refreshData();
    } catch (error) {
      alert("Erro ao atualizar item.");
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string) => {
    if (deleteWarning) {
        if (!confirm(deleteWarning)) return;
    } else {
        if (!confirm("Tem certeza que deseja remover este item?")) return;
    }

    setLoading(true);
    try {
      await firebaseService.deleteSettingItem(collectionName, id);
      refreshData();
    } catch (error) {
      alert("Erro ao excluir item.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden flex flex-col h-[600px] transition-all hover:shadow-md">
      {/* SaaS Card Header - Clean Slate/Indigo */}
      <div className="bg-slate-50 px-6 py-4 flex items-center justify-between shrink-0 border-b border-slate-100">
        <div className="flex items-center gap-3">
          <div className="p-2 bg-indigo-50 rounded-lg text-indigo-600">
            <Icon size={20} />
          </div>
          <div>
            <h3 className="text-slate-800 font-bold text-base leading-tight">{title}</h3>
            <p className="text-slate-500 text-xs mt-0.5">{subtitle}</p>
          </div>
        </div>
        <span className="text-xs font-bold bg-slate-200 text-slate-600 px-2.5 py-1 rounded-full">
          {items.length}
        </span>
      </div>

      {/* Search Filter - Discrete */}
      <div className="border-b border-slate-100 p-3 bg-white">
        <div className="relative">
            <Search className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
            <input 
                type="text" 
                placeholder={`Filtrar ${title.toLowerCase()}...`}
                value={filter}
                onChange={e => setFilter(e.target.value)}
                className="w-full pl-9 pr-3 py-2 text-sm border border-slate-200 rounded-lg bg-slate-50 focus:bg-white focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 transition-all text-slate-600 placeholder-slate-400"
            />
        </div>
      </div>

      {/* Compact List Area */}
      <div className="flex-1 overflow-y-auto custom-scrollbar p-0 bg-white">
        {filteredItems.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400 text-sm">
                <p>{filter ? 'Nenhum resultado encontrado.' : 'Nenhum item cadastrado.'}</p>
            </div>
        ) : (
            <ul className="divide-y divide-slate-50">
                {filteredItems.map(item => (
                <li key={item.id} className="group flex items-center justify-between px-5 py-2.5 hover:bg-slate-50 transition-colors">
                    {editingId === item.id ? (
                    <div className="flex flex-1 items-center gap-2 animate-fade-in">
                        <input 
                        autoFocus
                        type="text" 
                        value={editName}
                        onChange={e => setEditName(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleUpdate()}
                        className="flex-1 text-sm border border-indigo-500 rounded px-2 py-1.5 focus:outline-none bg-white text-slate-900 shadow-sm"
                        />
                        <button onClick={handleUpdate} className="p-1.5 bg-indigo-600 text-white hover:bg-indigo-700 rounded shadow-sm transition-colors"><Save size={14}/></button>
                        <button onClick={() => setEditingId(null)} className="p-1.5 text-slate-400 hover:text-slate-600 hover:bg-slate-200 rounded transition-colors"><X size={14}/></button>
                    </div>
                    ) : (
                    <>
                        <span className="text-sm font-medium text-slate-700 truncate select-none">{item.name}</span>
                        <div className="flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity duration-200">
                        <button 
                            onClick={() => handleEdit(item)}
                            className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-md transition-colors" 
                            title="Editar"
                        >
                            <Edit2 size={14} />
                        </button>
                        <button 
                            onClick={() => handleDelete(item.id)}
                            className="p-1.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-md transition-colors" 
                            title="Excluir"
                        >
                            <Trash2 size={14} />
                        </button>
                        </div>
                    </>
                    )}
                </li>
                ))}
            </ul>
        )}
      </div>

      {/* Footer Add Form - Compact & Elegant */}
      <div className="p-4 border-t border-slate-100 bg-slate-50 shrink-0">
        <form onSubmit={handleAdd} className="flex gap-2 items-center">
          <input 
            type="text" 
            placeholder="Adicionar novo..." 
            value={newItemName}
            onChange={e => setNewItemName(e.target.value)}
            disabled={loading}
            className="flex-1 text-sm border border-slate-300 rounded-lg px-3 py-2.5 focus:outline-none focus:border-indigo-500 focus:ring-1 focus:ring-indigo-500 bg-white text-slate-900 shadow-sm transition-shadow"
          />
          <button 
            type="submit" 
            disabled={loading || !newItemName.trim()}
            className="bg-indigo-600 hover:bg-indigo-700 text-white p-2.5 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm hover:shadow-md active:scale-95"
          >
            {loading ? <Loader2 size={18} className="animate-spin" /> : <Plus size={18} strokeWidth={3} />}
          </button>
        </form>
      </div>
    </div>
  );
};

const Settings: React.FC<SettingsProps> = ({ companies, teams, employees, refreshData }) => {
  const [isMigrating, setIsMigrating] = useState(false);

  useEffect(() => {
    const performMigration = async () => {
       // TRAVA DE SEGURANÇA IMEDIATA: Se já existir QUALQUER dado, aborta para evitar duplicidade.
       if (companies.length > 0 || teams.length > 0) {
           return;
       }

       setIsMigrating(true);
       console.log("🔄 Iniciando Auto-Hidratação de configurações...");

       try {
          const uniqueCompanies = new Set(DEFAULT_COMPANIES);
          const uniqueTeams = new Set(DEFAULT_TEAMS);

          if (employees.length > 0) {
             employees.forEach(emp => {
                if (emp.company && emp.company.trim()) uniqueCompanies.add(emp.company.trim());
                if (emp.team && emp.team.trim()) uniqueTeams.add(emp.team.trim());
             });
          }

          const promises = [];

          for (const comp of uniqueCompanies) {
             if (comp) promises.push(firebaseService.addSettingItem('settings_companies', comp));
          }

          for (const team of uniqueTeams) {
             if (team) promises.push(firebaseService.addSettingItem('settings_areas', team));
          }

          if (promises.length > 0) {
            await Promise.all(promises);
            refreshData(); 
          }

       } catch (error) {
          console.error("Erro na migração automática:", error);
       } finally {
          setIsMigrating(false);
       }
    };

    performMigration();
  }, [companies.length, teams.length, employees]); 

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* Page Header */}
