import React, { useState, useEffect } from 'react';
import { AlertCircle, Lock, Mail, ShieldCheck, CheckCircle } from 'lucide-react';
import { firebaseService } from '../services/firebaseService';
import { Employee } from '../types';

interface LoginProps {
  onLoginSuccess: (user: Employee) => void;
}

const Login: React.FC<LoginProps> = ({ onLoginSuccess }) => {
  const [loading, setLoading] = useState(false);
  const [resetLoading, setResetLoading] = useState(false);
  const [error, setError] = useState('');
  const [successMsg, setSuccessMsg] = useState('');

  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');

  // Limpa mensagens automaticamente após 5 segundos
  useEffect(() => {
    if (error || successMsg) {
      const timer = setTimeout(() => {
        setError('');
        setSuccessMsg('');
      }, 5000);
      return () => clearTimeout(timer);
    }
  }, [error, successMsg]);

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!email || !password) {
      setError('Preencha todos os campos.');
      return;
    }

    setLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      const result = await firebaseService.login(email, password);

      if (result.success && result.user) {
        onLoginSuccess(result.user);
      } else {
        // Se a mensagem vier do serviço, usa ela. Se for erro genérico, exibe mensagem amigável.
        setError(result.message || 'Erro de conexão: Não foi possível realizar o login. Verifique sua internet.');
      }
    } catch (err: any) {
      setError('Erro de conexão: Verifique sua internet e tente novamente.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!email) {
      setError('Por favor, digite seu e-mail no campo acima para recuperar a senha.');
      return;
    }

    setResetLoading(true);
    setError('');
    setSuccessMsg('');

    try {
      const result = await firebaseService.sendPasswordReset(email);
      if (result.success) {
        setSuccessMsg(result.message);
      } else {
        setError(result.message);
      }
    } catch (err) {
      setError('Erro de conexão: Não foi possível enviar a solicitação. Verifique sua internet.');
    } finally {
      setResetLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-100 flex items-center justify-center p-4">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl overflow-hidden border border-slate-200">
        <div className="bg-slate-900 p-8 text-center relative overflow-hidden">
          <div className="absolute top-0 left-0 w-full h-full opacity-10 bg-[url('https://www.transparenttextures.com/patterns/cubes.png')]"></div>
          <h1 className="text-3xl font-bold text-white tracking-wider uppercase relative z-10">Hurafy</h1>
          <p className="text-indigo-300 mt-2 text-sm relative z-10 font-medium">Banco de Horas Digital</p>
        </div>

        <div className="p-8 space-y-6">
          <div className="text-center">
            <div className="mx-auto w-12 h-12 bg-slate-100 text-slate-700 rounded-full flex items-center justify-center mb-4 border border-slate-200">
               <ShieldCheck size={24} />
            </div>
            <h2 className="text-xl font-semibold text-slate-800">Acesso ao Sistema</h2>
            <p className="text-sm text-slate-500 mt-1">Entre com seu login corporativo</p>
          </div>

          {error && (
            <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-lg flex items-center text-sm animate-fade-in">
              <AlertCircle size={16} className="mr-2 shrink-0" />
              {error}
            </div>
          )}

          {successMsg && (
            <div className="bg-green-50 border border-green-200 text-green-700 px-4 py-3 rounded-lg flex items-center text-sm animate-fade-in">
              <CheckCircle size={16} className="mr-2 shrink-0" />
              {successMsg}
            </div>
          )}

          <form onSubmit={handleLogin} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">E-mail</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Mail className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                  placeholder="seu.email@arcaplast.com.br"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-1">Senha</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Lock className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="password"
                  required
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-xl leading-5 bg-white placeholder-slate-400 text-slate-900 focus:outline-none focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
                  placeholder="••••••••"
                />
              </div>
              <div className="flex justify-end mt-2">
                <button
                  type="button"
                  onClick={handleForgotPassword}
                  disabled={resetLoading || loading}
                  className="text-sm text-slate-400 hover:text-indigo-600 hover:underline transition-colors focus:outline-none"
                >
                  {resetLoading ? 'Enviando solicitação...' : 'Esqueceu sua senha?'}
                </button>
              </div>
            </div>

            <button
              type="submit"
              disabled={loading || resetLoading}
              className={`w-full flex items-center justify-center py-3.5 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white bg-indigo-600 hover:bg-indigo-700 transition-all focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 ${
                (loading || resetLoading) ? 'opacity-70 cursor-not-allowed' : ''
              }`}
            >
              {loading ? (
                <div className="flex items-center">
                   <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin mr-2"></div>
                   Acessando...
                </div>
              ) : (
                'Entrar'
              )}
            </button>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Login;

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Loader2, ShieldAlert } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto', type: RecordType.NEUTRAL },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [absenceTime, setAbsenceTime] = useState('');

  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const isAbsenceAdjustment = ['Ausência de Batida', 'Ajuste de Ponto'].includes(occurrenceType);
  // Define se o registro é meramente informativo/neutro (sem impacto de cálculo de horas obrigatório)
  const isInformational = mappedRecordType === RecordType.NEUTRAL || isAbsenceAdjustment;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (currentUser.role === Role.EMPLOYEE) {
       setSelectedEmployee(currentUser.id);
       setSearchTerm(currentUser.name);
    }
  }, [currentUser]);

  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
    setStartTime('');
    setEndTime('');
    setAbsenceTime('');
    setCalculatedDuration({ hours: 0, minutes: 0 });
    setIsTimeValid(true);
  }, [occurrenceType]);

  // --- LÓGICA DE VALIDAÇÃO DE TEMPO ---
  useEffect(() => {
    // 1. Caso especial: Ausência de Batida
    if (isAbsenceAdjustment) {
        setCalculatedDuration({ hours: 0, minutes: 0 });
        if (absenceTime) {
            setIsTimeValid(true);
            return;
        }
        // Se estiver usando intervalo em vez de horário único (ex: Ajuste de Ponto)
        if (startTime && endTime) {
             const [startH, startM] = startTime.split(':').map(Number);
             const [endH, endM] = endTime.split(':').map(Number);
             const startTotalMins = startH * 60 + startM;
             const endTotalMins = endH * 60 + endM;

             // Permite tempos iguais para ajustes neutros
             if (startTotalMins === endTotalMins) {
                 setIsTimeValid(true);
                 return;
             }
             if (endTotalMins < startTotalMins) {
                 setIsTimeValid(false);
                 return;
             }
             setIsTimeValid(true);
             return;
        }
        // Se for Ausência mas não tiver horário preenchido ainda, marcamos como inválido se for obrigatório
        // Mas deixamos true inicialmente para não mostrar erro visual antes de digitar
        setIsTimeValid(true); 
        return;
    }

    // 2. Casos normais (Crédito/Débito/Neutro genérico)
    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true); // Vazio é considerado "válido" até tentar enviar, para não ficar vermelho
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);
    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins < startTotalMins) {
      // Fim menor que início = ERRO
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else if (endTotalMins === startTotalMins) {
      // Fim igual a início
      // Se for informativo (Neutro), permitimos (0h). Se for Crédito/Débito, exigimos duração.
      if (mappedRecordType === RecordType.NEUTRAL) {
         setIsTimeValid(true);
         setCalculatedDuration({ hours: 0, minutes: 0 });
      } else {
         setIsTimeValid(false); // Crédito/Débito precisa de tempo > 0
         setCalculatedDuration({ hours: 0, minutes: 0 });
      }
    } else {
      // Cálculo normal de diferença
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime, absenceTime, isAbsenceAdjustment, mappedRecordType]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedEmployee || !date || !reason) {
        alert("Preencha todos os campos obrigatórios.");
        return;
    }

    // Validação específica por tipo
    if (isAbsenceAdjustment) {
        // Validação para Ausência/Ajuste
        const hasSpecificTime = !!absenceTime;
        const hasRange = !!(startTime && endTime);

        if (occurrenceType === 'Ausência de Batida' && !hasSpecificTime) {
            alert("Informe o horário do esquecimento.");
            return;
        }

        if (hasRange && !isTimeValid) {
           alert("Horário inválido.");
           return;
        }

        if (reason.trim().length < 3) {
            alert("A justificativa é obrigatória.");
            return;
        }
    } else {
        // Validação para Crédito/Débito (precisa de horários e duração > 0)
        // Se for NEUTRO que não é ausência, permitimos duração 0 se estiver válido (início == fim)
        if (mappedRecordType !== RecordType.NEUTRAL) {
             if (!startTime || !endTime || !isTimeValid) {
                 alert("Verifique os horários de início e fim.");
                 return;
             }
             if (calculatedDuration.hours === 0 && calculatedDuration.minutes === 0) {
                 alert("A duração deve ser maior que zero para lançamentos de Crédito ou Débito.");
                 return;
             }
        } else {
             // Para neutros, apenas verificamos se os horários não são inválidos (fim < inicio)
             if ((startTime && endTime) && !isTimeValid) {
                 alert("Horário inválido.");
                 return;
             }
        }
    }

    setLoading(true);

    const employee = employees.find(e => e.id === selectedEmployee);
    const finalStartTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : (startTime || '');
    const finalEndTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : (endTime || '');

    const newRecord: TimeRecord = {
      id: uuidv4(),
      employeeId: selectedEmployee,
      employeeName: employee?.name || 'Desconhecido',
      date, 
      hours: isAbsenceAdjustment ? 0 : calculatedDuration.hours,
      minutes: isAbsenceAdjustment ? 0 : calculatedDuration.minutes,
      startTime: finalStartTime,
      endTime: finalEndTime,
      type: isAbsenceAdjustment ? RecordType.NEUTRAL : mappedRecordType,
      occurrenceType,
      reason,
      createdAt: new Date().toISOString(),
      createdBy: currentUser.id,
      isAdjustment: isAbsenceAdjustment ? true : undefined,
      status: isAbsenceAdjustment ? 'regularized' : undefined
    };

    console.log('Enviando registro:', newRecord);

    try {
      await firebaseService.saveTimeRecord(newRecord);
      setSuccess(true);
      onRecordAdded();

      // Limpar form
      if (currentUser.role !== Role.EMPLOYEE) {
         setSelectedEmployee('');
         setSearchTerm('');
      }
      setStartTime('');
      setEndTime('');
      setAbsenceTime('');
      setReason('');
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setOccurrenceType('BH Positivo');

      // Fecha o modal de sucesso após 3s
      setTimeout(() => setSuccess(false), 3000);
    } catch (error) {
      console.error("Erro ao salvar batida:", error);
      alert("Falha na comunicação com o servidor. Tente novamente.");
    } finally {
      setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in">

      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">
              {isAbsenceAdjustment 
                ? 'Ajuste registrado. Saldo inalterado.' 
                : 'Registro salvo no banco de dados.'}
            </p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Os dados serão sincronizados com o servidor.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  disabled={currentUser.role === Role.EMPLOYEE}
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-indigo-600 ring-1 ring-indigo-600 bg-indigo-50' : ''} ${currentUser.role === Role.EMPLOYEE ? 'bg-slate-100 cursor-not-allowed text-slate-500' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-indigo-600 bg-indigo-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {isDropdownOpen && currentUser.role !== Role.EMPLOYEE && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
