import React, { Component, ErrorInfo, ReactNode } from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

// Error Boundary para capturar erros de renderização e evitar tela branca total
class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {

  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { 
      hasError: false, 
      error: null, 
      errorInfo: null 
    };
  }

  static getDerivedStateFromError(error: Error): Partial<ErrorBoundaryState> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error in application:", error, errorInfo);
    this.setState({ errorInfo });
  }

  render() {
    if (this.state.hasError) {
      return (
        <div style={{ padding: '2rem', fontFamily: 'sans-serif', maxWidth: '800px', margin: '0 auto' }}>
          <h1 style={{ color: '#ef4444' }}>Ops! Algo deu errado.</h1>
          <p>A aplicação encontrou um erro crítico e não pôde ser carregada.</p>

          <div style={{ marginTop: '1rem', padding: '1rem', backgroundColor: '#f1f5f9', borderRadius: '0.5rem', overflow: 'auto' }}>
            <p style={{ fontWeight: 'bold', marginBottom: '0.5rem' }}>Erro:</p>
            <code style={{ color: '#b91c1c' }}>{this.state.error?.toString()}</code>
          </div>

          <div style={{ marginTop: '1rem' }}>
             <p>Verifique o console do navegador (F12) para mais detalhes.</p>
             <button 
               onClick={() => window.location.reload()}
               style={{ marginTop: '1rem', padding: '0.5rem 1rem', backgroundColor: '#4f46e5', color: 'white', border: 'none', borderRadius: '0.25rem', cursor: 'pointer' }}
             >
               Recarregar Página
             </button>
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <ErrorBoundary>
      <App />
    </ErrorBoundary>
  </React.StrictMode>
);

import React, { useState, useMemo, useEffect } from 'react';
import { 
  Users, Filter, Calendar, CheckSquare, Square, 
  Save, Loader2, Building2, Briefcase, Check, AlertCircle 
} from 'lucide-react';
import { Employee, RecordType, TimeRecord, AppSetting } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface BulkOccurrenceProps {
  employees: Employee[];
  currentUser: Employee;
  onRecordsAdded: () => void;
  companyList: AppSetting[];
  teamList: AppSetting[];
}

const BULK_TYPES = [
  { label: 'BH Positivo (Crédito)', type: RecordType.CREDIT },
  { label: 'BH Negativo (Débito)', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto (Manual)', type: RecordType.NEUTRAL },
];

const BulkOccurrence: React.FC<BulkOccurrenceProps> = ({ 
  employees, 
  currentUser, 
  onRecordsAdded,
  companyList,
  teamList
}) => {
  const [selectedCompany, setSelectedCompany] = useState<string>('');
  const [selectedTeam, setSelectedTeam] = useState<string>('');
  const [selectedUserIds, setSelectedUserIds] = useState<Set<string>>(new Set());

  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);
  const [occurrenceLabel, setOccurrenceLabel] = useState(BULK_TYPES[0].label);
  const [hours, setHours] = useState<number>(0);
  const [minutes, setMinutes] = useState<number>(0);
  const [observation, setObservation] = useState('');

  const [loading, setLoading] = useState(false);
  const [successMsg, setSuccessMsg] = useState<string | null>(null);

  const filteredEmployees = useMemo(() => {
    return employees.filter(e => {
      const matchCompany = selectedCompany ? e.company === selectedCompany : true;
      const matchTeam = selectedTeam ? e.team === selectedTeam : true;
      return matchCompany && matchTeam && e.active;
    });
  }, [employees, selectedCompany, selectedTeam]);

  const handleSelectAll = () => {
    if (selectedUserIds.size === filteredEmployees.length) {
      setSelectedUserIds(new Set()); 
    } else {
      setSelectedUserIds(new Set(filteredEmployees.map(e => e.id))); 
    }
  };

  const handleToggleUser = (id: string) => {
    const newSet = new Set(selectedUserIds);
    if (newSet.has(id)) {
      newSet.delete(id);
    } else {
      newSet.add(id);
    }
    setSelectedUserIds(newSet);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (selectedUserIds.size === 0) {
      alert("Selecione pelo menos um colaborador.");
      return;
    }
    if (!observation) {
      alert("A observação é obrigatória para lançamentos em massa.");
      return;
    }

    setLoading(true);

    try {
      const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
      const recordType = typeObj ? typeObj.type : RecordType.NEUTRAL;
      const batchId = uuidv4();

      const recordsToSave: TimeRecord[] = Array.from(selectedUserIds).map((userId: string) => {
        const emp = employees.find(e => e.id === userId);
        return {
          id: uuidv4(),
          batchId: batchId,
          employeeId: userId,
          employeeName: emp?.name || 'Desconhecido',
          date: date,
          hours: Number(hours),
          minutes: Number(minutes),
          startTime: '', 
          endTime: '',   
          type: recordType,
          occurrenceType: occurrenceLabel,
          reason: observation,
          createdAt: new Date().toISOString(),
          createdBy: currentUser.id,
        };
      });

      const result = await firebaseService.saveBulkOccurrences(recordsToSave);

      if (result.success) {
        setSuccessMsg(`Lançamento concluído com sucesso para ${result.count} colaboradores!`);
        onRecordsAdded();

        setSelectedUserIds(new Set());
        setObservation('');
        setHours(0);
        setMinutes(0);

        setTimeout(() => setSuccessMsg(null), 5000);
      } else {
          throw new Error("Falha na gravação em massa.");
      }
    } catch (error) {
      console.error(error);
      alert("Erro de conexão: Não foi possível salvar os dados. Verifique sua internet.");
    } finally {
      setLoading(false);
    }
  };

  const getSelectedTypeImpact = () => {
    const typeObj = BULK_TYPES.find(t => t.label === occurrenceLabel);
    if (!typeObj) return null;
    if (typeObj.type === RecordType.CREDIT) return <span className="text-emerald-600 font-medium text-xs ml-2">(Adiciona Horas)</span>;
    if (typeObj.type === RecordType.DEBIT) return <span className="text-red-600 font-medium text-xs ml-2">(Desconta Horas)</span>;
    return <span className="text-slate-500 font-medium text-xs ml-2">(Apenas Histórico)</span>;
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">

      {successMsg && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-md w-full mx-4">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">{successMsg}</p>
          </div>
        </div>
      )}

      <div className="flex items-center gap-3">
        <div className="p-3 bg-indigo-100 text-indigo-700 rounded-xl">
          <Users size={28} />
        </div>
        <div>
          <h2 className="text-2xl font-bold text-slate-800">Lançamento em Massa (RH)</h2>
          <p className="text-slate-500">Aplique ocorrências para múltiplos colaboradores de uma só vez.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        <div className="lg:col-span-2 bg-white rounded-2xl shadow-sm border border-slate-200 flex flex-col h-[600px]">

          <div className="p-4 border-b border-slate-200 space-y-4 bg-slate-50/50 rounded-t-2xl">
            <div className="flex gap-4">
              <div className="flex-1 relative">
                 <Building2 className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedCompany} 
                   onChange={e => setSelectedCompany(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-indigo-500 focus:border-indigo-500 transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todas as Empresas</option>
                   {companyList.map(c => <option key={c.id} value={c.name}>{c.name}</option>)}
                 </select>
              </div>
              <div className="flex-1 relative">
                 <Briefcase className="absolute left-3 top-2.5 text-slate-400 w-4 h-4" />
                 <select 
                   value={selectedTeam} 
                   onChange={e => setSelectedTeam(e.target.value)}
                   className="w-full pl-9 pr-3 py-2 border border-slate-300 rounded-xl text-sm focus:ring-indigo-500 focus:border-indigo-500 transition-shadow bg-white text-slate-700"
                 >
                   <option value="">Todos os Setores</option>
                   {teamList.map(t => <option key={t.id} value={t.name}>{t.name}</option>)}
                 </select>
              </div>
            </div>

            <div className="flex justify-between items-center pt-2">
              <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                {filteredEmployees.length} Colaboradores
              </span>
              <button 
                onClick={handleSelectAll}
                className="text-sm text-indigo-600 font-medium hover:text-indigo-800 flex items-center gap-1 transition-colors"
              >
                {selectedUserIds.size === filteredEmployees.length && filteredEmployees.length > 0 ? (
                  <><CheckSquare size={16}/> Desmarcar Todos</>
                ) : (
                  <><Square size={16}/> Selecionar Todos</>
                )}
              </button>
            </div>
          </div>

          <div className="flex-1 overflow-y-auto custom-scrollbar p-2">
            {filteredEmployees.length > 0 ? (
              <div className="space-y-1">
                {filteredEmployees.map(emp => {
                  const isSelected = selectedUserIds.has(emp.id);
                  return (
                    <div 
                      key={emp.id}
                      onClick={() => handleToggleUser(emp.id)}
                      className={`flex items-center p-3 rounded-xl cursor-pointer transition-all ${isSelected ? 'bg-indigo-50 border border-indigo-200' : 'hover:bg-slate-50 border border-transparent'}`}
                    >
                      <div className={`mr-4 transition-colors ${isSelected ? 'text-indigo-600' : 'text-slate-300'}`}>
                        {isSelected ? <CheckSquare size={20} /> : <Square size={20} />}
                      </div>
                      <div>
                        <p className={`text-sm font-medium ${isSelected ? 'text-indigo-900' : 'text-slate-700'}`}>{emp.name}</p>
                        <p className="text-xs text-slate-500">{emp.company} - {emp.team}</p>
                      </div>
                    </div>
                  );
                })}
              </div>
            ) : (
              <div className="h-full flex items-center justify-center text-slate-400 text-sm">
                Nenhum colaborador encontrado com os filtros atuais.
              </div>
            )}
          </div>

          <div className="p-3 bg-slate-50 border-t border-slate-200 text-center text-xs text-slate-500 rounded-b-2xl">
             {selectedUserIds.size} selecionados
          </div>
        </div>

        <div className="bg-white rounded-2xl shadow-lg border border-slate-200 p-6 h-fit sticky top-6">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
             <Filter className="mr-2 text-indigo-600" size={20}/>
             Detalhes do Lançamento
          </h3>

          <form onSubmit={handleSubmit} className="space-y-5">

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Data da Ocorrência</label>
              <div className="relative">
                 <Calendar className="absolute left-3 top-3 text-slate-400 w-4 h-4" />
                 <input 
                   type="date" 
                   required
                   value={date}
                   onChange={e => setDate(e.target.value)}
                   className="block w-full pl-9 px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                 />
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">
                  Tipo de Ocorrência {getSelectedTypeImpact()}
              </label>
              <select 
                value={occurrenceLabel}
                onChange={e => setOccurrenceLabel(e.target.value)}
                className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 text-sm transition-all shadow-sm"
              >
                {BULK_TYPES.map(t => <option key={t.label} value={t.label}>{t.label}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Impacto (Opcional)</label>
              <div className="grid grid-cols-2 gap-3">
                 <div>
                    <input 
                      type="number" 
                      min="0" 
                      value={hours}
                      onChange={e => setHours(Number(e.target.value))}
                      placeholder="0"
                      className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                    />
                    <span className="text-[10px] text-slate-400 mt-1 block text-center uppercase tracking-wide">Horas</span>
                 </div>
                 <div>
                    <input 
                      type="number" 
                      min="0" max="59"
                      value={minutes}
                      onChange={e => setMinutes(Number(e.target.value))}
                      placeholder="0"
                      className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all shadow-sm"
                    />
                     <span className="text-[10px] text-slate-400 mt-1 block text-center uppercase tracking-wide">Minutos</span>
                 </div>
              </div>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-600 uppercase tracking-wide mb-1.5">Observação Coletiva</label>
              <textarea 
                required
                rows={3}
                value={observation}
                onChange={e => setObservation(e.target.value)}
                placeholder="Justificativa para o lançamento em lote..."
                className="block w-full px-3 py-2.5 border border-slate-200 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-transparent bg-white text-slate-900 placeholder-slate-400 text-sm transition-all resize-none shadow-sm"
              />
            </div>

            <div className="pt-4">
              <button
                type="submit"
                disabled={loading || selectedUserIds.size === 0}
                className={`w-full flex justify-center py-3.5 px-4 border border-transparent rounded-xl shadow-lg text-sm font-bold transition-all duration-300 ${
                  loading || selectedUserIds.size === 0
                    ? 'bg-slate-300 text-slate-500 cursor-not-allowed shadow-none' 
                    : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:-translate-y-0.5 shadow-md'
                }`}
              >
                {loading ? (
                  <span className="flex items-center">
                    <Loader2 className="animate-spin -ml-1 mr-2 h-5 w-5" />
                    Processando...
                  </span>
                ) : (
                  <span className="flex items-center">
                    <Save className="mr-2" size={18} />
                    {selectedUserIds.size > 0 ? `Lançar para ${selectedUserIds.size} colaboradores` : 'Selecione Colaboradores'}
                  </span>
                )}
              </button>
            </div>
          </form>
        </div>

      </div>
    </div>
  );
};

export default BulkOccurrence;

import React, { useState, useRef, useEffect } from 'react';
import { Save, AlertTriangle, Calendar, Clock, User, ChevronDown, Check, Calculator, Info, Loader2, ShieldAlert } from 'lucide-react';
import { Employee, RecordType, TimeRecord, Role } from '../types';
import { v4 as uuidv4 } from 'uuid';
import { firebaseService } from '../services/firebaseService';

interface TimeEntryFormProps {
  currentUser: Employee;
  employees: Employee[];
  onRecordAdded: () => void;
}

const OCCURRENCE_OPTIONS = [
  { label: 'BH Positivo', type: RecordType.CREDIT },
  { label: 'BH Negativo', type: RecordType.DEBIT },
  { label: 'Ajuste de Ponto', type: RecordType.NEUTRAL },
  { label: 'Compensação de horas positivas', type: RecordType.DEBIT },
  { label: 'Falta do dia inteiro', type: RecordType.DEBIT },
  { label: 'Ausência de Batida', type: RecordType.NEUTRAL },
  { label: 'Pagamento de horas', type: RecordType.DEBIT },
  { label: 'Exame periódico', type: RecordType.NEUTRAL },
  { label: 'Atrasos e saídas antecipadas (desconto em folha)', type: RecordType.NEUTRAL },
  { label: 'Liberação por atestado médico', type: RecordType.NEUTRAL },
];

const TimeEntryForm: React.FC<TimeEntryFormProps> = ({ currentUser, employees, onRecordAdded }) => {
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);

  // Form State
  const [selectedEmployee, setSelectedEmployee] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  // Time Calculation State
  const [startTime, setStartTime] = useState('');
  const [endTime, setEndTime] = useState('');
  const [absenceTime, setAbsenceTime] = useState('');

  const [calculatedDuration, setCalculatedDuration] = useState({ hours: 0, minutes: 0 });
  const [isTimeValid, setIsTimeValid] = useState(true);

  const [occurrenceType, setOccurrenceType] = useState<string>('BH Positivo');
  const [mappedRecordType, setMappedRecordType] = useState<RecordType>(RecordType.CREDIT);
  const [reason, setReason] = useState('');

  // Search/Autocomplete State
  const [searchTerm, setSearchTerm] = useState('');
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const isAbsenceAdjustment = ['Ausência de Batida', 'Ajuste de Ponto'].includes(occurrenceType);
  const isInformational = mappedRecordType === RecordType.NEUTRAL || isAbsenceAdjustment;

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  useEffect(() => {
    if (currentUser.role === Role.EMPLOYEE) {
       setSelectedEmployee(currentUser.id);
       setSearchTerm(currentUser.name);
    }
  }, [currentUser]);

  useEffect(() => {
    const option = OCCURRENCE_OPTIONS.find(o => o.label === occurrenceType);
    if (option) {
      setMappedRecordType(option.type);
    }
    setStartTime('');
    setEndTime('');
    setAbsenceTime('');
    setCalculatedDuration({ hours: 0, minutes: 0 });
    setIsTimeValid(true);
  }, [occurrenceType]);

  // --- LÓGICA DE VALIDAÇÃO DE TEMPO ---
  useEffect(() => {
    // 1. Caso especial: Ausência de Batida
    if (isAbsenceAdjustment) {
        setCalculatedDuration({ hours: 0, minutes: 0 });
        if (absenceTime) {
            setIsTimeValid(true);
            return;
        }
        if (startTime && endTime) {
             const [startH, startM] = startTime.split(':').map(Number);
             const [endH, endM] = endTime.split(':').map(Number);
             const startTotalMins = startH * 60 + startM;
             const endTotalMins = endH * 60 + endM;

             // Permite tempos iguais para ajustes neutros
             if (startTotalMins === endTotalMins) {
                 setIsTimeValid(true);
                 return;
             }
             if (endTotalMins < startTotalMins) {
                 setIsTimeValid(false);
                 return;
             }
             setIsTimeValid(true);
             return;
        }
        setIsTimeValid(true); 
        return;
    }

    // 2. Casos normais
    if (!startTime || !endTime) {
      setCalculatedDuration({ hours: 0, minutes: 0 });
      setIsTimeValid(true);
      return;
    }

    const [startH, startM] = startTime.split(':').map(Number);
    const [endH, endM] = endTime.split(':').map(Number);
    const startTotalMins = startH * 60 + startM;
    const endTotalMins = endH * 60 + endM;

    if (endTotalMins < startTotalMins) {
      setIsTimeValid(false);
      setCalculatedDuration({ hours: 0, minutes: 0 });
    } else if (endTotalMins === startTotalMins) {
      // Se for informativo (Neutro), permitimos 0h.
      if (mappedRecordType === RecordType.NEUTRAL) {
         setIsTimeValid(true);
         setCalculatedDuration({ hours: 0, minutes: 0 });
      } else {
         // Se for crédito/débito e o tempo for igual, tecnicamente é 0h, o que é permitido salvar (pode ser erro de digitação, mas não bloqueante pelo requerimento atual)
         setIsTimeValid(true); 
         setCalculatedDuration({ hours: 0, minutes: 0 });
      }
    } else {
      setIsTimeValid(true);
      const diffMins = endTotalMins - startTotalMins;
      const h = Math.floor(diffMins / 60);
      const m = diffMins % 60;
      setCalculatedDuration({ hours: h, minutes: m });
    }
  }, [startTime, endTime, absenceTime, isAbsenceAdjustment, mappedRecordType]);

  const filteredEmployees = employees.filter(emp => 
    emp.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    emp.team.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const handleSelectEmployee = (emp: Employee) => {
    setSelectedEmployee(emp.id);
    setSearchTerm(emp.name);
    setIsDropdownOpen(false);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validação mínima para não quebrar o banco
    if (!selectedEmployee) {
        alert("Selecione um colaborador.");
        return;
    }
    if (!date) {
        alert("Selecione uma data.");
        return;
    }
    if (!reason) {
        alert("A justificativa é obrigatória.");
        return;
    }

    setLoading(true);

    try {
        const employee = employees.find(e => e.id === selectedEmployee);

        // Normalização de Horários
        // Se estiver vazio, salva como string vazia ''
        const finalStartTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : (startTime || '');
        const finalEndTime = (isAbsenceAdjustment && absenceTime) ? absenceTime : (endTime || '');

        // Normalização de Horas/Minutos
        let finalHours = calculatedDuration.hours;
        let finalMinutes = calculatedDuration.minutes;

        if (isAbsenceAdjustment) {
            finalHours = 0;
            finalMinutes = 0;
        }

        const newRecord: TimeRecord = {
          id: uuidv4(),
          employeeId: selectedEmployee,
          employeeName: employee?.name || 'Desconhecido',
          date, 
          hours: finalHours,
          minutes: finalMinutes,
          startTime: finalStartTime,
          endTime: finalEndTime,
          type: isAbsenceAdjustment ? RecordType.NEUTRAL : mappedRecordType,
          occurrenceType,
          reason,
          createdAt: new Date().toISOString(),
          createdBy: currentUser.id,
          isAdjustment: isAbsenceAdjustment ? true : undefined,
          status: isAbsenceAdjustment ? 'regularized' : undefined
        };

        console.log('Enviando registro:', newRecord);

        await firebaseService.saveTimeRecord(newRecord);

        console.log('✅ GRAVADO COM SUCESSO NO FIRESTORE');

        setSuccess(true);
        onRecordAdded();

        // Reset do Formulário
        if (currentUser.role !== Role.EMPLOYEE) {
           setSelectedEmployee('');
           setSearchTerm('');
        }
        setStartTime('');
        setEndTime('');
        setAbsenceTime('');
        setReason('');
        setCalculatedDuration({ hours: 0, minutes: 0 });
        setOccurrenceType('BH Positivo');

        setTimeout(() => setSuccess(false), 3000);

    } catch (error: any) {
        console.error("Erro CRÍTICO ao salvar batida:", error);
        alert('Erro ao salvar no banco de dados: ' + (error.message || 'Erro desconhecido'));
    } finally {
        setLoading(false);
    }
  };

  const getTypeStyles = (type: RecordType) => {
    switch (type) {
      case RecordType.CREDIT:
        return 'bg-emerald-100 text-emerald-800 border-emerald-200';
      case RecordType.DEBIT:
        return 'bg-red-100 text-red-800 border-red-200';
      case RecordType.NEUTRAL:
        return 'bg-slate-100 text-slate-600 border-slate-200';
      default:
        return 'bg-slate-100 text-slate-800';
    }
  };

  return (
    <div className="max-w-2xl mx-auto animate-fade-in">

      {success && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fade-in">
          <div className="bg-white rounded-2xl shadow-2xl p-8 flex flex-col items-center max-w-sm w-full mx-4 transform transition-all scale-100">
            <div className="h-16 w-16 bg-green-100 rounded-full flex items-center justify-center mb-4">
              <Check size={32} className="text-green-600" strokeWidth={3} />
            </div>
            <h3 className="text-2xl font-bold text-slate-800 mb-2">Sucesso!</h3>
            <p className="text-slate-600 text-center">
              {isAbsenceAdjustment 
                ? 'Ajuste registrado. Saldo inalterado.' 
                : 'Registro salvo no banco de dados.'}
            </p>
          </div>
        </div>
      )}

      <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
        <div className="bg-indigo-600 p-6 text-white">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <Clock className="w-6 h-6" />
            Nova Ocorrência
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Os dados serão sincronizados com o servidor.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="col-span-1 md:col-span-2 relative" ref={dropdownRef}>
              <label className="block text-sm font-medium text-slate-700 mb-2">Colaborador</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <User className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="text"
                  required
                  disabled={currentUser.role === Role.EMPLOYEE}
                  value={searchTerm}
                  onChange={(e) => {
                    setSearchTerm(e.target.value);
                    setSelectedEmployee(''); 
                    setIsDropdownOpen(true);
                  }}
                  onFocus={() => setIsDropdownOpen(true)}
                  placeholder="Buscar colaborador..."
                  className={`block w-full pl-10 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900 placeholder-slate-400 ${selectedEmployee ? 'border-indigo-600 ring-1 ring-indigo-600 bg-indigo-50' : ''} ${currentUser.role === Role.EMPLOYEE ? 'bg-slate-100 cursor-not-allowed text-slate-500' : ''}`}
                />
                <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                   {selectedEmployee ? (
                     <div className="text-indigo-600 bg-indigo-100 rounded-full p-0.5">
                        <Check size={14} strokeWidth={3} />
                     </div>
                   ) : (
                     <ChevronDown className="h-5 w-5 text-slate-400" />
                   )}
                </div>
              </div>

              {isDropdownOpen && currentUser.role !== Role.EMPLOYEE && (
                <div className="absolute z-10 mt-1 w-full bg-white shadow-xl max-h-60 rounded-md py-1 text-base ring-1 ring-black ring-opacity-5 overflow-auto focus:outline-none sm:text-sm">
                  {filteredEmployees.length > 0 ? (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.id}
                        onClick={() => handleSelectEmployee(emp)}
                        className="cursor-pointer select-none relative py-3 pl-10 pr-4 hover:bg-slate-100 text-slate-900 border-b border-slate-50 last:border-0 transition-colors"
                      >
                         <span className={`block truncate ${selectedEmployee === emp.id ? 'font-semibold text-indigo-700' : 'font-normal'}`}>
                          {emp.name}
                        </span>
                        <span className="text-xs text-slate-500 ml-2">({emp.team})</span>

                        {selectedEmployee === emp.id && (
                          <span className="absolute inset-y-0 left-0 flex items-center pl-3 text-indigo-600">
                            <Check className="h-5 w-5" aria-hidden="true" />
                          </span>
                        )}
                      </div>
                    ))
                  ) : (
                    <div className="cursor-default select-none relative py-3 px-4 text-slate-500 text-center">
                      Nenhum colaborador encontrado.
                    </div>
                  )}
                </div>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-slate-700 mb-2">Data da Ocorrência</label>
              <div className="relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                  <Calendar className="h-5 w-5 text-slate-400" />
                </div>
                <input
                  type="date"
                  required
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="block w-full pl-10 pr-3 py-3 border-slate-300 rounded-lg border bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900"
                />
              </div>
            </div>

            <div>
               <label className="block text-sm font-medium text-slate-700 mb-2">Tipo de Ocorrência</label>
               <div className="relative">
                 <select
                    value={occurrenceType}
                    onChange={(e) => setOccurrenceType(e.target.value)}
                    className="block w-full pl-3 pr-10 py-3 text-base border-slate-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-lg border bg-slate-50 text-slate-900"
                 >
                   {OCCURRENCE_OPTIONS.map((opt) => (
                     <option key={opt.label} value={opt.label}>{opt.label}</option>
                   ))}
                 </select>
               </div>

               <div className={`mt-2 p-2 rounded-lg border text-xs font-semibold flex items-center justify-center ${getTypeStyles(mappedRecordType)}`}>
                  {mappedRecordType === RecordType.CREDIT && <span className="flex items-center"><Check size={14} className="mr-1"/> Adiciona ao Banco de Horas (Crédito)</span>}
                  {mappedRecordType === RecordType.DEBIT && <span className="flex items-center"><AlertTriangle size={14} className="mr-1"/> Desconta do Banco de Horas (Débito)</span>}
                  {mappedRecordType === RecordType.NEUTRAL && <span className="flex items-center"><Info size={14} className="mr-1"/> Informativo / Neutro (0h)</span>}
               </div>
            </div>

            {occurrenceType === 'Ausência de Batida' ? (
                <div className="col-span-1 md:col-span-2 animate-fade-in">
                    <label className="block text-sm font-medium text-slate-700 mb-2">Horário do Esquecimento</label>

                    <div className="bg-amber-50 p-4 rounded-xl border border-amber-200">
                        <div className="flex flex-col md:flex-row gap-4 items-center">
                            <div className="w-full md:w-1/2">
                                <label className="block text-xs font-semibold text-amber-700 mb-1">Hora da Batida</label>
                                <input 
                                  type="time" 
                                  required
                                  value={absenceTime}
                                  onChange={(e) => setAbsenceTime(e.target.value)}
                                  className="block w-full px-3 py-3 border border-amber-300 rounded-lg bg-white text-slate-900 focus:ring-amber-500 focus:border-amber-500 text-lg font-medium"
                                />
                            </div>

                            <div className="w-full md:w-1/2 flex items-start gap-3 text-sm text-amber-800">
                                <ShieldAlert className="shrink-0 w-8 h-8 text-amber-600" />
                                <div>
                                    <p className="font-bold">Regularização Detectada</p>
                                    <p className="text-xs mt-1">
                                        O sistema registrará <strong>entrada e saída simultâneas</strong> no horário informado para manter seu saldo inalterado.
                                    </p>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="col-span-1 md:col-span-2">
                  <label className="block text-sm font-medium text-slate-700 mb-2">Período da Atividade</label>
                  <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Início/Entrada</label>
                      <input 
                        type="time" 
                        value={startTime}
                        onChange={(e) => setStartTime(e.target.value)}
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500"
                      />
                    </div>
                    <div>
                      <label className="block text-xs font-semibold text-slate-500 mb-1">Hora Fim/Saída</label>
                      <input 
                        type="time" 
                        value={endTime}
                        onChange={(e) => setEndTime(e.target.value)}
                        className={`block w-full px-3 py-2 border rounded-lg bg-white text-slate-900 focus:ring-indigo-500 focus:border-indigo-500 ${!isTimeValid ? 'border-red-500 ring-1 ring-red-500' : 'border-slate-300'}`}
                      />
                    </div>

                    <div className="col-span-1 sm:col-span-2 mt-2 pt-4 border-t border-slate-200 flex items-center justify-between">
                      <div className="flex items-center text-slate-600">
                        <Calculator size={18} className="mr-2" />
                        <span className="text-sm font-medium">Tempo Calculado:</span>
                      </div>
                      <div className={`text-lg font-bold ${!isTimeValid ? 'text-red-500' : 'text-slate-800'}`}>
                        {!isTimeValid ? (
                          <span className="text-sm">Horário Inválido</span>
                        ) : (
                           <span>{calculatedDuration.hours}h {calculatedDuration.minutes}m</span>
                        )}
                      </div>
                    </div>
                  </div>
                  {!isTimeValid && !isAbsenceAdjustment && (
                    <p className="text-xs text-red-500 mt-1">A hora de término deve ser posterior à hora de início (exceto para informativos).</p>
                  )}
                </div>
            )}

          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">
              Justificativa {isAbsenceAdjustment && <span className="text-red-500">* (Obrigatório)</span>}
            </label>
            <textarea
              required
              rows={3}
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder={isAbsenceAdjustment ? "Explique detalhadamente o motivo do ajuste..." : "Detalhes adicionais..."}
              className={`block w-full px-3 py-3 border rounded-lg bg-slate-50 focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm text-slate-900 ${isAbsenceAdjustment && !reason ? 'border-amber-300 ring-1 ring-amber-300' : 'border-slate-300'}`}
            />
          </div>

          <div className="pt-2">
            <button
              type="submit"
              disabled={loading} 
              className={`w-full flex justify-center py-4 px-4 border border-transparent rounded-xl shadow-sm text-base font-bold text-white transition-all ${
                loading 
                  ? 'bg-slate-400 cursor-not-allowed' 
                  : 'bg-indigo-600 hover:bg-indigo-700 focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500'
              }`}
            >
              {loading ? (
                <span className="flex items-center">
                  <Loader2 className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" />
                  Salvando no Firebase...
                </span>
              ) : (
                <span className="flex items-center">
                  <Save className="mr-2" size={20} />
                  {isAbsenceAdjustment ? 'Registrar Ajuste' : 'Registrar Batida'}
                </span>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default TimeEntryForm;

import { 
  signInWithEmailAndPassword, 
  signOut, 
  sendPasswordResetEmail,
  User 
} from 'firebase/auth';
import { 
  doc, 
  getDoc, 
  setDoc, 
  collection, 
  query, 
  getDocs, 
  where, 
  orderBy, 
  deleteDoc, 
  updateDoc,
  serverTimestamp,
  writeBatch,
  addDoc
} from 'firebase/firestore';
import { auth, db } from '../lib/firebase';
import { Employee, Role, TimeRecord, RecordType, AppSetting } from '../types';

export const firebaseService = {
  auth,
  db,

  // --- AUTHENTICATION ---

  async login(email: string, pass: string): Promise<{ success: boolean; user?: Employee; message?: string }> {
    try {
      if (!auth) {
         throw new Error("Serviço de autenticação não está pronto.");
      }

      const userCredential = await signInWithEmailAndPassword(auth, email, pass);
      const profile = await this.getOrCreateProfile(userCredential.user);
      return { success: true, user: profile };
    } catch (error: any) {
      console.error("Login Error:", error);
      let msg = "Erro ao realizar login.";

      if (error.code === 'auth/invalid-credential' || error.code === 'auth/wrong-password' || error.code === 'auth/user-not-found') {
        msg = "E-mail ou senha inválidos.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas. Tente novamente mais tarde.";
      } else if (error.code === 'auth/network-request-failed') {
        msg = "Erro de conexão. Verifique sua internet.";
      }

      return { success: false, message: msg };
    }
  },

  async logout(): Promise<void> {
    if (auth) await signOut(auth);
  },

  async sendPasswordReset(email: string): Promise<{ success: boolean; message: string }> {
    try {
      if (!auth) throw new Error("Auth service not initialized");
      await sendPasswordResetEmail(auth, email);
      return { success: true, message: "E-mail de recuperação enviado! Verifique sua caixa de entrada." };
    } catch (error: any) {
      console.error("Reset Password Error:", error);
      let msg = "Erro ao enviar e-mail de recuperação.";

      if (error.code === 'auth/user-not-found') {
        msg = "Este e-mail não está cadastrado no sistema.";
      } else if (error.code === 'auth/invalid-email') {
        msg = "Formato de e-mail inválido.";
      } else if (error.code === 'auth/too-many-requests') {
        msg = "Muitas tentativas. Aguarde um momento.";
      }

      return { success: false, message: msg };
    }
  },

  // --- USER PROFILE ---

  async getUserProfile(uid: string): Promise<Employee | null> {
    try {
      const docRef = doc(db, 'employees', uid);
      const docSnap = await getDoc(docRef);
      return docSnap.exists() ? (docSnap.data() as Employee) : null;
    } catch (e) {
      console.error("Erro ao buscar perfil:", e);
      return null;
    }
  },

  async getOrCreateProfile(user: User, name?: string): Promise<Employee> {
    const email = user.email?.toLowerCase() || '';
    const isSuperAdmin = email === 'ti@arcaplast.com.br';

    // Tenta buscar pelo UID primeiro (Login padrão)
    let existingProfile = await this.getUserProfile(user.uid);

    // Se não achar pelo UID, tenta buscar pelo username (caso tenha sido importado via CSV e seja o primeiro login)
    if (!existingProfile && email) {
        const username = email.split('@')[0];
        const docRefUser = doc(db, 'employees', username);
        const docSnapUser = await getDoc(docRefUser);

        if (docSnapUser.exists()) {
            console.log("Perfil encontrado via username (importado). Vinculando UID...");
            existingProfile = docSnapUser.data() as Employee;
        }
    }

    if (existingProfile) {
      if (isSuperAdmin && existingProfile.role !== Role.ADMIN) {
        console.log("Atualizando permissão de Super Admin...");
        const updated = { ...existingProfile, role: Role.ADMIN };
        await setDoc(doc(db, 'employees', user.uid), updated, { merge: true });
        return updated;
      }
      return existingProfile;
    }

    console.log("Criando novo perfil para:", email);
    const newEmployee: Employee = {
      id: user.uid,
      name: name || user.displayName || 'Colaborador',
      email: email,
      username: email.split('@')[0],
      role: isSuperAdmin ? Role.ADMIN : Role.EMPLOYEE,
      team: 'Geral',
      company: 'Arca Plast',
      active: true
    };

    await setDoc(doc(db, 'employees', user.uid), newEmployee);
    return newEmployee;
