              <Users size={20} />
            </div>
          </div>
          <p className="text-xs text-slate-400 mt-2">
            {selectedEmpId 
              ? 'Visualizando 1 colaborador' 
              : 'Ativos neste filtro'}
          </p>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm transition-all">
          <div className="flex justify-between items-start">
